// Set to true to enable verbose Planner rendering diagnostics in the console.
// Toggle here without recompiling business logic.
const bool kDebugPlanner = false;

// ─────────────────────────────────────────────────────────────────────────────
// AppClock — single source of truth for "what time is it / what time is this
// timestamp" across the whole app.
//
// All persisted timestamps in this app (plannedAt, etc.) are stored as
// unix-ms, i.e. a true, zone-independent instant. The bug this fixes: many
// places used to render those instants with DateTime.fromMillisecondsSinceEpoch
// (ms).toLocal(), which trusts whatever timezone the OS/device happens to be
// set to. If the device clock/timezone is off (or the workspace is opened on
// a machine in a different zone), every card/report shows the wrong hour.
//
// AppClock instead applies a single, user-chosen fixed UTC offset
// (configured in Settings → Date and Time) so displayed times are always
// correct and consistent, independent of the OS timezone. It intentionally
// uses a fixed offset rather than the full IANA tz database (no extra
// package dependency) — daylight saving transitions are not auto-applied,
// so pick whichever zone matches your current offset.
// ─────────────────────────────────────────────────────────────────────────────
class AppClock {
  /// Offset from UTC, in minutes. Defaults to Brasília time (UTC-03:00).
  static int offsetMinutes = -180;

  /// IANA-style id, kept only so the Settings dropdown can show a checked
  /// item; the offset above is what's actually used for conversions.
  static String timezoneId = 'America/Sao_Paulo';

  /// Manual clock delta in milliseconds. When non-zero the app's notion of
  /// "now" is shifted by this amount, letting you verify that countdowns
  /// compute correctly for any chosen date/time. Set via Settings → Date and
  /// Time → Internal Clock. Zero means "use the real system clock".
  static int clockDeltaMs = 0;

  /// "Now", expressed in the configured app timezone — use this instead of
  /// DateTime.now() anywhere the *displayed* current time/day matters.
  static DateTime now() => DateTime.fromMillisecondsSinceEpoch(
        DateTime.now().toUtc().millisecondsSinceEpoch + clockDeltaMs,
        isUtc: true,
      ).add(Duration(minutes: offsetMinutes));

  /// The real system "now" in the app timezone (ignores clockDeltaMs).
  /// Used only by the Settings clock display so users can compare real vs
  /// simulated time side-by-side.
  static DateTime realNow() =>
      DateTime.now().toUtc().add(Duration(minutes: offsetMinutes));

  /// Converts a stored unix-ms timestamp (a true UTC instant) into the
  /// configured app timezone for display. Use this instead of
  /// DateTime.fromMillisecondsSinceEpoch(ms).toLocal().
  static DateTime fromEpoch(int ms) => DateTime.fromMillisecondsSinceEpoch(
    ms,
    isUtc: true,
  ).add(Duration(minutes: offsetMinutes));
}

// ─────────────────────────────────────────────────────────────────────────────
// AppTheme — InheritedWidget that propagates isLight to all descendants.
// Use AppTheme.of(context).isLight to query the current mode anywhere.
// ─────────────────────────────────────────────────────────────────────────────

class AppTheme extends InheritedWidget {
  final bool isLight;
  const AppTheme({super.key, required this.isLight, required super.child});

  static AppTheme of(BuildContext context) {
    final r = context.dependOnInheritedWidgetOfExactType<AppTheme>();
    assert(r != null, 'No AppTheme in context');
    return r!;
  }

  // Convenience getter: SpColors token set for the current mode.
  SpColors get colors => SpColors(isLight);

  @override
  bool updateShouldNotify(AppTheme old) => old.isLight != isLight;
}

// ─────────────────────────────────────────────────────────────────────────────
// SpColors — semantic color tokens that flip between dark and light mode.
// ─────────────────────────────────────────────────────────────────────────────

class SpColors {
  final bool isLight;
  const SpColors(this.isLight);

  // Surfaces
  Color get canvasBg =>
      isLight ? const Color(0xFFF2F3F5) : const Color(0xFF12141A);
  Color get sidebarBg =>
      isLight ? const Color(0xFFE8EAED) : const Color(0xFF1A1C22);
  Color get panelBg =>
      isLight ? const Color(0xFFFFFFFF) : const Color(0xFF1E2124);
  Color get cardBg =>
      isLight ? const Color(0xFFFFFFFF) : const Color(0xFF252830);
  Color get headerBg =>
      isLight ? const Color(0xFFECEDF0) : const Color(0xFF181A1C);
  Color get inputBg =>
      isLight ? const Color(0xFFF5F6F8) : const Color(0xFF1C1F24);
  Color get dividerColor =>
      isLight ? const Color(0xFFDDDFE3) : const Color(0xFF2C2F35);
  Color get overlay =>
      isLight ? const Color(0xFFFFFFFF) : const Color(0xFF252830);

  // Text
  Color get textPrimary => isLight ? const Color(0xFF1A1C22) : Colors.white;
  Color get textSecondary => isLight ? const Color(0xFF555D6B) : Colors.white70;
  Color get textDisabled => isLight ? const Color(0xFF9EA7B3) : Colors.white38;
  Color get textHint =>
      isLight ? const Color(0xFFB0B8C4) : const Color(0x44FFFFFF);

  // Borders
  Color get borderSubtle =>
      isLight ? const Color(0xFFD0D4DA) : Colors.white.withOpacity(0.07);
  Color get borderMed =>
      isLight ? const Color(0xFFBBC0C8) : Colors.white.withOpacity(0.12);

  // Accent (same in both modes)
  Color get accent => const Color(0xFF4FC3F7);

  // Scrim
  Color get scrim =>
      isLight ? Colors.black.withOpacity(0.12) : Colors.black.withOpacity(0.35);
}

// ─────────────────────────────────────────────────────────────────────────────
// Contrast-border helpers (Features 4 & 5).
//   Dark mode:  fill luminance < 0.15  → white outline
//   Light mode: fill luminance > 0.85  → black outline
// ─────────────────────────────────────────────────────────────────────────────

const double _kLowLumThreshold = 0.15;
const double _kHighLumThreshold = 0.85;

Border? adaptiveBorder(Color fill, bool isLight) {
  final lum = fill.computeLuminance();
  if (!isLight && lum < _kLowLumThreshold)
    return Border.all(color: Colors.white, width: 1.5);
  if (isLight && lum > _kHighLumThreshold)
    return Border.all(color: Colors.black, width: 1.5);
  return null;
}

BoxDecoration withAdaptiveBorder(
  BoxDecoration base,
  Color fillColor,
  bool isLight,
) {
  final b = adaptiveBorder(fillColor, isLight);
  return b == null ? base : base.copyWith(border: b);
}

// --- 1. DATA MODELS ---

enum TaskStatus {
  none(
    label: 'None',
    color: Color(0xFF9E9E9E),
    icon: Icons.check_box_outline_blank,
  ),
  todo(
    label: 'To Do',
    color: Color(0xFFFFD600),
    icon: Icons.radio_button_unchecked,
  ),
  inProgress(
    label: 'In Progress',
    color: Color(0xFFE91E63),
    icon: Icons.autorenew,
  ),
  done(label: 'Done', color: Color(0xFF4CAF50), icon: Icons.check_box),
  waiting(
    label: 'Waiting',
    color: Color(0xFFFF9800),
    icon: Icons.hourglass_top,
  ),
  cancelled(
    label: 'Cancelled',
    color: Color(0xFFB71C1C),
    icon: Icons.cancel_outlined,
  ),
  withdrawn(
    label: 'Withdrawn',
    color: Color(0xFFF44336),
    icon: Icons.not_interested,
  ),
  surpassed(label: 'Surpassed', color: Color(0xFF9E9E9E), icon: Icons.block);

  final String label;
  final Color color;
  final IconData icon;

  const TaskStatus({
    required this.label,
    required this.color,
    required this.icon,
  });
}

class Task {
  final String id;
  String title; // mutable – editable from canvas
  bool isDone;
  TaskStatus status; // Multi-status indicator
  String projectId; // mutable – editable from details panel

  // Fields from the JSON structure
  final List<dynamic> subTaskIds;
  final int timeSpentOriginal; // keep original for display fallback
  int timeSpent; // mutable – editable from task details panel
  String? dueDay; // mutable – editable from canvas (date portion)
  int? plannedAt; // SP "planned at" unix-ms timestamp — drives canvas position
  int durationMinutes; // schedule block duration (default 30)
  final List<dynamic> attachments;
  final String? repeatCfgId;
  List<dynamic> tagIds;
  String? notes; // mutable – editable from canvas
  RepeatConfig? repeatConfig; // mutable – set via details panel
  String? repeatParentId; // non-null on auto-generated repeat instances

  /// Canonical series membership key.
  /// • Parent task  → equals its own [id] (set at construction / fromJson).
  /// • Instance     → equals the parent's [id] (same as [repeatParentId]).
  /// • Non-repeating → null.
  ///
  /// Use [isPartOfSeries] / [isSeriesParent] instead of reading raw fields.
  String? seriesId;

  /// True for every task that belongs to a repeat series (parent or instance).
  bool get isPartOfSeries => seriesId != null;

  /// True only for the originating task of a series (the one that owns
  /// the master [repeatConfig]). Instances have [seriesId] != [id].
  bool get isSeriesParent => seriesId != null && seriesId == id;

  // UI State fields
  bool isExpanded;
  double cardWidth;
  double cardHeight;
  Set<String> visibleProperties;
  Map<String, double>
  propertyHeights; // NEW: Stores custom heights for each region
  bool titleWrap; // Whether the card title wraps (true) or truncates (false)
  double?
  cardManualHeight; // User-dragged height for collapsed (non-expanded) cards; null = auto

  Task({
    required this.id,
    required this.title,
    required this.isDone,
    this.status = TaskStatus.none,
    required this.projectId,
    required this.subTaskIds,
    required this.timeSpent,
    this.dueDay,
    this.plannedAt,
    this.durationMinutes = 30,
    required this.attachments,
    this.repeatCfgId,
    required this.tagIds,
    this.notes,
    this.repeatParentId,
    this.seriesId,
    this.isExpanded = false,
    this.cardWidth = 250,
    this.cardHeight = 250,
    Set<String>? visibleProperties,
    Map<String, double>? propertyHeights,
    this.titleWrap = false,
    this.cardManualHeight,
  }) : timeSpentOriginal = timeSpent,
       visibleProperties = visibleProperties ?? {},
       propertyHeights = propertyHeights ?? {};

  /// Returns the best DateTime for canvas positioning:
  /// 1. plannedAt (unix ms) — highest priority (set by SP scheduler)
  /// 2. dueDay if it contains a time component (T)
  /// 3. null
  ///
  /// Always returns a local-time DateTime so that .hour/.minute correctly
  /// map to the user's wall-clock time on the canvas time-grid.
  DateTime? get scheduledDateTime {
    if (plannedAt != null && plannedAt! > 0) {
      // Convert via AppClock (configured timezone) instead of .toLocal()
      // (OS timezone), so the displayed hour is correct and consistent
      // regardless of how the device clock is set.
      return AppClock.fromEpoch(plannedAt!);
    }
    if (dueDay != null && dueDay!.contains('T')) {
      return DateTime.tryParse(dueDay!)?.toLocal();
    }
    return null;
  }

  /// Returns the date portion only (for day-column matching), from either
  /// plannedAt or dueDay.
  DateTime? get scheduledDate {
    final dt = scheduledDateTime;
    if (dt != null) return DateTime(dt.year, dt.month, dt.day);
    if (dueDay != null) {
      final d = DateTime.tryParse(dueDay!);
      if (d != null) return DateTime(d.year, d.month, d.day);
    }
    return null;
  }

  factory Task.fromJson(Map<String, dynamic> json) {
    final isDone = json['isDone'] as bool? ?? false;
    // Prefer an explicit 'status' field (written by toJson / workspace save).
    // Fall back to deriving from isDone for SP __meta_ imports that lack it.
    TaskStatus status;
    if (json['status'] is String) {
      try {
        status = TaskStatus.values.byName(json['status'] as String);
      } catch (_) {
        status = isDone ? TaskStatus.done : TaskStatus.none;
      }
    } else {
      status = isDone ? TaskStatus.done : TaskStatus.none;
    }
    return Task(
      id: json['id'] as String,
      title: json['title'] as String,
      isDone: isDone,
      status: status,
      projectId: json['projectId'] as String? ?? 'INBOX_PROJECT',
      subTaskIds: json['subTaskIds'] as List<dynamic>? ?? [],
      timeSpent: json['timeSpent'] as int? ?? 0,
      dueDay: json['dueDay'] as String?,
      plannedAt: json['plannedAt'] as int?,
      durationMinutes: json['durationMinutes'] as int? ?? 30,
      attachments: json['attachments'] as List<dynamic>? ?? [],
      repeatCfgId: json['repeatCfgId'] as String?,
      tagIds: json['tagIds'] as List<dynamic>? ?? [],
      notes: json['notes'] as String?,
      repeatParentId: json['repeatParentId'] as String?,
      // Derive seriesId: prefer the persisted value, then infer from legacy fields.
      // Parent: seriesId == own id (has repeatCfgId but no repeatParentId).
      // Instance: seriesId == repeatParentId.
      seriesId: json['seriesId'] as String? ??
          (json['repeatParentId'] as String?) ??
          (json['repeatCfgId'] != null ? json['id'] as String? : null),
    );
  }

  Map<String, dynamic> toJson() {
    return {
      'id': id,
      'title': title,
      'isDone': isDone,
      'status': status.name,
      'projectId': projectId,
      'subTaskIds': subTaskIds,
      'timeSpent': timeSpent,
      if (dueDay != null) 'dueDay': dueDay,
      if (plannedAt != null && plannedAt! > 0) 'plannedAt': plannedAt,
      'durationMinutes': durationMinutes,
      'attachments': attachments,
      if (repeatCfgId != null) 'repeatCfgId': repeatCfgId,
      'tagIds': tagIds,
      if (notes != null && notes!.isNotEmpty) 'notes': notes,
      if (repeatParentId != null) 'repeatParentId': repeatParentId,
      if (seriesId != null) 'seriesId': seriesId,
    };
  }
}

