/// Preset for Notes FGS Sort.
/// The built-in "Manual Ordering" preset (id == _kNotesManualPresetId) is undeletable.
class NotesSortPreset {
  final String id; String name; final bool isManual;
  List<NoteSortCriterion> folderCriteria; List<NoteSortCriterion> itemCriteria;
  NotesSortPreset({required this.id, required this.name, this.isManual = false,
      List<NoteSortCriterion>? folderCriteria, List<NoteSortCriterion>? itemCriteria})
      : folderCriteria = folderCriteria ?? [], itemCriteria = itemCriteria ?? [];
  NotesSortPreset copyWith({String? name}) => NotesSortPreset(
        id: id, name: name ?? this.name, isManual: isManual,
        folderCriteria: folderCriteria.map((c) => NoteSortCriterion(id: c.id, fieldName: c.fieldName, ascending: c.ascending, emptyLast: c.emptyLast)).toList(),
        itemCriteria: itemCriteria.map((c) => NoteSortCriterion(id: c.id, fieldName: c.fieldName, ascending: c.ascending, emptyLast: c.emptyLast)).toList(),
      );
}

const _kNotesManualPresetId = '__notes_manual_ordering__';

enum TaskFilterField {
  none('No Filter'),
  name('Name'),
  tag('Tag'),
  project('Project'),
  estimatedTime('Estimated Time'),
  scheduledDate('Scheduled Date'),
  insertionDate('Insertion Date'),
  timeSpent('Time Spent'),
  status('Status'),
  repeating('Repeating'),
  groups('Groups');

  final String label;
  const TaskFilterField(this.label);
}

// ── Grist-style stackable Filter / Group / Sort data classes ──────────────────

/// A single filter rule targeting one field.
class FilterRule {
  final String id; // unique uuid for key
  TaskFilterField field;
  // Tag / Project / Status: selected values (empty = no constraint)
  Set<String> selectedValues;
  // Name filter (substring search)
  String nameQuery;
  // Date range
  DateTime? dateFrom;
  DateTime? dateTo;
  // Numeric range (minutes)
  int? numMin;
  int? numMax;

  FilterRule({
    required this.id,
    this.field = TaskFilterField.tag,
    Set<String>? selectedValues,
    this.nameQuery = '',
    this.dateFrom,
    this.dateTo,
    this.numMin,
    this.numMax,
  }) : selectedValues = selectedValues ?? {};

  /// Returns true if this rule has at least one value / bound configured.
  bool get isConfigured {
    switch (field) {
      case TaskFilterField.none:
        return false;
      case TaskFilterField.name:
        return nameQuery.trim().isNotEmpty;
      case TaskFilterField.tag:
      case TaskFilterField.project:
      case TaskFilterField.status:
      case TaskFilterField.repeating:
      case TaskFilterField.groups:
        return selectedValues.isNotEmpty;
      case TaskFilterField.scheduledDate:
      case TaskFilterField.insertionDate:
        return dateFrom != null || dateTo != null;
      case TaskFilterField.estimatedTime:
      case TaskFilterField.timeSpent:
        return numMin != null || numMax != null;
    }
  }

  bool matches(Task t, Map<String, Project> projects) {
    switch (field) {
      case TaskFilterField.none:
        return true;
      case TaskFilterField.name:
        final q = nameQuery.trim().toLowerCase();
        if (q.isEmpty) return true;
        return t.title.toLowerCase().contains(q);
      case TaskFilterField.tag:
        if (selectedValues.isEmpty) return true;
        return t.tagIds.map((id) => id.toString()).any(selectedValues.contains);
      case TaskFilterField.project:
        if (selectedValues.isEmpty) return true;
        return selectedValues.contains(t.projectId);
      case TaskFilterField.status:
        if (selectedValues.isEmpty) return true;
        return selectedValues.contains(t.status.name);
      case TaskFilterField.repeating:
        if (selectedValues.isEmpty) return true;
        final isRep = t.isPartOfSeries;
        if (selectedValues.contains('repeating') && isRep) return true;
        if (selectedValues.contains('nonRepeating') && !isRep) return true;
        return false;
      case TaskFilterField.groups:
        // Matched externally against _groupContainers; always pass here.
        return true;
      case TaskFilterField.insertionDate:
        // Task IDs are ms-epoch timestamps — use as creation date proxy.
        final ms = int.tryParse(t.id);
        if (ms == null) return true;
        final created = DateTime.fromMillisecondsSinceEpoch(ms);
        if (dateFrom != null && created.isBefore(dateFrom!)) return false;
        if (dateTo != null && created.isAfter(dateTo!)) return false;
        return true;
      case TaskFilterField.scheduledDate:
        final d = t.scheduledDate;
        if (d == null) return false;
        if (dateFrom != null && d.isBefore(dateFrom!)) return false;
        if (dateTo != null && d.isAfter(dateTo!)) return false;
        return true;
      case TaskFilterField.estimatedTime:
        final dur = t.durationMinutes;
        if (numMin != null && dur < numMin!) return false;
        if (numMax != null && dur > numMax!) return false;
        return true;
      case TaskFilterField.timeSpent:
        final spent = t.timeSpent ~/ 60000;
        if (numMin != null && spent < numMin!) return false;
        if (numMax != null && spent > numMax!) return false;
        return true;
    }
  }
}

/// A single group criterion.
class GroupCriterion {
  final String id;
  TaskGroupOption field;
  bool ascending;

  GroupCriterion({
    required this.id,
    this.field = TaskGroupOption.tag,
    this.ascending = true,
  });

  String keyFor(Task t, Map<String, Project> projects) {
    switch (field) {
      case TaskGroupOption.none:
        return '—';
      case TaskGroupOption.tag:
        return t.tagIds.isNotEmpty ? t.tagIds.first.toString() : '—';
      case TaskGroupOption.project:
        if (t.projectId == 'INBOX_PROJECT') return '__inbox__';
        return projects[t.projectId]?.title ?? t.projectId;
      case TaskGroupOption.scheduledDate:
        final d = t.scheduledDate;
        if (d == null) return 'No date';
        return '${d.year}-${d.month.toString().padLeft(2, '0')}-${d.day.toString().padLeft(2, '0')}';
      case TaskGroupOption.status:
        return t.status.label;
    }
  }
}

// ── Metagroup / Container system ──────────────────────────────────────────────

/// Metagroups are the "axes" the user can pick from.
/// Each metagroup expands into one or more pre-defined containers.
enum TaskMetagroup {
  status('Status'),
  tag('Tag'),
  project('Project'),
  scheduledDate('Scheduled Date'),
  repeating('Repeating'),
  remainder('Remainder');

  final String label;
  const TaskMetagroup(this.label);
}

/// A container is a named bucket that matches tasks via an AND of criteria.
// ── ContainerCriteriaItem ─────────────────────────────────────────────────────
/// One editable criteria slot inside a GroupContainer.
/// A criteria item can be a status, a repeating flag, an overdue flag,
/// a catch-all, or a parenthesis group opener/closer.
enum CriteriaItemType {
  status,
  repeating,    // true = repeating, false = non-repeating
  overdue,      // true = overdue, false = not overdue
  catchAll,
  parenOpen,
  parenClose,
}

class ContainerCriteriaItem {
  final String id;
  final CriteriaItemType type;
  // For status: the TaskStatus value
  TaskStatus? status;
  // For repeating: true=repeating, false=non-repeating
  bool? boolValue;
  // Logical operator that follows this item (null for the last item)
  LogicalOperator? operatorAfter;

  ContainerCriteriaItem({
    required this.id,
    required this.type,
    this.status,
    this.boolValue,
    this.operatorAfter,
  });

  String get label {
    switch (type) {
      case CriteriaItemType.status:
        return status?.label ?? '?';
      case CriteriaItemType.repeating:
        return boolValue == true ? 'Repeating' : 'Non-Repeating';
      case CriteriaItemType.overdue:
        return boolValue == true ? 'Overdue' : 'Not Overdue';
      case CriteriaItemType.catchAll:
        return 'catch-all';
      case CriteriaItemType.parenOpen:
        return '(';
      case CriteriaItemType.parenClose:
        return ')';
    }
  }

  Color get color {
    switch (type) {
      case CriteriaItemType.status:
        return status?.color.withOpacity(0.7) ?? Colors.white24;
      case CriteriaItemType.repeating:
        return boolValue == true
            ? const Color(0xFF7C4DFF).withOpacity(0.7)
            : Colors.white38;
      case CriteriaItemType.overdue:
        return boolValue == true
            ? const Color(0xFFEF5350).withOpacity(0.7)
            : Colors.white38;
      case CriteriaItemType.catchAll:
        return Colors.white24;
      case CriteriaItemType.parenOpen:
      case CriteriaItemType.parenClose:
        return const Color(0xFF4FC3F7).withOpacity(0.6);
    }
  }
}

/// The user can rename the display label but the internal [statusMatches],
/// [repeatingMatch], [isOverdue], and [isRest] semantics are fixed.
class GroupContainer {
  final String id;
  String displayLabel; // user-editable name
  // Which statuses count (empty = any)
  final Set<TaskStatus> statusMatches;
  // null = don't filter by repeating; true = only repeating; false = only non-repeating
  final bool? repeatingMatch;
  // true  = only tasks whose scheduledDate < today
  // false = only tasks whose scheduledDate >= today OR no date
  // null  = no overdue constraint
  final bool? overdueMatch;
  // true = catch-all: matches everything NOT matched by earlier containers
  final bool isRest;
  // Whether to show this container even when empty
  bool collapsed;
  // Editable criteria items (logical expression built by the user)
  List<ContainerCriteriaItem> criteriaItems;
  // Default logical operator shown between items when none is set
  LogicalOperator defaultOperator;

  GroupContainer({
    required this.id,
    required this.displayLabel,
    Set<TaskStatus>? statusMatches,
    this.repeatingMatch,
    this.overdueMatch,
    this.isRest = false,
    this.collapsed = false,
    List<ContainerCriteriaItem>? criteriaItems,
    this.defaultOperator = LogicalOperator.and,
  }) : statusMatches = statusMatches ?? {},
       criteriaItems = criteriaItems ?? _defaultCriteriaFor(
         statusMatches: statusMatches ?? {},
         repeatingMatch: repeatingMatch,
         overdueMatch: overdueMatch,
         isRest: isRest,
       );

  /// Build the default criteria items from the legacy fields.
  static List<ContainerCriteriaItem> _defaultCriteriaFor({
    required Set<TaskStatus> statusMatches,
    bool? repeatingMatch,
    bool? overdueMatch,
    bool isRest = false,
  }) {
    final items = <ContainerCriteriaItem>[];
    if (isRest) {
      items.add(ContainerCriteriaItem(
        id: _gristId(),
        type: CriteriaItemType.catchAll,
      ));
      return items;
    }
    for (final s in statusMatches) {
      items.add(ContainerCriteriaItem(
        id: _gristId(),
        type: CriteriaItemType.status,
        status: s,
      ));
    }
    if (repeatingMatch != null) {
      items.add(ContainerCriteriaItem(
        id: _gristId(),
        type: CriteriaItemType.repeating,
        boolValue: repeatingMatch,
      ));
    }
    if (overdueMatch != null) {
      items.add(ContainerCriteriaItem(
        id: _gristId(),
        type: CriteriaItemType.overdue,
        boolValue: overdueMatch,
      ));
    }
    // Assign operators between consecutive items (last has no operator).
    // Status criteria are combined with OR (a task has status X *or* Y),
    // while the transition from status → repeating/overdue uses AND.
    for (int i = 0; i < items.length - 1; i++) {
      final curr = items[i];
      final next = items[i + 1];
      // Both current and next are status items → OR
      if (curr.type == CriteriaItemType.status &&
          next.type == CriteriaItemType.status) {
        curr.operatorAfter = LogicalOperator.or;
      } else {
        curr.operatorAfter = LogicalOperator.and;
      }
    }

    // Wrap contiguous OR-connected status items in parentheses so that
    // operator precedence is explicit: ( None OR ToDo OR ... ) AND Non-Repeating
    // Only wrap when there are items after the status block (repeating/overdue),
    // since without a following AND the parens add no value visually.
    final hasTrailing = items.any((e) =>
        e.type == CriteriaItemType.repeating ||
        e.type == CriteriaItemType.overdue);
    final statusCount = items.where((e) => e.type == CriteriaItemType.status).length;
    if (hasTrailing && statusCount > 1) {
      // Find the index of the first non-status item
      final splitIdx = items.indexWhere((e) =>
          e.type != CriteriaItemType.status);
      // Remove the AND that the operator loop placed on the last status item
      // (index splitIdx-1) — it must move to the ) instead.
      items[splitIdx - 1].operatorAfter = null;
      // Insert ) after the last status item; assign AND so the next item
      // (repeating/overdue) reads as: ) AND <C>
      final parenClose = ContainerCriteriaItem(
        id: _gristId(),
        type: CriteriaItemType.parenClose,
      )..operatorAfter = LogicalOperator.and;
      items.insert(splitIdx, parenClose);
      // Insert ( before the first status item (index 0)
      items.insert(
        0,
        ContainerCriteriaItem(id: _gristId(), type: CriteriaItemType.parenOpen),
      );
    }

    return items;
  }

  bool matches(Task t, DateTime today) {
    if (isRest) return true; // handled by caller to be "everything else"
    // Status gate
    if (statusMatches.isNotEmpty && !statusMatches.contains(t.status)) {
      return false;
    }
    // Repeating gate
    if (repeatingMatch != null) {
      final isRep = t.isPartOfSeries;
      if (repeatingMatch! && !isRep) return false;
      if (!repeatingMatch! && isRep) return false;
    }
    // Overdue gate
    if (overdueMatch != null) {
      final sd = t.scheduledDate;
      final isOvd = sd != null && sd.isBefore(today);
      if (overdueMatch! && !isOvd) return false;
      if (!overdueMatch! && isOvd) return false;
    }
    return true;
  }
}

/// Returns the default set of containers that replicates the legacy bucketing.
List<GroupContainer> _defaultGroupContainers() {
  return [
    // Standard: active non-overdue non-repeating tasks
    GroupContainer(
      id: 'default_standard',
      displayLabel: 'Standard',
      statusMatches: {TaskStatus.none, TaskStatus.todo, TaskStatus.inProgress, TaskStatus.waiting},
      repeatingMatch: false,
      overdueMatch: false,
      defaultOperator: LogicalOperator.or,
    ),
    // Overdue: active non-repeating overdue
    GroupContainer(
      id: 'default_overdue',
      displayLabel: 'Overdue',
      statusMatches: {TaskStatus.none, TaskStatus.todo, TaskStatus.inProgress, TaskStatus.waiting},
      repeatingMatch: false,
      overdueMatch: true,
      defaultOperator: LogicalOperator.or,
    ),
    // Done: terminal-status, non-repeating
    GroupContainer(
      id: 'default_done',
      displayLabel: 'Done',
      statusMatches: {TaskStatus.done, TaskStatus.cancelled, TaskStatus.withdrawn, TaskStatus.surpassed},
      repeatingMatch: false,
      defaultOperator: LogicalOperator.or,
    ),
    // Not-Done & Repeating
    GroupContainer(
      id: 'default_repeating_active',
      displayLabel: 'Not-Done & Repeating',
      statusMatches: {TaskStatus.none, TaskStatus.todo, TaskStatus.inProgress, TaskStatus.waiting},
      repeatingMatch: true,
      defaultOperator: LogicalOperator.or,
    ),
    // Done & Repeating
    GroupContainer(
      id: 'default_repeating_done',
      displayLabel: 'Done & Repeating',
      statusMatches: {TaskStatus.done, TaskStatus.cancelled, TaskStatus.withdrawn, TaskStatus.surpassed},
      repeatingMatch: true,
      defaultOperator: LogicalOperator.or,
    ),
  ];
}

/// Returns the containers that a metagroup adds when clicked.
List<GroupContainer> _containersForMetagroup(TaskMetagroup mg) {
  switch (mg) {
    case TaskMetagroup.status:
      return TaskStatus.values.map((s) => GroupContainer(
        id: _gristId(),
        displayLabel: s.label,
        statusMatches: {s},
      )).toList();
    case TaskMetagroup.repeating:
      return [
        GroupContainer(id: _gristId(), displayLabel: 'Non-Repeating', repeatingMatch: false),
        GroupContainer(id: _gristId(), displayLabel: 'Repeating', repeatingMatch: true),
      ];
    case TaskMetagroup.remainder:
      return [
        GroupContainer(id: _gristId(), displayLabel: 'Remainder', isRest: true),
      ];
    case TaskMetagroup.tag:
    case TaskMetagroup.project:
    case TaskMetagroup.scheduledDate:
      return [];
  }
}

/// A single sort criterion.
class SortCriterion {
  final String id;
  TaskSortOption field;
  bool ascending;
  bool emptyLast;

  SortCriterion({
    required this.id,
    this.field = TaskSortOption.insertionDate,
    this.ascending = true,
    this.emptyLast = true,
  });
}

int _compareBySort(Task a, Task b, SortCriterion s) {
  int result;
  switch (s.field) {
    case TaskSortOption.scheduledDate:
      // Use scheduledDateTime (not scheduledDate) so tasks on the same day are
      // ordered by time (e.g. 09:00 before 15:00). plannedAt takes priority
      // over dueDay, matching the same logic in Task.scheduledDateTime.
      final da =
          a.scheduledDateTime ??
          (a.scheduledDate != null ? a.scheduledDate! : null);
      final db =
          b.scheduledDateTime ??
          (b.scheduledDate != null ? b.scheduledDate! : null);
      if (da == null && db == null) return 0;
      if (da == null) return s.emptyLast ? 1 : -1;
      if (db == null) return s.emptyLast ? -1 : 1;
      result = da.compareTo(db);
      break;
    case TaskSortOption.insertionDate:
      result = a.id.compareTo(b.id);
      break;
    case TaskSortOption.estimatedTime:
      result = a.durationMinutes.compareTo(b.durationMinutes);
      if (s.emptyLast && a.durationMinutes == 0) return 1;
      if (s.emptyLast && b.durationMinutes == 0) return -1;
      break;
    case TaskSortOption.timeSpent:
      result = a.timeSpent.compareTo(b.timeSpent);
      if (s.emptyLast && a.timeSpent == 0) return 1;
      if (s.emptyLast && b.timeSpent == 0) return -1;
      break;
    case TaskSortOption.tag:
      final ta = a.tagIds.isNotEmpty ? a.tagIds.first.toString() : '';
      final tb = b.tagIds.isNotEmpty ? b.tagIds.first.toString() : '';
      if (s.emptyLast && ta.isEmpty) return 1;
      if (s.emptyLast && tb.isEmpty) return -1;
      result = ta.compareTo(tb);
      break;
    case TaskSortOption.name:
      result = a.title.compareTo(b.title);
      break;
    case TaskSortOption.project:
      final pa = a.projectId;
      final pb = b.projectId;
      if (s.emptyLast && pa.isEmpty) return 1;
      if (s.emptyLast && pb.isEmpty) return -1;
      result = pa.compareTo(pb);
      break;
    case TaskSortOption.status:
      result = a.status.index.compareTo(b.status.index);
      break;
    case TaskSortOption.repeating:
      final ra = a.isPartOfSeries ? 1 : 0;
      final rb = b.isPartOfSeries ? 1 : 0;
      result = ra.compareTo(rb);
      break;
  }
  return s.ascending ? result : -result;
}

/// Apply all sort criteria in order (first = primary, rest = tiebreakers).
List<Task> _applySortCriteria(List<Task> tasks, List<SortCriterion> criteria) {
  if (criteria.isEmpty) return tasks;
  final copy = List<Task>.from(tasks);
  copy.sort((a, b) {
    for (final s in criteria) {
      final r = _compareBySort(a, b, s);
      if (r != 0) return r;
    }
    return 0;
  });
  return copy;
}

// ── Custom Sort Presets ──────────────────────────────────────────────────────

/// A named custom sort preset that stores a user-defined task ordering.
/// The ordering is a list of task IDs that defines their explicit position.
/// Tasks not in the list are appended at the end in their natural order.
class CustomSortPreset {
  final String id;
  String name;
  List<String> taskOrder; // task IDs in their user-defined sequence
  bool isDefault; // reserved for future built-in presets (currently unused)
  /// Criterion-based sort list (kept for forward compatibility).
  List<SortCriterion> sortCriteria;

  CustomSortPreset({
    required this.id,
    required this.name,
    List<String>? taskOrder,
    this.isDefault = false,
    List<SortCriterion>? sortCriteria,
  })  : taskOrder = taskOrder ?? [],
        sortCriteria = sortCriteria ?? [];

  /// Returns a copy with the given task order.
  CustomSortPreset copyWith({String? name, List<String>? taskOrder}) {
    return CustomSortPreset(
      id: id,
      name: name ?? this.name,
      taskOrder: taskOrder ?? List.from(this.taskOrder),
      isDefault: isDefault,
      sortCriteria: sortCriteria,
    );
  }

  /// Applies this preset ordering to [tasks].
  List<Task> applyTo(List<Task> tasks) {
    if (taskOrder.isEmpty) return tasks;
    final ordered = <Task>[];
    final remaining = List<Task>.from(tasks);
    for (final tid in taskOrder) {
      final idx = remaining.indexWhere((t) => t.id == tid);
      if (idx >= 0) {
        ordered.add(remaining.removeAt(idx));
      }
    }
    // Append any tasks not explicitly in the order list
    ordered.addAll(remaining);
    return ordered;
  }
}

int _gristIdSeq = 0;
void _noop(List<String> _) {}

/// Formats a date for display on task card chips.
/// Shows `dd/MM` when [date] is in the current year, `dd/MM/yyyy` otherwise.
/// Returns 'Today' / 'Tomorrow' for those special cases.
String _fmtDateChip(DateTime date) {
  final now = DateTime.now();
  final today = DateTime(now.year, now.month, now.day);
  final d = DateTime(date.year, date.month, date.day);
  if (d == today) return 'Today';
  if (d == today.add(const Duration(days: 1))) return 'Tomorrow';
  final dd = date.day.toString().padLeft(2, '0');
  final mm = date.month.toString().padLeft(2, '0');
  if (date.year == now.year) return '$dd/$mm';
  return '$dd/$mm/${date.year}';
}

String _gristId() => 'gr${++_gristIdSeq}';

/// Controls how edits made inside the Task Details panel propagate
/// to sibling repeat instances.
enum _RepeatPropagateScope {
  current('Current only', Icons.looks_one_outlined),
  forward('This & future', Icons.arrow_forward_rounded),
  backward('This & past', Icons.arrow_back_rounded),
  all('All instances', Icons.select_all_rounded);

  final String label;
  final IconData icon;
  const _RepeatPropagateScope(this.label, this.icon);
}

class RepeatConfig {
  RepeatPreset preset;
  // Custom fields
  int customEvery; // "every N …"
  RepeatCycle customCycle;
  DateTime customStartDate;
  Set<int> customWeekDays; // 1=Mon … 7=Sun (only for week cycle)
  final bool cleared; // sentinel: user hit "Remove"

  /// The date this repeat segment anchors to.
  /// For the parent task's config: drives the series start (and task's plannedAt/dueDay).
  /// For an instance-level override config: equals that instance's scheduledDate.
  DateTime? anchorDate;

  /// Optional hard end-date for this segment.
  /// When set, no instances are generated beyond this date.
  DateTime? endDate;

  /// How many days into the future to generate instances.
  /// Acts as a rolling horizon unless [endDate] is set (whichever is earlier).
  /// When null, only [endDate] controls the horizon (no days cap).
  int? propagationDays;

  RepeatConfig({
    this.preset = RepeatPreset.everyday,
    this.customEvery = 1,
    this.customCycle = RepeatCycle.day,
    DateTime? customStartDate,
    Set<int>? customWeekDays,
    this.cleared = false,
    this.anchorDate,
    this.endDate,
    this.propagationDays,
  }) : customStartDate = customStartDate ?? DateTime.now(),
       customWeekDays = customWeekDays ?? {DateTime.now().weekday};

  String get label {
    switch (preset) {
      case RepeatPreset.everyday:
        return 'Every day';
      case RepeatPreset.weekdays:
        return 'Mon – Fri';
      case RepeatPreset.everyWeek:
        {
          final days = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'];
          return 'Every ${days[DateTime.now().weekday - 1]}';
        }
      case RepeatPreset.everyMonth:
        {
          final d = DateTime.now().day;
          final suffix = d == 1 || d == 21 || d == 31
              ? 'st'
              : d == 2 || d == 22
              ? 'nd'
              : d == 3 || d == 23
              ? 'rd'
              : 'th';
          return 'Monthly on the $d$suffix';
        }
      case RepeatPreset.everyYear:
        {
          final now = DateTime.now();
          return 'Yearly on ${now.day.toString().padLeft(2, '0')}/${now.month.toString().padLeft(2, '0')}';
        }
      case RepeatPreset.custom:
        {
          final cycleStr = customEvery == 1
              ? customCycle.name
              : '${customCycle.name}s';
          return 'Every $customEvery $cycleStr';
        }
    }
  }
}

class _SubConnectionsPainter extends CustomPainter {
  final List<TaskRelation> relations;
  final Map<String, Offset> taskPositions;

  _SubConnectionsPainter({
    required this.relations,
    required this.taskPositions,
  });

  @override
  void paint(Canvas canvas, Size size) {
    final linePaint = Paint()
      ..color = Colors.orangeAccent.withOpacity(0.8)
      ..strokeWidth = 1.5
      ..style = PaintingStyle.stroke;

    final arrowPaint = Paint()
      ..color = Colors.orangeAccent.withOpacity(0.8)
      ..style = PaintingStyle.fill;

    for (var rel in relations) {
      // Offset by half the width (50) and half the height (12.5) to center the line
      final start =
          (taskPositions[rel.sourceId] ?? const Offset(10, 10)) +
          const Offset(50, 12.5);
      final end =
          (taskPositions[rel.targetId] ?? const Offset(10, 10)) +
          const Offset(50, 12.5);

      final path = Path()
        ..moveTo(start.dx, start.dy)
        ..lineTo(end.dx, end.dy);
      canvas.drawPath(path, linePaint);

      // Draw simple arrowhead at the end
      final double angle = atan2(end.dy - start.dy, end.dx - start.dx);
      final arrowPath = Path();
      arrowPath.moveTo(end.dx, end.dy);
      arrowPath.lineTo(
        end.dx - 8 * cos(angle - pi / 7),
        end.dy - 8 * sin(angle - pi / 7),
      );
      arrowPath.lineTo(
        end.dx - 8 * cos(angle + pi / 7),
        end.dy - 8 * sin(angle + pi / 7),
      );
      arrowPath.close();
      canvas.drawPath(arrowPath, arrowPaint);
    }
  }

  @override
  bool shouldRepaint(covariant _SubConnectionsPainter oldDelegate) => true;
}

enum LogicalOperator {
  and("AND", "&"),
  or("OR", "≥1"),
  xor("XOR", "=1");

  final String label;
  final String symbol;
  const LogicalOperator(this.label, this.symbol);
}

extension LogicalOperatorExtension on LogicalOperator {}

// ─── Flat token types for independent criteria / operator reordering ──────────
// The GROUP panel flattens each GroupContainer's criteriaItems into a list of
// _GcToken values — one per criterion and one per operator — so that every
// element can be dragged independently via ReorderableListView.

abstract class _GcToken {
  String get tokenKey;
}

/// Wraps a [ContainerCriteriaItem] (a criterion chip or a paren).
class _GcCriterionToken extends _GcToken {
  final ContainerCriteriaItem item;
  _GcCriterionToken(this.item);
  @override
  String get tokenKey => item.id;
}

/// Represents a standalone logical operator that sits between two criteria.
class _GcOperatorToken extends _GcToken {
  final String id; // stable key, e.g. '${precedingItemId}_op'
  LogicalOperator op;
  _GcOperatorToken({required this.id, required this.op});
  @override
  String get tokenKey => id;
}
