  /// GlobalKey so the tab bar can trigger sync on the active board.
  final GlobalKey<_BoardViewState> _boardViewKey = GlobalKey<_BoardViewState>();

  /// Each board: { 'id', 'title', 'type', 'projectId',
  ///   'trelloApiKey', 'trelloToken', 'trelloBoardId' }
  List<Map<String, dynamic>> _savedBoards = [];
  String _currentBoardId = '';

  // Canvas background colors
  Map<String, Color> _canvasColors = {};
  Color _currentCanvasBackgroundColor = const Color(0xFF121212);

  // Category Group data
  String _currentCategoriesGroupName = "";
  // Category groups whose names end with ' - Subcanvas' are auto-generated and
  // must not appear in the general group switcher.
  final Set<String> _subcanvasGroupNames = {};
  Map<String, Map<String, dynamic>> _categoriesGroups = {};

  bool _showWorkspaceAppearance = false;
  bool _showDataSourceOptions = false;
  // Settings group collapsibles
  bool _settingsGeneralExpanded = true;
  bool _settingsDateTimeExpanded = true;
  bool _settingsTasksExpanded = false;
  bool _taskStagingSubExpanded = false;
  int _repeatPropagationDays = 60; // Settings > Tasks: repeat lookahead
  // Task Staging blocks (work/rest sequence)
  List<_StagingBlock> _stagingBlocks = [
    _StagingBlock(type: _StagingType.work, minutes: 25),
    _StagingBlock(type: _StagingType.rest, minutes: 5),
