  // Users can add named custom presets per page.
  // _customSortPresets[pageKey] = list of presets for that page.
  final Map<String, List<CustomSortPreset>> _customSortPresets = {};
  // _activeCustomPresetId[pageKey] = id of the currently active preset,
  // or null when "Default" (criterion-based sort via _defaultSortCriteria /
  // _sortCriteria) is active.
  final Map<String, String?> _activeCustomPresetId = {};
