  // ── Default preset sort criteria (Insertion Date asc by default) ─────────
  // Shared across pages; represents the sort applied when activePreset == null.
  final List<SortCriterion> _defaultSortCriteria = [];

  /// Returns the preset list for [pageKey] (starts empty — no built-in preset).
  List<CustomSortPreset> _presetsForPage(String pageKey) {
    return _customSortPresets.putIfAbsent(pageKey, () => []);
  }

  /// Returns the active preset for [pageKey], or null.
  CustomSortPreset? _activePresetFor(String pageKey) {
    final id = _activeCustomPresetId[pageKey];
    if (id == null) return null;
    final presets = _presetsForPage(pageKey);
    try {
      return presets.firstWhere((p) => p.id == id);
    } catch (_) {
      return null;
    }
  }

  /// Activates a preset by id for [pageKey]. Pass null to deactivate.
  void _activatePreset(String pageKey, String? presetId) {
    setState(() {
      _activeCustomPresetId[pageKey] = presetId;
      // When activating a custom preset, clear criterion-based sort
      if (presetId != null) _sortCriteria.clear();
    });
  }

  /// Updates the task order stored in [presetId] for [pageKey].
  void _updatePresetOrder(String pageKey, String presetId, List<String> order) {
    final presets = _presetsForPage(pageKey);
    final idx = presets.indexWhere((p) => p.id == presetId);
    if (idx >= 0) {
      presets[idx] = presets[idx].copyWith(taskOrder: order);
    }
  }

