  Widget _buildBezierHandle(TaskRelation rel, int index) {
    final worldPos = rel.handles[index];
    final screenPos = (worldPos * _scale) + _canvasOffset;

    return Positioned(
      left: screenPos.dx - (6 * _scale),
      top: screenPos.dy - (6 * _scale),
      child: MouseRegion(
        cursor: SystemMouseCursors.allScroll,
        child: GestureDetector(
          onPanUpdate: (details) {
            setState(() {
              rel.handles[index] += details.delta / _scale;
            });
          },
          onSecondaryTap: () {
            setState(() {
              rel.handles.removeAt(index);
            });
          },
          child: Container(
            width: 12 * _scale,
            height: 12 * _scale,
            decoration: BoxDecoration(
              color: Colors.white,
              shape: BoxShape.circle,
              border: Border.all(color: rel.color, width: 2 * _scale),
              boxShadow: [
                BoxShadow(
                  color: Colors.black26,
                  blurRadius: 4 * _scale,
                  spreadRadius: 1 * _scale,
                ),
              ],
            ),
          ),
        ),
      ),
    );
  }

  // ── ID generator ─────────────────────────────────────────────────────────

  String _generateId() {
    final t = DateTime.now().millisecondsSinceEpoch;
    final r = (t ^ (t >> 16)) & 0xFFFFFF;
    return '${t.toRadixString(16)}${r.toRadixString(16)}';
  }

  // ── File paths ───────────────────────────────────────────────────────────

  // ── Root paths ──────────────────────────────────────────────────────────
  // general.json is the cross-workspace registry.  It lives under
  // $XDG_CONFIG_HOME/chaos_control/ (defaults to ~/.config/chaos_control/) per the
  // XDG Base Directory Specification, so it is independent of any individual
  // workspace's storage location.
  String get _generalFilePath {
    final xdgConfig = Platform.environment['XDG_CONFIG_HOME'] ?? '';
    if (xdgConfig.isNotEmpty) return '$xdgConfig/chaos_control/general.json';
    final home =
        Platform.environment['HOME'] ??
        Platform.environment['USERPROFILE'] ??
        '';
    if (home.isNotEmpty) return '$home/.config/chaos_control/general.json';
    throw StateError(
      'Cannot determine config directory: neither XDG_CONFIG_HOME nor HOME '
      'are set in the environment.',
    );
  }

  // Per-workspace root: always read from the 'basePath' key that every
  // workspace entry carries since the dynamic-path feature was introduced.
  // Entries without a basePath are treated as corrupt/incomplete and are
  // filtered out during _loadGeneral(), so this should never return empty
  // in practice.
  String _wsRoot(String id) {
    final entry = _savedWorkspaces.firstWhere(
      (w) => w['id'] == id,
      orElse: () => <String, String>{},
    );
    final bp = (entry['basePath'] ?? '').trim();
    assert(bp.isNotEmpty, '_wsRoot: workspace $id has no basePath');
    return bp;
  }

  // metadata/ — app-specific config (not portable on its own)
  String _wsMetaDir(String id) => '${_wsRoot(id)}/metadata';
  String _workspaceFilePath(String id) =>
      '${_wsMetaDir(id)}/workspace_$id.json';

  // files/ — portable user content
  String _wsFilesDir(String id) => '${_wsRoot(id)}/files';

  // ── Notes / files paths (workspace-scoped) ────────────────────────────────────
  /// Metadata sidecar — lives in workspace metadata/, indexed from files/ root.
  String get _notesMetaPath => '${_wsMetaDir(_workspaceId)}/notes_meta.json';

  /// Inbox folder: files/Inbox/  (tasks/notes with no project).
  String get _inboxDir => '${_wsFilesDir(_workspaceId)}/Inbox';

  /// Per-project folder root: files/<safe title>/
  /// Falls back to _inboxDir when the project is unknown.
  String _projectDir(String projectId) {
    final proj = _projects[projectId];
    if (proj == null) return _inboxDir;
    final safe = _fsSafe(proj.title);
    return safe.isEmpty ? _inboxDir : '${_wsFilesDir(_workspaceId)}/projects/$safe';
  }

  /// Ensures files/<project>/{tasks,common,workspace}/ exist for every
  /// project + the inbox equivalent. Call after loading a workspace and
  /// after creating or renaming a project.
  Future<void> _syncProjectDirs() async {
    if (_workspaceId.isEmpty) return;
    try {
      for (final sub in ['tasks', 'common', 'workspace']) {
        await Directory('$_inboxDir/$sub').create(recursive: true);
      }
      for (final project in _projects.values) {
        final dir = _projectDir(project.id);
        if (dir == _inboxDir) continue;
        for (final sub in ['tasks', 'common', 'workspace']) {
          await Directory('$dir/$sub').create(recursive: true);
        }
      }
    } catch (e) {
      debugPrint('_syncProjectDirs ERROR: $e');
    }
  }

  /// Scaffolds the initial directory structure for a brand-new workspace.
  /// Called once from [_showCreateWorkspaceDialog] right after the workspace
  /// entry is registered. Does nothing destructive if directories already exist.
  ///
  /// Layout (files/):
  ///   generalized/.types/*.yaml    entity type definitions, created by the user
  ///                                in the entity types designer (none by default)
  ///   generalized/<type>/...       entity instances
  ///   vault/works, vault/personal_memory
  ///   projects/
  Future<void> _scaffoldNewWorkspace(String workspaceName) async {
    if (_workspaceId.isEmpty) return;
    final filesRoot = _wsFilesDir(_workspaceId);
    final metaRoot  = _wsMetaDir(_workspaceId);
    try {
      await Directory('$metaRoot/canvas_layouts').create(recursive: true);
      await Directory('$metaRoot/cache').create(recursive: true);
      await Directory('$filesRoot/projects').create(recursive: true);
      await Directory('$filesRoot/vault/works').create(recursive: true);
      await Directory('$filesRoot/vault/personal_memory').create(recursive: true);
      // No entity type is generated: the user defines them in the designer.
      await Directory('$filesRoot/generalized/.types').create(recursive: true);
      _typeRegistry = EntityTypeRegistry.empty;
    } catch (e) {
      debugPrint('_scaffoldNewWorkspace ERROR: $e');
    }
  }

  /// Creates an instance of the entity type [typeId] named [name], applying
  /// the type's file pattern. [parentDir] defaults to the type's root folder;
  /// pass `<instance>/<slot folder>` to create a nested child instance.
  Future<void> _scaffoldEntity(String typeId, String name, {String? parentDir}) async {
    if (_workspaceId.isEmpty) return;
    final def = _typeRegistry[typeId];
    if (def == null) return;
    try {
      await EntityScaffolder(
        registry: _typeRegistry,
        genRoot: _genRoot,
        workspaceName: _workspaceName.isNotEmpty ? _workspaceName : 'Eu',
      ).create(typeId, name, parentDir: parentDir ?? '$_genRoot/${def.folder}');
      _autoExportEntities(typeId);
    } catch (e) {
      debugPrint('_scaffoldEntity ERROR: $e');
    }
  }

  /// Moves the on-disk project folder from [oldDir] to the project's current
  /// (post-rename) directory, instead of leaving the old folder behind and
  /// letting [_syncProjectDirs] create an empty new one. Pass the directory
  /// path captured *before* the project's title was mutated; pass null when
  /// the title didn't actually change (no-op).
  Future<void> _renameProjectDir(String projectId, String? oldDir) async {
    if (_workspaceId.isEmpty) return;
    try {
      if (oldDir != null) {
        final newDir = _projectDir(projectId);
        if (oldDir != newDir) {
          final oldDirEntity = Directory(oldDir);
          if (await oldDirEntity.exists()) {
            final newDirEntity = Directory(newDir);
            if (!await newDirEntity.exists()) {
              // Simple case: just rename the whole folder in place.
              await oldDirEntity.rename(newDir);
            } else {
              // Destination already exists (rare name collision) — move
              // contents over individually instead of overwriting anything.
              await for (final entity in oldDirEntity.list(recursive: false)) {
                final destPath = '$newDir/${entity.uri.pathSegments.last}';
                final destExists =
                    await File(destPath).exists() ||
                    await Directory(destPath).exists();
                if (!destExists) await entity.rename(destPath);
              }
              try {
                await oldDirEntity.delete(recursive: true);
              } catch (_) {}
            }
          }
        }
      }
    } catch (e) {
      debugPrint('_renameProjectDir ERROR: $e');
    }
    // Make sure the (possibly just-renamed) project directory still has its
    // tasks/common/workspace sub-folders.
    await _syncProjectDirs();
  }

  /// Scans <workspace>/files/ and imports any folder that does not yet
  /// correspond to an existing project.  Reserved names (inbox, metadata,
  /// hidden dot-folders) are skipped.
  ///
  /// For each new folder found a Project is created with a stable ID derived
  /// from the folder name so repeated calls are idempotent.  The project is
  /// appended to [_projectOrder] and its subdirectories
  /// (tasks / common / workspace) are created by the subsequent
  /// [_syncProjectDirs] call.
  ///
  /// Always call [_syncProjectDirs] right after this method to ensure the
  /// sub-folder structure is consistent.
  Future<void> _syncProjectsFromFilesystem() async {
    if (_workspaceId.isEmpty) return;
    // Projects now live under files/projects/ — scan that subdirectory.
    final filesRoot = Directory('${_wsFilesDir(_workspaceId)}/projects');
    if (!await filesRoot.exists()) return;

    // Build a set of folder names that are already represented by a project
    // so we can skip them efficiently (case-insensitive, fs-safe comparison).
    final existingFolderNames = _projects.values
        .map((p) => _fsSafe(p.title).toLowerCase())
        .toSet();

    bool changed = false;

    try {
      await for (final entity in filesRoot.list()) {
        if (entity is! Directory) continue;

        final folderName = entity.path.split(Platform.pathSeparator).last;

        // Skip hidden folders (dot-prefix).
        if (folderName.startsWith('.')) continue;

        // Skip if a project already owns this folder name.
        if (existingFolderNames.contains(folderName.toLowerCase())) continue;

        // Derive a stable ID from the folder name so re-runs are idempotent.
        final stableId =
            'proj_fs_${folderName.toLowerCase().replaceAll(RegExp(r'[^a-z0-9]'), '_')}';

        // Guard against duplicate IDs (shouldn't happen but be safe).
        if (_projects.containsKey(stableId)) continue;

        final project = Project(
          id: stableId,
          title: folderName,
          createdAt: DateTime.now(),
        );
        _projects[stableId] = project;
        if (!_projectOrder.contains(stableId)) {
          _projectOrder.add(stableId);
        }
        existingFolderNames.add(folderName.toLowerCase());
        changed = true;
        debugPrint('_syncProjectsFromFilesystem: imported project "$folderName" ($stableId)');
      }
    } catch (e) {
      debugPrint('_syncProjectsFromFilesystem ERROR: $e');
    }

    if (changed) {
      // Persist the new projects immediately so they survive a restart.
      await _saveWorkspace();
    }
  }

  // ── Spec §3: filesystem-safe name helper ────────────────────────────────
  static String _fsSafe(String s) => s
      .replaceAll(RegExp(r'[<>:"/\\|?*\x00-\x1F]'), '_')
      .trim()
      .replaceAll(RegExp(r'\s+'), ' ');

  // Sanitizes a project title for use as the project note's .md filename.
  // On top of the base filesystem-safe rules, strips markdown-special
  // characters (^ # [ ] |) that would otherwise look odd in a filename,
  // replacing each with '_'.
  static String _projectNoteFileBase(String title) =>
      _fsSafe(title).replaceAll(RegExp(r'[\^#\[\]|]'), '_');

  // ── Spec: file path for a note under the new per-project structure ────────────────
  // • project note  → files/<proj>/<proj title, sanitized>.md
  // • task note     → files/<proj>/tasks/<Task - Project (date)>.md
  // • common note   → files/<proj>/common/<title>.md
  //   where <proj> = _projectDir(projId) or _inboxDir when no project.
  // For common notes the project is encoded as folderId = 'proj:<projId>'.
  String _noteFilePath(Note n) {
    final titleSafe = _fsSafe(n.title);

    switch (n.type) {
      // ── Project note ────────────────────────────────────────────
      case NoteType.project:
        final pDir = n.linkedProjectId != null &&
                _projects.containsKey(n.linkedProjectId)
            ? _projectDir(n.linkedProjectId!)
            : _inboxDir;
        final fileBase = _projectNoteFileBase(n.title);
        return '$pDir/${fileBase.isEmpty ? 'untitled' : fileBase}.md';

      // ── Task note ─────────────────────────────────────────────────
      case NoteType.task:
        if (n.linkedTaskId != null) {
          final task = _allTasks.firstWhere(
            (t) => t.id == n.linkedTaskId,
            orElse: () => Task(
              id: '',
              title: n.title,
              isDone: false,
              projectId: '',
              subTaskIds: const [],
              timeSpent: 0,
              attachments: const [],
              tagIds: const [],
            ),
          );
          final projId = task.projectId;
          final base = projId.isNotEmpty && _projects.containsKey(projId)
              ? _projectDir(projId)
              : _inboxDir;
          final projName = projId.isNotEmpty
              ? (_projects[projId]?.title ?? 'Inbox')
              : 'Inbox';
          final dt = task.scheduledDateTime;
          final dateStr = dt != null
              ? '${dt.year.toString().padLeft(4, '0')}-'
                    '${dt.month.toString().padLeft(2, '0')}-'
                    '${dt.day.toString().padLeft(2, '0')}'
              : (task.scheduledDate != null
                    ? '${task.scheduledDate!.year.toString().padLeft(4, '0')}-'
                          '${task.scheduledDate!.month.toString().padLeft(2, '0')}-'
                          '${task.scheduledDate!.day.toString().padLeft(2, '0')}'
                    : null);
          final timeStr = dt != null
              ? '${dt.hour.toString().padLeft(2, '0')}-'
                    '${dt.minute.toString().padLeft(2, '0')}'
              : null;
          final datePart = dateStr != null
              ? (timeStr != null ? '$dateStr - $timeStr' : dateStr)
              : null;
          final suffix = datePart != null ? ' ($datePart)' : '';
          final taskSafe = '${_fsSafe(n.title)} - ${_fsSafe(projName)}$suffix';
          return '$base/tasks/$taskSafe.md';
        }
        return '$_inboxDir/tasks/$titleSafe.md';

      // ── Common note ────────────────────────────────────────────
      case NoteType.common:
      default:
        // folderId 'proj:<projId>' -> belongs to that project's common/ subdir.
        if (n.folderId?.startsWith('proj:') == true) {
          final projId = n.folderId!.substring(5);
          if (_projects.containsKey(projId)) {
            return '${_projectDir(projId)}/common/$titleSafe.md';
          }
        }
        return '$_inboxDir/common/$titleSafe.md';
    }
  }

  // ── Task .md persistence (frontmatter-based) ──────────────────────────────
  //
  // Each task is stored as a Markdown file whose YAML front-matter (a JSON
  // block between --- fences) holds all task properties.  The file body is
  // the task's free-text notes.  This makes the per-task .md the single
  // source of truth, so a workspace-JSON corruption can only lose settings,
  // never task data.
  //
  // Relation to the notes system
  // ─────────────────────────────
  // Task notes have always been written to
  //   files/<proj>/tasks/<title> - <proj> (<date>).md
  // That is the same file managed here.  _saveTaskMd replaces _saveNote for
  // NoteType.task — it writes frontmatter first, then the body — so the two
  // systems share one file without stepping on each other.

  /// Canonical .md path for [task].
  /// Identical logic to the NoteType.task branch of [_noteFilePath] but
  /// operates directly on a Task, avoiding the dummy-Note indirection.
  String _taskMdPath(Task task) {
    final projId = task.projectId;
    // Prefer the canonical project directory when the project is known.
    // If the project is temporarily absent from _projects (e.g. during an
    // async load race or after a workspace sync), fall back to Inbox so the
    // file is at least written somewhere recoverable rather than crashing.
    final base = projId.isNotEmpty &&
            projId != 'INBOX_PROJECT' &&
            _projects.containsKey(projId)
        ? _projectDir(projId)
        : _inboxDir;
    final projName = projId.isNotEmpty
        ? (_projects[projId]?.title ?? 'Inbox')
        : 'Inbox';
    final dt = task.scheduledDateTime;
    final dateStr = dt != null
        ? '${dt.year.toString().padLeft(4, '0')}-'
              '${dt.month.toString().padLeft(2, '0')}-'
              '${dt.day.toString().padLeft(2, '0')}'
        : (task.scheduledDate != null
              ? '${task.scheduledDate!.year.toString().padLeft(4, '0')}-'
                    '${task.scheduledDate!.month.toString().padLeft(2, '0')}-'
                    '${task.scheduledDate!.day.toString().padLeft(2, '0')}'
              : null);
    final timeStr = dt != null
        ? '${dt.hour.toString().padLeft(2, '0')}-'
              '${dt.minute.toString().padLeft(2, '0')}'
        : null;
    final datePart = dateStr != null
        ? (timeStr != null ? '$dateStr - $timeStr' : dateStr)
        : null;
    final suffix = datePart != null ? ' ($datePart)' : '';
    final taskSafe = '${_fsSafe(task.title)} - ${_fsSafe(projName)}$suffix';
    return '$base/tasks/$taskSafe.md';
  }

  /// Serialises a [RepeatConfig] to a plain Map suitable for JSON encoding.
  /// RepeatConfig has no toJson() — this is its first serialisation path.
  static Map<String, dynamic> _repeatConfigToMap(RepeatConfig cfg) {
    final m = <String, dynamic>{
      'preset': cfg.preset.name,
      'customEvery': cfg.customEvery,
      'customCycle': cfg.customCycle.name,
      'customStartDate': cfg.customStartDate.toIso8601String(),
      'customWeekDays': (cfg.customWeekDays.toList()..sort()),
      'cleared': cfg.cleared,
    };
    if (cfg.anchorDate != null) m['anchorDate'] = cfg.anchorDate!.toIso8601String();
    if (cfg.endDate != null) m['endDate'] = cfg.endDate!.toIso8601String();
    if (cfg.propagationDays != null) m['propagationDays'] = cfg.propagationDays;
    return m;
  }

  /// Reconstructs a [RepeatConfig] from a frontmatter map.
  static RepeatConfig _repeatConfigFromMap(Map<String, dynamic> m) {
    RepeatPreset preset = RepeatPreset.everyday;
    try {
      preset = RepeatPreset.values.byName(m['preset'] as String? ?? '');
    } catch (_) {}
    RepeatCycle cycle = RepeatCycle.day;
    try {
      cycle = RepeatCycle.values.byName(m['customCycle'] as String? ?? '');
    } catch (_) {}
    return RepeatConfig(
      preset: preset,
      customEvery: m['customEvery'] as int? ?? 1,
      customCycle: cycle,
      customStartDate:
          DateTime.tryParse(m['customStartDate'] as String? ?? '') ??
          DateTime.now(),
      customWeekDays: (m['customWeekDays'] as List<dynamic>?)
              ?.map((e) => e as int)
              .toSet() ??
          {DateTime.now().weekday},
      cleared: m['cleared'] as bool? ?? false,
      anchorDate: m['anchorDate'] != null
          ? DateTime.tryParse(m['anchorDate'] as String)
          : null,
      endDate: m['endDate'] != null
          ? DateTime.tryParse(m['endDate'] as String)
          : null,
      propagationDays: m['propagationDays'] as int?,
    );
  }

  // ── YAML helpers ──────────────────────────────────────────────────────────

  /// Serialises a scalar to its YAML representation.
  /// Strings are always double-quoted to avoid YAML ambiguity.
  static String _toYamlScalar(dynamic v) {
    if (v == null) return 'null';
    if (v is bool) return v.toString();
    if (v is int) return v.toString();
    if (v is double) {
      // Avoid scientific notation (e.g. 1.0e+20) — write full decimal.
      return v.toStringAsFixed(v.truncateToDouble() == v ? 1 : 10)
          .replaceAll(RegExp(r'0+$'), '')
          .replaceAll(RegExp(r'\.$'), '.0');
    }
    // String — always double-quoted, escaping backslash, quote, and newlines.
    final esc = v
        .toString()
        .replaceAll(r'\', r'\\')
        .replaceAll('"', r'\"')
        .replaceAll('\r', r'\r')
        .replaceAll('\n', r'\n');
    return '"$esc"';
  }

  /// Recursively serialises a [Map] to a YAML block-mapping string.
  /// Nested maps are indented by [indent] extra spaces.
  /// Lists are rendered as inline flow sequences.
  static String _serializeYamlMap(Map<String, dynamic> map, {int indent = 0}) {
    final sb = StringBuffer();
    final pad = ' ' * indent;
    for (final entry in map.entries) {
      final key = entry.key;
      final value = entry.value;
      if (value is Map) {
        sb.writeln('$pad$key:');
        sb.write(
          _serializeYamlMap(
            Map<String, dynamic>.from(value as Map),
            indent: indent + 2,
          ),
        );
      } else if (value is List) {
        final items = value.map(_toYamlScalar).join(', ');
        sb.writeln('$pad$key: [$items]');
      } else {
        sb.writeln('$pad$key: ${_toYamlScalar(value)}');
      }
    }
    return sb.toString();
  }

  /// Deep-converts a [YamlMap]/[YamlList] tree returned by [loadYaml] into
  /// plain Dart [Map<String, dynamic>] / [List<dynamic>] so that the normal
  /// `as Map<String, dynamic>` / `as List` casts work as expected.
  static dynamic _yamlToDart(dynamic v) {
    if (v is YamlMap) {
      return <String, dynamic>{
        for (final e in v.entries) e.key.toString(): _yamlToDart(e.value),
      };
    }
    if (v is YamlList) {
      return [for (final e in v) _yamlToDart(e)];
    }
    return v;
  }

  /// Writes [task] to its canonical .md file.
  ///
  /// Format:
  ///   ---
  ///   key: value   # YAML front-matter
  ///   ---
  ///
  ///   <notes body>
  ///
  /// When the task was previously stored under a different path (e.g. its
  /// title or date changed), pass the old path via [oldPath] so the stale
  /// file is removed.
  Future<void> _saveTaskMd(Task task, {String? oldPath}) async {
    if (_workspaceId.isEmpty) return;
    try {
      final path = _taskMdPath(task);
      final file = File(path);
      await file.parent.create(recursive: true);

      // Move stale file when the canonical path changed.
      if (oldPath != null && oldPath != path) {
        final old = File(oldPath);
        if (await old.exists()) await old.rename(path);
      }

      // Build front-matter map — mirrors Task.toJson() plus UI state and
      // RepeatConfig, which Task.toJson() does not currently serialise.
      final front = <String, dynamic>{
        'id': task.id,
        'title': task.title,
        'isDone': task.isDone,
        'status': task.status.name,
        'projectId': task.projectId,
        'subTaskIds': task.subTaskIds,
        'timeSpent': task.timeSpent,
        if (task.dueDay != null) 'dueDay': task.dueDay,
        if (task.plannedAt != null && task.plannedAt! > 0)
          'plannedAt': task.plannedAt,
        'durationMinutes': task.durationMinutes,
        'attachments': task.attachments,
        if (task.repeatCfgId != null) 'repeatCfgId': task.repeatCfgId,
        'tagIds': task.tagIds,
        if (task.repeatParentId != null)
          'repeatParentId': task.repeatParentId,
        if (task.seriesId != null) 'seriesId': task.seriesId,
        // RepeatConfig — first time this is persisted per-task.
        if (task.repeatConfig != null)
          'repeatConfig': _repeatConfigToMap(task.repeatConfig!),
        // UI state (canvas card dimensions / visibility).
        'isExpanded': task.isExpanded,
        'cardWidth': task.cardWidth,
        'cardHeight': task.cardHeight,
        if (task.visibleProperties.isNotEmpty)
          'visibleProperties': task.visibleProperties.toList(),
        if (task.propertyHeights.isNotEmpty)
          'propertyHeights': task.propertyHeights,
        'titleWrap': task.titleWrap,
        if (task.cardManualHeight != null)
          'cardManualHeight': task.cardManualHeight,
      };

      final yamlStr = _serializeYamlMap(front);
      final body = task.notes ?? '';
      await file.writeAsString('---\n$yamlStr---\n\n$body');
    } catch (e) {
      debugPrint('_saveTaskMd ERROR (${task.id}): $e');
    }
  }

  /// Parses a task .md file and reconstructs a [Task].
  ///
  /// [path] is used only for error messages.
  /// [content] is the full file content (caller is responsible for reading).
  /// Returns null if the content is missing, has no front-matter, or is
  /// malformed — callers should skip/log and continue.
  static Task? _loadTaskFromMd(String path, String content) {
    try {
      if (!content.startsWith('---')) return null;

      // Locate the closing fence.  The opening fence is at index 0 so we
      // search from index 3 onward to skip it.
      final closingFence = content.indexOf('\n---', 3);
      if (closingFence == -1) return null;

      final frontRaw = content.substring(3, closingFence).trim();
      // Body starts after the closing '\n---\n' (or '\n---' at EOF).
      final bodyStart = closingFence + 4; // skip '\n---\n'
      final rawBody = bodyStart < content.length
          ? content.substring(bodyStart).trimLeft()
          : '';
      // If the body itself opens with '---' it is a corrupted double-write
      // (a previous frontmatter dump was appended as notes). Discard it so
      // the garbage is stripped on the next _saveTaskMd call.
      final body = rawBody.startsWith('---') ? '' : rawBody;

      final m = _yamlToDart(loadYaml(frontRaw)) as Map<String, dynamic>;

      final isDone = m['isDone'] as bool? ?? false;
      TaskStatus status;
      try {
        status = TaskStatus.values.byName(m['status'] as String? ?? '');
      } catch (_) {
        status = isDone ? TaskStatus.done : TaskStatus.none;
      }

      RepeatConfig? repeatConfig;
      if (m['repeatConfig'] is Map) {
        repeatConfig = _repeatConfigFromMap(
          Map<String, dynamic>.from(m['repeatConfig'] as Map),
        );
      }

      final task = Task(
        id: m['id'] as String,
        title: m['title'] as String,
        isDone: isDone,
        status: status,
        projectId: m['projectId'] as String? ?? 'INBOX_PROJECT',
        subTaskIds: m['subTaskIds'] as List<dynamic>? ?? [],
        timeSpent: m['timeSpent'] as int? ?? 0,
        dueDay: m['dueDay'] as String?,
        plannedAt: m['plannedAt'] as int?,
        durationMinutes: m['durationMinutes'] as int? ?? 30,
        attachments: m['attachments'] as List<dynamic>? ?? [],
        repeatCfgId: m['repeatCfgId'] as String?,
        tagIds: m['tagIds'] as List<dynamic>? ?? [],
        notes: body.isEmpty ? null : body,
        repeatParentId: m['repeatParentId'] as String?,
        seriesId: m['seriesId'] as String? ??
            (m['repeatParentId'] as String?) ??
            (m['repeatCfgId'] != null ? m['id'] as String? : null),
        // UI state
        isExpanded: m['isExpanded'] as bool? ?? false,
        cardWidth: (m['cardWidth'] as num?)?.toDouble() ?? 250.0,
        cardHeight: (m['cardHeight'] as num?)?.toDouble() ?? 250.0,
        visibleProperties: m['visibleProperties'] != null
            ? Set<String>.from(m['visibleProperties'] as List)
            : {},
        propertyHeights: m['propertyHeights'] != null
            ? Map<String, double>.from(
                (m['propertyHeights'] as Map).map(
                  (k, v) => MapEntry(k.toString(), (v as num).toDouble()),
                ),
              )
            : {},
        titleWrap: m['titleWrap'] as bool? ?? false,
        cardManualHeight: (m['cardManualHeight'] as num?)?.toDouble(),
      )..repeatConfig = repeatConfig;

      return task;
    } catch (e) {
      debugPrint('_loadTaskFromMd ERROR ($path): $e');
      return null;
    }
  }

  // ── general.json: workspace registry + global preferences ─────────────────

  Future<void> _saveGeneral() async {
    try {
      final data = {
        // Registry: list of {id, name, metaPath?} — metaPath is optional SP import path
        'workspaces': _savedWorkspaces,
        'lastWorkspaceId': _lastWorkspaceId,
        // Global preferences
        'prefAllowDuplicateConnections': _prefAllowDuplicateConnections,
        'prefShowWorkspacePaths': _prefShowWorkspacePaths,
        'prefDefaultOperator': _prefDefaultOperator.name,
        'prefDefaultArrowSize': _prefDefaultArrowSize,
        'prefShowIdOnCards': _prefShowIdOnCards,
        'prefShowProjectName': _prefShowProjectName,
        'prefShowDueDateOnCards': _prefShowDueDateOnCards,
        'prefShowCountdownOnCards': _prefShowCountdownOnCards,
        'prefShowTimeOnCards': _prefShowTimeOnCards,
        'prefStandardVisibleInfos': _prefStandardVisibleInfos.toList(),
        'prefShowDateOnListedTasks': _prefShowDateOnListedTasks,
      };
      final gFile = File(_generalFilePath);
      await gFile.parent.create(recursive: true);
      await gFile.writeAsString(jsonEncode(data));
    } catch (e) {
      debugPrint('SAVE GENERAL ERROR: $e');
    }
  }

  Future<void> _loadGeneral() async {
    try {
      File file = File(_generalFilePath);

      if (!await file.exists()) return;
      final data =
          jsonDecode(await file.readAsString()) as Map<String, dynamic>;

      // Filter the registry: only keep workspaces whose workspace_{id}.json
      // still exists on disk.  We resolve the root directly from the entry's
      // 'basePath' here (we can't use _wsRoot() yet because _savedWorkspaces
      // hasn't been populated at this point in the boot sequence).
      // Entries that carry no basePath are silently skipped — they predate
      // the dynamic-path feature and their on-disk location is unknown.
      List<Map<String, String>> validWorkspaces = [];
      if (data['workspaces'] != null) {
        for (final e in data['workspaces'] as List) {
          final entry = Map<String, String>.from(e);
          final id = entry['id'] ?? '';
          if (id.isEmpty) continue;
          final bp = (entry['basePath'] ?? '').trim();
          if (bp.isEmpty) continue; // no known location — skip
          final wsFile = '$bp/metadata/workspace_$id.json';
          if (await File(wsFile).exists()) {
            validWorkspaces.add(entry);
          }
        }
      }

      setState(() {
        _savedWorkspaces = validWorkspaces;
        // Remember the last-opened workspace so startup can auto-load it
        _lastWorkspaceId = (data['lastWorkspaceId'] as String? ?? '').trim();
        // Preferences
        _prefAllowDuplicateConnections =
            data['prefAllowDuplicateConnections'] ?? false;
        _prefShowWorkspacePaths = data['prefShowWorkspacePaths'] ?? false;
        if (data['prefDefaultOperator'] != null) {
          try {
            _prefDefaultOperator = LogicalOperator.values.byName(
              data['prefDefaultOperator'],
            );
          } catch (_) {}
        }
        _prefDefaultArrowSize =
            (data['prefDefaultArrowSize'] as num?)?.toDouble() ?? 10.0;
        _prefShowIdOnCards = data['prefShowIdOnCards'] ?? true;
        _prefShowProjectName = data['prefShowProjectName'] ?? true;
        _prefShowDueDateOnCards = data['prefShowDueDateOnCards'] ?? false;
        _prefShowCountdownOnCards = data['prefShowCountdownOnCards'] ?? false;
        _prefShowTimeOnCards = data['prefShowTimeOnCards'] ?? false;
        if (data['prefStandardVisibleInfos'] != null) {
          _prefStandardVisibleInfos = Set<String>.from(
            data['prefStandardVisibleInfos'],
          );
        }
        _prefShowDateOnListedTasks = data['prefShowDateOnListedTasks'] ?? false;
      });
    } catch (e) {
      debugPrint('LOAD GENERAL ERROR: $e');
    }
  }

  // ── _savePreferences: delegate to _saveGeneral ────────────────────────────
  Future<void> _savePreferences() => _saveGeneral();

  // ── workspace_{id}.json ───────────────────────────────────────────────────

  Map<String, dynamic> _serialiseCanvas(Map<String, dynamic> snap) {
    final tasks = (snap['canvasTasks'] as List<Task>? ?? []);
    final positions = (snap['taskPositions'] as Map<String, Offset>? ?? {});
    final junctions = (snap['junctions'] as List<JunctionNode>? ?? []);
    final conditionals = (snap['conditionals'] as List<ConditionalNode>? ?? []);
    final relations = (snap['taskRelations'] as Set<TaskRelation>? ?? {});
    final scale = snap['scale'] ?? 1.0;
    final offset = snap['canvasOffset'] as Offset? ?? Offset.zero;
    final bgColor = (snap['bgColor'] as Color?)?.value ?? 0xFF121212;

    return {
      'canvasTasks': tasks.map((t) => t.id).toList(),
      'taskPositions': positions.map(
        (k, v) => MapEntry(k, {'dx': v.dx, 'dy': v.dy}),
      ),
      'junctions': junctions
          .map(
            (j) => {
              'id': j.id,
              'dx': j.position.dx,
              'dy': j.position.dy,
              'operatorType': j.operatorType.name,
            },
          )
          .toList(),
      'conditionals': conditionals
          .map(
            (c) => {
              'id': c.id,
              'dx': c.position.dx,
              'dy': c.position.dy,
              'width': c.width,
              'height': c.height,
              'label': c.label,
            },
          )
          .toList(),
      'taskRelations': relations
          .map(
            (r) => {
              'sourceId': r.sourceId,
              'targetId': r.targetId,
              'sdx': r.sourceLocalPos.dx,
              'sdy': r.sourceLocalPos.dy,
              'tdx': r.targetLocalPos.dx,
              'tdy': r.targetLocalPos.dy,
              'arrowSize': r.arrowSize,
              'thickness': r.thickness,
              'color': r.color.value,
              'handles': r.handles
                  .map((h) => {'dx': h.dx, 'dy': h.dy})
                  .toList(),
            },
          )
          .toList(),
      'scale': scale,
      'canvasOffset': {'dx': offset.dx, 'dy': offset.dy},
      'bgColor': bgColor,
      'taskUiStates': Map.fromEntries(
        tasks.map(
          (t) => MapEntry(t.id, {
            'isExpanded': t.isExpanded,
            'cardWidth': t.cardWidth,
            'cardHeight': t.cardHeight,
            'isDone': t.isDone,
            'status': t.status.name,
            'visibleProperties': t.visibleProperties.toList(),
            'propertyHeights': t.propertyHeights,
            'titleWrap': t.titleWrap,
            if (t.cardManualHeight != null)
              'cardManualHeight': t.cardManualHeight,
          }),
        ),
      ),
    };
  }

  Future<void> _saveWorkspace() async {
    if (_workspaceId.isEmpty) return;
    try {
      // Snapshot the currently-active canvas before serialising
      if (_currentCanvasName.isNotEmpty) {
        _canvasStates[_currentCanvasName] = _snapshotCurrentCanvas();
        _canvasColors[_currentCanvasName] = _currentCanvasBackgroundColor;
      }

      final data = {
        // ── Identity ────────────────────────────────────────────────────
        'id': _workspaceId,
        'workspaceName': _workspaceName,
        'workspaceImagePath': _workspaceImagePath,
        // ── Multi-canvas ─────────────────────────────────────────────────
        'savedCanvases': _savedCanvases,
        'savedBoards': _savedBoards,
        'currentBoardId': _currentBoardId,
        'openCanvases': _openCanvases.toList(),
        'currentCanvasName': _currentCanvasName,
        'canvasColors': _canvasColors.map((k, v) => MapEntry(k, v.value)),
        'canvasStates': _canvasStates.map(
          (k, v) => MapEntry(k, _serialiseCanvas(v)),
        ),

        // ── Category groups ──────────────────────────────────────────────
        'categoriesGroups': _categoriesGroups.map(
          (groupName, g) => MapEntry(groupName, {
            'projectColors': (g['projectColors'] as Map? ?? {}).map(
              (k, v) => MapEntry(k.toString(), v),
            ),
            'recentColors': g['recentColors'] ?? [],
            'categoryMappings': g['categoryMappings'] ?? {},
            'sidebarSectionOrder': g['sidebarSectionOrder'] ?? [],
            'favoriteProjectIds': g['favoriteProjectIds'] ?? [],
            'sectionExpandedStates': g['sectionExpandedStates'] ?? {},
            'sectionSortAsc': g['sectionSortAsc'] ?? {},
          }),
        ),
        'currentCategoriesGroupName': _currentCategoriesGroupName,

        // ── Sidebar state ────────────────────────────────────────────────
        'projectColors': _projectColors.map((k, v) => MapEntry(k, v.value)),
        'viewColors': _viewColors.map((k, v) => MapEntry(k, v.value)),
        'projectIcons': _projectIcons,
        'psycheColors': _psycheColors.map((k, v) => MapEntry(k, v.value)),
        'psycheIcons': _psycheIcons,
        'projectBacklogEnabled': _projectBacklogEnabled,
        'projectHiddenFromMenu': _projectHiddenFromMenu,
        'projectFolders': _projectFolders.map(
          (k, v) => MapEntry(k, v.toList()),
        ),
        'tagFolders': _tagFolders.map((k, v) => MapEntry(k, v.toList())),
        'projectFolderOrder': _projectFolderOrder,
        'tagFolderOrder': _tagFolderOrder,
        'tagOrder': _tagOrder,
        'noteProjectOrder': _noteProjectOrder,
        'noteTaskOrder': _noteTaskOrder,
        'hiddenNoteProjects': _hiddenNoteProjects.toList(),
        'hiddenNoteTasks': _hiddenNoteTasks.toList(),
        'hiddenTags': _hiddenTags.toList(),
        'tagColors': _tagColors.map((k, v) => MapEntry(k, v.value)),
        'tagIcons': _tagIcons,
        'showHiddenProjects': _showHiddenProjects,
        'ganttEnabled': _ganttEnabled,
        'ganttProportional': _ganttProportional,
        'ganttDayWidth': _ganttDayWidth,
        'ganttForceTimeAlign': _ganttForceTimeAlign,
        'ganttSnapMinutes': _ganttSnapMinutes,
        'ganttShowProjectAxis': _ganttShowProjectAxis,
        'ganttWeekdayColors': _ganttWeekdayColors.map((c) => c.value).toList(),
        'ganttColumnWidths': _ganttColumnWidths.map(
          (k, v) => MapEntry(k.toIso8601String(), v),
        ),
        'ganttLaneHeights': _ganttLaneHeights,
        'themeMode': _themeMode,
        'appLanguage': _appLanguage,
        'timeLocale': _timeLocale,
        'timezoneId': _timezoneId,
        'timezoneOffsetMinutes': _timezoneOffsetMinutes,
        'clockDeltaMs': _clockDeltaMs,
        'markParentDoneOnSubtasks': _markParentDoneOnSubtasks,
        'firstDayOfWeek': _firstDayOfWeek,
        'nextDayStartHour': _nextDayStartHour,
        'taskDescTemplate': _taskDescTemplate,
