        'gridColor': _gridColor.value,

        // ── Task index + Projects ────────────────────────────────────────
        // Task properties now live in per-task .md files (_saveTaskMd).
        // The index gives O(1) path lookup (id → relative .md path) without
        // reading every file on startup.  The old 'tasks' JSON array is
        // intentionally omitted; workspaces that still carry it are migrated
        // to the new format by _migrateLegacyTasksToMd on the first load.
        'taskIndex': _taskIndex,
        'projects': _projects.map((k, v) => MapEntry(k, v.toJson())),
        'projectOrder': _projectOrder,

        // ── Notes tab state ──────────────────────────────────────────────
        'openNoteTabs': _openNoteTabs,
        'activeNoteId': _activeNoteId,

        // ── Notes collapsed headers ──────────────────────────────────────
        'notesOrgNotesCollapsed': _notesOrgNotesCollapsed.toList(),
        'notesOrgTasksCollapsed': _notesOrgTasksCollapsed.toList(),

        // ── Sidebar nav collapsed folders ────────────────────────────────
        'collapsedNavProjectFolders': _collapsedNavProjectFolders.toList(),

        // ── Notes sidebar section expanded / folder collapsed state ──────
        'notesSectionTaskExpanded': _notesSectionTaskExpanded,
        'notesSectionProjectExpanded': _notesSectionProjectExpanded,
        'notesSectionCommonExpanded': _notesSectionCommonExpanded,
        'collapsedNoteTaskFolders': _collapsedNoteTaskFolders.toList(),
        'collapsedNoteProjectFolders': _collapsedNoteProjectFolders.toList(),
        'collapsedNoteCommonFolders': _collapsedNoteCommonFolders.toList(),

        // ── Active tab / subtab ──────────────────────────────────────────
        'isTasksView': _isTasksView,
        'isNotesView': _isNotesView,
        'isSettingsView': _isSettingsView,
        'isVisualizerView': _isVisualizerView,
        'tasksNavSection': _tasksNavSection,
        'notesNavSection': _notesNavSection,
        'noteCommonFolderOrder': _noteCommonFolderOrder,

        // ── F/G/S section collapsed states ──────────────────────────────
        'fgsSectionFilterCollapsed': _fgsSectionFilterCollapsed,
        'fgsSectionGroupCollapsed': _fgsSectionGroupCollapsed,
        'fgsSectionSortCollapsed': _fgsSectionSortCollapsed,
        'fgsPlannerFilterCollapsed': _fgsPlannerFilterCollapsed,
        'fgsPlannerSortCollapsed': _fgsPlannerSortCollapsed,
      };

      final wsFile = File(_workspaceFilePath(_workspaceId));
      await wsFile.parent.create(recursive: true);
      await wsFile.writeAsString(jsonEncode(data));
    } catch (e) {
      debugPrint('AUTOSAVE ERROR: $e');
    }
  }

  Map<String, dynamic> _deserialiseCanvas(Map<String, dynamic> snap) {
    final taskIds = snap['canvasTasks'] != null
        ? List<String>.from(snap['canvasTasks'])
        : <String>[];
    final taskUiStates = (snap['taskUiStates'] as Map? ?? {})
        .cast<String, dynamic>();

    final tasks = <Task>[];
    for (final id in taskIds) {
      final task = _allTasks.firstWhere(
        (t) => t.id == id,
        orElse: () => Task(
          id: 'err',
          title: 'err',
          isDone: false,
          projectId: '',
          subTaskIds: [],
          timeSpent: 0,
          attachments: [],
          tagIds: [],
        ),
      );
      if (task.id == 'err') continue;
      if (taskUiStates.containsKey(id)) {
        final s = taskUiStates[id] as Map;
        task.isExpanded = s['isExpanded'] ?? false;
        task.cardWidth = (s['cardWidth'] as num?)?.toDouble() ?? 250.0;
        task.cardHeight = (s['cardHeight'] as num?)?.toDouble() ?? 250.0;
        task.isDone = s['isDone'] ?? task.isDone;
        if (s['status'] != null) {
          try {
            task.status = TaskStatus.values.byName(s['status']);
          } catch (_) {
            task.status = task.isDone ? TaskStatus.done : TaskStatus.none;
          }
        }
        if (s['visibleProperties'] != null) {
          task.visibleProperties = Set<String>.from(s['visibleProperties']);
        }
        if (s['propertyHeights'] != null) {
          task.propertyHeights = Map<String, double>.from(s['propertyHeights']);
        }
        task.titleWrap = s['titleWrap'] ?? false;
        task.cardManualHeight = (s['cardManualHeight'] as num?)?.toDouble();
      }
      tasks.add(task);
    }

    final positions = <String, Offset>{};
    if (snap['taskPositions'] != null) {
      (snap['taskPositions'] as Map).forEach(
        (k, v) => positions[k] = Offset(
          (v['dx'] as num).toDouble(),
          (v['dy'] as num).toDouble(),
        ),
      );
    }

    final junctions = <JunctionNode>[];
    if (snap['junctions'] != null) {
      for (final j in snap['junctions'] as List) {
        LogicalOperator op = LogicalOperator.and;
        if (j['operatorType'] != null) {
          try {
            op = LogicalOperator.values.byName(j['operatorType']);
          } catch (_) {}
        }
        junctions.add(
          JunctionNode(
            id: j['id'],
            position: Offset(
              (j['dx'] as num).toDouble(),
              (j['dy'] as num).toDouble(),
            ),
            operatorType: op,
          ),
        );
      }
    }

    // ── Load ConditionalNodes ─────────────────────────────────────────────────
    final conditionals = <ConditionalNode>[];
    if (snap['conditionals'] != null) {
      for (final c in snap['conditionals'] as List) {
        conditionals.add(
          ConditionalNode(
            id: c['id'],
            position: Offset(
              (c['dx'] as num).toDouble(),
              (c['dy'] as num).toDouble(),
            ),
            width: (c['width'] as num?)?.toDouble() ?? 140,
            height: (c['height'] as num?)?.toDouble() ?? 80,
            label: (c['label'] as String?) ?? '',
          ),
        );
      }
    }

    final relations = <TaskRelation>{};
    if (snap['taskRelations'] != null) {
      for (final r in snap['taskRelations'] as List) {
        final handles = <Offset>[];
        if (r['handles'] != null) {
          for (final h in r['handles'] as List) {
            handles.add(
              Offset((h['dx'] as num).toDouble(), (h['dy'] as num).toDouble()),
            );
          }
        }
        relations.add(
          TaskRelation(
            sourceId: r['sourceId'],
            targetId: r['targetId'],
            sourceLocalPos: Offset(
              (r['sdx'] as num).toDouble(),
              (r['sdy'] as num).toDouble(),
            ),
            targetLocalPos: Offset(
              (r['tdx'] as num).toDouble(),
              (r['tdy'] as num).toDouble(),
            ),
            arrowSize:
                (r['arrowSize'] as num?)?.toDouble() ?? _defaultArrowSize,
            thickness: (r['thickness'] as num?)?.toDouble() ?? 2.0,
            color: r['color'] != null
                ? Color(r['color'] as int)
                : Colors.orangeAccent.withOpacity(0.8),
            handles: handles,
          ),
        );
      }
    }

    return {
      'canvasTasks': tasks,
      'taskPositions': positions,
      'junctions': junctions,
      'conditionals': conditionals,
      'taskRelations': relations,
      'scale': (snap['scale'] as num?)?.toDouble() ?? 1.0,
      'canvasOffset': snap['canvasOffset'] != null
          ? Offset(
              (snap['canvasOffset']['dx'] as num).toDouble(),
              (snap['canvasOffset']['dy'] as num).toDouble(),
            )
          : Offset.zero,
      'bgColor': snap['bgColor'] != null
          ? Color(snap['bgColor'] as int)
          : const Color(0xFF121212),
    };
  }

  /// Opens a workspace. metaPath is optional — when present it points to
  /// a SuperProductivity __meta_ file for data import via the settings panel.
  Future<bool> _loadWorkspaceById(Map<String, String> entry) async {
    final metaPath = entry['metaPath'] ?? '';
    final id = entry['id'] ?? '';
    final name = entry['name'] ?? '';
    if (id.isEmpty) return false;

    // Set active workspace identity and clear all previous workspace state
    // Clear all previous workspace state
    setState(() {
      _workspaceId = id;
      _workspaceName = name;
      _workspaceNameController.text = name;
      _sourceFilePath = metaPath;
      _dataSourceController.text = metaPath;
      _workspaceImagePath = '';
      // Clear canvas state
      _currentCanvasName = '';
      _canvasNameController.text = '';
      _savedCanvases.clear();
      _openCanvases.clear();
      _canvasStates.clear();
      _canvasColors.clear();
      _canvasTasks.clear();
      _taskPositions.clear();
      _junctions.clear();
      _conditionals.clear();
      _selectedConditionalId = null;
      _selectedConditionalIds.clear();
      _taskRelations.clear();
      // Clear category groups
      _currentCategoriesGroupName = '';
      _categoriesGroupNameController.text = '';
      _categoriesGroups.clear();
      // Clear sidebar/projects
      _allTasks.clear();
      _projects.clear();
      _sidebarSectionOrder.clear();
      _favoriteProjectIds.clear();
      _projectColors.clear();
      _categoryMappings.clear();
      _sectionExpandedStates.clear();
      _sectionSortAsc.clear();
      // Clear notes
      _notes.clear();
      _noteFolders.clear();
      _openNoteTabs.clear();
      _notesDetailOpen = false;
      _activeNoteId = null;
      _notesOrgNotesCollapsed.clear();
      _notesOrgTasksCollapsed.clear();
      _collapsedNavProjectFolders.clear();
    });

    // Load workspace config and notes
    await _loadWorkspace();
    await _loadNotes();
    await _syncProjectsFromFilesystem(); // import folders in files/ as projects
    await _syncProjectDirs(); // ensure files/<project>/{tasks,common,workspace}/ exist

    // Persist this as the most-recently opened workspace so the next
    // app launch can restore it automatically.
    _lastWorkspaceId = id;
    await _saveGeneral();

    // Eagerly populate Visualizer filesystem data after every workspace
    // load — ensures works / personal_memory entries are visible even
    // when the app restores directly into Visualizer view on startup.
    await _loadVisualizerChildren();

    return true;
  }

  // ── Task index helpers ────────────────────────────────────────────────────

  /// Rebuilds [_taskIndex] from the current [_allTasks] list.
  ///
  /// Called after any bulk mutation (migration, repeat propagation) so the
  /// in-memory index stays consistent with the loaded task set.
  /// [_saveWorkspace] reads [_taskIndex] to persist it (Step 3).
  void _buildTaskIndex() {
    final filesDir = _wsFilesDir(_workspaceId);
    _taskIndex = {};
    for (final task in _allTasks) {
      final absPath = _taskMdPath(task);
      // Store relative to filesDir so the path survives workspace moves.
      final relativePath = absPath.startsWith('$filesDir/')
          ? absPath.substring(filesDir.length + 1)
          : absPath;
      _taskIndex[task.id] = {
        'path': relativePath,
        // Anchors = series parents + stand-alone tasks: always loaded on startup.
        'anchor': task.isSeriesParent || !task.isPartOfSeries,
        if (task.dueDay != null) 'dueDay': task.dueDay,
      };
    }
  }

  /// Loads tasks from their .md files using [rawIndex] as the directory.
  ///
  /// Strategy:
  ///   • anchor == true  → always load (series parents + stand-alone tasks).
  ///   • anchor == false → load only if dueDay falls within the current
  ///     Mon–Sun week (repeat instances for other weeks are loaded on demand
  ///     by [_loadWeekTasks] when the user navigates the schedule).
  ///
  /// After populating [_allTasks] a setState is emitted and the active canvas
  /// is re-applied so task cards that were already on the canvas reappear.
  Future<void> _loadTasksFromIndex(Map<String, dynamic> rawIndex) async {
    final today = DateTime.now();
    // Monday of the current week (weekday == 1).
    final weekStart = DateTime(today.year, today.month, today.day)
        .subtract(Duration(days: today.weekday - 1));
    // Sunday of the current week (weekday == 7).
    final weekEnd = weekStart.add(const Duration(days: 6));

    final filesDir = _wsFilesDir(_workspaceId);
    _taskIndex = {};
    final pathsToLoad = <String>[];

    for (final entry in rawIndex.entries) {
      final id = entry.key;
      try {
      final meta = Map<String, dynamic>.from(entry.value as Map);
      _taskIndex[id] = meta;

      // Null-safe: a missing 'path' would previously cast to non-null String
      // and throw a _CastError that silently aborted ALL task loading via the
      // outer try/catch in _loadWorkspace. Now we skip only the bad entry.
      final relativePath = meta['path'] as String?;
      if (relativePath == null || relativePath.isEmpty) {
        debugPrint('_loadTasksFromIndex: skipping $id — missing path in index');
        continue;
      }
      final isAnchor = meta['anchor'] as bool? ?? false;
      final dueDayStr = meta['dueDay'] as String?;

      // Non-repeat tasks (anchor == true) are always loaded.
      // Repeat instances (anchor == false) are loaded only when their dueDay
      // falls within the current Mon–Sun week; other weeks load on demand via
      // _loadWeekTasks / _loadProjectTasks.
      // Additionally, any task whose path falls under a project folder is
      // always loaded as an anchor so it appears immediately on startup.
      bool shouldLoad = isAnchor || relativePath.startsWith('projects/');
      if (!shouldLoad && dueDayStr != null) {
        final date = DateTime.tryParse(dueDayStr);
        if (date != null) {
          final d = DateTime(date.year, date.month, date.day);
          shouldLoad = !d.isBefore(weekStart) && !d.isAfter(weekEnd);
        }
      }

      if (shouldLoad) pathsToLoad.add('$filesDir/$relativePath');
      } catch (e) {
        debugPrint('_loadTasksFromIndex: bad index entry $id — $e');
      }
    }

    final loaded = <Task>[];
    for (final absPath in pathsToLoad) {
      try {
        final file = File(absPath);
        if (!await file.exists()) {
          debugPrint('_loadTasksFromIndex: missing $absPath — skipping');
          continue;
        }
        final task = _loadTaskFromMd(absPath, await file.readAsString());
        if (task != null) loaded.add(task);
      } catch (e) {
        debugPrint('_loadTasksFromIndex: error reading $absPath: $e');
      }
    }

    // ── Reconcile projectId mismatches ───────────────────────────────────────
    // Tasks created before a project ID changed (e.g. re-imported via
    // _syncProjectsFromFilesystem which generates 'proj_fs_<name>' IDs) may
    // have a stale projectId that no longer exists in _projects.  Fix them by
    // matching on project title derived from the file path so they appear in
    // the correct project view immediately, without requiring a manual re-
    // assignment by the user.
    final projectTitleToId = <String, String>{
      for (final e in _projects.entries)
        _fsSafe(e.value.title).toLowerCase(): e.key,
    };
    bool indexDirty = false;
    for (final task in loaded) {
      if (_projects.containsKey(task.projectId)) continue;
      if (task.projectId == 'INBOX_PROJECT') continue;
      // Try to recover the right project from the file path stored in index.
      final entry = _taskIndex[task.id];
      if (entry == null) continue;
      final relPath = entry['path'] as String? ?? '';
      // Path shape: 'projects/<FsTitle>/tasks/<file>.md'
      final parts = relPath.split('/');
      if (parts.length >= 3 && parts[0] == 'projects') {
        final fsTitle = parts[1].toLowerCase();
        final recoveredId = projectTitleToId[fsTitle];
        if (recoveredId != null) {
          task.projectId = recoveredId;
          // Update the index entry so _saveTaskMd writes to the right folder.
          _taskIndex[task.id] = {
            ...entry,
            'path': relPath, // path is already correct
          };
          indexDirty = true;
          debugPrint(
            '_loadTasksFromIndex: reconciled projectId for "${task.title}" → $recoveredId',
          );
        }
      }
    }

    setState(() => _allTasks = loaded);

    if (indexDirty) {
      // Persist corrected index so subsequent startups don't repeat the repair.
      unawaited(_saveWorkspace());
    }

    // Re-apply the active canvas so task cards repopulate after the async load.
    if (_currentCanvasName.isNotEmpty &&
        _canvasStates.containsKey(_currentCanvasName)) {
      setState(() => _applyCanvas(_canvasStates[_currentCanvasName]!));
    }

    // If the app was closed while a project page was open, restore its repeat
    // instances in memory so the series appears complete without the user
    // having to click the project again.
    if (_tasksNavSection.startsWith('proj:')) {
      final pid = _tasksNavSection.substring(5);
      await _generateProjectSeriesInstances(pid);
    }
  }

  /// Loads tasks for [weekStart]–[weekStart+6] that are not already in
  /// [_allTasks], reading their .md files on demand.
  ///
  /// Called when the user navigates the schedule to a week that has not been
  /// loaded yet. Non-week tasks (anchors, other weeks) are untouched.
  /// Loads and — if necessary — generates repeat instances for the week that
  /// contains [anyDayInWeek], then merges them into [_allTasks].
  ///
  /// Three phases:
  ///   1. Read instances already in [_taskIndex] for this week from disk.
  ///   2. For each loaded anchor series, generate any instances that are
  ///      still missing (week was never visited before).
  ///   3. Persist the updated index when new instances were created.
  ///
  /// Idempotent — safe to call when the week is already fully loaded.
  Future<void> _loadWeekTasks(DateTime anyDayInWeek) async {
    // Normalise to Monday of the requested week.
    final d = anyDayInWeek;
    final weekStart =
        DateTime(d.year, d.month, d.day).subtract(Duration(days: d.weekday - 1));
    final weekEnd = weekStart.add(const Duration(days: 6));

    final filesDir = _wsFilesDir(_workspaceId);
    final loadedIds = _allTasks.map((t) => t.id).toSet();

    // ── Phase 1: load existing index entries for this week ─────────────────
    final toLoad = <String>[];
    for (final entry in _taskIndex.entries) {
      if (loadedIds.contains(entry.key)) continue;
      final meta = entry.value;
      if (meta['anchor'] as bool? ?? false) continue;
      final dueDayStr = meta['dueDay'] as String?;
      if (dueDayStr == null) continue;
      final date = DateTime.tryParse(dueDayStr);
      if (date == null) continue;
      final day = DateTime(date.year, date.month, date.day);
      if (!day.isBefore(weekStart) && !day.isAfter(weekEnd)) {
        toLoad.add('$filesDir/${meta['path'] as String}');
      }
    }

    final loaded = <Task>[];
    for (final absPath in toLoad) {
      try {
        final file = File(absPath);
        if (!await file.exists()) continue;
        final task = _loadTaskFromMd(absPath, await file.readAsString());
        if (task != null) loaded.add(task);
      } catch (e) {
        debugPrint('_loadWeekTasks: error reading $absPath: $e');
      }
    }
    if (loaded.isNotEmpty) {
      setState(() => _allTasks = [..._allTasks, ...loaded]);
    }

    // ── Phase 2: generate missing instances for all anchor series ──────────
    final anchors = _allTasks
        .where(
          (t) =>
              t.isSeriesParent &&
              t.repeatConfig != null &&
              !t.repeatConfig!.cleared,
        )
        .toList();
    for (final anchor in anchors) {
      await _generateWeekInstances(anchor, weekStart, weekEnd);
    }
  }

  /// Loads all [_taskIndex] entries that belong to [projectId] and are not
  /// yet in [_allTasks]. Called when the user navigates to a project view so
  /// that repeat instances outside the current week become visible in the
  /// project task list (they are normally skipped by [_loadTasksFromIndex]
  /// because they fall outside the current Mon–Sun window).
  Future<void> _loadProjectTasks(String projectId) async {
    final filesDir = _wsFilesDir(_workspaceId);
    final projAbsDir = _projectDir(projectId);
    // Derive the relative prefix used in the index (e.g. 'projects/Project1').
    final projRelPrefix = projAbsDir.startsWith('$filesDir/')
        ? projAbsDir.substring(filesDir.length + 1)
        : projAbsDir;

    final loadedIds = _allTasks.map((t) => t.id).toSet();
    final toLoad = <String>[];

    for (final entry in _taskIndex.entries) {
      if (loadedIds.contains(entry.key)) continue;
      final relPath = entry.value['path'] as String? ?? '';
      // Match by path prefix (normal case) OR by any indexed path — we will
      // re-check projectId after reading the file (covers tasks that were
      // written to Inbox due to a project-not-found race on a previous run).
      if (relPath.startsWith('$projRelPrefix/tasks/')) {
        toLoad.add('$filesDir/$relPath');
      }
    }

    if (toLoad.isEmpty) return;

    final loaded = <Task>[];
    for (final absPath in toLoad) {
      try {
        final file = File(absPath);
        if (!await file.exists()) {
          debugPrint('_loadProjectTasks: missing $absPath — skipping');
          continue;
        }
        final task = _loadTaskFromMd(absPath, await file.readAsString());
        if (task != null) loaded.add(task);
      } catch (e) {
        debugPrint('_loadProjectTasks: error reading $absPath: $e');
      }
    }

    if (loaded.isNotEmpty) {
      setState(() => _allTasks = [..._allTasks, ...loaded]);
    }

    // After loading indexed tasks, also populate in-memory instances for any
    // repeat series that belongs to this project.
    await _generateProjectSeriesInstances(projectId);
  }

  /// Generates in-memory repeat instances for every anchor series that belongs
  /// to [projectId], covering the full series horizon (endDate / propagation
  /// cap / 1-year fallback). Instances that already exist in [_allTasks] or
  /// [_taskIndex] are skipped, so this is safe to call multiple times.
  ///
  /// Unlike [_generateWeekInstances], these instances are **not** written to
  /// disk — they exist only in [_allTasks] for the current session. When the
  /// user navigates to a week that contains an instance, [_loadWeekTasks]
  /// will persist it normally. This approach keeps the filesystem clean while
  /// making the full series visible in the project view immediately.
  Future<void> _generateProjectSeriesInstances(String projectId) async {
    final anchors = _allTasks.where((t) =>
        t.isSeriesParent &&
        t.repeatConfig != null &&
        !t.repeatConfig!.cleared &&
        t.projectId == projectId).toList();

    if (anchors.isEmpty) return;

    // IDs already in memory or on disk (index) — used to skip duplicates.
    final occupiedIds = _allTasks.map((t) => t.id).toSet();
    final occupiedDates = <String, Set<DateTime>>{}; // seriesId → dates

    for (final t in _allTasks) {
      if (!t.isPartOfSeries) continue;
      final sid = t.seriesId!;
      final d = t.scheduledDate;
      if (d != null) {
        occupiedDates.putIfAbsent(sid, () => {}).add(
          DateTime(d.year, d.month, d.day),
        );
      }
    }
    // Also count dates that exist in the index but aren't loaded yet.
    for (final entry in _taskIndex.entries) {
      final dueDayStr = entry.value['dueDay'] as String?;
      if (dueDayStr == null) continue;
      final d = DateTime.tryParse(dueDayStr);
      if (d == null) continue;
      // We don't know the seriesId from the index alone; mark all dates so
      // we conservatively avoid generating duplicates across the whole series.
      // The per-series collision check below uses occupiedDates which is
      // keyed by seriesId so this only matters for unloaded instances.
    }

    final today = DateTime.now();
    final newTasks = <Task>[];

    for (final anchor in anchors) {
      final cfg = anchor.repeatConfig!;
      final seriesDates = occupiedDates[anchor.id] ?? {};

      // Determine horizon: endDate, propagationDays, or 1-year fallback.
      final DateTime horizon;
      if (cfg.endDate != null) {
        horizon = DateTime(
          cfg.endDate!.year, cfg.endDate!.month, cfg.endDate!.day,
        );
      } else if (cfg.propagationDays != null) {
        final start = anchor.scheduledDate ?? today;
        horizon = start.add(Duration(days: cfg.propagationDays!));
      } else {
        horizon = today.add(const Duration(days: 365));
      }

      // All anchor tasks in this series (segments), sorted chronologically.
      final segments = _allTasks
          .where((t) =>
              t.seriesId == anchor.id &&
              t.repeatConfig != null &&
              !t.repeatConfig!.cleared)
          .toList()
        ..sort((a, b) {
          final da = a.scheduledDate ?? DateTime(2099);
          final db = b.scheduledDate ?? DateTime(2099);
          return da.compareTo(db);
        });

      final timeOfDay = anchor.plannedAt != null
          ? Duration(
              hours:
                  DateTime.fromMillisecondsSinceEpoch(anchor.plannedAt!).hour,
              minutes:
                  DateTime.fromMillisecondsSinceEpoch(anchor.plannedAt!).minute,
            )
          : null;

      for (int i = 0; i < segments.length; i++) {
        final seg = segments[i];
        final segCfg = seg.repeatConfig!;
        final segStart = seg.scheduledDate;
        if (segStart == null) continue;

        // Segment ends at min(horizon, nextSegment − 1, endDate).
        DateTime segHorizon = horizon;
        if (segCfg.endDate != null) {
          final ed = DateTime(
            segCfg.endDate!.year,
            segCfg.endDate!.month,
            segCfg.endDate!.day,
          );
          if (ed.isBefore(segHorizon)) segHorizon = ed;
        }
        if (i + 1 < segments.length) {
          final nextStart = segments[i + 1].scheduledDate;
          if (nextStart != null) {
            final bound = nextStart.subtract(const Duration(days: 1));
            if (bound.isBefore(segHorizon)) segHorizon = bound;
          }
        }

        DateTime cursor = segStart;
        while (true) {
          final next = _nextRepeatDate(segCfg, cursor);
          if (next == null) break;
          cursor = next;
          final day = DateTime(cursor.year, cursor.month, cursor.day);
          if (day.isAfter(segHorizon)) break;

          // Skip if already in memory or in the index.
          if (seriesDates.contains(day)) continue;

          final id =
              'repeat_${anchor.id}_${cursor.millisecondsSinceEpoch}';
          if (occupiedIds.contains(id)) continue;

          final instance = Task(
            id: id,
            title: seg.title,
            isDone: false,
            status: TaskStatus.none,
            projectId: anchor.projectId,
            subTaskIds: [],
            timeSpent: 0,
            dueDay: day.toIso8601String().split('T').first,
            plannedAt: timeOfDay != null
                ? cursor.add(timeOfDay).millisecondsSinceEpoch
                : null,
            durationMinutes: anchor.durationMinutes,
            attachments: [],
            tagIds: List.from(anchor.tagIds),
            notes: anchor.notes,
            repeatParentId: anchor.id,
            seriesId: anchor.id,
          );

          newTasks.add(instance);
          occupiedIds.add(id);
          seriesDates.add(day);
        }
        occupiedDates[anchor.id] = seriesDates;
      }
    }

    if (newTasks.isNotEmpty) {
      setState(() => _allTasks.addAll(newTasks));
    }
  }
  /// [[weekStart], [weekEnd]] and do not already exist.
  ///
  /// Respects segment boundaries: the series may have multiple anchor tasks
  /// each with their own config (set via "apply from here").  Dates already
  /// present in [_allTasks] or [_taskIndex] are skipped.
  ///
  /// Saves each new instance as a .md file, updates [_taskIndex], emits
  /// a setState, and persists [_saveWorkspace] if anything was created.
  Future<void> _generateWeekInstances(
    Task anchor,
    DateTime weekStart,
    DateTime weekEnd,
  ) async {
    final cfg = anchor.repeatConfig;
    if (cfg == null || cfg.cleared) return;

    // Collect already-occupied dates (memory + index) to avoid duplicates.
    final occupiedDates = <DateTime>{};
    for (final t in _allTasks.where((t) => t.seriesId == anchor.id)) {
      final d = t.scheduledDate;
      if (d != null) occupiedDates.add(DateTime(d.year, d.month, d.day));
    }
    // Only look at index entries that belong to THIS series (generated instances
    // have ids of the form "repeat_<anchorId>_<epochMs>", so the prefix is a
    // reliable filter). Using all _taskIndex entries was causing instances of
    // an unrelated series to "block" generation for this one on the same date.
    final seriesPrefix = 'repeat_${anchor.id}_';
    for (final kv in _taskIndex.entries) {
      if (!kv.key.startsWith(seriesPrefix)) continue;
      final dueDayStr = kv.value['dueDay'] as String?;
      if (dueDayStr == null) continue;
      final d = DateTime.tryParse(dueDayStr);
      if (d != null) occupiedDates.add(DateTime(d.year, d.month, d.day));
    }

    // All anchor tasks in this series, sorted chronologically.
    final anchorTasks = _allTasks
        .where(
          (t) =>
              t.seriesId == anchor.id &&
              t.repeatConfig != null &&
              !t.repeatConfig!.cleared,
        )
        .toList()
      ..sort((a, b) {
        final da = a.scheduledDate ?? DateTime(2099);
        final db = b.scheduledDate ?? DateTime(2099);
        return da.compareTo(db);
      });

    final timeOfDay = anchor.plannedAt != null
        ? Duration(
            hours: DateTime.fromMillisecondsSinceEpoch(anchor.plannedAt!).hour,
            minutes:
                DateTime.fromMillisecondsSinceEpoch(anchor.plannedAt!).minute,
          )
        : null;

    final newTasks = <Task>[];

    for (int i = 0; i < anchorTasks.length; i++) {
      final segAnchor = anchorTasks[i];
      final segCfg = segAnchor.repeatConfig!;
      final segStart = segAnchor.scheduledDate;
      if (segStart == null) continue;

      // Segment horizon = min(propagationDays, endDate, next-anchor − 1 day).
      DateTime segHorizon;
      if (segCfg.propagationDays != null) {
        segHorizon = segStart.add(Duration(days: segCfg.propagationDays!));
      } else if (segCfg.endDate != null) {
        segHorizon = DateTime(
          segCfg.endDate!.year,
          segCfg.endDate!.month,
          segCfg.endDate!.day,
        );
      } else {
        segHorizon = segStart.add(const Duration(days: 3650));
      }
      if (segCfg.endDate != null) {
        final ed = DateTime(
          segCfg.endDate!.year,
          segCfg.endDate!.month,
          segCfg.endDate!.day,
        );
        if (ed.isBefore(segHorizon)) segHorizon = ed;
      }
      if (i + 1 < anchorTasks.length) {
        final nextStart = anchorTasks[i + 1].scheduledDate;
        if (nextStart != null) {
          final bound = nextStart.subtract(const Duration(days: 1));
          if (bound.isBefore(segHorizon)) segHorizon = bound;
        }
      }

      // Skip segments that end before weekStart or start after weekEnd.
      if (segHorizon.isBefore(weekStart)) continue;
      if (segStart.isAfter(weekEnd)) continue;

      // Fast-forward cursor to the last date strictly before weekStart,
      // avoiding iteration from the series origin on distant future weeks.
      DateTime cursor = segStart;
      while (true) {
        final next = _nextRepeatDate(segCfg, cursor);
        if (next == null || !next.isBefore(weekStart)) break;
        cursor = next;
      }

      // Generate dates within [weekStart, weekEnd] ∩ (segStart, segHorizon].
      while (true) {
        final next = _nextRepeatDate(segCfg, cursor);
        if (next == null) break;
        cursor = next;
        final day = DateTime(cursor.year, cursor.month, cursor.day);
        if (day.isAfter(segHorizon)) break;
        if (day.isAfter(weekEnd)) break;
        if (day.isBefore(weekStart)) continue;
        if (occupiedDates.contains(day)) continue;

        final id =
            'repeat_${anchor.id}_${cursor.millisecondsSinceEpoch}';
        newTasks.add(
          Task(
            id: id,
            title: segAnchor.title,
            isDone: false,
            status: TaskStatus.none,
            projectId: anchor.projectId,
            subTaskIds: [],
            timeSpent: 0,
            dueDay: day.toIso8601String().split('T').first,
            plannedAt: timeOfDay != null
                ? cursor.add(timeOfDay).millisecondsSinceEpoch
                : null,
            durationMinutes: anchor.durationMinutes,
            attachments: [],
            tagIds: List.from(anchor.tagIds),
            notes: anchor.notes,
            repeatParentId: anchor.id,
            seriesId: anchor.id,
          ),
        );
        occupiedDates.add(day);
      }
    }

    if (newTasks.isEmpty) return;

    final filesDir = _wsFilesDir(_workspaceId);
    for (final task in newTasks) {
      await _saveTaskMd(task);
      final absPath = _taskMdPath(task);
      final relPath = absPath.startsWith('$filesDir/')
          ? absPath.substring(filesDir.length + 1)
          : absPath;
      _taskIndex[task.id] = {
        'path': relPath,
        'anchor': false,
        if (task.dueDay != null) 'dueDay': task.dueDay,
      };
    }

    setState(() => _allTasks.addAll(newTasks));
    await _saveWorkspace(); // persist updated taskIndex
  }

  /// One-time migration: writes every task currently in [_allTasks] (loaded
  /// from the legacy JSON array) to its own .md file, then rebuilds
  /// [_taskIndex] and triggers a workspace save so future startups use the
  /// new path.
  ///
  /// Safe to call multiple times — [_saveTaskMd] is idempotent.
  Future<void> _migrateLegacyTasksToMd() async {
    debugPrint('_migrateLegacyTasksToMd: migrating ${_allTasks.length} tasks…');
    for (final task in _allTasks) {
      await _saveTaskMd(task);
    }
    _buildTaskIndex();
    debugPrint(
      '_migrateLegacyTasksToMd: done — ${_taskIndex.length} index entries.',
    );
    // Persist the index immediately so the next startup uses the new path.
    // _saveWorkspace() will write taskIndex once Step 3 is in place; until
    // then this call writes the full legacy payload plus the new index key.
    await _saveWorkspace();
  }

  Future<void> _loadWorkspace() async {
    if (_workspaceId.isEmpty) return;
    // Hoisted outside try so the async task-loading block below can reference
    // them after the setState try/catch closes without making `data` nullable.
    Map<String, dynamic>? _taskIndexSnapshot;
    bool _hasLegacyTasks = false;
    try {
      final file = File(_workspaceFilePath(_workspaceId));
      if (!await file.exists()) return;

      final data =
          jsonDecode(await file.readAsString()) as Map<String, dynamic>;

      setState(() {
        // Identity
        if (data['workspaceName'] != null) {
          _workspaceName = data['workspaceName'];
          _workspaceNameController.text = _workspaceName;
        }
        if (data['workspaceImagePath'] != null) {
          _workspaceImagePath = data['workspaceImagePath'];
        }
        // Multi-canvas
        if (data['savedBoards'] != null) {
          _savedBoards = List<Map<String, dynamic>>.from(
            (data['savedBoards'] as List).map(
              (e) => Map<String, dynamic>.from(e as Map),
            ),
          );
        }
        _currentBoardId = data['currentBoardId'] ?? '';
        if (data['savedCanvases'] != null) {
          _savedCanvases = List<Map<String, String>>.from(
            (data['savedCanvases'] as List).map(
              (e) => Map<String, String>.from(e),
            ),
          );
        }
        if (data['openCanvases'] != null) {
          _openCanvases = Set<String>.from(data['openCanvases']);
        }
        if (data['canvasColors'] != null) {
          _canvasColors = (data['canvasColors'] as Map).map(
            (k, v) => MapEntry(k.toString(), Color(v as int)),
          );
        }

        // ── Tasks & Projects must be loaded BEFORE canvas states so that
        // _deserialiseCanvas can resolve task IDs against _allTasks. ─────────
        if (data['projects'] != null) {
          _projects = (data['projects'] as Map).map(
            (k, v) => MapEntry(
              k.toString(),
              Project.fromJson(Map<String, dynamic>.from(v as Map)),
            ),
          );
        }
        if (data['projectOrder'] != null) {
          _projectOrder = List<String>.from(data['projectOrder'] as List);
        }
        // Tasks are loaded outside setState via async .md reads.
        // Legacy fallback: only populate _allTasks here when taskIndex is
        // absent so that _deserialiseCanvas (below) has task objects to
        // reference during the same setState call.
        if (data['taskIndex'] == null && data['tasks'] != null) {
          _allTasks = (data['tasks'] as List)
              .map((e) => Task.fromJson(Map<String, dynamic>.from(e as Map)))
              .toList();
        }

        if (data['canvasStates'] != null) {
          _canvasStates = {};
          (data['canvasStates'] as Map).forEach((k, v) {
            _canvasStates[k.toString()] = _deserialiseCanvas(
              Map<String, dynamic>.from(v),
            );
          });
        }
        final canvasName = data['currentCanvasName'] ?? '';
        _currentCanvasName = canvasName;
        _canvasNameController.text = canvasName;
        if (canvasName.isNotEmpty && _canvasStates.containsKey(canvasName)) {
          _applyCanvas(_canvasStates[canvasName]!);
        }

        // Category groups
        if (data['categoriesGroups'] != null) {
          _categoriesGroups = (data['categoriesGroups'] as Map).map(
            (k, v) => MapEntry(k.toString(), Map<String, dynamic>.from(v)),
          );
        }
        _currentCategoriesGroupName = data['currentCategoriesGroupName'] ?? '';
        _categoriesGroupNameController.text = _currentCategoriesGroupName;

        // Sidebar
        if (data['projectColors'] != null) {
          _projectColors = (data['projectColors'] as Map).map(
            (k, v) => MapEntry(k.toString(), Color(v as int)),
          );
        }
        if (data['viewColors'] != null) {
          _viewColors = (data['viewColors'] as Map).map(
            (k, v) => MapEntry(k.toString(), Color(v as int)),
          );
        }
        if (data['projectIcons'] != null) {
          _projectIcons = Map<String, String>.from(data['projectIcons'] as Map);
        }
        if (data['psycheColors'] != null) {
          _psycheColors = (data['psycheColors'] as Map).map(
            (k, v) => MapEntry(k.toString(), Color(v as int)),
          );
        }
        if (data['psycheIcons'] != null) {
          _psycheIcons = Map<String, String>.from(data['psycheIcons'] as Map);
        }
        if (data['projectBacklogEnabled'] != null) {
          _projectBacklogEnabled = Map<String, bool>.from(
            data['projectBacklogEnabled'] as Map,
          );
        }
        if (data['projectHiddenFromMenu'] != null) {
          _projectHiddenFromMenu = Map<String, bool>.from(
            data['projectHiddenFromMenu'] as Map,
          );
        }
        _showHiddenProjects = data['showHiddenProjects'] ?? false;
        _ganttEnabled = data['ganttEnabled'] ?? false;
        _ganttProportional = data['ganttProportional'] ?? true;
        _ganttDayWidth = (data['ganttDayWidth'] as num?)?.toDouble() ?? 200.0;
        _ganttForceTimeAlign = data['ganttForceTimeAlign'] ?? false;
        _ganttSnapMinutes = data['ganttSnapMinutes'] ?? 30;
        _ganttShowProjectAxis = data['ganttShowProjectAxis'] ?? false;
        if (data['ganttWeekdayColors'] != null) {
          final raw = data['ganttWeekdayColors'] as List;
          if (raw.length == 7) {
            _ganttWeekdayColors = raw.map((v) => Color(v as int)).toList();
          }
        }
        if (data['ganttColumnWidths'] != null) {
          _ganttColumnWidths = (data['ganttColumnWidths'] as Map).map(
            (k, v) =>
                MapEntry(DateTime.parse(k.toString()), (v as num).toDouble()),
          );
        } else if (data['ganttSegmentWidths'] != null) {
          // Migrate legacy int-keyed widths → date-keyed on first load
          final ref = _ganttReferenceDay;
          _ganttColumnWidths = (data['ganttSegmentWidths'] as Map).map((k, v) {
            final idx = int.tryParse(k.toString()) ?? 0;
            final d = ref.add(Duration(days: idx));
            return MapEntry(
              DateTime(d.year, d.month, d.day),
              (v as num).toDouble(),
            );
          });
        }
        if (data['ganttLaneHeights'] != null) {
          _ganttLaneHeights = Map<String, double>.from(
            (data['ganttLaneHeights'] as Map).map(
              (k, v) => MapEntry(k.toString(), (v as num).toDouble()),
            ),
          );
        }
        _themeMode = data['themeMode'] ?? 'dark';
        WidgetsBinding.instance.addPostFrameCallback(
          (_) => widget.onThemeChange?.call(_themeMode == 'light'),
        );
        _appLanguage = data['appLanguage'] ?? 'en';
        _timeLocale = data['timeLocale'] ?? 'en_US';
        _timezoneId = data['timezoneId'] ?? 'America/Sao_Paulo';
        _timezoneOffsetMinutes = data['timezoneOffsetMinutes'] ?? -180;
        _clockDeltaMs = (data['clockDeltaMs'] as num?)?.toInt() ?? 0;
        AppClock.timezoneId = _timezoneId;
        AppClock.offsetMinutes = _timezoneOffsetMinutes;
        AppClock.clockDeltaMs = _clockDeltaMs;
        _markParentDoneOnSubtasks = data['markParentDoneOnSubtasks'] ?? false;
        _firstDayOfWeek = data['firstDayOfWeek'] ?? 1;
        _nextDayStartHour = data['nextDayStartHour'] ?? 0;
        _taskDescTemplate = data['taskDescTemplate'] ?? '';
        _defaultTimeEstimateMin = data['defaultTimeEstimateMin'] ?? 0;
        _defaultSubTimeEstimateMin = data['defaultSubTimeEstimateMin'] ?? 0;
        _trackNextOnDone = data['trackNextOnDone'] ?? false;
        if (data['stagingBlocks'] != null) {
          final raw = data['stagingBlocks'] as List;
          final parsed = <_StagingBlock>[];
          for (final item in raw) {
            final typeStr = item['type'] as String? ?? 'work';
            final mins = (item['minutes'] as num?)?.toInt() ?? 25;
            _StagingType type;
            try {
              type = _StagingType.values.byName(typeStr);
            } catch (_) {
              type = _StagingType.work;
            }
            parsed.add(_StagingBlock(type: type, minutes: mins));
          }
          if (parsed.isNotEmpty) _stagingBlocks = parsed;
        }
        _soundVolume = (data['soundVolume'] as num?)?.toDouble() ?? 0.5;
        _taskDoneSound = data['taskDoneSound'] ?? 'Small Ding';
        _increasePitch = data['increasePitch'] ?? false;
        _taskWorkStartSound = data['taskWorkStartSound'] ?? '';
        if (data['projectFolders'] != null) {
          _projectFolders = (data['projectFolders'] as Map).map(
            (k, v) => MapEntry(k as String, Set<String>.from(v as List)),
          );
        }
        if (data['tagFolders'] != null) {
          _tagFolders = (data['tagFolders'] as Map).map(
            (k, v) => MapEntry(k as String, Set<String>.from(v as List)),
          );
        }
        if (data['projectFolderOrder'] != null) {
          _projectFolderOrder = List<String>.from(
            data['projectFolderOrder'] as List,
          );
        }
        if (data['tagFolderOrder'] != null) {
          _tagFolderOrder = List<String>.from(data['tagFolderOrder'] as List);
        }
        if (data['tagOrder'] != null) {
