        // ── Notes collapsed headers ──────────────────────────────────────
        if (data['notesOrgNotesCollapsed'] != null) {
          _notesOrgNotesCollapsed
            ..clear()
            ..addAll(List<String>.from(data['notesOrgNotesCollapsed'] as List));
        }
        if (data['notesOrgTasksCollapsed'] != null) {
          _notesOrgTasksCollapsed
            ..clear()
            ..addAll(List<String>.from(data['notesOrgTasksCollapsed'] as List));
        }

        // ── Sidebar nav collapsed folders ────────────────────────────────
        if (data['collapsedNavProjectFolders'] != null) {
          _collapsedNavProjectFolders
            ..clear()
            ..addAll(
              List<String>.from(data['collapsedNavProjectFolders'] as List),
            );
        }

        // ── Notes sidebar section expanded / folder collapsed state ──────
        if (data['notesSectionTaskExpanded'] != null)
          _notesSectionTaskExpanded = data['notesSectionTaskExpanded'] as bool;
        if (data['notesSectionProjectExpanded'] != null)
          _notesSectionProjectExpanded = data['notesSectionProjectExpanded'] as bool;
        if (data['notesSectionCommonExpanded'] != null)
          _notesSectionCommonExpanded = data['notesSectionCommonExpanded'] as bool;
        if (data['collapsedNoteTaskFolders'] != null) {
          _collapsedNoteTaskFolders
            ..clear()
            ..addAll(List<String>.from(data['collapsedNoteTaskFolders'] as List));
        }
        if (data['collapsedNoteProjectFolders'] != null) {
          _collapsedNoteProjectFolders
            ..clear()
            ..addAll(List<String>.from(data['collapsedNoteProjectFolders'] as List));
        }
        if (data['collapsedNoteCommonFolders'] != null) {
          _collapsedNoteCommonFolders
            ..clear()
            ..addAll(List<String>.from(data['collapsedNoteCommonFolders'] as List));
        }

        // ── Restore active tab / subtab ──────────────────────────────────
        if (data['isTasksView'] != null)
          _isTasksView = data['isTasksView'] as bool;
        if (data['isNotesView'] != null)
          _isNotesView = data['isNotesView'] as bool;
        if (data['isSettingsView'] != null)
          _isSettingsView = data['isSettingsView'] as bool;
        if (data['isVisualizerView'] != null)
          _isVisualizerView = data['isVisualizerView'] as bool;
        if (data['tasksNavSection'] != null)
          _tasksNavSection = data['tasksNavSection'] as String;
        if (data['notesNavSection'] != null)
          _notesNavSection = data['notesNavSection'] as String;
        if (data['noteCommonFolderOrder'] != null)
          _noteCommonFolderOrder = List<String>.from(data['noteCommonFolderOrder'] as List);

        // ── F/G/S section collapsed states ──────────────────────────────
        if (data['fgsSectionFilterCollapsed'] != null)
          _fgsSectionFilterCollapsed = data['fgsSectionFilterCollapsed'] as bool;
        if (data['fgsSectionGroupCollapsed'] != null)
          _fgsSectionGroupCollapsed = data['fgsSectionGroupCollapsed'] as bool;
        if (data['fgsSectionSortCollapsed'] != null)
          _fgsSectionSortCollapsed = data['fgsSectionSortCollapsed'] as bool;
        if (data['fgsPlannerFilterCollapsed'] != null)
          _fgsPlannerFilterCollapsed = data['fgsPlannerFilterCollapsed'] as bool;
        if (data['fgsPlannerSortCollapsed'] != null)
          _fgsPlannerSortCollapsed = data['fgsPlannerSortCollapsed'] as bool;
      });

      // Capture what the async loading block needs before 'data' goes out of scope.
      if (data['taskIndex'] != null) {
        _taskIndexSnapshot =
            Map<String, dynamic>.from(data['taskIndex'] as Map);
      }
      _hasLegacyTasks = data['tasks'] != null;
    } catch (e) {
      debugPrint('LOAD WORKSPACE ERROR: $e');
    }

    // ── Async task loading (outside the outer try/catch) ──────────────────
    // Kept separate so an error inside _loadTasksFromIndex surfaces with its
    // own 'LOAD TASKS ERROR' message rather than being silently swallowed by
    // the outer catch, which would leave _allTasks empty with no indication why.
    try {
      if (_taskIndexSnapshot != null) {
        // New path: load anchors + current-week instances from .md files.
        await _loadTasksFromIndex(_taskIndexSnapshot!);
        // Repair pass: recover any .md files that exist on disk but are
        // absent from the index (e.g. after a crash between file write and
        // workspace save).
        await _repairOrphanedMdTasks();
        // Startup backfill: generate any repeat instances that are missing
        // for the current week.  This covers the gap that arises when the
        // app was closed for one or more weeks after a repeat task was
        // created — _propagateRepeat only ran for the week that was current
        // at creation time, so subsequent weeks had no .md files until the
        // user navigated to them via the schedule.  Calling _loadWeekTasks
        // here ensures the current week is always fully populated on launch,
        // even without user interaction.
        await _loadWeekTasks(AppClock.now());
      } else if (_hasLegacyTasks) {
        // Legacy path: _allTasks was populated inside setState above.
        // Write each task to its .md file and build the index so that
        // subsequent startups use the new path.
        await _migrateLegacyTasksToMd();
      }
    } catch (e) {
      debugPrint('LOAD TASKS ERROR: $e');
    }
  }

  /// Scans task directories on disk for .md files that are not tracked in
  /// [_taskIndex], reads their frontmatter, and adds them to the index and
  /// [_allTasks]. Called once per workspace load to recover from a crash that
  /// left the index incomplete (file written but workspace.json not yet saved).
  Future<void> _repairOrphanedMdTasks() async {
    final filesDir = _wsFilesDir(_workspaceId);

    // De-duplicate by task ID, not by file path.  Path-based comparison
    // fails when the stored relative path does not byte-match entity.path
    // (e.g. different slashes, project rename, or the file predates the
    // index entirely and was never registered in _taskIndex at all).
    final knownIds = _taskIndex.keys.toSet();

    // Scan Inbox + ALL subdirectories under projects/ — not just the ones
    // currently in _projects.  This recovers tasks from renamed or legacy
    // project folders that are no longer in _projects but whose .md files
    // still exist on disk.
    final scanDirs = <Directory>[Directory('$filesDir/Inbox/tasks')];
    final projectsRoot = Directory('$filesDir/projects');
    if (await projectsRoot.exists()) {
      await for (final entity in projectsRoot.list()) {
        if (entity is Directory) {
          scanDirs.add(Directory('${entity.path}/tasks'));
        }
      }
    }

    final orphans = <Task>[];
    var indexChanged = false;

    for (final dir in scanDirs) {
      if (!await dir.exists()) continue;
      await for (final entity in dir.list()) {
        if (entity is! File || !entity.path.endsWith('.md')) continue;

        try {
          final content = await entity.readAsString();
          final task = _loadTaskFromMd(entity.path, content);
          if (task == null) continue;

          // Already tracked by ID — skip (path mismatch self-heals on next save).
          if (knownIds.contains(task.id)) continue;

          final relPath = entity.path.startsWith('$filesDir/')
              ? entity.path.substring(filesDir.length + 1)
              : entity.path;
          _taskIndex[task.id] = {
            'path': relPath,
            'anchor': task.isSeriesParent || !task.isPartOfSeries,
            if (task.dueDay != null) 'dueDay': task.dueDay,
          };
          knownIds.add(task.id);
          orphans.add(task);
          indexChanged = true;
          debugPrint(
            '_repairOrphanedMdTasks: recovered "${task.title}" (${task.id})',
          );
        } catch (e) {
          debugPrint(
            '_repairOrphanedMdTasks: error reading ${entity.path}: $e',
          );
        }
      }
    }

    if (orphans.isNotEmpty) {
      setState(() => _allTasks = [..._allTasks, ...orphans]);
    }
    if (indexChanged) {
      await _saveWorkspace();
    }
  }
  // ── Restore workspace from a .json file picked by the user ────────────────
  Future<void> _restoreWorkspaceFromFile() async {
    // Step 1: pick the backup .json file.
    final result = await FilePicker.platform.pickFiles(
      dialogTitle: 'Restore workspace from file',
      type: FileType.custom,
      allowedExtensions: ['json'],
      allowMultiple: false,
    );
    if (result == null || result.files.single.path == null) return;
    final srcPath = result.files.single.path!;

    Map<String, dynamic> data;
    try {
      data =
          jsonDecode(await File(srcPath).readAsString())
              as Map<String, dynamic>;
    } catch (e) {
      if (mounted) {
        showDialog(
          context: context,
          builder: (_) => AlertDialog(
            backgroundColor: const Color(0xFF252525),
            title: const Text(
              'Invalid file',
              style: TextStyle(color: Colors.white),
            ),
            content: Text(
              'Could not read workspace file: $e',
              style: const TextStyle(color: Colors.white70, fontSize: 13),
            ),
            actions: [
              TextButton(
                onPressed: () => Navigator.pop(context),
                child: const Text('OK'),
              ),
            ],
          ),
        );
      }
      return;
    }

    final id = data['id'] as String? ?? _generateId();
    final name = data['workspaceName'] as String? ?? 'Restored Workspace';
    final meta = data['metaPath'] as String? ?? '';

    // Step 2: ask the user where to place the restored workspace.
    // Pre-select the backup file's grandparent as a sensible default
    // (standard workspace files live at <wsRoot>/metadata/workspace_X.json).
    final destDir = await FilePicker.platform.getDirectoryPath(
      dialogTitle: 'Choose folder for restored workspace',
    );
    if (destDir == null) return;

    final wsRoot = destDir;
    final dest = File('$wsRoot/metadata/workspace_$id.json');
    await dest.parent.create(recursive: true);
    // Only write if the source and destination are different paths.
    if (dest.path != srcPath) {
      await dest.writeAsString(jsonEncode({...data, 'id': id}));
    }

    final entry = {
      'id': id,
      'name': name,
      'metaPath': meta,
      'basePath': wsRoot,
    };

    // Register in workspace list if not already there.
    setState(() {
      if (!_savedWorkspaces.any((w) => w['id'] == id)) {
        _savedWorkspaces.add(entry);
      }
    });
    await _saveGeneral();

    // Close switcher dialog then load — deferred to avoid navigation race.
    if (mounted) Navigator.of(context, rootNavigator: true).pop();
    WidgetsBinding.instance.addPostFrameCallback((_) {
      _loadWorkspaceById(entry);
    });
  }

  TaskRelation? _getRelationAt(Offset localPos) {
    const double threshold = 15.0; // Distance in screen pixels
    final worldPos = (localPos - _canvasOffset) / _scale;

    for (var rel in _taskRelations) {
      // Get absolute world positions of start and end
      Offset start = _getRelationWorldPos(rel.sourceId, rel.sourceLocalPos);
      Offset end = _getRelationWorldPos(rel.targetId, rel.targetLocalPos);

      // Simple segment check (includes handles if any)
      List<Offset> segments = [start, ...rel.handles, end];
      for (int i = 0; i < segments.length - 1; i++) {
        double dist = _distToSegment(worldPos, segments[i], segments[i + 1]);
        if (dist * _scale < threshold) return rel;
      }
    }
    return null;
  }

  double _distToSegment(Offset p, Offset v, Offset w) {
    double l2 = (v - w).distanceSquared;
    if (l2 == 0.0) return (p - v).distance;
    double t =
        ((p.dx - v.dx) * (w.dx - v.dx) + (p.dy - v.dy) * (w.dy - v.dy)) / l2;
    t = t.clamp(0.0, 1.0);
    return (p - Offset(v.dx + t * (w.dx - v.dx), v.dy + t * (w.dy - v.dy)))
        .distance;
  }

  Offset _getRelationWorldPos(String id, Offset local) {
    if (_taskPositions.containsKey(id)) return _taskPositions[id]! + local;
    // ConditionalNode — check before junctions to avoid StateError
    final cnd = _conditionals.firstWhere(
      (c) => c.id == id,
      orElse: () => ConditionalNode(id: '', position: Offset.zero),
    );
    if (cnd.id.isNotEmpty) return cnd.position + local;
    final jnc = _junctions.firstWhere((j) => j.id == id);
    return jnc.position + local;
  }

  /// Projects [pos] (local to ConditionalNode) onto its rhombus border,
  /// clamped to the allowed x-zone.
  ///   isInput  → x ∈ [0,   0.4·w]  (left side)
  ///   isOutput → x ∈ [0.5·w, w]    (right side)
  /// The top/bottom edge is chosen by whether [pos.dy] is above/below centre.
  Offset _snapToConditionalBorder(
    Offset pos,
    double w,
    double h, {
    required bool isInput,
  }) {
    final cx = w / 2;
    final cy = h / 2;
    final minX = isInput ? 0.0 : w * 0.5;
    final maxX = isInput ? w * 0.4 : w;
    final dx = pos.dx.clamp(minX, maxX);
    final preferTop = pos.dy < cy;

    final double dy;
    if (dx <= cx) {
      // Left half of diamond
      dy = preferTop ? cy * (1 - dx / cx) : cy * (1 + dx / cx);
    } else {
      // Right half of diamond
      dy = preferTop ? cy * (dx / cx - 1) : h - cy * (dx / cx - 1);
    }
    return Offset(dx, dy);
  }

  List<Widget> _buildRhombusResizeHandles(ConditionalNode c, Offset sp) {
    const double hs = 12.0; // handle size in pixels (larger = easier to grab)
    final double sw = c.width * _scale;
    final double sh = c.height * _scale;

    // Build a single handle at canvas-space position (cx, cy)
    Widget handle({
      required double cx, // canvas-space center x
      required double cy, // canvas-space center y
      required MouseCursor cursor,
      required void Function(DragUpdateDetails) onPanUpdate,
    }) => Positioned(
      left: sp.dx + cx - hs / 2,
      top: sp.dy + cy - hs / 2,
      child: MouseRegion(
        cursor: cursor,
        child: GestureDetector(
          behavior: HitTestBehavior.opaque,
          onPanUpdate: (d) => setState(() => onPanUpdate(d)),
          child: Container(
            width: hs,
            height: hs,
            decoration: BoxDecoration(
              color: Colors.white,
              border: Border.all(color: const Color(0xFF4FC3F7), width: 1.5),
              borderRadius: BorderRadius.circular(2),
            ),
          ),
        ),
      ),
    );

    return [
      // right
      handle(
        cx: sw,
        cy: sh / 2,
        cursor: SystemMouseCursors.resizeColumn,
        onPanUpdate: (d) => c.width = (c.width + d.delta.dx / _scale).clamp(
          _kRhombusMinWidth,
          9999.0,
        ),
      ),
      // bottom
      handle(
        cx: sw / 2,
        cy: sh,
        cursor: SystemMouseCursors.resizeRow,
        onPanUpdate: (d) => c.height = (c.height + d.delta.dy / _scale).clamp(
          _kRhombusMinHeight,
          9999.0,
        ),
      ),
      // left
      handle(
        cx: 0,
        cy: sh / 2,
        cursor: SystemMouseCursors.resizeColumn,
        onPanUpdate: (d) {
          final dx = d.delta.dx / _scale;
          final nw = (c.width - dx).clamp(_kRhombusMinWidth, 9999.0);
          c.position = Offset(c.position.dx + (c.width - nw), c.position.dy);
          c.width = nw;
        },
      ),
      // top
      handle(
        cx: sw / 2,
        cy: 0,
        cursor: SystemMouseCursors.resizeRow,
        onPanUpdate: (d) {
          final dy = d.delta.dy / _scale;
          final nh = (c.height - dy).clamp(_kRhombusMinHeight, 9999.0);
          c.position = Offset(c.position.dx, c.position.dy + (c.height - nh));
          c.height = nh;
        },
      ),
      // top-left
      handle(
        cx: 0,
        cy: 0,
        cursor: SystemMouseCursors.resizeUpLeft,
        onPanUpdate: (d) {
          final dx = d.delta.dx / _scale;
          final dy = d.delta.dy / _scale;
          final nw = (c.width - dx).clamp(_kRhombusMinWidth, 9999.0);
          final nh = (c.height - dy).clamp(_kRhombusMinHeight, 9999.0);
          c.position = Offset(
            c.position.dx + (c.width - nw),
            c.position.dy + (c.height - nh),
          );
          c.width = nw;
          c.height = nh;
        },
      ),
      // top-right
      handle(
        cx: sw,
        cy: 0,
        cursor: SystemMouseCursors.resizeUpRight,
        onPanUpdate: (d) {
          final dy = d.delta.dy / _scale;
          final nh = (c.height - dy).clamp(_kRhombusMinHeight, 9999.0);
          c.position = Offset(c.position.dx, c.position.dy + (c.height - nh));
          c.height = nh;
          c.width = (c.width + d.delta.dx / _scale).clamp(
            _kRhombusMinWidth,
            9999.0,
          );
        },
      ),
      // bottom-left
      handle(
        cx: 0,
        cy: sh,
        cursor: SystemMouseCursors.resizeDownLeft,
        onPanUpdate: (d) {
          final dx = d.delta.dx / _scale;
          final nw = (c.width - dx).clamp(_kRhombusMinWidth, 9999.0);
          c.position = Offset(c.position.dx + (c.width - nw), c.position.dy);
          c.width = nw;
          c.height = (c.height + d.delta.dy / _scale).clamp(
            _kRhombusMinHeight,
            9999.0,
          );
        },
      ),
      // bottom-right
      handle(
        cx: sw,
        cy: sh,
        cursor: SystemMouseCursors.resizeDownRight,
        onPanUpdate: (d) {
          c.width = (c.width + d.delta.dx / _scale).clamp(
            _kRhombusMinWidth,
            9999.0,
          );
          c.height = (c.height + d.delta.dy / _scale).clamp(
            _kRhombusMinHeight,
            9999.0,
          );
        },
      ),
    ];
  }

