  /// Reusable collapsible section header for the preferences page.
  Widget _prefSection({
    required IconData icon,
    required String label,
    required bool expanded,
    required VoidCallback onToggle,
    required List<Widget> children,
  }) {
    return Column(
      mainAxisSize: MainAxisSize.min,
      children: [
        ListTile(
          leading: Icon(icon, color: Colors.blueAccent, size: 20),
          title: Text(
            label,
            style: const TextStyle(color: Colors.white70, fontSize: 13),
          ),
          trailing: Icon(
            expanded ? Icons.expand_more : Icons.chevron_right,
            color: Colors.white24,
          ),
          onTap: onToggle,
        ),
        if (expanded) ...children,
      ],
    );
  }

  Widget _buildModeToggleButton() {
    final bool anyPan = _isPanMode || _isMiddleMousePanning;
    final Color accent = _isMiddleMousePanning
        ? Colors.orangeAccent
        : _isPanMode
        ? Colors.blueAccent
        : Colors.white24;
    return GestureDetector(
      onTap: () => setState(() => _isPanMode = !_isPanMode),
      child: AnimatedContainer(
        duration: const Duration(milliseconds: 200),
        padding: const EdgeInsets.all(4),
        decoration: BoxDecoration(
          color: anyPan ? accent.withOpacity(0.15) : Colors.transparent,
          borderRadius: BorderRadius.circular(4),
          border: Border.all(color: accent),
        ),
        child: Icon(
          anyPan ? Icons.pan_tool_rounded : Icons.mouse_rounded,
          size: 14,
          color: anyPan ? accent : Colors.white70,
        ),
      ),
    );
  }

  // --- CANVAS COMPONENT ---
  Widget _buildRightScrollbar() {
    Rect bounds = _getContentBounds();
    double extentRatio = (_viewportSize.height / bounds.height).clamp(0.0, 1.0);
    double thumbHeight = _viewportSize.height * extentRatio;
    double scrollProgress =
        (-_canvasOffset.dy - bounds.top) /
        (bounds.height - _viewportSize.height);
    double thumbTop =
        (_viewportSize.height - thumbHeight) *
        (scrollProgress.isNaN ? 0 : scrollProgress.clamp(0.0, 1.0));

    return Positioned(
      right: 0,
      top: 0,
      bottom: 0,
      child: Container(
        width: 12,
        color: Colors.white.withOpacity(0.02),
        child: Stack(
          children: [
            Positioned(
              top: thumbTop,
              child: GestureDetector(
                onVerticalDragUpdate: (d) {
                  double scrollDelta =
                      (d.delta.dy / (_viewportSize.height - thumbHeight)) *
                      (bounds.height - _viewportSize.height);
                  setState(
                    () => _canvasOffset = Offset(
                      _canvasOffset.dx,
                      _canvasOffset.dy - (scrollDelta.isNaN ? 0 : scrollDelta),
                    ),
                  );
                },
                child: Container(
                  width: 8,
                  height: thumbHeight,
                  margin: EdgeInsets.all(2),
                  decoration: BoxDecoration(
                    color: Colors.blueAccent.withOpacity(0.5),
                    borderRadius: BorderRadius.circular(4),
                  ),
                ),
              ),
            ),
          ],
        ),
      ),
    );
  }

  Widget _buildBottomScrollbar() {
    Rect bounds = _getContentBounds();
    double extentRatio = (_viewportSize.width / bounds.width).clamp(0.0, 1.0);
    double thumbWidth = _viewportSize.width * extentRatio;
    double scrollProgress =
        (-_canvasOffset.dx - bounds.left) /
        (bounds.width - _viewportSize.width);
    double thumbLeft =
        (_viewportSize.width - thumbWidth) *
        (scrollProgress.isNaN ? 0 : scrollProgress.clamp(0.0, 1.0));

    return Positioned(
      bottom: 0,
      left: 0, // Simplified because it's already inside the Expanded column
      right: 12, // Leave room for the vertical scrollbar
      child: Container(
        height: 12,
        color: Colors.white.withOpacity(0.02),
        child: Stack(
          children: [
            Positioned(
              left: thumbLeft,
              child: GestureDetector(
                onHorizontalDragUpdate: (d) {
                  double scrollDelta =
                      (d.delta.dx / (_viewportSize.width - thumbWidth)) *
                      (bounds.width - _viewportSize.width);
                  setState(
                    () => _canvasOffset = Offset(
                      _canvasOffset.dx - (scrollDelta.isNaN ? 0 : scrollDelta),
                      _canvasOffset.dy,
                    ),
                  );
                },
                child: Container(
                  height: 8,
                  width: thumbWidth,
                  margin: EdgeInsets.all(2),
                  decoration: BoxDecoration(
                    color: Colors.blueAccent.withOpacity(0.5),
                    borderRadius: BorderRadius.circular(4),
                  ),
                ),
              ),
            ),
          ],
        ),
      ),
    );
  }

