  Widget _buildRightEdgeBar() {
    return Positioned(
      right: 0,
      top: 0,
      bottom: 0,
      child: GestureDetector(
        onVerticalDragUpdate: (details) {
          setState(() {
            // Dragging down on the bar moves the camera "up" (canvas moves down)
            _canvasOffset = Offset(
              _canvasOffset.dx,
              _canvasOffset.dy - details.delta.dy * 2.5,
            );
          });
        },
        child: Container(
          width: 16,
          decoration: BoxDecoration(
            color: const Color(0xFF1E1E1E),
            border: Border(
              left: BorderSide(color: Colors.white.withOpacity(0.05)),
            ),
          ),
          child: Stack(
            alignment: Alignment.center,
            children: [
              // Vertical Track Line
              Container(width: 1, color: Colors.white10),
              // Moving Indicator (Indicator position is bound to coordinate system)
              Positioned(
                top:
                    (MediaQuery.of(context).size.height / 2) +
                    (_canvasOffset.dy / 10).clamp(-200, 200),
                child: Container(
                  width: 4,
                  height: 100,
                  decoration: BoxDecoration(
                    color: Colors.blueAccent,
                    borderRadius: BorderRadius.circular(2),
                    boxShadow: [
                      BoxShadow(
                        color: Colors.blueAccent.withOpacity(0.3),
                        blurRadius: 8,
                      ),
                    ],
                  ),
                ),
              ),
            ],
          ),
        ),
      ),
    );
  }

