  Widget _buildCanvasSelector() {
    return Container(
      width: double.infinity,
      child: Column(
        mainAxisSize: MainAxisSize.min,
        children: [
          // ── Category Group Row ────────────────────────────────────────
          Container(
            padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 9),
            decoration: const BoxDecoration(
              color: Color(0xFF1F1F1F),
              borderRadius: BorderRadius.only(
                topLeft: Radius.circular(8),
                topRight: Radius.circular(8),
              ),
            ),
            child: Row(
              children: [
                Tooltip(
                  message: 'Category Group settings',
                  waitDuration: const Duration(milliseconds: 400),
                  child: GestureDetector(
                    onTap: _currentCategoriesGroupName.isEmpty
                        ? null
                        : () => setState(
                            () =>
                                _showCatGroupSettings = !_showCatGroupSettings,
                          ),
                    child: Icon(
                      Icons.folder_outlined,
                      size: 16,
                      color: _showCatGroupSettings
                          ? Colors.purpleAccent
                          : (_currentCategoriesGroupName.isEmpty
                                ? Colors.white24
                                : Colors.purpleAccent),
                    ),
                  ),
                ),
                const SizedBox(width: 10),
                Expanded(
                  child: _currentCategoriesGroupName.isEmpty
                      ? const Text(
                          'No Category Group',
                          style: TextStyle(
                            color: Colors.white24,
                            fontSize: 11,
                            fontWeight: FontWeight.bold,
                            letterSpacing: 0.5,
                          ),
                        )
                      : TextField(
                          controller: _categoriesGroupNameController,
                          style: const TextStyle(
                            color: Colors.white,
                            fontSize: 11,
                            fontWeight: FontWeight.bold,
                            letterSpacing: 0.5,
                          ),
                          decoration: const InputDecoration(
                            isDense: true,
                            contentPadding: EdgeInsets.symmetric(vertical: 4),
                            border: InputBorder.none,
                          ),
                          onChanged: (val) {
                            if (val.trim().isEmpty) return;
                            setState(() {
                              final oldName = _currentCategoriesGroupName;
                              _currentCategoriesGroupName = val;
                              // Rename the key in the groups map
                              if (_categoriesGroups.containsKey(oldName)) {
                                _categoriesGroups[val] = _categoriesGroups
                                    .remove(oldName)!;
                              }
                            });
                          },
                        ),
                ),
                GestureDetector(
                  onTap: _showSwitchCategoriesGroupDialog,
                  child: const Padding(
                    padding: EdgeInsets.all(4),
                    child: Icon(
                      Icons.swap_horiz_rounded,
                      size: 18,
                      color: Colors.white38,
                    ),
                  ),
                ),
              ],
            ),
          ),
          // ── Current Canvas Row ──────────────────────────────────────────
          Container(
            padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 6),
            decoration: const BoxDecoration(color: Color(0xFF252525)),
            child: Row(
              children: [
                Icon(
                  Icons.layers_outlined,
                  size: 16,
                  color: _currentCanvasName.isEmpty
                      ? Colors.white24
                      : Colors.tealAccent,
                ),
                const SizedBox(width: 10),
                Expanded(
                  child: _currentCanvasName.isEmpty
                      ? const Text(
                          'No Canvas',
                          style: TextStyle(
                            color: Colors.white24,
                            fontSize: 11,
                            fontWeight: FontWeight.bold,
                            letterSpacing: 0.5,
                          ),
                        )
                      : TextField(
                          controller: _canvasNameController,
                          style: const TextStyle(
                            color: Colors.white,
                            fontSize: 11,
                            fontWeight: FontWeight.bold,
                            letterSpacing: 0.5,
                          ),
                          decoration: const InputDecoration(
                            isDense: true,
                            contentPadding: EdgeInsets.symmetric(vertical: 4),
                            border: InputBorder.none,
                          ),
                          onChanged: (val) {
                            setState(() {
                              if (val.trim().isEmpty) return;

                              String oldName = _currentCanvasName;
                              _currentCanvasName = val;

                              // 1. Update list for the selector
                              int idx = _savedCanvases.indexWhere(
                                (c) => c['name'] == oldName,
                              );
                              if (idx != -1) {
                                _savedCanvases[idx]['name'] = val;
                              } else {
                                _savedCanvases.add({'name': val});
                              }

                              // 2. Transfer saved states map key so we don't lose the canvas info
                              if (_canvasStates.containsKey(oldName)) {
                                _canvasStates[val] = _canvasStates.remove(
                                  oldName,
                                )!;
                              }
                            });
                          },
                        ),
                ),
                GestureDetector(
                  onTap: _showSwitchCanvasDialog,
                  child: const Icon(
                    Icons.swap_horiz_rounded,
                    size: 18,
                    color: Colors.white38,
                  ),
                ),
              ],
            ),
          ),
        ],
      ),
    );
  }

  Widget _buildCatGroupSettingsView() {
    return _CatGroupSettingsView(
      key: ValueKey('catgroup-settings:$_currentCategoriesGroupName'),
      groupName: _currentCategoriesGroupName,
      categories: List<String>.from(_sidebarSectionOrder),
      categoryColors: Map<String, Color>.from(_categoryColors),
      categoryEmojis: Map<String, String>.from(_categoryEmojis),
      onShowColorPicker: (initial, onPicked) => _showUnifiedColorPicker(
        title: 'Category Color',
        initialColor: initial,
        showRecentColors: true,
        onApply: onPicked,
      ),
      onRename: (oldName, newName) {
        if (oldName == newName || newName.isEmpty) return;
        setState(() {
          final idx = _sidebarSectionOrder.indexOf(oldName);
          if (idx >= 0) {
            _sidebarSectionOrder[idx] = newName;
          }
          // Migrate categoryMappings key
          if (_categoryMappings.containsKey(oldName)) {
            _categoryMappings[newName] = _categoryMappings.remove(oldName)!;
          }
          // Migrate color/emoji keys
          if (_categoryColors.containsKey(oldName)) {
            _categoryColors[newName] = _categoryColors.remove(oldName)!;
          }
          if (_categoryEmojis.containsKey(oldName)) {
            _categoryEmojis[newName] = _categoryEmojis.remove(oldName)!;
          }
          // Keep filter in sync
          if (_selectedCatFilter == oldName) _selectedCatFilter = newName;
        });
        _saveWorkspace();
      },
      onApply: (colors, emojis) {
        setState(() {
          _categoryColors = colors;
          _categoryEmojis = emojis;
        });
        _saveWorkspace();
      },
      onBack: () => setState(() => _showCatGroupSettings = false),
    );
  }

