  /// Narrow vertical strip showing each category as a coloured circle.
  /// Tap to filter the project list; drag to reorder; hover to see full name.
  /// "Add Category" button is pinned at the bottom.
  Widget _buildCatCirclesSidebar() {
    // Fallback hue-derived color when no explicit color is set.
    Color _defaultColor(String name) {
      final hue = (name.codeUnits.fold(0, (h, c) => h + c) * 37) % 360;
      return HSLColor.fromAHSL(1, hue.toDouble(), 0.55, 0.50).toColor();
    }

    return Container(
      width: 36,
      decoration: const BoxDecoration(
        color: Color(0xFF151515),
        border: Border(right: BorderSide(color: Colors.white10, width: 0.5)),
      ),
      child: Column(
        children: [
          // ── Draggable / tappable circles ──────────────────────────────
          Expanded(
            child: ReorderableListView(
              buildDefaultDragHandles: false,
              padding: const EdgeInsets.symmetric(vertical: 6),
              onReorder: (oldIndex, newIndex) {
                setState(() {
                  if (newIndex > oldIndex) newIndex -= 1;
                  final item = _sidebarSectionOrder.removeAt(oldIndex);
                  _sidebarSectionOrder.insert(newIndex, item);
                });
              },
              children: List.generate(_sidebarSectionOrder.length, (i) {
                final cat = _sidebarSectionOrder[i];

                // Use saved color or fall back to hue-derived color.
                final color = _categoryColors[cat] ?? _defaultColor(cat);

                // Show saved emoji, or abbreviation if none set.
                final emoji = _categoryEmojis[cat] ?? '';
                final String label;
                if (emoji.isNotEmpty) {
                  label = emoji;
                } else {
                  final words = cat.trim().split(RegExp(r'\s+'));
                  label = words.length >= 2
                      ? '${words[0][0]}${words[1][0]}'.toUpperCase()
                      : cat.substring(0, cat.length.clamp(0, 2)).toUpperCase();
                }

                final isSelected = _selectedCatFilter == cat;

                return ReorderableDragStartListener(
                  key: ValueKey('catcircle_$cat'),
                  index: i,
                  child: Tooltip(
                    message: cat,
                    preferBelow: false,
                    verticalOffset: 0,
                    waitDuration: const Duration(milliseconds: 300),
                    child: GestureDetector(
                      onTap: () => setState(() {
                        _selectedCatFilter = isSelected ? null : cat;
                      }),
                      child: Padding(
                        padding: const EdgeInsets.symmetric(vertical: 3),
                        child: Center(
                          child: Container(
                            width: 26,
                            height: 26,
                            decoration: BoxDecoration(
                              color: isSelected
                                  ? color.withOpacity(0.85)
                                  : color.withOpacity(0.20),
                              shape: BoxShape.circle,
                              border: Border.all(
                                color: isSelected
                                    ? color
                                    : color.withOpacity(0.55),
                                width: isSelected ? 2.0 : 1.5,
                              ),
                              boxShadow: isSelected
                                  ? [
                                      BoxShadow(
                                        color: color.withOpacity(0.45),
                                        blurRadius: 6,
                                        spreadRadius: 1,
                                      ),
                                    ]
                                  : null,
                            ),
                            child: Center(
                              child: Text(
                                label,
                                style: TextStyle(
                                  color: isSelected ? Colors.white : color,
                                  // Emoji needs a slightly larger size.
                                  fontSize: emoji.isNotEmpty ? 12 : 9,
                                  fontWeight: FontWeight.bold,
                                  letterSpacing: 0.3,
                                ),
                              ),
                            ),
                          ),
                        ),
                      ),
                    ),
                  ),
                );
              }),
            ),
          ),

          // ── Add Category button pinned at bottom ──────────────────────
          if (_currentCategoriesGroupName.isNotEmpty)
            Tooltip(
              message: 'Add Category',
              waitDuration: const Duration(milliseconds: 300),
              child: InkWell(
                onTap: _showAddCategoryDialog,
                child: SizedBox(
                  width: 36,
                  height: 36,
                  child: Center(
                    child: Icon(
                      Icons.add_circle_outline_rounded,
                      size: 18,
                      color: Colors.blueAccent.withOpacity(0.8),
                    ),
                  ),
                ),
              ),
            ),
        ],
      ),
    );
  }

  /// Narrow vertical strip showing each project as a coloured circle.
  /// Tap to filter the main content to only that project's tasks.
  Widget _buildProjCirclesSidebar() {
    // Hue-derived fallback color when no explicit color is set.
    Color _defaultColor(String name) {
      final hue = (name.codeUnits.fold(0, (h, c) => h + c) * 53) % 360;
      return HSLColor.fromAHSL(1, hue.toDouble(), 0.50, 0.48).toColor();
    }

    // Build the full list: Inbox first, then ordered projects.
    final allIds = <String>['INBOX_PROJECT', ..._projectOrder];

    // Apply search filter.
    final String q = _projSidebarSearchQuery.toLowerCase().trim();
    final filteredIds = q.isEmpty
        ? allIds
        : allIds.where((pid) {
            final title = pid == 'INBOX_PROJECT'
                ? 'Inbox'
                : (_projects[pid]?.title ?? pid);
            return title.toLowerCase().contains(q);
          }).toList();

    return Container(
      width: 36,
      decoration: const BoxDecoration(
        color: Color(0xFF141618),
        border: Border(right: BorderSide(color: Colors.white10, width: 0.5)),
      ),
      child: Column(
        children: [
          // ── Magnifying-glass button ───────────────────────────────────
          Tooltip(
            message: _projSidebarSearchOpen
                ? 'Close search'
                : 'Search projects',
            waitDuration: const Duration(milliseconds: 400),
            child: InkWell(
              onTap: () => setState(() {
                _projSidebarSearchOpen = !_projSidebarSearchOpen;
                if (!_projSidebarSearchOpen) {
                  _projSidebarSearchQuery = '';
                  _projSidebarSearchCtrl.clear();
                }
              }),
              borderRadius: BorderRadius.circular(4),
              child: SizedBox(
                width: 36,
                height: 30,
                child: Center(
                  child: Icon(
                    _projSidebarSearchOpen
                        ? Icons.search_off_rounded
                        : Icons.search_rounded,
                    size: 14,
                    color: _projSidebarSearchOpen
                        ? Colors.tealAccent
                        : (q.isNotEmpty
                              ? Colors.tealAccent.withOpacity(0.7)
                              : Colors.white30),
                  ),
                ),
              ),
            ),
          ),

          // ── Search bar (shown when open) ──────────────────────────────
          AnimatedSize(
            duration: const Duration(milliseconds: 160),
            curve: Curves.easeInOut,
            child: _projSidebarSearchOpen
                ? Container(
                    width: 36,
                    padding: const EdgeInsets.symmetric(
                      horizontal: 4,
                      vertical: 4,
                    ),
                    decoration: const BoxDecoration(
                      border: Border(
                        top: BorderSide(color: Colors.white10, width: 0.5),
                        bottom: BorderSide(color: Colors.white10, width: 0.5),
                      ),
                    ),
                    child: Center(
                      child: SizedBox(
                        width: 28,
                        child: TextField(
                          controller: _projSidebarSearchCtrl,
                          autofocus: true,
                          textAlign: TextAlign.center,
                          style: const TextStyle(
                            color: Colors.white70,
                            fontSize: 10,
                          ),
                          cursorColor: Colors.tealAccent,
                          cursorWidth: 1.2,
                          maxLines: 1,
                          decoration: InputDecoration(
                            isDense: true,
                            contentPadding: const EdgeInsets.symmetric(
                              vertical: 4,
                            ),
                            hintText: '…',
                            hintStyle: TextStyle(
                              color: Colors.white.withOpacity(0.18),
                              fontSize: 10,
                            ),
                            border: InputBorder.none,
                          ),
                          onChanged: (v) =>
                              setState(() => _projSidebarSearchQuery = v),
                        ),
                      ),
                    ),
                  )
                : const SizedBox.shrink(),
          ),

          // ── Divider ───────────────────────────────────────────────────
          Container(height: 0.5, color: Colors.white10),

          // ── Scrollable project circles ────────────────────────────────
          Expanded(
            child: filteredIds.isEmpty
                ? Center(
                    child: Padding(
                      padding: const EdgeInsets.symmetric(vertical: 8),
                      child: Icon(
                        Icons.folder_off_outlined,
                        size: 14,
                        color: Colors.white12,
                      ),
                    ),
                  )
                : ListView.builder(
                    padding: const EdgeInsets.symmetric(vertical: 6),
                    itemCount: filteredIds.length,
                    itemBuilder: (context, i) {
                      final pid = filteredIds[i];
                      final isInbox = pid == 'INBOX_PROJECT';
                      final title = isInbox
                          ? 'Inbox'
                          : (_projects[pid]?.title ?? pid);
                      final color = _projectColors[pid] ?? _defaultColor(title);

                      final words = title.trim().split(RegExp(r'\s+'));
                      final label = words.length >= 2
                          ? '${words[0][0]}${words[1][0]}'.toUpperCase()
                          : title
                                .substring(0, title.length.clamp(0, 2))
                                .toUpperCase();

                      final isSelected = _sidebarSelectedProjectId == pid;

                      return Tooltip(
                        message: title,
                        preferBelow: false,
                        verticalOffset: 0,
                        waitDuration: const Duration(milliseconds: 300),
                        child: GestureDetector(
                          onTap: () => setState(() {
                            _sidebarSelectedProjectId = isSelected ? null : pid;
                          }),
                          child: Padding(
                            padding: const EdgeInsets.symmetric(vertical: 3),
                            child: Center(
                              child: Container(
                                width: 26,
                                height: 26,
                                decoration: BoxDecoration(
                                  color: isSelected
                                      ? color.withOpacity(0.85)
