  // NOTES TAB
  // ══════════════════════════════════════════════════════════════════════════

  static const Color _notesBg = Color(0xFF2E3440); // Nord base
  static const Color _notesSurface = Color(0xFF3B4252); // Nord base1
  static const Color _notesBorder = Color(0xFF3B4252); // Nord divider
  static const Color _notesAccent = Color(0xFF88C0D0); // Nord cyan

  // ── Sync helpers ──────────────────────────────────────────────────────────

  /// Ensures every task and project has a matching Note entry. Call whenever
  /// tasks or projects change and after loading data.
  // ══════════════════════════════════════════════════════════════════════════
  // NOTES  –  File I/O
  // ══════════════════════════════════════════════════════════════════════════

  /// Loads all .md files from the notes directory and rebuilds _notes.
  /// Must be called after a workspace is opened.
  /// Loads all .md files from the per-project directory structure and rebuilds
  /// _notes.  New layout:
  ///   files/<project_safe>/tasks/*.md   -> NoteType.task
  ///   files/<project_safe>/<project title, sanitized>.md  -> NoteType.project
  ///   files/<project_safe>/common/*.md -> NoteType.common (folderId='proj:<id>')
  ///   files/Inbox/tasks/*.md           -> NoteType.task (no project)
  ///   files/Inbox/common/*.md          -> NoteType.common (folderId=null)
  ///
  /// Legacy layout (files/notes/{tasks,projects,common,notes}/*.md) is also
  /// scanned so existing workspaces continue to load without migration.
  Future<void> _loadNotes() async {
    if (_workspaceId.isEmpty) return;
    try {
      // \u2500\u2500 Read sidecar metadata \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500
      final Map<String, dynamic> meta = {};
      final metaFile = File(_notesMetaPath);
      if (await metaFile.exists()) {
        try {
          final decoded =
              jsonDecode(await metaFile.readAsString()) as Map<String, dynamic>;
          if (decoded.containsKey('notes')) {
            meta.addAll(decoded['notes'] as Map<String, dynamic>);
            // folder list no longer used \u2014 project folders are auto-synced
          } else {
            meta.addAll(decoded); // legacy flat format
          }
        } catch (_) {}
      }

      // \u2500\u2500 Build safe-folder-name \u2192 projectId reverse lookup \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500
      final Map<String, String> safeToProjId = {};
      for (final proj in _projects.values) {
        final s = _fsSafe(proj.title);
        if (s.isNotEmpty) safeToProjId[s] = proj.id;
      }
      final filesRoot = _wsFilesDir(_workspaceId);

      final newNotes = <String, Note>{};

      // \u2500\u2500 Helper: parse one .md file into a Note \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500
      Future<void> parseNote(
        File entity,
        NoteType type,
        String? linkedProjectId,
        String? folderId,
      ) async {
        final rawContent = await entity.readAsString();
        String body = rawContent;
        final firstNewline = rawContent.indexOf('\n');
        if (firstNewline > 0) {
          final firstLine = rawContent.substring(0, firstNewline);
          if (firstLine.startsWith('# ')) {
            body = rawContent
                .substring(firstNewline + 1)
                .replaceFirst(RegExp(r'^\n'), '');
          }
        } else if (rawContent.startsWith('# ') && firstNewline < 0) {
          body = '';
        }

        final fileName = entity.uri.pathSegments.last;
        final title = fileName.replaceAll('.md', '').split(' - ').first.trim();

        final relativePath =
            entity.path.substring(filesRoot.length + 1).replaceAll('\\', '/');
        final sideMeta = meta[relativePath] as Map<String, dynamic>? ?? {};
        final noteId =
            sideMeta['id'] as String? ??
            '${type.name}:${DateTime.now().millisecondsSinceEpoch}';
        final linkedTask = sideMeta['linkedTaskId'] as String?;
        final effectiveLinkedProject =
            sideMeta['linkedProjectId'] as String? ?? linkedProjectId;
        final updatedAt = sideMeta['updatedAt'] != null
            ? DateTime.fromMillisecondsSinceEpoch(sideMeta['updatedAt'] as int)
            : (await entity.stat()).modified;
        final effectiveFolderId = sideMeta['folderId'] as String? ?? folderId;
        final collapsedHeadings = sideMeta['collapsedHeadings'] != null
            ? List<String>.from(sideMeta['collapsedHeadings'] as List)
            : <String>[];

        newNotes[noteId] = Note(
          id: noteId,
          type: type,
          title: title,
          content: body,
          linkedTaskId: linkedTask,
          linkedProjectId: effectiveLinkedProject,
          updatedAt: updatedAt,
          folderId: effectiveFolderId,
          collapsedHeadings: collapsedHeadings,
        );
      }

      // \u2500\u2500 Scan inbox at files/Inbox/ \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500
      final inboxDir = Directory('$filesRoot/Inbox');
      if (await inboxDir.exists()) {
        final inboxTasksDir = Directory('$filesRoot/Inbox/tasks');
        if (await inboxTasksDir.exists()) {
          await for (final e in inboxTasksDir.list()) {
            if (e is File && e.path.endsWith('.md')) {
              await parseNote(e, NoteType.task, null, null);
            }
          }
        }
        final inboxCommonDir = Directory('$filesRoot/Inbox/common');
        if (await inboxCommonDir.exists()) {
          await for (final e in inboxCommonDir.list()) {
            if (e is File && e.path.endsWith('.md')) {
              await parseNote(e, NoteType.common, null, null);
            }
          }
        }
      }

      // \u2500\u2500 Scan projects at files/projects/<name>/ \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500
      final projectsRootDir = Directory('$filesRoot/projects');
      if (await projectsRootDir.exists()) {
        await for (final topEntity in projectsRootDir.list()) {
          if (topEntity is! Directory) continue;
          final folderName = topEntity.uri.pathSegments
              .where((s) => s.isNotEmpty)
              .last;
          if (folderName == 'notes') continue;
          final projId = safeToProjId[folderName];
          if (projId == null) continue;

          final folderIdForCommon = 'proj:$projId';

          final tasksDir = Directory('${topEntity.path}/tasks');
          if (await tasksDir.exists()) {
            await for (final e in tasksDir.list()) {
              if (e is File && e.path.endsWith('.md')) {
                await parseNote(e, NoteType.task, projId, null);
              }
            }
          }

          final commonDir = Directory('${topEntity.path}/common');
          if (await commonDir.exists()) {
            await for (final e in commonDir.list()) {
              if (e is File && e.path.endsWith('.md')) {
                await parseNote(e, NoteType.common, projId, folderIdForCommon);
              }
            }
          }

          final fileBase = _projectNoteFileBase(_projects[projId]!.title);
          final projMd = File(
            '${topEntity.path}/${fileBase.isEmpty ? 'untitled' : fileBase}.md',
          );
          if (await projMd.exists()) {
            await parseNote(projMd, NoteType.project, projId, null);
          }
        }
      }

      // \u2500\u2500 Legacy scan: files/notes/{tasks,projects,common,notes}/*.md \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500
      final legacyDir = Directory('$filesRoot/notes');
      if (await legacyDir.exists()) {
        await for (final entity in legacyDir.list(recursive: true)) {
          if (entity is! File || !entity.path.endsWith('.md')) continue;
          final relParts = entity.path
              .substring(legacyDir.path.length + 1)
              .split(Platform.pathSeparator);
          if (relParts.isEmpty) continue;
          NoteType type;
          switch (relParts[0]) {
            case 'tasks':
              type = NoteType.task;
              break;
            case 'projects':
              type = NoteType.project;
              break;
            default:
              type = NoteType.common;
          }
          await parseNote(entity, type, null, null);
        }
      }

      setState(() => _notes.addAll(newNotes));
    } catch (e, st) {
      debugPrint('_loadNotes ERROR: $e\n$st');
    }
  }

  /// Writes a note to its .md file and updates notes_meta.json.
  ///
  /// When [oldPath] is supplied and differs from the note's current target
  /// path (e.g. because the note/task/project was renamed), the existing
  /// file is moved on disk via [File.rename] instead of a brand-new file
  /// being written at the new path and the old one left behind.
  Future<void> _saveNote(Note note, {String? oldPath}) async {
    if (_workspaceId.isEmpty) return;
    try {
      // ── Task notes ──────────────────────────────────────────────────────
      // A task note shares its .md file with the task itself.  Writing only
      // the body would silently destroy the YAML front-matter that holds all
      // task properties.  Delegate to _saveTaskMd so frontmatter + body are
      // always written atomically.
      if (note.type == NoteType.task && note.linkedTaskId != null) {
        final matches =
            _allTasks.where((t) => t.id == note.linkedTaskId).toList();
        if (matches.isEmpty) {
          // Task not loaded (e.g. belongs to a different week).  Fall back to
          // updating the sidecar only — the .md already contains the correct
          // frontmatter from when the task was last saved.
          await _saveNotesMeta();
          return;
        }
        final task = matches.first;

        // Sync note content → task.notes before writing.
        task.notes = note.content.isEmpty ? null : note.content;

        // _saveTaskMd handles rename when oldPath differs from the new path.
        await _saveTaskMd(task, oldPath: oldPath);
        await _saveNotesMeta();
        return;
      }

      // ── Non-task notes: original behaviour ─────────────────────────────
      final filePath = _noteFilePath(note);
      final file = File(filePath);
      await file.parent.create(recursive: true);

      if (oldPath != null && oldPath != filePath) {
        final oldFile = File(oldPath);
        if (await oldFile.exists()) {
          await oldFile.rename(filePath);
        }
      }

      // Spec §1-2: write body only — title lives in the filename and in
      // notes_meta.json.  No '# Title' header is injected.
      await file.writeAsString(note.content);
      await _saveNotesMeta();
    } catch (e) {
      debugPrint('_saveNote ERROR: $e');
    }
  }

  /// Removes a note's .md file and cleans up notes_meta.json.
  Future<void> _deleteNoteFile(Note note) async {
    if (_workspaceId.isEmpty) return;
    try {
      final file = File(_noteFilePath(note));
      if (await file.exists()) await file.delete();
      await _saveNotesMeta();
    } catch (e) {
      debugPrint('_deleteNoteFile ERROR: $e');
    }
  }

  /// Serialises the full _notes map and folder list into notes_meta.json.
  Future<void> _saveNotesMeta() async {
    try {
      final metaFile = File(_notesMetaPath);
      await metaFile.parent.create(recursive: true);

      final notesMap = <String, dynamic>{};
      for (final note in _notes.values) {
        final relativePath = _noteFilePath(
          note,
        ).substring(_wsFilesDir(_workspaceId).length + 1).replaceAll('\\', '/');
        notesMap[relativePath] = {
          'id': note.id,
          'type': note.type.name,
          'linkedTaskId': note.linkedTaskId,
          'linkedProjectId': note.linkedProjectId,
          'updatedAt': note.updatedAt.millisecondsSinceEpoch,
          if (note.folderId != null) 'folderId': note.folderId,
          if (note.collapsedHeadings.isNotEmpty)
            'collapsedHeadings': note.collapsedHeadings,
        };
      }

      final foldersJson = _noteFolders.values
          .map((f) => {'id': f.id, 'name': f.name})
          .toList();

      await metaFile.writeAsString(
        const JsonEncoder.withIndent('  ').convert({
          'notes': notesMap,
          'folders': foldersJson,
          'folderOrder': _noteFolderOrder,
        }),
      );
    } catch (e) {
      debugPrint('_saveNotesMeta ERROR: $e');
    }
  }

  void _syncNotes() {
    // Task notes — title always mirrors task title; content is the .md body.
    for (final t in _allTasks) {
      final noteId = 'task:${t.id}';
      if (_notes.containsKey(noteId)) {
        // Keep title in sync with task name; content was loaded from .md
        final prev = _notes[noteId]!;
        if (prev.title != t.title) {
          final oldPath = _noteFilePath(prev); // capture before title mutates
          prev.title = t.title;
          _saveNote(prev, oldPath: oldPath); // rename .md if title changed
        }
      } else {
        final note = Note(
          id: noteId,
          type: NoteType.task,
          title: t.title,
          content: t.notes ?? '',
          linkedTaskId: t.id,
        );
        _notes[noteId] = note;
        _saveNote(note); // create the .md file for new tasks
      }
    }
    // Remove task notes for deleted tasks
    final deleted = _notes.entries
        .where(
          (e) =>
              e.value.type == NoteType.task &&
              !_allTasks.any((t) => 'task:${t.id}' == e.key),
        )
        .toList();
    for (final e in deleted) {
      _deleteNoteFile(e.value);
      _notes.remove(e.key);
    }

    // Project notes
    for (final entry in _projects.entries) {
      final noteId = 'proj:${entry.key}';
      if (_notes.containsKey(noteId)) {
        final prev = _notes[noteId]!;
        if (prev.title != entry.value.title) {
          final oldPath = _noteFilePath(prev); // capture before title mutates
          prev.title = entry.value.title;
          _saveNote(prev, oldPath: oldPath);
        }
      } else {
        final note = Note(
          id: noteId,
          type: NoteType.project,
          title: entry.value.title,
          content: '',
          linkedProjectId: entry.key,
        );
        _notes[noteId] = note;
        _saveNote(note);
      }
    }
    final deletedProj = _notes.entries
        .where(
          (e) =>
              e.value.type == NoteType.project &&
              !_projects.containsKey(e.value.linkedProjectId),
        )
        .toList();
    for (final e in deletedProj) {
      _deleteNoteFile(e.value);
      _notes.remove(e.key);
    }
  }

  // ── Title bar ─────────────────────────────────────────────────────────────

  Widget _buildNotesTitleBar() {
    // ── Org sub-page title bar ────────────────────────────────────────────
    if (_notesNavSection == 'notes_org_notes') {
      return Row(
        children: [
          const SizedBox(width: 14),
          const Icon(Icons.folder_outlined, size: 14, color: Color(0xFF88C0D0)),
          const SizedBox(width: 8),
          const Expanded(
            child: Text(
              'Notes Folders',
              style: TextStyle(
                fontSize: 12,
                color: Color(0xFF8896AC),
                fontWeight: FontWeight.w500,
              ),
            ),
          ),
          TextButton.icon(
            onPressed: () => setState(() => _notesNavSection = 'editor'),
            icon: const Icon(
              Icons.arrow_back_rounded,
              size: 13,
              color: Colors.white54,
            ),
            label: const Text(
              'Back',
              style: TextStyle(color: Colors.white54, fontSize: 12),
            ),
          ),
          const SizedBox(width: 8),
        ],
      );
    }

    if (_notesNavSection == 'org_projects') {
      return Row(
        children: [
          InkWell(
            onTap: () => setState(() => _notesNavSection = 'editor'),
            borderRadius: BorderRadius.circular(4),
            child: const Padding(
              padding: EdgeInsets.symmetric(horizontal: 8, vertical: 4),
              child: Icon(
                Icons.arrow_back_rounded,
                size: 15,
                color: Colors.white54,
              ),
            ),
          ),
          const SizedBox(width: 4),
          const Icon(Icons.settings_outlined, size: 14, color: Colors.white38),
          const SizedBox(width: 8),
          const Text(
            'Projects Settings',
            style: TextStyle(
              fontSize: 14,
              fontWeight: FontWeight.w600,
              color: Colors.white,
            ),
          ),
          const Spacer(),
        ],
      );
    }

    if (_notesNavSection == 'org_tasks') {
      return Row(
        children: [
          InkWell(
            onTap: () => setState(() => _notesNavSection = 'editor'),
            borderRadius: BorderRadius.circular(4),
            child: const Padding(
              padding: EdgeInsets.symmetric(horizontal: 8, vertical: 4),
              child: Icon(
                Icons.arrow_back_rounded,
                size: 15,
                color: Colors.white54,
              ),
            ),
          ),
          const SizedBox(width: 4),
          const Icon(Icons.settings_outlined, size: 14, color: Colors.white38),
          const SizedBox(width: 8),
          const Text(
            'Tasks Settings',
            style: TextStyle(
              fontSize: 14,
              fontWeight: FontWeight.w600,
              color: Colors.white,
            ),
          ),
          const Spacer(),
        ],
      );
    }

    final note = _activeNoteId != null ? _notes[_activeNoteId] : null;
    Color typeColor = const Color(0xFF88C0D0);
    if (note != null) {
      switch (note.type) {
        case NoteType.task:
          typeColor = const Color(0xFFA3BE8C);
          break;
        case NoteType.project:
          typeColor = const Color(0xFFEBCB8B);
          break;
        case NoteType.common:
          typeColor = const Color(0xFF88C0D0);
          break;
      }
    }

    // Detail panel toggle — only enabled for task/project notes
    final canShowDetail =
        note != null &&
        (note.type == NoteType.task || note.type == NoteType.project);

    // ── Tab bar ──────────────────────────────────────────────────────────────
    Widget tabBar = const SizedBox.shrink();
    if (_openNoteTabs.isNotEmpty) {
      tabBar = SizedBox(
        height: double.infinity,
        // 9g: ReorderableListView enables drag-to-reorder tabs horizontally.
        child: ReorderableListView.builder(
          scrollDirection: Axis.horizontal,
          shrinkWrap: true,
          buildDefaultDragHandles: false,
          onReorder: (oldIdx, newIdx) {
            setState(() {
              if (newIdx > oldIdx) newIdx--;
              final tab = _openNoteTabs.removeAt(oldIdx);
              _openNoteTabs.insert(newIdx, tab);
            });
          },
          itemCount: _openNoteTabs.length,
          itemBuilder: (_, i) {
            final tid = _openNoteTabs[i];
            final tn = _notes[tid];
            final isActive = tid == _activeNoteId;
            return ReorderableDragStartListener(
              key: ValueKey(tid),
              index: i,
              child: GestureDetector(
                onTap: () => setState(() => _activeNoteId = tid),
                child: AnimatedContainer(
                  duration: const Duration(milliseconds: 120),
                  constraints: const BoxConstraints(maxWidth: 160),
                  margin: const EdgeInsets.only(right: 1),
                  padding: const EdgeInsets.symmetric(horizontal: 10),
                  decoration: BoxDecoration(
                    color: isActive
                        ? const Color(0xFF1E2124)
                        : const Color(0xFF161819),
                    border: Border(
                      bottom: BorderSide(
                        color: isActive
                            ? const Color(0xFF4FC3F7)
                            : Colors.transparent,
                        width: 2,
                      ),
                    ),
                  ),
                  child: Row(
                    mainAxisSize: MainAxisSize.min,
                    children: [
                      Flexible(
                        child: Text(
                          tn?.title ?? 'Note',
                          maxLines: 1,
                          overflow: TextOverflow.ellipsis,
                          style: TextStyle(
                            fontSize: 11,
                            color: isActive
                                ? const Color(0xFFECEFF4)
                                : const Color(0xFF6B7080),
                            fontWeight: isActive
                                ? FontWeight.w600
                                : FontWeight.normal,
                          ),
                        ),
                      ),
                      const SizedBox(width: 6),
                      GestureDetector(
                        onTap: () => setState(() {
                          _openNoteTabs.removeAt(i);
                          if (_activeNoteId == tid) {
                            _activeNoteId = _openNoteTabs.isEmpty
                                ? null
                                : _openNoteTabs.last;
                          }
                        }),
                        child: const Icon(
                          Icons.close_rounded,
                          size: 12,
                          color: Color(0xFF4A4F58),
                        ),
                      ),
                    ],
                  ),
                ),
              ),
            );
          },
        ),
      );
    }

    return Row(
      children: [
        const SizedBox(width: 14),
        const Icon(Icons.article_outlined, size: 15, color: Color(0xFF8896AC)),
        const SizedBox(width: 8),
        // Tab bar expands in the middle
        Expanded(child: tabBar),
        if (note != null) ...[
          const SizedBox(width: 8),
          Container(
            padding: const EdgeInsets.symmetric(horizontal: 6, vertical: 2),
            decoration: BoxDecoration(
              color: typeColor.withOpacity(0.12),
              borderRadius: BorderRadius.circular(4),
              border: Border.all(color: typeColor.withOpacity(0.3)),
            ),
            child: Text(
              note.type == NoteType.task
                  ? 'Task'
                  : note.type == NoteType.project
                  ? 'Project'
                  : 'Note',
              style: TextStyle(
                fontSize: 9,
                fontWeight: FontWeight.w600,
                color: typeColor,
                letterSpacing: 0.5,
              ),
            ),
          ),
          const SizedBox(width: 6),
        ],
        // Details panel toggle button
        Tooltip(
          message: canShowDetail
              ? (_notesDetailOpen ? 'Hide details' : 'Show details')
              : 'No details for this note type',
          child: Opacity(
            opacity: canShowDetail ? 1.0 : 0.3,
            child: InkWell(
              onTap: canShowDetail
                  ? () {
                      if (note.type == NoteType.task &&
                          note.linkedTaskId != null) {
                        try {
                          final task = _allTasks.firstWhere(
                            (t) => t.id == note.linkedTaskId,
                          );
                          setState(() {
                            _notesDetailOpen = !_notesDetailOpen;
                            _taskListDetailTask = task;
                            _taskListDetailOpen = _notesDetailOpen;
                            // 9h fix: drive the shared right-sidebar so
                            // TaskDetailsPanel actually appears.
                            _selectedTask = _notesDetailOpen
                                ? task
                                : _selectedTask;
                            _showDetails = _notesDetailOpen;
                          });
                        } catch (_) {}
                      } else {
                        setState(() => _notesDetailOpen = !_notesDetailOpen);
                      }
                    }
                  : null,
              borderRadius: BorderRadius.circular(4),
              child: Container(
                width: 26,
                height: 26,
                decoration: BoxDecoration(
                  color: _notesDetailOpen
                      ? const Color(0xFF4FC3F7).withOpacity(0.15)
                      : Colors.transparent,
                  borderRadius: BorderRadius.circular(4),
                  border: Border.all(
                    color: _notesDetailOpen
                        ? const Color(0xFF4FC3F7).withOpacity(0.4)
                        : Colors.transparent,
                  ),
                ),
                child: Icon(
                  Icons.info_outline_rounded,
                  size: 14,
                  color: _notesDetailOpen
                      ? const Color(0xFF4FC3F7)
                      : const Color(0xFF6B7080),
                ),
              ),
            ),
          ),
        ),
        const SizedBox(width: 8),
      ],
    );
  }

  // ── Sidebar nav content ───────────────────────────────────────────────────

  Widget _buildNotesNavContent() {
    _syncNotes();

    final taskNotes =
        _notes.values.where((n) => n.type == NoteType.task).toList()
          ..sort((a, b) => a.title.compareTo(b.title));
    final projectNotes =
        _notes.values.where((n) => n.type == NoteType.project).toList()
          ..sort((a, b) => a.title.compareTo(b.title));
    final commonNotes =
        _notes.values.where((n) => n.type == NoteType.common).toList()
          ..sort((a, b) => b.updatedAt.compareTo(a.updatedAt));

    return _NotesSidebar(
      taskNotes: taskNotes,
      projectNotes: projectNotes,
      commonNotes: commonNotes,
      activeNoteId: _activeNoteId,
      allTasks: _allTasks,
      noteFolders: _noteFolders,
      filterRules: List<FilterRule>.from(_filterRules),
      sortCriteria: List<SortCriterion>.from(_sortCriteria),
      noteTaskFilterRules: _noteTaskFilterRules,
      noteTaskGroupField: _noteTaskGroupField,
      noteTaskFolderSortCriteria: _notesIsManualActive(true) ? const [] : (_notesActivePreset(true)?.folderCriteria ?? _noteTaskDefaultFolderCriteria),
      noteTaskItemSortCriteria: _notesIsManualActive(true) ? const [] : (_notesActivePreset(true)?.itemCriteria ?? _noteTaskDefaultItemCriteria),
      noteTaskManualActive: _notesIsManualActive(true),
      noteTaskManualOrder: _noteTaskManualOrder,
      onNoteTaskManualReorder: (order) => setState(() => _noteTaskManualOrder = order),
      noteCommonFilterRules: _noteCommonFilterRules,
      noteCommonGroupField: _noteCommonGroupField,
      noteCommonFolderSortCriteria: _notesIsManualActive(false) ? const [] : (_notesActivePreset(false)?.folderCriteria ?? _noteCommonDefaultFolderCriteria),
      noteCommonItemSortCriteria: _notesIsManualActive(false) ? const [] : (_notesActivePreset(false)?.itemCriteria ?? _noteCommonDefaultItemCriteria),
      noteCommonManualActive: _notesIsManualActive(false),
      noteCommonManualOrder: _noteCommonManualOrder,
      onNoteCommonManualReorder: (order) => setState(() => _noteCommonManualOrder = order),
      initialTaskExpanded: _notesSectionTaskExpanded,
      initialProjectExpanded: _notesSectionProjectExpanded,
      initialCommonExpanded: _notesSectionCommonExpanded,
      onTaskExpandedChanged: (v) {
        setState(() => _notesSectionTaskExpanded = v);
        _saveWorkspace();
      },
      onProjectExpandedChanged: (v) {
        setState(() => _notesSectionProjectExpanded = v);
        _saveWorkspace();
      },
      onCommonExpandedChanged: (v) {
        setState(() => _notesSectionCommonExpanded = v);
        _saveWorkspace();
      },
      initialCollapsedNoteTaskFolders: _collapsedNoteTaskFolders,
      initialCollapsedNoteProjectFolders: _collapsedNoteProjectFolders,
      initialCollapsedNoteCommonFolders: _collapsedNoteCommonFolders,
      onNoteTaskFoldersCollapsedChanged: (s) {
        setState(() {
          _collapsedNoteTaskFolders
            ..clear()
            ..addAll(s);
        });
        _saveWorkspace();
      },
      onNoteProjectFoldersCollapsedChanged: (s) {
        setState(() {
          _collapsedNoteProjectFolders
            ..clear()
            ..addAll(s);
        });
        _saveWorkspace();
      },
      onNoteCommonFoldersCollapsedChanged: (s) {
        setState(() {
          _collapsedNoteCommonFolders
            ..clear()
            ..addAll(s);
        });
        _saveWorkspace();
      },
      onSelectNote: (id) => setState(() {
        _activeNoteId = id;
        if (!_openNoteTabs.contains(id)) _openNoteTabs.add(id);
      }),
      onNewNote: ([String? folderKey]) async {
        // folderKey is 'proj_common_<projId>' or '__inbox_common__' or null.
        // Derive the folderId ('proj:<projId>' or null) from it.
        String? folderId;
        if (folderKey != null && folderKey.startsWith('proj_common_')) {
          final projId = folderKey.substring('proj_common_'.length);
          if (_projects.containsKey(projId)) {
            folderId = 'proj:$projId';
          }
        }
        // Spec §4: find the next available "Untitled [N]" title.
        // Checks both in-memory notes (title collision) and the filesystem
        // (file collision) so renaming an old Untitled note doesn't block
        // creation of a new one.
        String candidateTitle = 'Untitled';
        int counter = 0;
        while (true) {
          final titleUsed = _notes.values.any(
            (n) => n.title == candidateTitle && n.type == NoteType.common,
          );
          final candidateNote = Note(
            id: 'tmp',
            type: NoteType.common,
            title: candidateTitle,
            folderId: folderId,
          );
          final filePath = _noteFilePath(candidateNote);
          final fileUsed = File(filePath).existsSync();
          if (!titleUsed && !fileUsed) break;
          counter++;
          candidateTitle = 'Untitled $counter';
        }
        final id = 'common:${DateTime.now().millisecondsSinceEpoch}';
        final note = Note(
          id: id,
          type: NoteType.common,
          title: candidateTitle,
          content: '',
          folderId: folderId,
        );
        _saveNote(note);
        setState(() {
          _notes[id] = note;
          _activeNoteId = id;
        });
      },
      onCreateFolder: (name) async {
        final fid = 'folder:${DateTime.now().millisecondsSinceEpoch}';
        setState(() => _noteFolders[fid] = NoteFolder(id: fid, name: name));
        // Feature 12: create the corresponding directory on disk
        try {
          // Project folders are managed by _syncProjectDirs.
          // User sub-folders land in inbox/common/.
          final folderDir = Directory('$_inboxDir/common/$name');
          if (!await folderDir.exists()) {
            await folderDir.create(recursive: true);
          }
        } catch (e) {
          debugPrint('onCreateFolder mkdir error: $e');
        }
        _saveNotesMeta();
      },
      onAssignFolder: (noteId, folderId) async {
        final note = _notes[noteId];
        if (note == null) return;
        // Capture the old path before mutating folderId.
        final oldPath = _noteFilePath(note);
        setState(() => note.folderId = folderId);
        // Physically move the .md file into the target folder's directory.
        if (note.type == NoteType.common) {
          final targetFolder = folderId != null ? _noteFolders[folderId] : null;
          try {
            final src = File(oldPath);
            final fileName = src.uri.pathSegments.last;
            final destDir = targetFolder != null
                ? '${_projectDir(folderId!.substring(5))}/common'
                : '$_inboxDir/common';
            final destPath = '$destDir/$fileName';
            if (await src.exists() && oldPath != destPath) {
              // Ensure destination directory exists.
              await Directory(destDir).create(recursive: true);
              await src.rename(destPath);
            }
          } catch (e) {
            debugPrint('onAssignFolder file move error: $e');
          }
        }
        _saveNote(note);
      },
      onRenameFolder: (folderId, newName) async {
        final oldFolder = _noteFolders[folderId];
        final oldName = oldFolder?.name ?? '';
        setState(() => _noteFolders[folderId]?.name = newName);
        // 9d: rename the backing directory on disk
        if (oldName.isNotEmpty && newName.isNotEmpty && oldName != newName) {
          try {
            final oldDir = Directory('$_inboxDir/common/$oldName');
            final newDir = Directory('$_inboxDir/common/$newName');
            if (await oldDir.exists()) await oldDir.rename(newDir.path);
          } catch (e) {
            debugPrint('onRenameFolder rename dir error: $e');
          }
        }
        _saveNotesMeta();
      },
      onDeleteFolder: (folderId) async {
        final folder = _noteFolders[folderId];
        final folderName = folder?.name ?? '';
        setState(() {
          _noteFolders.remove(folderId);
          for (final n in _notes.values) {
            if (n.folderId == folderId) n.folderId = null;
          }
        });
        // 9d: move contained files back to the root notes dir, then delete dir.
        if (folderName.isNotEmpty) {
          try {
            final folderDir = Directory('$_inboxDir/common/$folderName');
            final rootNotesDir = Directory('$_inboxDir/common');
            if (await folderDir.exists()) {
              await for (final entity in folderDir.list()) {
                if (entity is File) {
                  final dest =
                      '${rootNotesDir.path}/${entity.uri.pathSegments.last}';
                  await entity.copy(dest);
                  await entity.delete();
                }
              }
              await folderDir.delete();
            }
          } catch (e) {
            debugPrint('onDeleteFolder rmdir error: $e');
          }
        }
        _saveNotesMeta();
      },
      onFilterGroupSort: (scope) => setState(() {
        _filterSidebarTitle = scope;
        _filterSidebarOpen = true;
      }),

      tagColors: _tagColors,
      onNoteTaskAction: (action, task, ctx) async {
        final now = DateTime.now();
        final today = DateTime(now.year, now.month, now.day);

        if (action.startsWith('tag_toggle:')) {
          final tagId = action.split(':').last;
          setState(() {
            if (task.tagIds.contains(tagId))
              task.tagIds.remove(tagId);
            else
              task.tagIds.add(tagId);
          });
          _saveTaskToMeta(task);
          return;
        }
        if (action.startsWith('move:')) {
          final projId = action.split(':').last;
          final moved = Task(
            id: task.id,
            title: task.title,
            isDone: task.isDone,
            status: task.status,
            projectId: projId,
            subTaskIds: task.subTaskIds,
            timeSpent: task.timeSpent,
            dueDay: task.dueDay,
            durationMinutes: task.durationMinutes,
            attachments: task.attachments,
            tagIds: task.tagIds,
            notes: task.notes,
          );
          setState(() {
            final idx = _allTasks.indexOf(task);
            if (idx >= 0) _allTasks[idx] = moved;
          });
          _saveTaskToMeta(moved);
          return;
        }

        switch (action) {
          case 'sched_today':
            setState(
              () => task.dueDay = today.toIso8601String().split('T').first,
            );
            _saveTaskToMeta(task);
            break;
          case 'sched_tomorrow':
            final tmr = today.add(const Duration(days: 1));
            setState(
              () => task.dueDay = tmr.toIso8601String().split('T').first,
            );
            _saveTaskToMeta(task);
            break;
          case 'sched_nextweek':
            final nw = today.add(Duration(days: 8 - today.weekday));
            setState(() => task.dueDay = nw.toIso8601String().split('T').first);
            _saveTaskToMeta(task);
            break;
          case 'sched_reschedule':
            final pickedDate = await showDatePicker(
              context: ctx,
              initialDate: task.dueDay != null
                  ? (DateTime.tryParse(task.dueDay!) ?? today)
                  : today,
              firstDate: today,
              lastDate: today.add(const Duration(days: 365 * 5)),
              builder: (c, child) => Theme(
                data: Theme.of(c).copyWith(
                  colorScheme: const ColorScheme.dark(
                    primary: Color(0xFF4FC3F7),
                    surface: Color(0xFF1E2124),
                  ),
                ),
                child: child!,
              ),
            );
            if (pickedDate != null && mounted) {
              final pickedTime = await showTimePicker(
                context: ctx,
                initialTime: task.plannedAt != null
                    ? TimeOfDay.fromDateTime(
                        DateTime.fromMillisecondsSinceEpoch(task.plannedAt!),
                      )
                    : TimeOfDay.now(),
                builder: (c, child) => Theme(
                  data: Theme.of(c).copyWith(
                    colorScheme: const ColorScheme.dark(
                      primary: Color(0xFF4FC3F7),
                      surface: Color(0xFF1E2124),
                    ),
                    timePickerTheme: const TimePickerThemeData(
                      backgroundColor: Color(0xFF1E2124),
                    ),
                  ),
                  child: child!,
                ),
              );
              setState(() {
                task.dueDay = pickedDate.toIso8601String().split('T').first;
                if (pickedTime != null) {
                  task.plannedAt = DateTime(
                    pickedDate.year,
                    pickedDate.month,
                    pickedDate.day,
                    pickedTime.hour,
                    pickedTime.minute,
                  ).millisecondsSinceEpoch;
                }
              });
              _saveTaskToMeta(task);
            }
            break;
          case 'sched_unschedule':
            setState(() => task.dueDay = null);
            _saveTaskToMeta(task);
            break;
          case 'start_focus':
            _showFocusPopup();
            break;
          case 'details':
            setState(() {
              _taskListDetailTask = task;
              _taskListDetailOpen = true;
            });
            break;
          case 'duplicate':
            final dup = Task(
              id: DateTime.now().millisecondsSinceEpoch.toString(),
              title: '${task.title} (copy)',
              isDone: false,
              status: TaskStatus.none,
              projectId: task.projectId,
              subTaskIds: [],
              timeSpent: 0,
              dueDay: task.dueDay,
              durationMinutes: task.durationMinutes,
              attachments: [],
              tagIds: List.from(task.tagIds),
              notes: task.notes,
            );
            setState(() {
              final idx = _allTasks.indexOf(task);
              _allTasks.insert(idx >= 0 ? idx + 1 : _allTasks.length, dup);
            });
            _saveTaskToMeta(dup);
            break;
          case 'subtask':
            await _showTaskContextMenu(ctx, task, Offset.zero);
            break;
          case 'convert_to_parent':
            setState(() {
              for (final t in _allTasks) {
                if (t.subTaskIds.any((id) => id.toString() == task.id)) {
                  t.subTaskIds.remove(task.id);
                  _saveTaskToMeta(t);
                }
              }
            });
            break;
          case 'delete':
            setState(() {
              final subIds = List<String>.from(
                task.subTaskIds.map((s) => s.toString()),
              );
              _allTasks.removeWhere((t) => subIds.contains(t.id));
              _clearRepeatInstances(task.id);
              for (final t in _allTasks) {
                if (t.subTaskIds.any((id) => id.toString() == task.id)) {
                  t.subTaskIds.remove(task.id);
                  _saveTaskToMeta(t);
                }
              }
              _allTasks.remove(task);
            });
            _saveTaskToMeta(task);
            break;
        }
      },

      // 9f: delete a note from the sidebar right-click context menu
      onDeleteNote: (noteId) async {
        final note = _notes[noteId];
        if (note == null) return;
        await _deleteNoteFile(note);
        setState(() {
          _notes.remove(noteId);
          _openNoteTabs.remove(noteId);
          if (_activeNoteId == noteId) {
            _activeNoteId = _openNoteTabs.isEmpty ? null : _openNoteTabs.last;
          }
        });
      },
      // 9e: persist note order after drag-to-reorder; also handles
      // '__commonFolderOrder__' prefix for folder reordering.
      onReorderNotes: (orderedIds) {
        if (orderedIds.isNotEmpty && orderedIds.first == '__commonFolderOrder__') {
          setState(() => _noteCommonFolderOrder = orderedIds.skip(1).toList());
          _saveWorkspace();
        } else {
          _saveNotesMeta();
        }
      },
      // Parity: task/project note reordering
      onReorderProjectNotes: (orderedIds) {
        // The Notes sidebar sends a '__folderOrder__' prefix when the user
        // reorders folder groups rather than individual notes.
        if (orderedIds.isNotEmpty && orderedIds.first == '__folderOrder__') {
          setState(() => _projectFolderOrder = orderedIds.skip(1).toList());
        } else {
          setState(() => _noteProjectOrder = orderedIds);
        }
        _saveWorkspace();
      },
      onReorderTaskNotes: (orderedIds) {
        // '__taskFolderOrder__' prefix means the Notes sidebar reordered
        // task-note folder groups — update _projectFolderOrder, same as
        // the Projects section does with '__folderOrder__'.
        if (orderedIds.isNotEmpty &&
            orderedIds.first == '__taskFolderOrder__') {
          setState(() => _projectFolderOrder = orderedIds.skip(1).toList());
        } else {
          setState(() => _noteTaskOrder = orderedIds);
        }
        _saveWorkspace();
      },
      // Parity: visibility toggles
      onToggleProjectVisibility: (linkedId) {
        setState(() {
          _projectHiddenFromMenu[linkedId] =
              !(_projectHiddenFromMenu[linkedId] ?? false);
        });
        _saveWorkspace();
      },
      onToggleTaskVisibility: (linkedId) {
        setState(() {
          if (_hiddenNoteTasks.contains(linkedId)) {
            _hiddenNoteTasks.remove(linkedId);
          } else {
            _hiddenNoteTasks.add(linkedId);
          }
        });
        _saveWorkspace();
      },
      // Parity: pass current hidden sets and order lists
      hiddenNoteProjects: _projectHiddenFromMenu.entries
          .where((e) => e.value)
          .map((e) => e.key)
          .toSet(),
      hiddenNoteTasks: _hiddenNoteTasks,
      noteProjectOrder: _noteProjectOrder,
      noteTaskOrder: _noteTaskOrder,
      noteCommonFolderOrder: _noteCommonFolderOrder,
      // Projects header buttons
      onAddProject: _showCreateProjectDialog,
      // Settings gear → projects settings replaces the notes region (stays in Notes tab)
      onProjectSettings: () =>
          setState(() => _notesNavSection = 'org_projects'),
      onTaskSettings: () => setState(() => _notesNavSection = 'org_tasks'),
      // Notes section: gear button → folder settings sub-page
      onNotesSettings: () =>
          setState(() => _notesNavSection = 'notes_org_notes'),
      // Note-folder order (independent from projectFolderOrder)
      noteFolderOrder: _noteFolderOrder,
      onReorderNoteFolders: (orderedIds) {
        setState(() => _noteFolderOrder = orderedIds);
        _saveNotesMeta();
      },
      // Project-folder parity — same references as the Tasks sidebar uses.
      projectFolders: _projectFolders,
      projectFolderOrder: _projectFolderOrder,
      projects: _projects,
      projectHiddenFromMenu: _projectHiddenFromMenu,
      // Right-click on a project note → same popup as Tasks sidebar projects.
      onNoteProjectContextMenu: (details, projectId) {
        final projColor = _projectColors[projectId];
        final textColor = projColor != null
            ? (projColor.computeLuminance() > 0.5
                  ? Colors.black87
                  : Colors.white)
            : Colors.white.withOpacity(0.88);
        final iconColor = projColor != null ? textColor : Colors.white24;
        _showProjectFolderMenu(
          details: details,
          projectId: projectId,
          projColor: projColor,
          textColor: textColor,
          iconColor: iconColor,
        );
      },
      // ── Persons section wiring ──────────────────────────────────────────
      personPaths: _workspaceId.isEmpty ? const [] : [
        ...(_visualizerChildren['person'] ?? []).map((e) => 'person/$e'),
      ],
      personsFilesRoot: _workspaceId.isNotEmpty ? _genRoot : '',
      onOpenPersonFile: (absolutePath) async {
        // Read the file and open it as a note in Notes view.
        try {
          final file = File(absolutePath);
          if (!await file.exists()) return;
          final raw = await file.readAsString();
          final fileName = absolutePath.split('/').last;
          final title = fileName.replaceAll('.md', '');
          // Use a stable id based on path so re-opening same file reuses tab.
          final noteId = 'person_file:${absolutePath.hashCode.abs()}';
          final note = Note(
            id: noteId,
            type: NoteType.common,
            title: title,
            content: raw,
          );
          setState(() {
            _notes[noteId] = note;
            if (!_openNoteTabs.contains(noteId)) _openNoteTabs.add(noteId);
            _activeNoteId = noteId;
            _isNotesView = true;
            _notesNavSection = 'editor';
          });
        } catch (e) {
          debugPrint('onOpenPersonFile error: $e');
        }
      },
    );
  }

  // ── Main area ─────────────────────────────────────────────────────────────

  Widget _buildNotesMainArea() {
    _syncNotes();
    // Sub-page routing: settings page for Notes folders
    if (_notesNavSection == 'notes_org_notes') {
      return _buildNotesOrgNotesView();
    }
    // Sub-page routing: Projects Settings rendered in the notes region
    if (_notesNavSection == 'org_projects') {
      return _buildOrgView(
        isProjects: true,
        onBack: () => setState(() => _notesNavSection = 'editor'),
      );
    }
    // Sub-page routing: Tasks Settings rendered in the notes region
    if (_notesNavSection == 'org_tasks') {
      return _buildNotesOrgTasksView(
        onBack: () => setState(() => _notesNavSection = 'editor'),
      );
    }
    final note = _activeNoteId != null ? _notes[_activeNoteId] : null;

    return _NotesEditor(
      key: ValueKey(_activeNoteId ?? '__empty__'),
      note: note,
      projects: _projects,
      projectIcons: _projectIcons,
      allTasks: _allTasks,
      isTitleTaken: (newTitle, currentId) => _notes.values.any(
        (n) =>
            n.type == NoteType.common &&
            n.id != currentId &&
            n.title.trim() == newTitle.trim(),
      ),
      onNoteChanged: (updatedNote, {String? oldTitle}) {
        // Save content to .md file (source of truth for all note types).
        // If the title changed, reconstruct the path it used to live at so
        // _saveNote can rename the existing file instead of creating a new
        // one and leaving the old one behind.
        String? oldPath;
        if (oldTitle != null && oldTitle != updatedNote.title) {
          final currentTitle = updatedNote.title;
          updatedNote.title = oldTitle;
          oldPath = _noteFilePath(updatedNote);
          updatedNote.title = currentTitle;
        }
        _saveNote(updatedNote, oldPath: oldPath);
        // For task notes: also keep task.notes in sync so the Task Details
        // panel and SP export still see the latest description.
        if (updatedNote.linkedTaskId != null) {
          final idx = _allTasks.indexWhere(
            (t) => t.id == updatedNote.linkedTaskId,
          );
          if (idx >= 0) {
            _allTasks[idx].notes = updatedNote.content.isEmpty
                ? null
                : updatedNote.content;
            _saveTaskToMeta(_allTasks[idx]);
          }
        }
        // Update in-memory map without full setState to avoid editor rebuild
        _notes[updatedNote.id] = updatedNote;
      },
      onDeleteNote:
          _activeNoteId != null &&
              (_notes[_activeNoteId]?.type == NoteType.common)
          ? () {
              final note = _notes[_activeNoteId];
              if (note != null) _deleteNoteFile(note);
              setState(() {
                _notes.remove(_activeNoteId);
                _activeNoteId = null;
              });
            }
          : null,
      onFoldsChanged: (noteId, headings) {
        // Update the in-memory note and persist to notes_meta.json only —
        // no .md rewrite needed since fold state is sidecar-only.
        final target = _notes[noteId];
        if (target != null) {
          target.collapsedHeadings = headings;
          _saveNotesMeta();
        }
      },
    );
  }

  // ══════════════════════════════════════════════════════════════════════════
  // TASKS TAB
  // ══════════════════════════════════════════════════════════════════════════

  static const Color _tasksAccent = Color(0xFF4FC3F7); // light blue highlight
  static const Color _tasksBg = Color(0xFF181A1B);
  static const Color _tasksSurface = Color(0xFF212426);
  static const Color _tasksBorder = Color(0xFF2C2F32);

  /// Ensures [color] is legible on a dark background — delegates to top-level helper.
  static Color _ensureVisible(Color color) => ensureAccentVisible(color);

  /// Returns the project color for the current nav section, falling back to
  /// the default Tasks accent so all project views are themed consistently.
  /// The returned color is always legible on dark backgrounds.
  Color get _activeProjectAccent {
    String? pid;
    final s = _tasksNavSection;
    if (s.startsWith('proj:')) {
      pid = s.substring(5);
    } else if (s.startsWith('metrics:proj:')) {
      pid = s.substring(13);
    } else if (s.startsWith('worklog:proj:')) {
      pid = s.substring(13);
    } else if (s.startsWith('quick_history:proj:')) {
      pid = s.substring(19);
    } else if (s.startsWith('settings:proj:')) {
      pid = s.substring(14);
    }
    if (pid != null) {
      final c = _projectColors[pid];
      if (c != null) return _ensureVisible(c);
    }
    // Check per-view accent for Today / Inbox (and their sub-sections)
    for (final viewId in ['Today', 'Inbox']) {
      if (s == viewId ||
          s == 'settings:$viewId' ||
          s == 'quick_history:$viewId' ||
          s == 'worklog:$viewId' ||
          s == 'metrics:$viewId') {
        final c = _viewColors[viewId];
        if (c != null) return _ensureVisible(c);
      }
    }
    return _tasksAccent;
  }

  /// Left sidebar navigation for the Tasks tab.

  Widget _buildPlannerTitleBar() {
    // Human-readable label for the current color mode button.
    String _colorModeLabel(String mode) {
      switch (mode) {
        case 'status':  return 'Color by Status';
        case 'none':    return 'No Color';
        case 'custom':  return 'Custom';
        default:        return 'Color by Project';
      }
    }

    final modeLabel = _colorModeLabel(_plannerCardColorMode);
    // Button accent: dim white normally, highlighted blue when non-default.
    final btnColor = (_plannerCardColorMode == 'project')
        ? Colors.white38
        : const Color(0xFF4FC3F7);

    return Padding(
      padding: const EdgeInsets.symmetric(horizontal: 16),
      child: Row(
        children: [
          const Icon(Icons.view_week_outlined, size: 15, color: Colors.white54),
          const SizedBox(width: 8),
          const Text(
            'Planner',
            style: TextStyle(
              fontSize: 14,
              fontWeight: FontWeight.w600,
              color: Colors.white,
              letterSpacing: 0.3,
            ),
          ),
          const Spacer(),
          // ── Planner Filter / Sort button ────────────────────────────────
          Builder(builder: (context) {
            final totalRules =
                _plannerFilterRules.where((r) => r.isConfigured).length +
                _plannerSortCriteria.length;
            final isActive = _plannerFilterOpen || totalRules > 0;
            return Stack(
              clipBehavior: Clip.none,
              children: [
                Tooltip(
                  message: 'Filter / Sort',
                  child: GestureDetector(
                    onTap: () => setState(() {
                      _plannerFilterOpen = !_plannerFilterOpen;
                    }),
                    child: Container(
                      padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 4),
                      decoration: BoxDecoration(
                        color: isActive
                            ? const Color(0xFF4FC3F7).withOpacity(0.12)
                            : Colors.white.withOpacity(0.05),
                        borderRadius: BorderRadius.circular(6),
                        border: Border.all(
                          color: isActive
                              ? const Color(0xFF4FC3F7).withOpacity(0.4)
                              : Colors.white.withOpacity(0.1),
                        ),
                      ),
                      child: Row(
                        mainAxisSize: MainAxisSize.min,
                        children: [
                          Icon(
                            Icons.filter_list,
                            size: 13,
                            color: isActive
                                ? const Color(0xFF4FC3F7)
                                : Colors.white54,
                          ),
                          const SizedBox(width: 5),
                          Text(
                            'Filter / Sort',
                            style: TextStyle(
                              fontSize: 11,
                              fontWeight: FontWeight.w600,
                              color: isActive
                                  ? const Color(0xFF4FC3F7)
                                  : Colors.white54,
                            ),
                          ),
                        ],
                      ),
                    ),
                  ),
                ),
                if (totalRules > 0)
                  Positioned(
                    top: 2,
                    right: 2,
                    child: Container(
                      width: 14,
                      height: 14,
                      decoration: const BoxDecoration(
                        color: Color(0xFF4FC3F7),
                        shape: BoxShape.circle,
                      ),
                      child: Center(
                        child: Text(
                          '$totalRules',
                          style: const TextStyle(
                            fontSize: 8,
                            fontWeight: FontWeight.w700,
                            color: Colors.black,
                          ),
                        ),
                      ),
                    ),
                  ),
              ],
            );
          }),
          const SizedBox(width: 8),
          // ── Card Color Mode picker ──────────────────────────────────
          PopupMenuButton<String>(
            tooltip: 'Card Color Mode',
            onSelected: (val) {
              setState(() {
                if (val == 'custom') {
                  // Restore the last saved custom snapshot (if any).
                  // If there is no snapshot yet, this is a no-op — Custom
                  // only becomes meaningful once columns have diverged.
                  if (_plannerSavedCustomModes.isNotEmpty) {
                    _plannerColColorModes = Map.of(_plannerSavedCustomModes);
                    _plannerCardColorMode = 'custom';
                  }
                } else {
                  // Switching to a uniform mode: persist current custom
                  // overrides so they can be restored later, then clear.
                  if (_plannerCardColorMode == 'custom' &&
                      _plannerColColorModes.isNotEmpty) {
                    _plannerSavedCustomModes = Map.of(_plannerColColorModes);
                  }
                  _plannerCardColorMode = val;
                  _plannerColColorModes = {};
                }
              });
            },
            itemBuilder: (ctx) {
              PopupMenuEntry<String> item(String value, String label) {
                final selected = _plannerCardColorMode == value;
                return PopupMenuItem<String>(
                  value: value,
                  // 'custom' is tappable only when there is a saved snapshot to restore.
                  enabled: value != 'custom' || _plannerSavedCustomModes.isNotEmpty,
                  child: Row(
                    children: [
                      SizedBox(
                        width: 16,
                        child: selected
                            ? const Icon(Icons.check,
                                size: 13, color: Color(0xFF4FC3F7))
                            : null,
                      ),
                      const SizedBox(width: 6),
                      Text(
                        label,
                        style: TextStyle(
                          fontSize: 13,
                          color: (value == 'custom' && !selected)
                              ? Colors.white38
                              : Colors.white,
                        ),
                      ),
                    ],
                  ),
                );
              }
              return <PopupMenuEntry<String>>[
                item('project', 'Color by Project'),
                item('status',  'Color by Status'),
                item('none',    'No Color'),
                const PopupMenuDivider(),
                item('custom',  'Custom'),
              ];
            },
            child: Container(
              padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 4),
              decoration: BoxDecoration(
                color: btnColor.withOpacity(0.08),
                borderRadius: BorderRadius.circular(6),
                border: Border.all(color: btnColor.withOpacity(0.25)),
              ),
              child: Row(
                mainAxisSize: MainAxisSize.min,
                children: [
                  Icon(Icons.palette_outlined, size: 13, color: btnColor),
                  const SizedBox(width: 5),
                  Text(
                    modeLabel,
                    style: TextStyle(
                      fontSize: 11,
                      fontWeight: FontWeight.w600,
                      color: btnColor,
                      letterSpacing: 0.1,
                    ),
                  ),
                  const SizedBox(width: 3),
                  Icon(Icons.expand_more, size: 13, color: btnColor.withOpacity(0.7)),
                ],
              ),
            ),
          ),
        ],
      ),
    );
  }

  // ── Planner Filter / Sort panel ────────────────────────────────────────────
  Widget _buildPlannerFilterPanel() {
    if (!_plannerFilterOpen) return const SizedBox.shrink();

    const accent = Color(0xFF4FC3F7);
    const bg = Color(0xFF1A1C1F);
    const surface = Color(0xFF22252A);
    const border = Color(0xFF2C2F35);

    final allTags = {
      for (final t in _allTasks) ...t.tagIds.map((id) => id.toString()),
    }.toList()..sort();
    final allProjects = _projects.entries.toList();

    // ── shared helpers ──────────────────────────────────────────────────────
    Widget sectionHeader(
      String title,
      VoidCallback onClearAll,
      bool collapsed,
      VoidCallback onToggle,
    ) {
      return GestureDetector(
        onTap: onToggle,
        child: Padding(
          padding: const EdgeInsets.fromLTRB(10, 10, 10, 6),
          child: Row(
            children: [
              AnimatedRotation(
                turns: collapsed ? -0.25 : 0,
                duration: const Duration(milliseconds: 150),
                child: const Icon(
                  Icons.expand_more_rounded,
                  size: 14,
                  color: Colors.white38,
                ),
              ),
              const SizedBox(width: 6),
              Text(
                title,
                style: const TextStyle(
                  fontSize: 10,
                  fontWeight: FontWeight.w700,
                  letterSpacing: 1.0,
                  color: Colors.white60,
                ),
              ),
              const Spacer(),
              GestureDetector(
                onTap: onClearAll,
                child: const Text(
                  'Clear All',
                  style: TextStyle(fontSize: 9, color: accent),
                ),
              ),
            ],
          ),
        ),
      );
    }

    Widget fieldDropdown<T>({
      required T value,
      required List<T> items,
      required String Function(T) label,
      required void Function(T) onChanged,
    }) {
      return GestureDetector(
        onTap: () => showDialog<T>(
          context: context,
          barrierColor: Colors.transparent,
          builder: (_) => _DropdownDialog<T>(
            current: value,
            items: items,
            itemLabel: label,
            onSelected: (v) {
              onChanged(v);
              Navigator.of(context).pop();
            },
          ),
        ),
        child: Container(
          padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 6),
          decoration: BoxDecoration(
            color: surface,
            borderRadius: BorderRadius.circular(5),
            border: Border.all(color: border),
          ),
          child: Row(
            mainAxisSize: MainAxisSize.min,
            children: [
              Flexible(
                child: Text(
                  label(value),
                  overflow: TextOverflow.ellipsis,
                  style: const TextStyle(fontSize: 11, color: Colors.white70),
                ),
              ),
              const SizedBox(width: 4),
              const Icon(Icons.expand_more_rounded, size: 12, color: Colors.white38),
            ],
          ),
        ),
      );
    }

    Widget removeBtn(VoidCallback onTap) => GestureDetector(
      onTap: onTap,
      child: const Padding(
        padding: EdgeInsets.only(left: 4),
        child: Icon(Icons.close_rounded, size: 14, color: Colors.white30),
      ),
    );

    Widget dirBtn(bool asc, void Function(bool) onTap) {
      return GestureDetector(
        onTap: () => onTap(!asc),
        child: Container(
          padding: const EdgeInsets.symmetric(horizontal: 6, vertical: 5),
          decoration: BoxDecoration(
            color: accent.withOpacity(0.12),
            borderRadius: BorderRadius.circular(4),
            border: Border.all(color: accent.withOpacity(0.3)),
          ),
          child: Text(
            asc ? '↑ Asc' : '↓ Desc',
            style: const TextStyle(
              fontSize: 9,
              color: accent,
              fontWeight: FontWeight.w600,
            ),
          ),
        ),
      );
    }

    // ── Filter value widget per rule ─────────────────────────────────────────
    Widget filterValueWidget(FilterRule rule) {
      switch (rule.field) {
        case TaskFilterField.none:
          return const SizedBox.shrink();

        case TaskFilterField.name:
          return _NameFilterField(
            initialValue: rule.nameQuery,
            onChanged: (v) => setState(() => rule.nameQuery = v),
          );

        case TaskFilterField.tag:
        case TaskFilterField.project:
        case TaskFilterField.status:
          final items = rule.field == TaskFilterField.tag
              ? allTags
              : rule.field == TaskFilterField.project
                  ? allProjects.map((e) => e.key).toList()
                  : TaskStatus.values.map((s) => s.name).toList();
          String labelFor(String v) {
            if (rule.field == TaskFilterField.project) {
              return _projects[v]?.title ?? v;
            }
            if (rule.field == TaskFilterField.status) {
              try {
                return TaskStatus.values.byName(v).label;
              } catch (_) {
                return v;
              }
            }
            return v;
          }
          return Column(
            crossAxisAlignment: CrossAxisAlignment.stretch,
            children: [
              ...items.map((v) {
                final checked = rule.selectedValues.contains(v);
                return GestureDetector(
                  onTap: () => setState(() {
                    if (checked)
                      rule.selectedValues.remove(v);
                    else
                      rule.selectedValues.add(v);
                  }),
                  child: Padding(
                    padding: const EdgeInsets.symmetric(vertical: 3),
                    child: Row(
                      children: [
                        AnimatedContainer(
                          duration: const Duration(milliseconds: 100),
                          width: 14,
                          height: 14,
                          decoration: BoxDecoration(
                            color: checked
                                ? accent.withOpacity(0.2)
                                : Colors.transparent,
                            borderRadius: BorderRadius.circular(3),
                            border: Border.all(
                              color: checked ? accent : Colors.white30,
                              width: 1.2,
                            ),
                          ),
                          child: checked
                              ? const Icon(Icons.check_rounded,
                                  size: 10, color: accent)
                              : null,
                        ),
                        const SizedBox(width: 8),
                        if (rule.field == TaskFilterField.status) ...[
                          Builder(builder: (_) {
                            try {
                              final s = TaskStatus.values.byName(v);
                              return Row(children: [
                                Icon(s.icon, size: 11, color: s.color),
                                const SizedBox(width: 4),
                              ]);
                            } catch (_) {
                              return const SizedBox.shrink();
                            }
                          }),
                        ],
                        Expanded(
                          child: Text(
                            labelFor(v),
                            style: TextStyle(
                              fontSize: 11,
                              color: checked ? Colors.white : Colors.white60,
                            ),
                          ),
                        ),
                      ],
                    ),
                  ),
                );
              }),
            ],
          );

        case TaskFilterField.repeating:
          final repOptions = [
            {'value': 'repeating', 'label': 'Repeating'},
            {'value': 'nonRepeating', 'label': 'Non-Repeating'},
          ];
          return Column(
            crossAxisAlignment: CrossAxisAlignment.stretch,
            children: repOptions.map((opt) {
              final value = opt['value'] as String;
              final label = opt['label'] as String;
              final checked = rule.selectedValues.contains(value);
              return GestureDetector(
                onTap: () => setState(() {
                  if (checked)
                    rule.selectedValues.remove(value);
                  else
                    rule.selectedValues.add(value);
                }),
                child: Padding(
                  padding: const EdgeInsets.symmetric(vertical: 3),
                  child: Row(
                    children: [
                      AnimatedContainer(
                        duration: const Duration(milliseconds: 100),
                        width: 14,
                        height: 14,
                        decoration: BoxDecoration(
                          color: checked ? accent.withOpacity(0.2) : Colors.transparent,
                          borderRadius: BorderRadius.circular(3),
                          border: Border.all(
                            color: checked ? accent : Colors.white30,
                            width: 1.2,
                          ),
                        ),
                        child: checked
                            ? const Icon(Icons.check_rounded, size: 10, color: accent)
                            : null,
                      ),
                      const SizedBox(width: 8),
                      Text(
                        label,
                        style: TextStyle(
                          fontSize: 11,
                          color: checked ? Colors.white : Colors.white60,
                        ),
                      ),
                    ],
                  ),
                ),
              );
            }).toList(),
          );

        case TaskFilterField.scheduledDate:
        case TaskFilterField.insertionDate:
          Future<void> pickDate(bool isFrom) async {
            final picked = await showDatePicker(
              context: context,
              initialDate: (isFrom ? rule.dateFrom : rule.dateTo) ?? DateTime.now(),
              firstDate: DateTime(2020),
              lastDate: DateTime(2099),
              builder: (ctx, child) => Theme(
                data: Theme.of(ctx).copyWith(
                  colorScheme: const ColorScheme.dark(
                    primary: accent,
                    surface: Color(0xFF1E2124),
                    onSurface: Colors.white,
                  ),
                  dialogBackgroundColor: const Color(0xFF1E2124),
                ),
                child: child!,
              ),
            );
            if (picked == null) return;
            setState(() {
              if (isFrom)
                rule.dateFrom = picked;
              else
                rule.dateTo = picked;
            });
          }

          String fmtDate(DateTime? d) =>
              d == null ? 'Any' : '${d.day}/${d.month}/${d.year}';

          return Column(
            crossAxisAlignment: CrossAxisAlignment.stretch,
            children: [
              Row(
                children: [
                  const Text('From', style: TextStyle(fontSize: 10, color: Colors.white38)),
                  const SizedBox(width: 6),
                  Expanded(
                    child: GestureDetector(
                      onTap: () => pickDate(true),
                      child: Container(
                        padding: const EdgeInsets.symmetric(horizontal: 6, vertical: 4),
                        decoration: BoxDecoration(
                          color: surface,
                          borderRadius: BorderRadius.circular(4),
                          border: Border.all(color: border),
                        ),
                        child: Text(fmtDate(rule.dateFrom),
                            style: const TextStyle(fontSize: 11, color: Colors.white70)),
                      ),
                    ),
                  ),
                  if (rule.dateFrom != null)
                    GestureDetector(
                      onTap: () => setState(() => rule.dateFrom = null),
                      child: const Padding(
                        padding: EdgeInsets.only(left: 4),
                        child: Icon(Icons.close_rounded, size: 12, color: Colors.white30),
                      ),
                    ),
                ],
              ),
              const SizedBox(height: 4),
              Row(
                children: [
                  const Text('To  ', style: TextStyle(fontSize: 10, color: Colors.white38)),
                  const SizedBox(width: 6),
                  Expanded(
                    child: GestureDetector(
                      onTap: () => pickDate(false),
                      child: Container(
                        padding: const EdgeInsets.symmetric(horizontal: 6, vertical: 4),
                        decoration: BoxDecoration(
                          color: surface,
                          borderRadius: BorderRadius.circular(4),
                          border: Border.all(color: border),
                        ),
                        child: Text(fmtDate(rule.dateTo),
                            style: const TextStyle(fontSize: 11, color: Colors.white70)),
                      ),
                    ),
                  ),
                  if (rule.dateTo != null)
                    GestureDetector(
                      onTap: () => setState(() => rule.dateTo = null),
                      child: const Padding(
                        padding: EdgeInsets.only(left: 4),
                        child: Icon(Icons.close_rounded, size: 12, color: Colors.white30),
                      ),
                    ),
                ],
              ),
            ],
          );

        case TaskFilterField.estimatedTime:
        case TaskFilterField.timeSpent:
          return Row(
            children: [
              Expanded(
                child: TextField(
                  decoration: InputDecoration(
                    hintText: 'Min (min)',
                    hintStyle: const TextStyle(fontSize: 10, color: Colors.white24),
                    filled: true,
                    fillColor: surface,
                    contentPadding: const EdgeInsets.symmetric(horizontal: 6, vertical: 4),
                    border: OutlineInputBorder(
                        borderRadius: BorderRadius.circular(4),
                        borderSide: const BorderSide(color: border)),
                  ),
                  style: const TextStyle(fontSize: 11, color: Colors.white70),
                  keyboardType: TextInputType.number,
                  onChanged: (v) => setState(
                      () => rule.numMin = int.tryParse(v)),
                ),
              ),
              const SizedBox(width: 4),
              Expanded(
                child: TextField(
                  decoration: InputDecoration(
                    hintText: 'Max (min)',
                    hintStyle: const TextStyle(fontSize: 10, color: Colors.white24),
                    filled: true,
                    fillColor: surface,
                    contentPadding: const EdgeInsets.symmetric(horizontal: 6, vertical: 4),
                    border: OutlineInputBorder(
                        borderRadius: BorderRadius.circular(4),
                        borderSide: const BorderSide(color: border)),
                  ),
                  style: const TextStyle(fontSize: 11, color: Colors.white70),
                  keyboardType: TextInputType.number,
                  onChanged: (v) => setState(
                      () => rule.numMax = int.tryParse(v)),
                ),
              ),
            ],
          );

        case TaskFilterField.groups:
          return const SizedBox.shrink();
      }
    }

    // ── Sort allowed fields for Planner ─────────────────────────────────────
    const plannerSortFields = [
      TaskSortOption.name,
      TaskSortOption.status,
      TaskSortOption.project,
      TaskSortOption.tag,
      TaskSortOption.estimatedTime,
      TaskSortOption.timeSpent,
      TaskSortOption.insertionDate,
      TaskSortOption.repeating,
    ];

    return Container(
      width: 240,
      decoration: BoxDecoration(
        color: bg,
        border: Border(
          left: BorderSide(color: Colors.white.withOpacity(0.08)),
          bottom: BorderSide(color: Colors.white.withOpacity(0.05)),
        ),
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.stretch,
        children: [
          // ── Header ────────────────────────────────────────────────────────
          Container(
            padding: const EdgeInsets.fromLTRB(10, 10, 10, 8),
            decoration: BoxDecoration(
              border: Border(
                bottom: BorderSide(color: Colors.white.withOpacity(0.07)),
              ),
            ),
            child: Row(
              children: [
                const Icon(Icons.filter_list, size: 13, color: Colors.white54),
                const SizedBox(width: 8),
                const Expanded(
                  child: Text(
                    'Planner Filter / Sort',
                    style: TextStyle(
                      fontSize: 11,
                      fontWeight: FontWeight.w600,
                      color: Colors.white70,
                    ),
                  ),
                ),
                GestureDetector(
                  onTap: () => setState(() => _plannerFilterOpen = false),
                  child: const Icon(Icons.close_rounded, size: 15, color: Colors.white38),
                ),
              ],
            ),
          ),

          Expanded(
            child: ListView(
              padding: const EdgeInsets.only(bottom: 20),
              children: [
                // ════════════════ FILTER ════════════════
                sectionHeader(
                  'FILTER',
                  () => setState(() => _plannerFilterRules.clear()),
                  _fgsPlannerFilterCollapsed,
                  () => setState(() => _fgsPlannerFilterCollapsed = !_fgsPlannerFilterCollapsed),
                ),
                if (!_fgsPlannerFilterCollapsed)
                  ..._plannerFilterRules.asMap().entries.map((entry) {
                    final idx = entry.key;
                    final rule = entry.value;
                    return Container(
                      key: ValueKey(rule.id),
                      margin: const EdgeInsets.fromLTRB(10, 0, 10, 8),
                      padding: const EdgeInsets.all(10),
                      decoration: BoxDecoration(
                        color: surface,
                        borderRadius: BorderRadius.circular(7),
                        border: Border.all(color: border),
                      ),
                      child: Column(
                        crossAxisAlignment: CrossAxisAlignment.stretch,
                        children: [
                          Row(
                            children: [
                              Expanded(
                                child: fieldDropdown<TaskFilterField>(
                                  value: rule.field,
                                  items: TaskFilterField.values
                                      .where((f) =>
                                          f != TaskFilterField.none &&
                                          f != TaskFilterField.groups &&
                                          f != TaskFilterField.scheduledDate)
                                      .toList(),
                                  label: (f) => f.label,
                                  onChanged: (f) => setState(() {
                                    rule.field = f;
                                    rule.selectedValues.clear();
                                    rule.nameQuery = '';
                                    rule.dateFrom = null;
                                    rule.dateTo = null;
                                    rule.numMin = null;
                                    rule.numMax = null;
                                    if (f == TaskFilterField.repeating) {
                                      rule.selectedValues
                                          .addAll(const {'repeating', 'nonRepeating'});
                                    }
                                  }),
                                ),
                              ),
                              removeBtn(
                                () => setState(() => _plannerFilterRules.removeAt(idx)),
                              ),
                            ],
                          ),
                          if (rule.field != TaskFilterField.none) ...[
                            const SizedBox(height: 8),
                            filterValueWidget(rule),
                          ],
                        ],
                      ),
                    );
                  }),
                if (!_fgsPlannerFilterCollapsed)
                  Padding(
                    padding: const EdgeInsets.symmetric(horizontal: 10),
                    child: GestureDetector(
                      onTap: () => setState(
                        () => _plannerFilterRules
                            .add(FilterRule(id: _gristId())),
                      ),
                      child: Container(
                        padding: const EdgeInsets.symmetric(vertical: 7),
                        decoration: BoxDecoration(
                          color: Colors.white.withOpacity(0.03),
                          borderRadius: BorderRadius.circular(5),
                          border: Border.all(color: Colors.white12),
                        ),
                        child: const Row(
                          mainAxisAlignment: MainAxisAlignment.center,
                          children: [
                            Icon(Icons.add, size: 13, color: Colors.white38),
                            SizedBox(width: 4),
                            Text(
                              'Add Filter',
                              style: TextStyle(fontSize: 11, color: Colors.white38),
                            ),
                          ],
                        ),
                      ),
                    ),
                  ),

                // ════════════════ SORT ════════════════
                Padding(
                  padding: const EdgeInsets.only(top: 6),
                  child: Container(height: 1, color: Colors.white.withOpacity(0.05)),
                ),
                sectionHeader(
                  'SORT',
                  () => setState(() => _plannerSortCriteria.clear()),
                  _fgsPlannerSortCollapsed,
                  () => setState(() => _fgsPlannerSortCollapsed = !_fgsPlannerSortCollapsed),
                ),

                // ── Default sort UI (mirrors the main F/G/S pattern) ─────────
                // When no extra criteria: show "+ Add Sort" + fixed Scheduled Date chip.
                // When extras exist: show reorderable extras above separator, then
                // fixed chip dimmed/locked below.
                if (!_fgsPlannerSortCollapsed)
                Builder(builder: (context) {
                  final extras = _plannerSortCriteria;
                  final hasExtra = extras.isNotEmpty;

                  String _ascLabel(TaskSortOption f) {
                    switch (f) {
                      case TaskSortOption.scheduledDate:
                      case TaskSortOption.insertionDate:
                        return 'Earliest';
                      case TaskSortOption.estimatedTime:
                      case TaskSortOption.timeSpent:
                        return 'Shortest';
                      case TaskSortOption.tag:
                      case TaskSortOption.name:
                      case TaskSortOption.project:
                        return 'A→Z';
                      case TaskSortOption.status:
                        return '↑';
                      case TaskSortOption.repeating:
                        return 'Non-Rep first';
                    }
                  }

                  String _descLabel(TaskSortOption f) {
                    switch (f) {
                      case TaskSortOption.scheduledDate:
                      case TaskSortOption.insertionDate:
                        return 'Latest';
                      case TaskSortOption.estimatedTime:
                      case TaskSortOption.timeSpent:
                        return 'Longest';
                      case TaskSortOption.tag:
                      case TaskSortOption.name:
                      case TaskSortOption.project:
                        return 'Z→A';
                      case TaskSortOption.status:
                        return '↓';
                      case TaskSortOption.repeating:
                        return 'Rep first';
                    }
                  }

                  return Column(
                    crossAxisAlignment: CrossAxisAlignment.stretch,
                    children: [
                      // ── Extra criteria (reorderable) ──────────────────────
                      if (hasExtra)
                        ReorderableListView(
                          shrinkWrap: true,
                          physics: const NeverScrollableScrollPhysics(),
                          buildDefaultDragHandles: false,
                          onReorder: (o, n) => setState(() {
                            if (n > o) n--;
                            final item = extras.removeAt(o);
                            extras.insert(n, item);
                          }),
                          children: extras.asMap().entries.map((entry) {
                            final idx = entry.key;
                            final sc = entry.value;
                            return Container(
                              key: ValueKey(sc.id),
                              margin: const EdgeInsets.fromLTRB(10, 0, 10, 8),
                              padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 7),
                              decoration: BoxDecoration(
                                color: surface,
                                borderRadius: BorderRadius.circular(7),
                                border: Border.all(color: border),
                              ),
                              child: Column(
                                crossAxisAlignment: CrossAxisAlignment.stretch,
                                children: [
                                  Row(
                                    children: [
                                      ReorderableDragStartListener(
                                        index: idx,
                                        child: const Padding(
                                          padding: EdgeInsets.only(right: 6),
                                          child: Icon(Icons.drag_indicator, size: 14, color: Colors.white24),
                                        ),
                                      ),
                                      Expanded(
                                        child: fieldDropdown<TaskSortOption>(
                                          value: sc.field,
                                          items: plannerSortFields,
                                          label: (f) => f.label,
                                          onChanged: (f) => setState(() => sc.field = f),
                                        ),
                                      ),
                                      const SizedBox(width: 6),
                                      dirBtn(sc.ascending, (v) => setState(() => sc.ascending = v)),
                                      removeBtn(() => setState(() => extras.removeAt(idx))),
                                    ],
                                  ),
                                  const SizedBox(height: 6),
                                  GestureDetector(
                                    onTap: () => setState(() => sc.emptyLast = !sc.emptyLast),
                                    child: Row(
                                      children: [
                                        const SizedBox(width: 20),
                                        AnimatedContainer(
                                          duration: const Duration(milliseconds: 100),
                                          width: 12, height: 12,
                                          decoration: BoxDecoration(
                                            color: sc.emptyLast ? accent.withOpacity(0.2) : Colors.transparent,
                                            borderRadius: BorderRadius.circular(3),
                                            border: Border.all(
                                              color: sc.emptyLast ? accent : Colors.white24,
                                              width: 1,
                                            ),
                                          ),
                                          child: sc.emptyLast
                                              ? const Icon(Icons.check_rounded, size: 8, color: accent)
                                              : null,
                                        ),
                                        const SizedBox(width: 6),
                                        const Text('Empty values last',
                                            style: TextStyle(fontSize: 10, color: Colors.white38)),
                                      ],
                                    ),
                                  ),
                                ],
                              ),
                            );
                          }).toList(),
                        ),

                      // ── + Add Sort button ─────────────────────────────────
                      Padding(
