  void _commitScheduleTask(
    String title,
    DateTime slot,
    int durationMinutes, {
    String projectId = 'INBOX_PROJECT',
  }) {
    final newTask = Task(
      id: DateTime.now().millisecondsSinceEpoch.toString(),
      title: title,
      isDone: false,
      projectId: projectId.isNotEmpty ? projectId : 'INBOX_PROJECT',
      subTaskIds: [],
      timeSpent: 0,
      attachments: [],
      tagIds: [],
      dueDay: slot.toIso8601String().split('T').first,
      plannedAt: slot.millisecondsSinceEpoch,
      durationMinutes: durationMinutes,
    );
    setState(() => _allTasks.add(newTask));
    _saveTaskToMeta(newTask);
  }

  /// Update mutable display properties on all instances when the parent changes.
  void _syncRepeatInstances(Task parent) {
    final children = _allTasks
        .where((t) => t.seriesId == parent.id && !t.isSeriesParent)
        .toList();
    if (children.isEmpty) return;
    setState(() {
      for (final child in children) {
        child.title = parent.title;
        child.notes = parent.notes;
        child.durationMinutes = parent.durationMinutes;
        // Keep isDone/status independent per instance
      }
    });
  }

  // ── Repeat propagation ────────────────────────────────────────────────────

  /// Remove every auto-generated instance belonging to [parentId].
  void _clearRepeatInstances(String parentId) {
    // Remove from index first (synchronous; file deletion is handled by callers).
    _allTasks
        .where((t) => t.seriesId == parentId && t.id != parentId)
        .forEach((t) => _taskIndex.remove(t.id));
    _allTasks.removeWhere((t) => t.seriesId == parentId && t.id != parentId);
  }

  /// When the series parent is deleted, promote the next chronological
  /// instance to become the new parent of the series.
  ///
  /// • Finds all remaining tasks whose [seriesId] equals [deletedParentId].
  /// • Picks the one with the earliest [scheduledDate] (the new "first").
  /// • Copies the repeat config from the old parent (passed in as [cfg]).
  /// • Sets its [seriesId] = its own [id] (making it the new parent).
  /// • Updates every other instance's [seriesId] and [repeatParentId] to
  ///   point to the new parent.
  /// • Re-runs propagation so the timeline stays correct.
  void _promoteNextSeriesParent(String deletedParentId, RepeatConfig? cfg) {
    final remaining = _allTasks
        .where((t) => t.seriesId == deletedParentId && t.id != deletedParentId)
        .toList()
      ..sort((a, b) {
        final da = a.scheduledDate ?? DateTime(2099);
        final db = b.scheduledDate ?? DateTime(2099);
        return da.compareTo(db);
      });

    if (remaining.isEmpty) return;

    final newParent = remaining.first;

    setState(() {
      // Promote: give it the series config (keep its own override if it has one).
      newParent.repeatConfig ??= cfg;
      newParent.seriesId = newParent.id;
      newParent.repeatParentId = null;

      // Re-point every other instance to the new parent.
      for (final t in remaining.skip(1)) {
        t.seriesId = newParent.id;
        t.repeatParentId = newParent.id;
      }
    });

    _propagateRepeat(newParent);
  }

  /// Anchor-segment-aware repeat propagation.
  ///
  /// The series is divided into segments by "anchor tasks" — the parent task
  /// plus any instance that carries its own [repeatConfig] override. Each
  /// anchor defines the rule for its segment, bounded by the next anchor's
  /// date (exclusive) or its own [endDate]/[propagationDays] horizon.
  ///
  /// All non-anchor instances are cleared and regenerated so the timeline
  /// always reflects the current set of rules.
  /// Anchor-segment-aware repeat propagation — current-week only.
  ///
  /// The series is divided into segments by "anchor tasks" — the parent plus
  /// any instance that carries its own [repeatConfig] override.  Each anchor
  /// defines the rule for its segment.
  ///
  /// All non-anchor instances are cleared from memory, removed from
  /// [_taskIndex], and their .md files are deleted.  Then
  /// [_generateWeekInstances] creates instances for the **current Mon–Sun
  /// week** only.  Instances for other weeks are generated on demand by
  /// [_loadWeekTasks] when the user navigates the schedule.
  Future<void> _propagateRepeat(Task parent) async {
    if (parent.repeatConfig == null || parent.repeatConfig!.cleared) {
      final toDelete = _allTasks
          .where((t) => t.seriesId == parent.id && t.id != parent.id)
          .toList();
      setState(() => _clearRepeatInstances(parent.id));
      for (final t in toDelete) {
        try {
          final f = File(_taskMdPath(t));
          if (await f.exists()) await f.delete();
        } catch (_) {}
      }
      await _saveWorkspace();
      return;
    }

    // Collect non-anchor instances to remove.
    final toRemove = _allTasks
        .where((t) {
          if (t.seriesId != parent.id || t.id == parent.id) return false;
          return t.repeatConfig == null || t.repeatConfig!.cleared;
        })
        .toList();

    setState(() {
      _allTasks.removeWhere((t) {
        if (t.seriesId != parent.id || t.id == parent.id) return false;
        return t.repeatConfig == null || t.repeatConfig!.cleared;
      });
    });

    // Remove from index and disk.
    for (final t in toRemove) {
      _taskIndex.remove(t.id);
      try {
        final f = File(_taskMdPath(t));
        if (await f.exists()) await f.delete();
      } catch (_) {}
    }

    final today = AppClock.now();
    final currentWeekStart = DateTime(today.year, today.month, today.day)
        .subtract(Duration(days: today.weekday - 1));
    final currentWeekEnd = currentWeekStart.add(const Duration(days: 6));

    // ── Backfill past weeks ───────────────────────────────────────────────
    // When the anchor date is before the current Mon–Sun window (e.g. the
    // user sets an anchor to a Monday two weeks ago), every week between
    // the anchor's week and today also needs its .md file materialised.
    // Without this, navigating the schedule shows a gap for those weeks.
    //
    // We find the earliest scheduled date across all segment anchors in the
    // series; that becomes the backfill start.  A 2-year safety cap prevents
    // runaway iteration on very old series.
    final allSegmentAnchors = _allTasks
        .where(
          (t) =>
              t.seriesId == parent.id &&
              t.repeatConfig != null &&
              !t.repeatConfig!.cleared,
        )
        .toList()
      ..sort((a, b) {
        final da = a.scheduledDate ?? DateTime(2099);
        final db = b.scheduledDate ?? DateTime(2099);
        return da.compareTo(db);
      });

    DateTime? seriesStart = allSegmentAnchors.isNotEmpty
        ? allSegmentAnchors.first.scheduledDate
        : null;
    // Fall back to the anchorDate stored on the RepeatConfig itself.
    final cfgAnchor = parent.repeatConfig?.anchorDate;
    if (cfgAnchor != null &&
        (seriesStart == null || cfgAnchor.isBefore(seriesStart))) {
      seriesStart = cfgAnchor;
    }

    if (seriesStart != null && seriesStart.isBefore(currentWeekStart)) {
      // Normalise to the Monday of the anchor's week.
      DateTime pastWeekStart = DateTime(
        seriesStart.year,
        seriesStart.month,
        seriesStart.day,
      ).subtract(Duration(days: seriesStart.weekday - 1));

      // Safety cap: never backfill more than 2 years of history.
      const maxBackfillDays = 730;
      final backfillCutoff =
          currentWeekStart.subtract(const Duration(days: maxBackfillDays));
      if (pastWeekStart.isBefore(backfillCutoff)) pastWeekStart = backfillCutoff;

      while (pastWeekStart.isBefore(currentWeekStart)) {
        final pastWeekEnd = pastWeekStart.add(const Duration(days: 6));
        await _generateWeekInstances(parent, pastWeekStart, pastWeekEnd);
        pastWeekStart = pastWeekStart.add(const Duration(days: 7));
      }
    }

    // Generate instances for the current week.
    await _generateWeekInstances(parent, currentWeekStart, currentWeekEnd);
  }

  /// Delegates to full [_propagateRepeat] so all segments stay consistent.
  Future<void> _propagateRepeatFromInstance(Task instance) async {
    // Resolve the series parent via seriesId (unified field), falling back
    // to the legacy repeatParentId for tasks loaded before the migration.
    final parentId = instance.isSeriesParent
        ? instance.id
        : (instance.repeatParentId ?? instance.seriesId);
    if (parentId == null) return;
    final parent = _allTasks.firstWhere(
      (t) => t.id == parentId,
      orElse: () => instance,
    );
    _propagateRepeat(parent);
  }

  /// Called when an instance user chooses "Apply from here" with a new config.
  ///
  /// The instance becomes an **anchor point**: [newCfg] is stored directly on
  /// it. All non-anchor future instances are pruned, then [_propagateRepeat]
  /// regenerates every segment (past anchor segments are untouched).
  void _applyForwardFromInstance(Task instance, RepeatConfig newCfg) {
    final sid = instance.seriesId;
    if (sid == null) return;

    final instanceDate = instance.scheduledDate;

    setState(() {
      // Store config on the instance — it becomes an anchor.
      instance.repeatConfig = newCfg;
      // seriesId is already set on all instances; nothing to change here.
      // Prune non-anchor instances strictly after this instance's date.
      _allTasks.removeWhere((t) {
        if (t.seriesId != sid) return false;
        if (t.id == instance.id) return false;
        if (t.repeatConfig != null && !t.repeatConfig!.cleared) return false;
        final tDate = t.scheduledDate;
        if (tDate == null || instanceDate == null) return false;
        return tDate.isAfter(instanceDate);
      });
    });

    final parent = _allTasks.firstWhere(
      (t) => t.id == sid && t.isSeriesParent,
      orElse: () => instance,
    );
    _propagateRepeat(parent);
  }

  /// Called when the parent task's "Apply Changes To" button is tapped.
  /// Updates the config on the parent and propagates field changes to
  /// sibling instances that fall within [scope]:
  ///   - current  → only the parent task itself (no siblings)
  ///   - forward  → parent + all instances on or after today
  ///   - backward → parent + all instances before today
  ///   - all      → every task in the series
  /// Then re-runs full propagation so the timeline reflects the new config.
  void _applyFromParentScoped(
    Task parent,
    RepeatConfig newCfg,
    _RepeatPropagateScope scope,
  ) {
    final today = DateTime(
      DateTime.now().year,
      DateTime.now().month,
      DateTime.now().day,
    );

    setState(() {
      parent.repeatConfig = newCfg;
      // Keep seriesId in sync with repeatConfig state.
      if (newCfg.cleared) {
        parent.seriesId = null;
      } else {
        parent.seriesId ??= parent.id;
      }
      if (scope != _RepeatPropagateScope.current) {
        final series = _allTasks
            .where((t) => t.seriesId == parent.id && !t.isSeriesParent)
            .toList();

        for (final t in series) {
          final tDate = t.scheduledDate;
          bool include = false;
          switch (scope) {
            case _RepeatPropagateScope.forward:
              include = tDate == null || !tDate.isBefore(today);
              break;
            case _RepeatPropagateScope.backward:
              include = tDate == null || tDate.isBefore(today);
              break;
            case _RepeatPropagateScope.all:
              include = true;
              break;
            case _RepeatPropagateScope.current:
              break;
          }
          if (include) {
            t.title = parent.title;
            t.notes = parent.notes;
            t.durationMinutes = parent.durationMinutes;
          }
        }
      }
    });

    _propagateRepeat(parent);
  }

  /// Sync mutable fields from [instance] to siblings according to [scope].
  void _propagateScopedRepeat(
    Task instance,
    _RepeatPropagateScope scope,
    Set<String> fields,
  ) {
    if (scope == _RepeatPropagateScope.current) return;
    final parentId = instance.seriesId ?? instance.repeatParentId ?? instance.id;

    final series = _allTasks
        .where((t) => t.seriesId == parentId)
        .toList();

    final instanceDate = instance.scheduledDate;

    setState(() {
      for (final t in series) {
        if (t.id == instance.id) continue;
        final tDate = t.scheduledDate;
        bool include = false;
        switch (scope) {
          case _RepeatPropagateScope.current:
            break;
          case _RepeatPropagateScope.forward:
            include =
                tDate == null ||
                instanceDate == null ||
                !tDate.isBefore(instanceDate);
            break;
          case _RepeatPropagateScope.backward:
            include =
                tDate == null ||
                instanceDate == null ||
                !tDate.isAfter(instanceDate);
            break;
          case _RepeatPropagateScope.all:
            include = true;
            break;
        }
        if (include) {
          if (fields.contains('title')) t.title = instance.title;
          if (fields.contains('status')) {
            t.status = instance.status;
            t.isDone = instance.isDone;
          }
          if (fields.contains('time')) t.plannedAt = instance.plannedAt;
          if (fields.contains('duration'))
            t.durationMinutes = instance.durationMinutes;
          if (fields.contains('notes')) t.notes = instance.notes;
          if (fields.contains('tags')) t.tagIds = List.from(instance.tagIds);
          if (fields.contains('subtasks')) t.subTaskIds.clear();
        }
      }
    });
  }

  /// Deletes series instances according to [scope] relative to [task]:
  ///   current  → only [task] itself (promotes next if it was the parent).
  ///   forward  → [task] + all instances on or after its date.
  ///   backward → [task] + all instances on or before its date.
  ///   all      → every task in the series.
  ///
  /// After deletion the series is re-propagated so the timeline stays
  /// consistent (except when [scope] is `all`, which wipes the whole series).
  void _deleteScopedRepeat(Task task, _RepeatPropagateScope scope) {
    final seriesId = task.seriesId ?? task.id;
    final taskDate = task.scheduledDate;
    final today = DateTime(
      DateTime.now().year,
      DateTime.now().month,
      DateTime.now().day,
    );

    // Collect IDs to remove.
    final toDelete = <String>{};

    switch (scope) {
      case _RepeatPropagateScope.current:
        toDelete.add(task.id);
        break;
      case _RepeatPropagateScope.forward:
        for (final t in _allTasks) {
          if (t.seriesId != seriesId) continue;
          final d = t.scheduledDate;
          if (taskDate == null || d == null || !d.isBefore(taskDate)) {
            toDelete.add(t.id);
          }
        }
        break;
      case _RepeatPropagateScope.backward:
        for (final t in _allTasks) {
          if (t.seriesId != seriesId) continue;
          final d = t.scheduledDate;
          if (taskDate == null || d == null || !d.isAfter(taskDate)) {
            toDelete.add(t.id);
          }
        }
        break;
      case _RepeatPropagateScope.all:
        for (final t in _allTasks) {
          if (t.seriesId == seriesId) toDelete.add(t.id);
        }
        break;
    }

    // If the series parent is being deleted, promote the next survivor first.
    final parent = _allTasks.firstWhere(
      (t) => t.seriesId == seriesId && t.isSeriesParent,
      orElse: () => task,
    );
    final parentIsDeleted = toDelete.contains(parent.id);

    if (parentIsDeleted && scope != _RepeatPropagateScope.all) {
      // Find the earliest remaining task (not in toDelete) to promote.
      _promoteNextSeriesParent(
        parent.id,
        parent.repeatConfig,
      );
    }

    setState(() {
      _allTasks.removeWhere((t) => toDelete.contains(t.id));
    });

    // Re-propagate from the (possibly new) parent, unless the whole series was wiped.
    if (scope != _RepeatPropagateScope.all) {
      final newParent = _allTasks.firstWhere(
        (t) => t.seriesId == seriesId && t.isSeriesParent,
        orElse: () => task,
      );
      if (_allTasks.contains(newParent)) {
        _propagateRepeat(newParent);
      }
    }
  }
  /// Returns null if no next date is determinable.
  DateTime? _nextRepeatDate(RepeatConfig cfg, DateTime from) {
    switch (cfg.preset) {
      case RepeatPreset.everyday:
        return from.add(const Duration(days: 1));

      case RepeatPreset.weekdays:
        var d = from.add(const Duration(days: 1));
        while (d.weekday == DateTime.saturday || d.weekday == DateTime.sunday) {
          d = d.add(const Duration(days: 1));
        }
        return d;

      case RepeatPreset.everyWeek:
        return from.add(const Duration(days: 7));

      case RepeatPreset.everyMonth:
        final target = from.day;
        var y = from.year;
        var m = from.month + 1;
        if (m > 12) {
          m = 1;
          y++;
        }
        final daysInMonth = DateTime(y, m + 1, 0).day;
        return DateTime(y, m, target.clamp(1, daysInMonth));

      case RepeatPreset.everyYear:
        return DateTime(from.year + 1, from.month, from.day);

      case RepeatPreset.custom:
        switch (cfg.customCycle) {
          case RepeatCycle.day:
            return from.add(Duration(days: cfg.customEvery));
          case RepeatCycle.week:
            // Find next matching weekday(s) within the cycle
            if (cfg.customWeekDays.isEmpty) return null;
            // Walk day-by-day until we hit a matching weekday within the period
            var d = from.add(const Duration(days: 1));
            final limit = from.add(Duration(days: cfg.customEvery * 7 + 7));
            while (d.isBefore(limit)) {
              if (cfg.customWeekDays.contains(d.weekday)) return d;
              d = d.add(const Duration(days: 1));
            }
            return null;
          case RepeatCycle.month:
            var y = from.year;
            var mo = from.month + cfg.customEvery;
            while (mo > 12) {
              mo -= 12;
              y++;
            }
            final daysInMonth = DateTime(y, mo + 1, 0).day;
            return DateTime(y, mo, from.day.clamp(1, daysInMonth));
          case RepeatCycle.year:
            return DateTime(from.year + cfg.customEvery, from.month, from.day);
        }
    }
    return null;
  }

  String _fmt12h(int hour, int minute) {
    final period = hour < 12 ? 'AM' : 'PM';
    final h = hour == 0 ? 12 : (hour > 12 ? hour - 12 : hour);
    return "$h:${minute.toString().padLeft(2, '0')} $period";
  }

  Widget _buildTasksNavContent() {
    // Compute counts
    final now = DateTime.now();
    final today = DateTime(now.year, now.month, now.day);

    final allSubtaskIds = _allTasks
        .expand((t) => t.subTaskIds.map((id) => id.toString()))
        .toSet();
    final rootTasks = _allTasks
        .where((t) => !allSubtaskIds.contains(t.id))
        .toList();

    int todayCount = 0, overdueCount = 0, inboxCount = 0;
    for (final t in rootTasks) {
      if (t.status == TaskStatus.done || t.status == TaskStatus.cancelled)
        continue;
      if (t.projectId == 'INBOX_PROJECT') inboxCount++;
      if (t.dueDay == null) continue;
      final due = DateTime.tryParse(t.dueDay!);
      if (due == null) continue;
      final dueDate = DateTime(due.year, due.month, due.day);
      if (dueDate.isBefore(today))
        overdueCount++;
      else if (dueDate == today)
        todayCount++;
    }

