  // ── Canvas category settings view ─────────────────────────────────────────
  Widget _buildCanvasCategorySettingsView(String categoryName) {
    final catProjects = _projectOrder
        .where(
          (id) =>
              (_categoryMappings[categoryName] ?? {}).contains(id) &&
              _projects.containsKey(id),
        )
        .toList();

    return Container(
      color: const Color(0xFF181A1B),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.stretch,
        children: [
          // ── Header ──────────────────────────────────────────────────────
          Container(
            padding: const EdgeInsets.fromLTRB(20, 14, 20, 14),
            decoration: const BoxDecoration(
              color: Color(0xFF1E2124),
              border: Border(bottom: BorderSide(color: Color(0xFF2C2F32))),
            ),
            child: Row(
              children: [
                Expanded(
                  child: Text(
                    'Category: $categoryName',
                    style: const TextStyle(
                      color: Colors.white,
                      fontSize: 15,
                      fontWeight: FontWeight.w600,
                    ),
                  ),
                ),
                TextButton.icon(
                  onPressed: () => setState(() => _tasksNavSection = 'Today'),
                  icon: const Icon(
                    Icons.arrow_back_rounded,
                    size: 13,
                    color: Colors.white54,
                  ),
                  label: const Text(
                    'Back',
                    style: TextStyle(color: Colors.white54, fontSize: 12),
                  ),
                ),
              ],
            ),
          ),
          Padding(
            padding: const EdgeInsets.fromLTRB(16, 10, 16, 4),
            child: Text(
              'Projects in this category — drag ≡ to reorder, toggle 👁 to hide',
              style: TextStyle(
                fontSize: 10,
                color: Colors.white.withOpacity(0.35),
              ),
            ),
          ),
          Expanded(
            child: ReorderableListView(
              padding: const EdgeInsets.symmetric(vertical: 4),
              buildDefaultDragHandles: false,
              onReorder: (oldIdx, newIdx) {
                setState(() {
                  if (newIdx > oldIdx) newIdx -= 1;
                  final movedId = catProjects.removeAt(oldIdx);
                  catProjects.insert(newIdx, movedId);
                  // Reflect new order within _projectOrder
                  for (final id in catProjects.reversed) {
                    _projectOrder.remove(id);
                    final insertAt = _projectOrder.indexWhere(
                      (pid) =>
                          (_categoryMappings[categoryName] ?? {}).contains(pid),
                    );
                    _projectOrder.insert(
                      insertAt < 0 ? _projectOrder.length : insertAt,
                      id,
                    );
                  }
                });
                _saveWorkspace();
              },
              children: catProjects.asMap().entries.map((entry) {
                final idx = entry.key;
                final pid = entry.value;
                final proj = _projects[pid];
                final title = proj?.title ?? pid;
                final color = _projectColors[pid] ?? Colors.blueAccent;
                final isHidden = _projectHiddenFromMenu[pid] ?? false;
                return Container(
                  key: ValueKey('catset_$pid'),
                  margin: const EdgeInsets.symmetric(
                    horizontal: 12,
                    vertical: 1,
                  ),
                  decoration: BoxDecoration(
                    color: const Color(0xFF212426),
                    borderRadius: BorderRadius.circular(5),
                    border: Border.all(color: const Color(0xFF2C2F32)),
                  ),
                  child: Row(
                    children: [
                      ReorderableDragStartListener(
                        index: idx,
                        child: const Padding(
                          padding: EdgeInsets.symmetric(horizontal: 10),
                          child: Icon(
                            Icons.drag_indicator_rounded,
                            size: 14,
                            color: Colors.white24,
                          ),
                        ),
                      ),
                      // Color dot
                      Container(
                        width: 9,
                        height: 9,
                        margin: const EdgeInsets.only(right: 8),
                        decoration: BoxDecoration(
                          color: color,
                          shape: BoxShape.circle,
                        ),
                      ),
                      Expanded(
                        child: Text(
                          title,
                          style: TextStyle(
                            fontSize: 12,
                            color: isHidden ? Colors.white30 : Colors.white70,
                          ),
                        ),
                      ),
                      // Color picker shortcut
                      Tooltip(
                        message: 'Change color',
                        child: InkWell(
                          onTap: () {
                            _showUnifiedColorPicker(
                              title: 'Project Color',
                              initialColor: color,
                              onApply: (c) {
                                setState(() => _projectColors[pid] = c);
                                _saveWorkspace();
                              },
                              colorContext: 'projectColor',
                            );
                          },
                          borderRadius: BorderRadius.circular(4),
                          child: Padding(
                            padding: const EdgeInsets.all(8),
                            child: Icon(
                              Icons.color_lens_outlined,
                              size: 14,
                              color: Colors.white38,
                            ),
                          ),
                        ),
                      ),
                      // Visibility toggle
                      Tooltip(
                        message: isHidden
                            ? 'Show in sidebar'
                            : 'Hide from sidebar',
                        child: InkWell(
                          onTap: () {
                            setState(() {
                              _projectHiddenFromMenu[pid] = !isHidden;
                            });
                            _saveWorkspace();
                          },
                          borderRadius: BorderRadius.circular(4),
                          child: Padding(
                            padding: const EdgeInsets.all(8),
                            child: Icon(
                              isHidden
                                  ? Icons.visibility_off_rounded
                                  : Icons.visibility_rounded,
                              size: 14,
                              color: isHidden ? Colors.white30 : Colors.white54,
                            ),
                          ),
                        ),
                      ),
                      const SizedBox(width: 4),
                    ],
                  ),
                );
              }).toList(),
            ),
          ),
        ],
      ),
    );
  }

  Widget _buildTasksTitleBar() {
    if (_tasksNavSection == 'org_projects')
      return _buildOrgTitleBar('Projects');
    if (_tasksNavSection == 'org_tags') return _buildOrgTitleBar('Tags');
    if (_tasksNavSection == 'notes_org_projects')
      return _buildOrgTitleBar('Project Notes');
    if (_tasksNavSection == 'notes_org_tasks')
      return _buildOrgTitleBar('Task Notes');
    if (_tasksNavSection.startsWith('canvas_category_settings:')) {
      final cat = _tasksNavSection.substring(
        'canvas_category_settings:'.length,
      );
      return _buildOrgTitleBar('Category: $cat');
    }
    if (_tasksNavSection == 'Schedule') return _buildScheduleTitleBar();
    if (_tasksNavSection == 'Planner') return _buildPlannerTitleBar();
    if (_tasksNavSection == 'Boards') return _buildBoardsTitleBar();

    final title = () {
      if (_tasksNavSection == 'Today') return 'Today';
      if (_tasksNavSection == 'Inbox') return 'Inbox';
      if (_tasksNavSection == 'Pipeline') return 'Pipeline';
      if (_tasksNavSection.startsWith('quick_history:')) {
        final ctx = _tasksNavSection.substring(14);
        if (ctx.startsWith('proj:')) {
          final pid = ctx.substring(5);
          return _projects[pid]?.title ?? 'Project';
        }
        if (ctx.startsWith('tag:')) return '#${ctx.substring(4)}';
        return 'Quick History';
      }
      if (_tasksNavSection.startsWith('worklog:')) {
        final ctx = _tasksNavSection.substring(8);
        if (ctx.startsWith('proj:')) {
          final pid = ctx.substring(5);
          return _projects[pid]?.title ?? 'Project';
        }
        if (ctx.startsWith('tag:')) return '#${ctx.substring(4)}';
        return 'Worklog';
      }
      if (_tasksNavSection.startsWith('metrics:')) {
        final ctx = _tasksNavSection.substring(8);
        if (ctx.startsWith('proj:')) {
          final pid = ctx.substring(5);
          return _projects[pid]?.title ?? 'Project';
        }
        if (ctx.startsWith('tag:')) return '#${ctx.substring(4)}';
        return 'Metrics';
      }
      if (_tasksNavSection.startsWith('settings:')) {
        final ctx = _tasksNavSection.substring(9);
        if (ctx.startsWith('proj:')) {
          final pid = ctx.substring(5);
          return _projects[pid]?.title ?? 'Project';
        }
        if (ctx.startsWith('tag:')) return '#${ctx.substring(4)}';
        return 'Settings';
      }
      if (_tasksNavSection.startsWith('proj:')) {
        final pid = _tasksNavSection.substring(5);
        return _projects[pid]?.title ?? 'Project';
      }
      if (_tasksNavSection.startsWith('tag:'))
        return '#${_tasksNavSection.substring(4)}';
      return _tasksNavSection;
    }();

    // ── Close Task Details button (always trailing) ──────────────────────
    final hasDetail =
        _taskListDetailOpen ||
        _showDetails ||
        _taskDetailExpanded.values.any((v) => v);
    final closeDetailsBtn = Tooltip(
      message: hasDetail ? 'Close Task Details' : 'No task details open',
      child: InkWell(
        onTap: hasDetail
            ? () => setState(() {
                _taskListDetailOpen = false;
                _taskListDetailTask = null;
                _showDetails = false;
                _taskDetailExpanded.clear();
              })
            : null,
        borderRadius: BorderRadius.circular(6),
        child: Container(
          width: 32,
          height: 32,
          decoration: BoxDecoration(
            color: hasDetail
                ? Colors.white.withOpacity(0.04)
                : Colors.transparent,
            borderRadius: BorderRadius.circular(6),
            border: Border.all(
              color: hasDetail
                  ? Colors.white12
                  : Colors.white.withOpacity(0.06),
            ),
          ),
          child: Icon(
            Icons.close_rounded,
            size: 15,
            color: hasDetail ? Colors.white54 : Colors.white.withOpacity(0.24),
          ),
        ),
      ),
    );

    return Padding(
      padding: const EdgeInsets.symmetric(horizontal: 16),
      child: _OverflowTopBar(
        leading: [
          Text(
            title,
            style: TextStyle(
              fontSize: 14,
              fontWeight: FontWeight.w600,
              color: _activeProjectAccent == _tasksAccent
                  ? Colors.white
                  : _activeProjectAccent,
              letterSpacing: 0.3,
            ),
          ),
        ],
        collapsible: [
          _OverflowItem(
            button: _tasksIconBtn(
              Icons.add,
              'New Task',
              () => _showAddTaskOverlay(),
              key: _addTaskBtnKey,
            ),
            icon: Icons.add,
            label: 'New Task',
            onTap: _showAddTaskOverlay,
          ),
          _OverflowItem(
            button: _buildFilterBtn(),
            icon: Icons.filter_list,
            label: 'Filter / Group / Sort',
            onTap: () => setState(() {
              _filterSidebarTitle = _computeFilterSidebarTitle();
              _filterSidebarOpen = !_filterSidebarOpen;
            }),
          ),
          _OverflowItem(
            button: _tasksIconBtn(
              Icons.center_focus_strong_outlined,
              'Focus',
              _showFocusPopup,
              key: _focusBtnKey,
            ),
            icon: Icons.center_focus_strong_outlined,
            label: 'Focus',
            onTap: _showFocusPopup,
          ),
          _OverflowItem(
            button: _tasksIconBtn(
              Icons.timeline_outlined,
              'Time Tracking',
              _showTimeTrackingPopup,
              key: _timeTrackingBtnKey,
            ),
            icon: Icons.timeline_outlined,
            label: 'Time Tracking',
            onTap: _showTimeTrackingPopup,
          ),
        ],
        trailing: [closeDetailsBtn],
      ),
    );
  }

  void _showTimeTrackingPopup() {
    final box =
        _timeTrackingBtnKey.currentContext?.findRenderObject() as RenderBox?;
    if (box == null) return;
    final pos = box.localToGlobal(Offset.zero);
    final size = box.size;
    final screen = MediaQuery.of(context).size;

    const popupW = 680.0;
    const popupH = 220.0;
    double left = pos.dx + size.width / 2 - popupW / 2;
    if (left + popupW > screen.width - 8) left = screen.width - popupW - 8;
    if (left < 8) left = 8;
    double top = pos.dy + size.height + 6;
    if (top + popupH > screen.height - 8) top = pos.dy - popupH - 6;

    showGeneralDialog(
      context: context,
      barrierDismissible: true,
      barrierLabel: 'TimeTracking',
      barrierColor: Colors.transparent,
      transitionDuration: const Duration(milliseconds: 140),
      transitionBuilder: (ctx, anim, _, child) => FadeTransition(
        opacity: CurvedAnimation(parent: anim, curve: Curves.easeOut),
        child: SlideTransition(
          position: Tween<Offset>(
            begin: const Offset(0, -0.04),
            end: Offset.zero,
          ).animate(CurvedAnimation(parent: anim, curve: Curves.easeOut)),
          child: child,
        ),
      ),
      pageBuilder: (ctx, _, __) => Stack(
        children: [
          Positioned(
            left: left,
            top: top,
            width: popupW,
            child: Material(
              color: Colors.transparent,
              child: _TimeTrackingPanel(
                allTasks: _allTasks,
                activeTimerTaskId: _activeTimerTaskId,
                timerStartedAt: _timerStartedAt,
                projects: _projects,
                execViewMode: _scheduleExecViewMode,
                taskSessions: _taskSessions,
              ),
            ),
          ),
        ],
      ),
    );
  }

  /// Returns the topmost undone task visible in the current list view.
  Task? _getTopmostTask() {
    final now = DateTime.now();
    final today = DateTime(now.year, now.month, now.day);
    final allSubtaskIds = _allTasks
        .expand((t) => t.subTaskIds.map((id) => id.toString()))
        .toSet();

    try {
      return _allTasks.firstWhere((t) {
        if (allSubtaskIds.contains(t.id)) return false;
        if (t.status == TaskStatus.done || t.status == TaskStatus.cancelled) {
          return false;
        }
        if (_tasksNavSection == 'Today') {
          if (t.dueDay == null) return false;
          final due = DateTime.tryParse(t.dueDay!);
          if (due == null) return false;
          return !DateTime(due.year, due.month, due.day).isAfter(today);
        }
        if (_tasksNavSection == 'Inbox') return t.projectId == 'INBOX_PROJECT';
        if (_tasksNavSection.startsWith('proj:'))
          return t.projectId == _tasksNavSection.substring(5);
        if (_tasksNavSection.startsWith('tag:'))
          return t.tagIds.contains(_tasksNavSection.substring(4));
        return true;
      });
    } catch (_) {
      return null;
    }
  }

  void _showFocusPopup() {
    // If a focus session is already running, go straight to its overlay.
    if (_activeStagingTaskId != null) {
      _showStagingOverlay(_activeStagingTaskId!);
      return;
    }
    if (_activeFlowtimeTaskId != null) {
      _showFlowtimeOverlay(_activeFlowtimeTaskId!);
      return;
    }
    if (_activeGeneralTaskId != null) {
      _showGeneralOverlay(_activeGeneralTaskId!);
      return;
    }

    final task = _getTopmostTask();
    showGeneralDialog(
      context: context,
      barrierDismissible: true,
      barrierLabel: 'FocusPopup',
      barrierColor: Colors.black.withOpacity(0.45),
      transitionDuration: const Duration(milliseconds: 180),
      transitionBuilder: (ctx, anim, _, child) => FadeTransition(
        opacity: CurvedAnimation(parent: anim, curve: Curves.easeOut),
        child: ScaleTransition(
          scale: Tween<double>(
            begin: 0.92,
            end: 1.0,
          ).animate(CurvedAnimation(parent: anim, curve: Curves.easeOutBack)),
          child: child,
        ),
      ),
      pageBuilder: (ctx, _, __) => Center(
        child: Material(
          color: Colors.transparent,
          child: _FocusModePopup(
            task: task,
            onCountdown: task != null
                ? () {
                    Navigator.of(ctx).pop();
                    _startGeneralTimer(task.id);
                  }
                : null,
            onPomodoro: task != null
                ? () {
                    Navigator.of(ctx).pop();
                    _startTaskStaging(task.id);
                  }
                : null,
            onFlowtime: task != null
                ? () {
                    Navigator.of(ctx).pop();
                    _startFlowtimeTimer(task.id);
                  }
                : null,
          ),
        ),
      ),
    );
  }

  // ── Filter button (icon-only, opens scoped sidebar) ────────────────────────
  /// Computes the display title for the sidebar based on the current nav section.
  String _computeFilterSidebarTitle() {
    final s = _tasksNavSection;
    if (s == 'Today') return 'Today';
    if (s == 'Inbox') return 'Inbox';
    if (s == 'Pipeline') return 'Pipeline';
    if (s.startsWith('proj:')) {
      final pid = s.substring(5);
      return 'Project: ${_projects[pid]?.title ?? pid}';
    }
    if (s.startsWith('tag:')) return 'Tag: ${s.substring(4)}';
    return 'All Tasks';
  }

  Widget _buildFilterBtn() {
    final totalRules =
        _filterRules.where((r) => r.isConfigured).length +
        _groupCriteria.length +
        _sortCriteria.length +
        (_activePresetFor(_tasksNavSection) == null && _sortCriteria.isEmpty ? _defaultSortCriteria.length : 0);
    final isActive = _filterSidebarOpen || totalRules > 0;

    return Stack(
      clipBehavior: Clip.none,
      children: [
        _HoverLabelBtn(
          key: _filterBtnKey,
          icon: Icons.filter_list,
          hoverLabel: 'Filter / Group / Sort',
          isActive: isActive,
          onTap: () => setState(() {
            _filterSidebarTitle = _computeFilterSidebarTitle();
            _filterSidebarOpen = !_filterSidebarOpen;
          }),
        ),
        if (totalRules > 0)
          Positioned(
            top: 2,
            right: 2,
            child: Container(
              width: 14,
              height: 14,
              decoration: const BoxDecoration(
                color: Color(0xFF4FC3F7),
                shape: BoxShape.circle,
              ),
              child: Center(
                child: Text(
                  '$totalRules',
                  style: const TextStyle(
                    fontSize: 8,
                    fontWeight: FontWeight.w700,
                    color: Colors.black,
                  ),
                ),
              ),
            ),
          ),
      ],
    );
  }

  // ── Grist-style Filter / Group / Sort sidebar ─────────────────────────────
  // ── Feature 6: Canvas Filter / Group / Sort panel ───────────────────────────
  Widget _buildCanvasFilterPanel() {
    const accent = Color(0xFF4FC3F7);
    const bg = Color(0xFF1A1C1F);
    const surface = Color(0xFF22252A);
    const border = Color(0xFF2C2F35);

    final allTags = {
      for (final t in _canvasTasks) ...t.tagIds.map((id) => id.toString()),
    }.toList()..sort();
    final allProjects = _projects.entries.toList();

    // ── shared helpers (mirrors _buildFilterSidebar) ────────────────────────
    Widget fieldDropdown<T>({
      required T value,
      required List<T> items,
      required String Function(T) label,
      required void Function(T) onChanged,
    }) {
      return GestureDetector(
        onTap: () => showDialog<T>(
          context: context,
          barrierColor: Colors.transparent,
          builder: (_) => _DropdownDialog<T>(
            current: value,
            items: items,
            itemLabel: label,
            onSelected: (v) {
              onChanged(v);
              Navigator.of(context).pop();
            },
          ),
        ),
        child: Container(
          padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 6),
          decoration: BoxDecoration(
            color: surface,
            borderRadius: BorderRadius.circular(5),
            border: Border.all(color: border),
          ),
          child: Row(
            mainAxisSize: MainAxisSize.min,
            children: [
              Flexible(
                child: Text(
                  label(value),
                  overflow: TextOverflow.ellipsis,
                  style: const TextStyle(fontSize: 11, color: Colors.white70),
                ),
              ),
              const SizedBox(width: 4),
              const Icon(Icons.expand_more_rounded, size: 12, color: Colors.white38),
            ],
          ),
        ),
      );
    }

    Widget removeBtn(VoidCallback onTap) => GestureDetector(
      onTap: onTap,
      child: const Padding(
        padding: EdgeInsets.only(left: 4),
        child: Icon(Icons.close_rounded, size: 14, color: Colors.white30),
      ),
    );

    // ── filter value widget — identical to _buildFilterSidebar ───────────────
    Widget filterValueWidget(FilterRule rule) {
      switch (rule.field) {
        case TaskFilterField.none:
          return const SizedBox.shrink();

        case TaskFilterField.name:
          return _NameFilterField(
            initialValue: rule.nameQuery,
            onChanged: (v) => setState(() => rule.nameQuery = v),
          );

        case TaskFilterField.tag:
        case TaskFilterField.project:
        case TaskFilterField.status:
          final items = rule.field == TaskFilterField.tag
              ? allTags
              : rule.field == TaskFilterField.project
                  ? allProjects.map((e) => e.key).toList()
                  : TaskStatus.values.map((s) => s.name).toList();
          String labelFor(String v) {
            if (rule.field == TaskFilterField.project) {
              return _projects[v]?.title ?? v;
            }
            if (rule.field == TaskFilterField.status) {
              try { return TaskStatus.values.byName(v).label; }
              catch (_) { return v; }
            }
            return v;
          }
          return Column(
            crossAxisAlignment: CrossAxisAlignment.stretch,
            children: items.map((v) {
              final checked = rule.selectedValues.contains(v);
              return GestureDetector(
                onTap: () => setState(() {
                  if (checked) rule.selectedValues.remove(v);
                  else rule.selectedValues.add(v);
                }),
                child: Padding(
                  padding: const EdgeInsets.symmetric(vertical: 3),
                  child: Row(
                    children: [
                      AnimatedContainer(
                        duration: const Duration(milliseconds: 100),
                        width: 14, height: 14,
                        decoration: BoxDecoration(
                          color: checked ? accent.withOpacity(0.2) : Colors.transparent,
                          borderRadius: BorderRadius.circular(3),
                          border: Border.all(
                            color: checked ? accent : Colors.white30,
                            width: 1.2,
                          ),
                        ),
                        child: checked
                            ? const Icon(Icons.check_rounded, size: 10, color: accent)
                            : null,
                      ),
                      const SizedBox(width: 8),
                      if (rule.field == TaskFilterField.status)
                        Builder(builder: (_) {
                          try {
                            final s = TaskStatus.values.byName(v);
                            return Row(children: [
                              Icon(s.icon, size: 11, color: s.color),
                              const SizedBox(width: 4),
                            ]);
                          } catch (_) { return const SizedBox.shrink(); }
                        }),
                      Expanded(
                        child: Text(
                          labelFor(v),
                          style: TextStyle(
                            fontSize: 11,
                            color: checked ? Colors.white : Colors.white60,
                          ),
                        ),
                      ),
                    ],
                  ),
                ),
              );
            }).toList(),
          );

        case TaskFilterField.repeating:
          final repOptions = [
            {'value': 'repeating',    'label': 'Repeating'},
            {'value': 'nonRepeating', 'label': 'Non-Repeating'},
          ];
          return Column(
            crossAxisAlignment: CrossAxisAlignment.stretch,
            children: repOptions.map((opt) {
              final v = opt['value']!;
              final checked = rule.selectedValues.contains(v);
              return GestureDetector(
                onTap: () => setState(() {
                  if (checked) rule.selectedValues.remove(v);
                  else rule.selectedValues.add(v);
                }),
                child: Padding(
                  padding: const EdgeInsets.symmetric(vertical: 3),
                  child: Row(
                    children: [
                      AnimatedContainer(
                        duration: const Duration(milliseconds: 100),
                        width: 14, height: 14,
                        decoration: BoxDecoration(
                          color: checked ? accent.withOpacity(0.2) : Colors.transparent,
                          borderRadius: BorderRadius.circular(3),
                          border: Border.all(
                            color: checked ? accent : Colors.white30,
                            width: 1.2,
                          ),
                        ),
                        child: checked
                            ? const Icon(Icons.check_rounded, size: 10, color: accent)
                            : null,
                      ),
                      const SizedBox(width: 8),
                      Text(
                        opt['label']!,
                        style: TextStyle(
                          fontSize: 11,
                          color: checked ? Colors.white : Colors.white60,
                        ),
                      ),
                    ],
                  ),
                ),
              );
            }).toList(),
          );

        case TaskFilterField.scheduledDate:
        case TaskFilterField.insertionDate:
          Future<void> pickDate(bool isFrom) async {
            final picked = await showDatePicker(
              context: context,
              initialDate: (isFrom ? rule.dateFrom : rule.dateTo) ?? DateTime.now(),
              firstDate: DateTime(2020),
              lastDate: DateTime(2099),
              builder: (ctx, child) => Theme(
                data: Theme.of(ctx).copyWith(
                  colorScheme: const ColorScheme.dark(
                    primary: accent,
                    surface: Color(0xFF1E2124),
                    onSurface: Colors.white,
                  ),
                  dialogBackgroundColor: const Color(0xFF1E2124),
                ),
                child: child!,
              ),
            );
            if (picked == null) return;
            setState(() {
              if (isFrom) rule.dateFrom = picked;
              else rule.dateTo = picked;
            });
          }
          String fmtDate(DateTime? d) =>
              d == null ? 'Any' : '${d.day}/${d.month}/${d.year}';
          return Column(
            crossAxisAlignment: CrossAxisAlignment.stretch,
            children: [
              Row(children: [
                const Text('From', style: TextStyle(fontSize: 10, color: Colors.white38)),
                const SizedBox(width: 6),
                Expanded(
                  child: GestureDetector(
                    onTap: () => pickDate(true),
                    child: Container(
                      padding: const EdgeInsets.symmetric(horizontal: 6, vertical: 4),
                      decoration: BoxDecoration(
                        color: surface,
                        borderRadius: BorderRadius.circular(4),
                        border: Border.all(color: border),
                      ),
                      child: Text(fmtDate(rule.dateFrom),
                          style: const TextStyle(fontSize: 11, color: Colors.white70)),
                    ),
                  ),
                ),
                if (rule.dateFrom != null)
                  GestureDetector(
                    onTap: () => setState(() => rule.dateFrom = null),
                    child: const Padding(padding: EdgeInsets.only(left: 4),
                        child: Icon(Icons.close_rounded, size: 12, color: Colors.white30)),
                  ),
              ]),
              const SizedBox(height: 4),
              Row(children: [
                const Text('To  ', style: TextStyle(fontSize: 10, color: Colors.white38)),
                const SizedBox(width: 6),
                Expanded(
                  child: GestureDetector(
                    onTap: () => pickDate(false),
                    child: Container(
                      padding: const EdgeInsets.symmetric(horizontal: 6, vertical: 4),
                      decoration: BoxDecoration(
                        color: surface,
                        borderRadius: BorderRadius.circular(4),
                        border: Border.all(color: border),
                      ),
                      child: Text(fmtDate(rule.dateTo),
                          style: const TextStyle(fontSize: 11, color: Colors.white70)),
                    ),
                  ),
                ),
                if (rule.dateTo != null)
                  GestureDetector(
                    onTap: () => setState(() => rule.dateTo = null),
                    child: const Padding(padding: EdgeInsets.only(left: 4),
                        child: Icon(Icons.close_rounded, size: 12, color: Colors.white30)),
                  ),
              ]),
            ],
          );

        case TaskFilterField.estimatedTime:
        case TaskFilterField.timeSpent:
          return Row(children: [
            Expanded(
              child: TextField(
                decoration: InputDecoration(
                  hintText: 'Min (min)',
                  hintStyle: const TextStyle(fontSize: 10, color: Colors.white24),
                  filled: true, fillColor: surface,
                  contentPadding: const EdgeInsets.symmetric(horizontal: 6, vertical: 4),
                  border: OutlineInputBorder(
                    borderRadius: BorderRadius.circular(4),
                    borderSide: const BorderSide(color: border),
                  ),
                ),
                style: const TextStyle(fontSize: 11, color: Colors.white70),
                keyboardType: TextInputType.number,
                onChanged: (v) => setState(() => rule.numMin = int.tryParse(v)),
              ),
            ),
            const SizedBox(width: 4),
            Expanded(
              child: TextField(
                decoration: InputDecoration(
                  hintText: 'Max (min)',
                  hintStyle: const TextStyle(fontSize: 10, color: Colors.white24),
                  filled: true, fillColor: surface,
                  contentPadding: const EdgeInsets.symmetric(horizontal: 6, vertical: 4),
                  border: OutlineInputBorder(
                    borderRadius: BorderRadius.circular(4),
                    borderSide: const BorderSide(color: border),
                  ),
                ),
                style: const TextStyle(fontSize: 11, color: Colors.white70),
                keyboardType: TextInputType.number,
                onChanged: (v) => setState(() => rule.numMax = int.tryParse(v)),
              ),
            ),
          ]);

        case TaskFilterField.groups:
          return const SizedBox.shrink();
      }
    }

    // ── fields available for canvas filter ───────────────────────────────────
    const canvasFilterFields = [
      TaskFilterField.name,
      TaskFilterField.status,
      TaskFilterField.tag,
      TaskFilterField.project,
      TaskFilterField.repeating,
      TaskFilterField.scheduledDate,
      TaskFilterField.insertionDate,
      TaskFilterField.estimatedTime,
      TaskFilterField.timeSpent,
    ];

    final hasActive = _canvasFilterRules.any((r) => r.isConfigured);

    return Container(
      width: 280,
      decoration: BoxDecoration(
        color: bg,
        borderRadius: BorderRadius.circular(10),
        border: Border.all(color: border),
        boxShadow: [
          BoxShadow(color: Colors.black.withOpacity(0.45), blurRadius: 20),
        ],
      ),
      child: Column(
        mainAxisSize: MainAxisSize.min,
        crossAxisAlignment: CrossAxisAlignment.stretch,
        children: [
          // ── Header ─────────────────────────────────────────────────────────
          Container(
            padding: const EdgeInsets.fromLTRB(12, 10, 10, 10),
            decoration: const BoxDecoration(
              color: surface,
              borderRadius: BorderRadius.vertical(top: Radius.circular(10)),
              border: Border(bottom: BorderSide(color: border)),
            ),
            child: Row(
              children: [
                const Icon(Icons.filter_list_rounded, size: 13, color: accent),
                const SizedBox(width: 8),
                const Expanded(
                  child: Text(
                    'Canvas Filter',
                    style: TextStyle(
                      fontSize: 11,
                      fontWeight: FontWeight.w600,
                      color: Colors.white,
                    ),
                  ),
                ),
                if (hasActive)
                  GestureDetector(
                    onTap: () => setState(() => _canvasFilterRules.clear()),
                    child: const Padding(
                      padding: EdgeInsets.only(right: 8),
                      child: Text(
                        'Clear all',
                        style: TextStyle(fontSize: 10, color: accent),
                      ),
                    ),
                  ),
                GestureDetector(
                  onTap: () => setState(() => _canvasFilterOpen = false),
                  child: const Icon(Icons.close_rounded, size: 14, color: Colors.white38),
                ),
              ],
            ),
          ),

          // ── Filter rule cards ───────────────────────────────────────────────
          ConstrainedBox(
            constraints: const BoxConstraints(maxHeight: 420),
            child: ListView(
              shrinkWrap: true,
              padding: const EdgeInsets.only(top: 6, bottom: 6),
              children: [
                ..._canvasFilterRules.asMap().entries.map((entry) {
                  final idx = entry.key;
                  final rule = entry.value;
                  return Container(
                    key: ValueKey(rule.id),
                    margin: const EdgeInsets.fromLTRB(10, 0, 10, 8),
                    padding: const EdgeInsets.all(10),
                    decoration: BoxDecoration(
                      color: surface,
                      borderRadius: BorderRadius.circular(7),
                      border: Border.all(color: border),
                    ),
                    child: Column(
                      crossAxisAlignment: CrossAxisAlignment.stretch,
                      children: [
                        Row(
                          children: [
                            Expanded(
                              child: fieldDropdown<TaskFilterField>(
                                value: rule.field,
                                items: canvasFilterFields,
                                label: (f) => f.label,
                                onChanged: (f) => setState(() {
                                  rule.field = f;
                                  rule.selectedValues.clear();
                                  rule.nameQuery = '';
                                  rule.dateFrom = null;
                                  rule.dateTo = null;
                                  rule.numMin = null;
                                  rule.numMax = null;
                                  if (f == TaskFilterField.repeating) {
                                    rule.selectedValues.addAll(
                                        const {'repeating', 'nonRepeating'});
                                  }
                                }),
                              ),
                            ),
                            removeBtn(
                              () => setState(() => _canvasFilterRules.removeAt(idx)),
                            ),
                          ],
                        ),
                        if (rule.field != TaskFilterField.none) ...[
                          const SizedBox(height: 8),
                          filterValueWidget(rule),
                        ],
                      ],
                    ),
                  );
                }),

                // ── + Add Filter button ─────────────────────────────────────
                Padding(
                  padding: const EdgeInsets.symmetric(horizontal: 10),
                  child: GestureDetector(
                    onTap: () => setState(() => _canvasFilterRules.add(
                      FilterRule(
                        id: _gristId(),
                        field: TaskFilterField.status,
                      ),
                    )),
                    child: Container(
                      padding: const EdgeInsets.symmetric(vertical: 7),
                      decoration: BoxDecoration(
                        color: Colors.white.withOpacity(0.03),
                        borderRadius: BorderRadius.circular(5),
                        border: Border.all(color: Colors.white12),
                      ),
                      child: const Row(
                        mainAxisAlignment: MainAxisAlignment.center,
                        children: [
                          Icon(Icons.add, size: 13, color: Colors.white38),
                          SizedBox(width: 4),
                          Text(
                            'Add Filter',
                            style: TextStyle(fontSize: 11, color: Colors.white38),
                          ),
                        ],
                      ),
                    ),
                  ),
                ),
              ],
            ),
          ),
        ],
      ),
    );
  }

  /// Per-section Filter / Sort panel — mirrors _buildCanvasFilterPanel but
  /// uses [_sectionFilterRules], [_sectionSortCriteria] keyed by [section].
  Widget _buildSectionFilterPanel(String section) {
    const accent = Color(0xFF4FC3F7);
    const bg = Color(0xFF1A1C1F);
    const surface = Color(0xFF22252A);
    const borderColor = Color(0xFF2C2F35);

    // Lazy-init lists for this section
    final filterRules = _sectionFilterRules.putIfAbsent(section, () => []);
    final sortCriteria = _sectionSortCriteria.putIfAbsent(section, () => []);

    // Tasks visible in this section
    List<String> sectionIds;
    if (section == 'Favorites') {
      sectionIds = _projectOrder
          .where((id) => _favoriteProjectIds.contains(id))
          .toList();
    } else if (section == 'All') {
      sectionIds = List.from(_projectOrder);
    } else {
      sectionIds = _projectOrder
          .where((id) => (_categoryMappings[section] ?? {}).contains(id))
          .toList();
    }
    final sectionProjects = _projects.entries
        .where((e) => sectionIds.contains(e.key))
        .toList();
    final allTags = {
      for (final t in _canvasTasks.where(
        (t) => sectionIds.contains(t.projectId),
      ))
        ...t.tagIds.map((id) => id.toString()),
    }.toList()..sort();

    final hasActiveFilters =
        filterRules.any((r) => r.isConfigured) || sortCriteria.isNotEmpty;

    Widget chip({
      required String label,
      required bool active,
      required VoidCallback onTap,
    }) {
      return GestureDetector(
        onTap: onTap,
        child: AnimatedContainer(
          duration: const Duration(milliseconds: 100),
          margin: const EdgeInsets.only(right: 4, bottom: 4),
          padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 4),
          decoration: BoxDecoration(
            color: active ? accent.withOpacity(0.15) : surface,
            borderRadius: BorderRadius.circular(5),
            border: Border.all(
              color: active ? accent.withOpacity(0.5) : borderColor,
            ),
          ),
          child: Text(
            label,
            style: TextStyle(
              fontSize: 11,
              color: active ? accent : Colors.white54,
              fontWeight: active ? FontWeight.w600 : FontWeight.normal,
            ),
          ),
        ),
      );
    }

    return Container(
      decoration: BoxDecoration(
        color: bg,
        borderRadius: BorderRadius.circular(10),
        border: Border.all(color: borderColor),
        boxShadow: [
          BoxShadow(color: Colors.black.withOpacity(0.45), blurRadius: 20),
        ],
      ),
      child: Column(
        mainAxisSize: MainAxisSize.min,
        crossAxisAlignment: CrossAxisAlignment.stretch,
        children: [
          // Header
          Container(
            padding: const EdgeInsets.fromLTRB(14, 10, 10, 10),
            decoration: const BoxDecoration(
              color: surface,
              borderRadius: BorderRadius.vertical(top: Radius.circular(10)),
              border: Border(bottom: BorderSide(color: borderColor)),
            ),
            child: Row(
              children: [
                const Icon(Icons.filter_list_rounded, size: 14, color: accent),
                const SizedBox(width: 8),
                Expanded(
                  child: Text(
                    'Filter / Sort  ·  ${section == 'All'
                        ? 'All'
                        : section == 'Favorites'
                        ? 'Favorites'
                        : section}',
                    style: const TextStyle(
                      fontSize: 12,
                      fontWeight: FontWeight.w600,
                      color: Colors.white,
                    ),
                    overflow: TextOverflow.ellipsis,
                  ),
                ),
                if (hasActiveFilters)
                  GestureDetector(
                    onTap: () => setState(() {
                      filterRules.clear();
                      sortCriteria.clear();
                    }),
                    child: const Text(
                      'Clear all',
                      style: TextStyle(fontSize: 10, color: accent),
                    ),
                  ),
                const SizedBox(width: 8),
                GestureDetector(
                  onTap: () => setState(() => _activeSectionFilter = null),
                  child: const Icon(
                    Icons.close_rounded,
                    size: 14,
                    color: Colors.white38,
                  ),
                ),
              ],
            ),
          ),

          // Filter by Status
          Padding(
            padding: const EdgeInsets.fromLTRB(14, 12, 14, 4),
            child: Text(
              'FILTER BY STATUS',
              style: TextStyle(
                fontSize: 9,
                letterSpacing: 1.0,
                fontWeight: FontWeight.w700,
                color: Colors.white38,
              ),
            ),
          ),
          Padding(
            padding: const EdgeInsets.fromLTRB(14, 4, 14, 8),
            child: Wrap(
              children: TaskStatus.values.map((s) {
                final rule = filterRules.firstWhere(
                  (r) => r.field == TaskFilterField.status,
                  orElse: () {
                    final r = FilterRule(
                      id: _gristId(),
                      field: TaskFilterField.status,
                    );
                    filterRules.add(r);
                    return r;
                  },
                );
                final active = rule.selectedValues.contains(s.name);
                return chip(
                  label: s.label,
                  active: active,
                  onTap: () => setState(() {
                    if (active)
                      rule.selectedValues.remove(s.name);
                    else
                      rule.selectedValues.add(s.name);
                  }),
                );
              }).toList(),
            ),
          ),

          // Filter by Tag
          if (allTags.isNotEmpty) ...[
            Padding(
              padding: const EdgeInsets.fromLTRB(14, 4, 14, 4),
              child: Text(
                'FILTER BY TAG',
                style: TextStyle(
                  fontSize: 9,
                  letterSpacing: 1.0,
                  fontWeight: FontWeight.w700,
                  color: Colors.white38,
                ),
              ),
            ),
            Padding(
              padding: const EdgeInsets.fromLTRB(14, 4, 14, 8),
              child: Wrap(
                children: allTags.map((tag) {
                  final rule = filterRules.firstWhere(
                    (r) => r.field == TaskFilterField.tag,
                    orElse: () {
                      final r = FilterRule(
                        id: _gristId(),
                        field: TaskFilterField.tag,
                      );
                      filterRules.add(r);
                      return r;
                    },
                  );
                  final active = rule.selectedValues.contains(tag);
                  return chip(
                    label: '#$tag',
                    active: active,
                    onTap: () => setState(() {
                      if (active)
                        rule.selectedValues.remove(tag);
                      else
                        rule.selectedValues.add(tag);
                    }),
                  );
                }).toList(),
              ),
            ),
          ],

          // Filter by Project (within the section)
          if (sectionProjects.isNotEmpty) ...[
            Padding(
              padding: const EdgeInsets.fromLTRB(14, 4, 14, 4),
              child: Text(
                'FILTER BY PROJECT',
                style: TextStyle(
                  fontSize: 9,
                  letterSpacing: 1.0,
                  fontWeight: FontWeight.w700,
                  color: Colors.white38,
                ),
              ),
            ),
            Padding(
              padding: const EdgeInsets.fromLTRB(14, 4, 14, 8),
              child: Wrap(
                children: sectionProjects.map((e) {
                  final rule = filterRules.firstWhere(
                    (r) => r.field == TaskFilterField.project,
                    orElse: () {
                      final r = FilterRule(
                        id: _gristId(),
                        field: TaskFilterField.project,
                      );
                      filterRules.add(r);
                      return r;
                    },
                  );
                  final active = rule.selectedValues.contains(e.key);
                  return chip(
                    label: e.value.title,
                    active: active,
                    onTap: () => setState(() {
                      if (active)
                        rule.selectedValues.remove(e.key);
                      else
                        rule.selectedValues.add(e.key);
                    }),
                  );
                }).toList(),
              ),
            ),
          ],

          // Sort
          const Divider(color: borderColor, height: 1),
          Padding(
            padding: const EdgeInsets.fromLTRB(14, 10, 14, 4),
            child: Text(
              'SORT',
              style: TextStyle(
                fontSize: 9,
                letterSpacing: 1.0,
                fontWeight: FontWeight.w700,
                color: Colors.white38,
              ),
            ),
          ),
          Padding(
            padding: const EdgeInsets.fromLTRB(14, 4, 14, 12),
            child: Wrap(
              children: TaskSortOption.values.map((opt) {
                final active =
                    sortCriteria.isNotEmpty && sortCriteria.first.field == opt;
                final asc = active && sortCriteria.first.ascending;
                return GestureDetector(
                  onTap: () => setState(() {
                    if (active) {
                      if (asc) {
                        sortCriteria[0] = SortCriterion(
                          id: _gristId(),
                          field: opt,
                          ascending: false,
                        );
                      } else {
                        sortCriteria.clear();
                      }
                    } else {
                      sortCriteria
                        ..clear()
                        ..add(
                          SortCriterion(
                            id: _gristId(),
                            field: opt,
                            ascending: true,
                          ),
                        );
                    }
                  }),
                  child: AnimatedContainer(
                    duration: const Duration(milliseconds: 100),
                    margin: const EdgeInsets.only(right: 4, bottom: 4),
                    padding: const EdgeInsets.symmetric(
                      horizontal: 8,
                      vertical: 4,
                    ),
                    decoration: BoxDecoration(
                      color: active ? accent.withOpacity(0.15) : surface,
                      borderRadius: BorderRadius.circular(5),
                      border: Border.all(
                        color: active ? accent.withOpacity(0.5) : borderColor,
                      ),
                    ),
                    child: Row(
                      mainAxisSize: MainAxisSize.min,
                      children: [
                        Text(
                          opt.label,
                          style: TextStyle(
                            fontSize: 11,
                            color: active ? accent : Colors.white54,
                            fontWeight: active
                                ? FontWeight.w600
                                : FontWeight.normal,
                          ),
                        ),
                        if (active) ...[
                          const SizedBox(width: 4),
                          Icon(
                            asc
                                ? Icons.arrow_upward_rounded
                                : Icons.arrow_downward_rounded,
                            size: 11,
                            color: accent,
                          ),
                        ],
                      ],
                    ),
                  ),
                );
              }).toList(),
            ),
          ),
        ],
      ),
    );
  }

  // ── Notes Tasks / Common FGS helpers ─────────────────────────────────────
  NotesSortPreset _notesManualPreset() => NotesSortPreset(id: _kNotesManualPresetId, name: 'Manual Ordering', isManual: true);

  List<NotesSortPreset> _notesPresetsFor(bool isTask) {
    final list = isTask ? _noteTaskPresets : _noteCommonPresets;
    if (list.isEmpty || list.first.id != _kNotesManualPresetId) {
      list.removeWhere((p) => p.id == _kNotesManualPresetId);
      list.insert(0, _notesManualPreset());
    }
    return list;
  }

  NotesSortPreset? _notesActivePreset(bool isTask) {
    final id = isTask ? _noteTaskActivePresetId : _noteCommonActivePresetId;
    if (id == null) return null;
    try { return _notesPresetsFor(isTask).firstWhere((p) => p.id == id); } catch (_) { return null; }
  }

  bool _notesIsManualActive(bool isTask) => _notesActivePreset(isTask)?.id == _kNotesManualPresetId;

  void _notesSetActivePreset(bool isTask, String? id) => setState(() {
    if (isTask) _noteTaskActivePresetId = id; else _noteCommonActivePresetId = id;
  });

  // ── Notes FGS sidebar ─────────────────────────────────────────────────────
  Widget _buildNotesFGSSidebar(String scope) {
    final isTask = scope == 'Notes Tasks';

    const accent = Color(0xFF4FC3F7);
    const bg = Color(0xFF1A1C1F);
    const surface = Color(0xFF22252A);
    const border = Color(0xFF2C2F35);
    const presetPurple = Color(0xFFCE93D8);

    // ── Per-scope closures ────────────────────────────────────────────────
    bool filterCollapsed() => isTask ? _ntFgsFilterCollapsed : _ncFgsFilterCollapsed;
    bool groupCollapsed() => isTask ? _ntFgsGroupCollapsed : _ncFgsGroupCollapsed;
    bool sortCollapsed() => isTask ? _ntFgsSortCollapsed : _ncFgsSortCollapsed;
    bool sortFoldersCollapsed() => isTask ? _ntFgsSortFoldersCollapsed : _ncFgsSortFoldersCollapsed;
    bool sortItemsCollapsed() => isTask ? _ntFgsSortItemsCollapsed : _ncFgsSortItemsCollapsed;
    List<NoteFilterRule> filterRules() => isTask ? _noteTaskFilterRules : _noteCommonFilterRules;

    void setFilterCollapsed(bool v) => setState(() => isTask ? _ntFgsFilterCollapsed = v : _ncFgsFilterCollapsed = v);
    void setGroupCollapsed(bool v) => setState(() => isTask ? _ntFgsGroupCollapsed = v : _ncFgsGroupCollapsed = v);
    void setSortCollapsed(bool v) => setState(() => isTask ? _ntFgsSortCollapsed = v : _ncFgsSortCollapsed = v);
    void setSortFoldersCollapsed(bool v) => setState(() => isTask ? _ntFgsSortFoldersCollapsed = v : _ncFgsSortFoldersCollapsed = v);
    void setSortItemsCollapsed(bool v) => setState(() => isTask ? _ntFgsSortItemsCollapsed = v : _ncFgsSortItemsCollapsed = v);

    // Active preset & criteria
    final presets = _notesPresetsFor(isTask);
    final activePreset = _notesActivePreset(isTask);
    final isManualActive = activePreset?.id == _kNotesManualPresetId;


    // ── Shared UI builders ────────────────────────────────────────────────
    Widget sectionHeader(String title, VoidCallback onRestore, bool collapsed, VoidCallback onToggle) {
      return GestureDetector(
        onTap: onToggle,
        child: Padding(
          padding: const EdgeInsets.fromLTRB(10, 10, 10, 6),
          child: Row(children: [
            AnimatedRotation(turns: collapsed ? -0.25 : 0, duration: const Duration(milliseconds: 150),
                child: const Icon(Icons.expand_more_rounded, size: 14, color: Colors.white38)),
            const SizedBox(width: 6),
            Text(title, style: const TextStyle(fontSize: 10, fontWeight: FontWeight.w700, letterSpacing: 1.0, color: Colors.white60)),
            const Spacer(),
            GestureDetector(onTap: onRestore, child: const Text('Restore Defaults', style: TextStyle(fontSize: 9, color: accent))),
          ]),
        ),
      );
    }

    Widget subSectionHeader(String title, bool collapsed, VoidCallback onToggle) {
      return GestureDetector(
        onTap: onToggle,
        child: Padding(
          padding: const EdgeInsets.fromLTRB(10, 8, 10, 4),
          child: Row(children: [
            AnimatedRotation(turns: collapsed ? -0.25 : 0, duration: const Duration(milliseconds: 150),
                child: const Icon(Icons.expand_more_rounded, size: 13, color: Colors.white30)),
            const SizedBox(width: 5),
            Text(title, style: const TextStyle(fontSize: 9, fontWeight: FontWeight.w700, letterSpacing: 0.9, color: Colors.white38)),
          ]),
        ),
      );
    }

    Widget divider() => Padding(padding: const EdgeInsets.only(top: 6), child: Container(height: 1, color: Colors.white.withOpacity(0.05)));

    Widget fieldDropdown<T>({required T value, required List<T> items, required String Function(T) label, required void Function(T) onChanged}) {
      return GestureDetector(
        onTap: () => showDialog<T>(context: context, barrierColor: Colors.transparent,
          builder: (_) => _DropdownDialog<T>(current: value, items: items, itemLabel: label,
              onSelected: (v) { onChanged(v); Navigator.of(context).pop(); })),
        child: Container(
          padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 6),
          decoration: BoxDecoration(color: surface, borderRadius: BorderRadius.circular(5), border: Border.all(color: border)),
          child: Row(mainAxisSize: MainAxisSize.min, children: [
            Flexible(child: Text(label(value), overflow: TextOverflow.ellipsis, style: const TextStyle(fontSize: 11, color: Colors.white70))),
            const SizedBox(width: 4),
            const Icon(Icons.expand_more_rounded, size: 12, color: Colors.white38),
          ]),
        ),
      );
    }

    Widget dirBtn(bool asc, void Function(bool) onTap, {String? ascLabel, String? descLabel}) {
      return GestureDetector(
        onTap: () => onTap(!asc),
        child: Container(
          padding: const EdgeInsets.symmetric(horizontal: 6, vertical: 5),
          decoration: BoxDecoration(color: accent.withOpacity(0.12), borderRadius: BorderRadius.circular(4), border: Border.all(color: accent.withOpacity(0.3))),
          child: Text(asc ? (ascLabel ?? '↑ Asc') : (descLabel ?? '↓ Desc'),
              style: const TextStyle(fontSize: 9, color: accent, fontWeight: FontWeight.w600)),
        ),
      );
    }

    Widget removeBtn(VoidCallback onTap) => GestureDetector(
      onTap: onTap,
      child: const Padding(padding: EdgeInsets.only(left: 4), child: Icon(Icons.close_rounded, size: 14, color: Colors.white30)));

    Widget checkbox(bool val, VoidCallback onTap) => GestureDetector(
      onTap: onTap,
      child: AnimatedContainer(duration: const Duration(milliseconds: 100), width: 12, height: 12,
        decoration: BoxDecoration(color: val ? accent.withOpacity(0.2) : Colors.transparent,
            borderRadius: BorderRadius.circular(3), border: Border.all(color: val ? accent : Colors.white24, width: 1)),
        child: val ? const Icon(Icons.check_rounded, size: 8, color: accent) : null));

    String folderDirLabel(String f, bool asc) {
      if (f == 'insertionDate') return asc ? 'Earliest' : 'Latest';
      if (f == 'itemCount') return asc ? 'Fewest' : 'Most';
      return asc ? 'A→Z' : 'Z→A';
    }
    String taskItemDirLabel(String f, bool asc) {
      if (f == 'scheduledDate' || f == 'updatedAt' || f == 'createdAt') return asc ? 'Earliest' : 'Latest';
      if (f == 'status') return asc ? '↑' : '↓';
      return asc ? 'A→Z' : 'Z→A';
    }
    String commonItemDirLabel(String f, bool asc) {
      if (f == 'updatedAt' || f == 'createdAt') return asc ? 'Earliest' : 'Latest';
      return asc ? 'A→Z' : 'Z→A';
    }

    final folderFieldNames = NoteFolderSortField.values.map((e) => e.name).toList();
    String folderFieldLabel(String f) { try { return NoteFolderSortField.values.byName(f).label; } catch (_) { return f; } }
    final taskItemFieldNames = NoteTaskItemSortField.values.map((e) => e.name).toList();
    String taskItemFieldLabel(String f) { try { return NoteTaskItemSortField.values.byName(f).label; } catch (_) { return f; } }
    final commonItemFieldNames = NoteCommonItemSortField.values.map((e) => e.name).toList();
    String commonItemFieldLabel(String f) { try { return NoteCommonItemSortField.values.byName(f).label; } catch (_) { return f; } }

    Widget sortCriterionRow({required NoteSortCriterion sc, required int idx, required List<NoteSortCriterion> list,
        required List<String> fieldNames, required String Function(String) fieldLabel, required String Function(String, bool) dirLabel}) {
      return Container(
        key: ValueKey(sc.id),
        margin: const EdgeInsets.fromLTRB(10, 0, 10, 8),
        padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 7),
        decoration: BoxDecoration(color: surface, borderRadius: BorderRadius.circular(7), border: Border.all(color: border)),
        child: Column(crossAxisAlignment: CrossAxisAlignment.stretch, children: [
          Row(children: [
            ReorderableDragStartListener(index: idx,
              child: const Padding(padding: EdgeInsets.only(right: 6), child: Icon(Icons.drag_indicator, size: 14, color: Colors.white24))),
            Expanded(child: fieldDropdown<String>(value: sc.fieldName, items: fieldNames, label: fieldLabel,
                onChanged: (f) => setState(() => sc.fieldName = f))),
            const SizedBox(width: 6),
            dirBtn(sc.ascending, (v) => setState(() => sc.ascending = v),
                ascLabel: dirLabel(sc.fieldName, true), descLabel: dirLabel(sc.fieldName, false)),
            removeBtn(() => setState(() => list.removeAt(idx))),
          ]),
          const SizedBox(height: 6),
          GestureDetector(
            onTap: () => setState(() => sc.emptyLast = !sc.emptyLast),
            child: Row(children: [
              const SizedBox(width: 20),
              checkbox(sc.emptyLast, () => setState(() => sc.emptyLast = !sc.emptyLast)),
              const SizedBox(width: 6),
              const Text('Empty values last', style: TextStyle(fontSize: 10, color: Colors.white38)),
            ])),
        ]),
      );
    }

    Widget addSortBtn(List<NoteSortCriterion> list, String defaultField) => Padding(
      padding: const EdgeInsets.fromLTRB(10, 0, 10, 8),
      child: GestureDetector(
        onTap: () => setState(() => list.add(NoteSortCriterion(id: _gristId(), fieldName: defaultField))),
        child: Container(
          padding: const EdgeInsets.symmetric(vertical: 7),
          decoration: BoxDecoration(color: Colors.white.withOpacity(0.03), borderRadius: BorderRadius.circular(5), border: Border.all(color: Colors.white12)),
          child: const Row(mainAxisAlignment: MainAxisAlignment.center, children: [
            Icon(Icons.add, size: 13, color: Colors.white38), SizedBox(width: 4),
            Text('Add Sort', style: TextStyle(fontSize: 11, color: Colors.white38)),
          ]),
        ),
      ));

    // ── Preset management ─────────────────────────────────────────────────
    Future<void> promptAddPreset() async {
      final ctrl = TextEditingController();
      final name = await showDialog<String>(context: context, builder: (_) => AlertDialog(
        backgroundColor: const Color(0xFF1E2124),
        shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(10)),
        title: const Text('New Sort Preset', style: TextStyle(fontSize: 13, fontWeight: FontWeight.w600, color: Colors.white)),
        content: TextField(controller: ctrl, autofocus: true,
          style: const TextStyle(fontSize: 12, color: Colors.white),
          decoration: const InputDecoration(hintText: 'Preset name…', hintStyle: TextStyle(fontSize: 12, color: Colors.white38),
            enabledBorder: UnderlineInputBorder(borderSide: BorderSide(color: Colors.white24)),
            focusedBorder: UnderlineInputBorder(borderSide: BorderSide(color: accent))),
          onSubmitted: (v) { if (v.trim().isNotEmpty) Navigator.of(context).pop(v.trim()); }),
        actions: [
          TextButton(onPressed: () => Navigator.of(context).pop(null), child: const Text('Cancel', style: TextStyle(fontSize: 11, color: Colors.white38))),
          TextButton(onPressed: () { final v = ctrl.text.trim(); if (v.isNotEmpty) Navigator.of(context).pop(v); },
              child: const Text('Add', style: TextStyle(fontSize: 11, color: accent))),
        ],
      ));
      if (name != null && name.isNotEmpty) {
        setState(() {
          final np = NotesSortPreset(id: _gristId(), name: name);
          presets.add(np);
          _notesSetActivePreset(isTask, np.id);
        });
      }
    }

    Widget buildPresetDropdown() {
      final selectedName = activePreset?.name ?? 'Default';
      final isCustomActive = activePreset != null && !isManualActive;

      return Padding(
        padding: const EdgeInsets.fromLTRB(10, 0, 10, 8),
        child: Column(crossAxisAlignment: CrossAxisAlignment.stretch, children: [
          // PRESET label
          const Padding(padding: EdgeInsets.only(bottom: 5),
            child: Text('PRESET', style: TextStyle(fontSize: 8, letterSpacing: 0.8, fontWeight: FontWeight.w700, color: Colors.white24))),

          // Dropdown button
          GestureDetector(
            onTap: () async {
              await showDialog<void>(context: context, barrierColor: Colors.transparent, builder: (ctx) {
                return StatefulBuilder(builder: (ctx, setLocal) {
                  return Dialog(
                    backgroundColor: const Color(0xFF1E2124),
                    shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(10), side: BorderSide(color: Colors.white.withOpacity(0.08))),
                    insetPadding: const EdgeInsets.symmetric(horizontal: 80, vertical: 80),
                    child: ConstrainedBox(
                      constraints: const BoxConstraints(maxWidth: 260, maxHeight: 300),
                      child: Column(mainAxisSize: MainAxisSize.min, children: [
                        // Top bar
                        Container(
                          decoration: const BoxDecoration(border: Border(bottom: BorderSide(color: Color(0xFF2C2F35)))),
                          padding: const EdgeInsets.fromLTRB(10, 8, 8, 8),
                          child: Row(children: [
                            const Icon(Icons.tune_rounded, size: 13, color: Colors.white38),
                            const SizedBox(width: 6),
                            const Expanded(child: Text('Sort Preset', style: TextStyle(fontSize: 12, color: Colors.white70, fontWeight: FontWeight.w600))),
                            GestureDetector(
                              onTap: () async { Navigator.of(ctx).pop(); await promptAddPreset(); },
                              child: Container(
                                padding: const EdgeInsets.symmetric(horizontal: 7, vertical: 4),
                                decoration: BoxDecoration(color: accent.withOpacity(0.1), borderRadius: BorderRadius.circular(5), border: Border.all(color: accent.withOpacity(0.3))),
                                child: const Row(mainAxisSize: MainAxisSize.min, children: [
                                  Icon(Icons.add, size: 11, color: accent), SizedBox(width: 3),
                                  Text('Add', style: TextStyle(fontSize: 10, color: accent, fontWeight: FontWeight.w600)),
                                ]),
                              ),
                            ),
                          ]),
                        ),
                        // Options list: Default + all presets (Manual Ordering first)
                        Flexible(child: ListView.builder(
                          shrinkWrap: true,
                          padding: const EdgeInsets.symmetric(vertical: 4),
                          itemCount: presets.length + 1, // +1 for Default
                          itemBuilder: (_, i) {
                            final isDefaultOption = i == 0;
                            final preset = isDefaultOption ? null : presets[i - 1];
                            final isManualOption = preset?.id == _kNotesManualPresetId;
                            final isSelected = isDefaultOption ? activePreset == null : preset?.id == activePreset?.id;

                            Future<void> showPresetMenu(NotesSortPreset p) async {
                              Navigator.of(ctx).pop();
                              final choice = await showDialog<String>(context: context, builder: (_) => SimpleDialog(
                                backgroundColor: const Color(0xFF1E2124),
                                shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(10)),
                                title: Text(p.name, style: const TextStyle(fontSize: 12, color: Colors.white70)),
                                children: [
                                  SimpleDialogOption(onPressed: () => Navigator.of(context).pop('rename'),
                                      child: const Text('Rename', style: TextStyle(fontSize: 12, color: Colors.white60))),
                                  if (!p.isManual)
                                    SimpleDialogOption(onPressed: () => Navigator.of(context).pop('delete'),
                                        child: const Text('Delete', style: TextStyle(fontSize: 12, color: Color(0xFFEF5350)))),
                                ],
                              ));
                              if (choice == 'delete' && !p.isManual) {
                                setState(() {
                                  presets.removeWhere((x) => x.id == p.id);
                                  if ((isTask ? _noteTaskActivePresetId : _noteCommonActivePresetId) == p.id) _notesSetActivePreset(isTask, null);
                                });
                              } else if (choice == 'rename') {
                                final rc = TextEditingController(text: p.name);
                                final newName = await showDialog<String>(context: context, builder: (_) => AlertDialog(
                                  backgroundColor: const Color(0xFF1E2124),
                                  shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(10)),
                                  title: const Text('Rename Preset', style: TextStyle(fontSize: 13, color: Colors.white)),
                                  content: TextField(controller: rc, autofocus: true,
                                    style: const TextStyle(fontSize: 12, color: Colors.white),
                                    decoration: const InputDecoration(
                                      enabledBorder: UnderlineInputBorder(borderSide: BorderSide(color: Colors.white24)),
                                      focusedBorder: UnderlineInputBorder(borderSide: BorderSide(color: accent))),
                                    onSubmitted: (v) { if (v.trim().isNotEmpty) Navigator.of(context).pop(v.trim()); }),
                                  actions: [
                                    TextButton(onPressed: () => Navigator.of(context).pop(null), child: const Text('Cancel', style: TextStyle(color: Colors.white38))),
                                    TextButton(onPressed: () { final v = rc.text.trim(); if (v.isNotEmpty) Navigator.of(context).pop(v); }, child: const Text('Save', style: TextStyle(color: accent))),
                                  ],
                                ));
                                if (newName != null && newName.isNotEmpty) {
                                  setState(() {
                                    final idx = presets.indexWhere((x) => x.id == p.id);
                                    if (idx >= 0) presets[idx] = p.copyWith(name: newName);
                                  });
                                }
                              }
                            }

                            return GestureDetector(
                              onTap: () { setState(() => _notesSetActivePreset(isTask, isDefaultOption ? null : preset!.id)); Navigator.of(ctx).pop(); },
                              child: Container(
                                padding: const EdgeInsets.symmetric(horizontal: 14, vertical: 9),
                                decoration: BoxDecoration(color: isSelected ? const Color(0xFF9C27B0).withOpacity(0.12) : Colors.transparent),
                                child: Row(children: [
                                  Icon(isDefaultOption ? Icons.sort_rounded : isManualOption ? Icons.drag_indicator : Icons.tune_rounded,
                                      size: 12, color: isSelected ? presetPurple : Colors.white30),
                                  const SizedBox(width: 8),
                                  Expanded(child: Text(isDefaultOption ? 'Default' : preset!.name,
                                      style: TextStyle(fontSize: 12, color: isSelected ? presetPurple : Colors.white70,
                                          fontWeight: isSelected ? FontWeight.w600 : FontWeight.normal))),
                                  if (isSelected) Padding(padding: const EdgeInsets.only(right: 4),
                                      child: Icon(Icons.check_rounded, size: 13, color: presetPurple)),
                                  if (!isDefaultOption)
                                    GestureDetector(onTap: () => showPresetMenu(preset!),
                                      child: Padding(padding: const EdgeInsets.only(left: 2),
                                        child: Icon(isManualOption ? Icons.lock_outline_rounded : Icons.more_vert_rounded,
                                            size: 14, color: isSelected ? presetPurple.withOpacity(0.6) : Colors.white24))),
                                ]),
                              ),
                            );
                          },
                        )),
                      ]),
                    ),
                  );
                });
              });
            },
            child: Container(
              padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 8),
              decoration: BoxDecoration(
                color: surface, borderRadius: BorderRadius.circular(7),
                border: Border.all(color: activePreset != null ? presetPurple.withOpacity(0.4) : border)),
              child: Row(children: [
                Icon(activePreset == null ? Icons.sort_rounded : isManualActive ? Icons.drag_indicator : Icons.tune_rounded,
                    size: 13, color: activePreset != null ? presetPurple : Colors.white38),
                const SizedBox(width: 8),
                Expanded(child: Text(selectedName, style: TextStyle(fontSize: 12,
                    color: activePreset != null ? presetPurple : Colors.white60,
                    fontWeight: activePreset != null ? FontWeight.w600 : FontWeight.normal))),
                Icon(Icons.expand_more_rounded, size: 15, color: activePreset != null ? presetPurple.withOpacity(0.6) : Colors.white24),
              ]),
            ),
          ),

          // Info chip when a preset is active
          if (activePreset != null) ...[
            const SizedBox(height: 6),
            Container(
              padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 6),
              decoration: BoxDecoration(
                color: const Color(0xFF9C27B0).withOpacity(0.08),
                borderRadius: BorderRadius.circular(5),
                border: Border.all(color: presetPurple.withOpacity(0.2))),
              child: Row(children: [
                Icon(isManualActive ? Icons.drag_indicator : Icons.info_outline_rounded,
                    size: 11, color: presetPurple),
                const SizedBox(width: 6),
                Expanded(child: Text(
                  isManualActive
                      ? 'Drag items in the list to set the Manual Ordering.'
                      : 'Sorting by preset "${activePreset.name}".',
                  style: const TextStyle(fontSize: 10, color: presetPurple))),
              ]),
            ),
          ],
        ]),
      );
    }

    // ── FILTER value widget ───────────────────────────────────────────────
    Widget filterValueWidget(NoteFilterRule rule) {
      final allTags = {for (final t in _allTasks) ...t.tagIds.map((id) => id.toString())}.toList()..sort();

      Widget checkList(List<String> items, String Function(String) labelFn) {
        return Column(crossAxisAlignment: CrossAxisAlignment.stretch, children: items.map((v) {
          final checked = rule.selectedValues.contains(v);
          return GestureDetector(
            onTap: () => setState(() { if (checked) rule.selectedValues.remove(v); else rule.selectedValues.add(v); }),
            child: Padding(padding: const EdgeInsets.symmetric(vertical: 3), child: Row(children: [
              checkbox(checked, () => setState(() { if (checked) rule.selectedValues.remove(v); else rule.selectedValues.add(v); })),
              const SizedBox(width: 8),
              Expanded(child: Text(labelFn(v), style: TextStyle(fontSize: 11, color: checked ? Colors.white : Colors.white60))),
            ])));
        }).toList());
      }

      switch (rule.fieldName) {
        case 'none': return const SizedBox.shrink();
        case 'name': return _NameFilterField(initialValue: rule.nameQuery, onChanged: (v) => setState(() => rule.nameQuery = v));
        case 'project': return checkList(_projects.keys.toList(), (v) => _projects[v]?.title ?? v);
        case 'tag': return checkList(allTags, (v) => v);
        case 'status':
          return Column(crossAxisAlignment: CrossAxisAlignment.stretch, children: TaskStatus.values.map((s) {
            final checked = rule.selectedValues.contains(s.name);
            return GestureDetector(
              onTap: () => setState(() { if (checked) rule.selectedValues.remove(s.name); else rule.selectedValues.add(s.name); }),
              child: Padding(padding: const EdgeInsets.symmetric(vertical: 3), child: Row(children: [
                checkbox(checked, () => setState(() { if (checked) rule.selectedValues.remove(s.name); else rule.selectedValues.add(s.name); })),
                const SizedBox(width: 8),
                Icon(s.icon, size: 11, color: s.color), const SizedBox(width: 4),
                Expanded(child: Text(s.label, style: TextStyle(fontSize: 11, color: checked ? Colors.white : Colors.white60))),
              ])));
          }).toList());
        case 'repeating':
          final opts = [('repeating', 'Repeating', Icons.repeat_rounded, const Color(0xFF4FC3F7)),
                        ('nonRepeating', 'Non-Repeating', Icons.repeat_one_rounded, const Color(0xFF9E9E9E))];
          return Column(crossAxisAlignment: CrossAxisAlignment.stretch, children: opts.map((o) {
            final (v, l, ic, co) = o; final checked = rule.selectedValues.contains(v);
            return GestureDetector(
              onTap: () => setState(() { if (checked) rule.selectedValues.remove(v); else rule.selectedValues.add(v); }),
              child: Padding(padding: const EdgeInsets.symmetric(vertical: 3), child: Row(children: [
                checkbox(checked, () => setState(() { if (checked) rule.selectedValues.remove(v); else rule.selectedValues.add(v); })),
                const SizedBox(width: 8),
                Icon(ic, size: 12, color: checked ? co : co.withOpacity(0.45)), const SizedBox(width: 5),
                Expanded(child: Text(l, style: TextStyle(fontSize: 11, color: checked ? Colors.white : Colors.white60))),
              ])));
          }).toList());
        case 'groups':
          if (_groupContainers.isEmpty)
            return const Padding(padding: EdgeInsets.symmetric(vertical: 4),
                child: Text('No group containers defined.', style: TextStyle(fontSize: 10, color: Colors.white38)));
          return checkList(_groupContainers.map((g) => g.id).toList(),
              (v) { try { final g = _groupContainers.firstWhere((g) => g.id == v); return g.displayLabel.isEmpty ? '(unnamed)' : g.displayLabel; } catch (_) { return v; } });
        case 'scheduledDate':
          String fmt(DateTime? d) => d == null ? 'Any' : '${d.day.toString().padLeft(2,'0')}/${d.month.toString().padLeft(2,'0')}/${d.year}';
          Widget datePick(String lbl, DateTime? val, void Function(DateTime) onPick) => Row(children: [
            SizedBox(width: 36, child: Text(lbl, style: const TextStyle(fontSize: 10, color: Colors.white38))),
            Expanded(child: GestureDetector(
              onTap: () async {
                final p = await showDatePicker(context: context, initialDate: val ?? DateTime.now(), firstDate: DateTime(2020), lastDate: DateTime(2040),
                    builder: (ctx, c) => Theme(data: Theme.of(ctx).copyWith(colorScheme: const ColorScheme.dark(primary: accent, surface: Color(0xFF1E2124))), child: c!));
                if (p != null) onPick(p);
              },
              child: Container(padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 5),
                  decoration: BoxDecoration(color: surface, borderRadius: BorderRadius.circular(4), border: Border.all(color: border)),
                  child: Text(fmt(val), style: const TextStyle(fontSize: 10, color: Colors.white70))))),
            if (val != null) GestureDetector(
              onTap: () => setState(() { if (lbl == 'From') rule.dateFrom = null; else rule.dateTo = null; }),
              child: const Padding(padding: EdgeInsets.only(left: 4), child: Icon(Icons.close_rounded, size: 12, color: Colors.white30))),
          ]);
          return Column(crossAxisAlignment: CrossAxisAlignment.stretch, children: [
            datePick('From', rule.dateFrom, (d) => setState(() => rule.dateFrom = d)),
            const SizedBox(height: 5),
            datePick('To', rule.dateTo, (d) => setState(() => rule.dateTo = d)),
          ]);
        default: return const SizedBox.shrink();
      }
    }

    final taskFilterFields = NoteTaskFilterField.values.where((f) => f != NoteTaskFilterField.none).map((e) => e.name).toList();
    String taskFilterLabel(String f) { try { return NoteTaskFilterField.values.byName(f).label; } catch (_) { return f; } }
    final commonFilterFields = NoteCommonFilterField.values.where((f) => f != NoteCommonFilterField.none).map((e) => e.name).toList();
    String commonFilterLabel(String f) { try { return NoteCommonFilterField.values.byName(f).label; } catch (_) { return f; } }
    final fieldList = isTask ? taskFilterFields : commonFilterFields;
    final fieldLabelFn = isTask ? taskFilterLabel : commonFilterLabel;

    Widget buildGroupSection() => isTask
        ? Padding(padding: const EdgeInsets.fromLTRB(10, 4, 10, 10), child: fieldDropdown<NoteTaskGroupField>(
            value: _noteTaskGroupField, items: NoteTaskGroupField.values.toList(), label: (f) => f.label,
            onChanged: (f) => setState(() => _noteTaskGroupField = f)))
        : Padding(padding: const EdgeInsets.fromLTRB(10, 4, 10, 10), child: fieldDropdown<NoteCommonGroupField>(
            value: _noteCommonGroupField, items: NoteCommonGroupField.values.toList(), label: (f) => f.label,
            onChanged: (f) => setState(() => _noteCommonGroupField = f)));

    // ── Layout ────────────────────────────────────────────────────────────
    return Container(
      width: 264,
      decoration: BoxDecoration(color: bg, border: Border(left: BorderSide(color: Colors.white.withOpacity(0.07)))),
      child: Column(crossAxisAlignment: CrossAxisAlignment.stretch, children: [
        Container(
          padding: const EdgeInsets.fromLTRB(14, 11, 10, 11),
          decoration: BoxDecoration(border: Border(bottom: BorderSide(color: Colors.white.withOpacity(0.07)))),
          child: Row(children: [
            const Icon(Icons.filter_list, size: 13, color: Colors.white54), const SizedBox(width: 8),
            Expanded(child: Text('Filter / Group / Sort  ·  ${isTask ? 'Tasks' : 'Common'}',
                style: const TextStyle(fontSize: 11, fontWeight: FontWeight.w600, color: Colors.white70))),
            GestureDetector(onTap: () => setState(() => _filterSidebarOpen = false),
                child: const Icon(Icons.close_rounded, size: 15, color: Colors.white38)),
          ]),
        ),
        Expanded(child: ListView(padding: const EdgeInsets.only(bottom: 20), children: [

          // ══════ FILTER ══════
          sectionHeader('FILTER', () => setState(() => filterRules().clear()), filterCollapsed(), () => setFilterCollapsed(!filterCollapsed())),
          if (!filterCollapsed()) ...[
            ...filterRules().asMap().entries.map((entry) {
              final rule = entry.value;
              return Container(key: ValueKey(rule.id), margin: const EdgeInsets.fromLTRB(10, 0, 10, 8), padding: const EdgeInsets.all(10),
                decoration: BoxDecoration(color: surface, borderRadius: BorderRadius.circular(7), border: Border.all(color: border)),
                child: Column(crossAxisAlignment: CrossAxisAlignment.stretch, children: [
                  Row(children: [
                    Expanded(child: fieldDropdown<String>(value: rule.fieldName, items: fieldList, label: fieldLabelFn,
                      onChanged: (f) => setState(() { rule.fieldName = f; rule.selectedValues.clear(); rule.nameQuery = ''; rule.dateFrom = null; rule.dateTo = null;
                        if (f == 'repeating') rule.selectedValues.addAll({'repeating', 'nonRepeating'}); }))),
                    removeBtn(() => setState(() => filterRules().remove(rule))),
                  ]),
                  if (rule.fieldName != 'none') ...[const SizedBox(height: 8), filterValueWidget(rule)],
                ]));
            }),
            Padding(padding: const EdgeInsets.symmetric(horizontal: 10),
              child: GestureDetector(onTap: () => setState(() => filterRules().add(NoteFilterRule(id: _gristId()))),
                child: Container(padding: const EdgeInsets.symmetric(vertical: 7),
                  decoration: BoxDecoration(color: Colors.white.withOpacity(0.03), borderRadius: BorderRadius.circular(5), border: Border.all(color: Colors.white12)),
                  child: const Row(mainAxisAlignment: MainAxisAlignment.center, children: [
                    Icon(Icons.add, size: 13, color: Colors.white38), SizedBox(width: 4),
                    Text('Add Filter', style: TextStyle(fontSize: 11, color: Colors.white38))])))),
          ],

          // ══════ GROUP ══════
          divider(),
          sectionHeader('GROUP', () => setState(() { if (isTask) _noteTaskGroupField = NoteTaskGroupField.none; else _noteCommonGroupField = NoteCommonGroupField.none; }),
              groupCollapsed(), () => setGroupCollapsed(!groupCollapsed())),
          if (!groupCollapsed()) buildGroupSection(),

          // ══════ SORT ══════
          divider(),
          sectionHeader('SORT', () => setState(() {
            _notesSetActivePreset(isTask, null);
            if (isTask) { _noteTaskDefaultFolderCriteria.clear(); _noteTaskDefaultItemCriteria.clear(); }
            else { _noteCommonDefaultFolderCriteria.clear(); _noteCommonDefaultItemCriteria.clear(); }
          }), sortCollapsed(), () => setSortCollapsed(!sortCollapsed())),

          if (!sortCollapsed()) ...[
            buildPresetDropdown(),

            // Sort criteria — only when NOT Manual Ordering
            if (!isManualActive) ...[

              // ── Sort Folders ──
              subSectionHeader('SORT FOLDERS', sortFoldersCollapsed(), () => setSortFoldersCollapsed(!sortFoldersCollapsed())),
              if (!sortFoldersCollapsed()) Builder(builder: (_) {
                final fc = activePreset?.folderCriteria ?? (isTask ? _noteTaskDefaultFolderCriteria : _noteCommonDefaultFolderCriteria);
                return Column(crossAxisAlignment: CrossAxisAlignment.stretch, children: [
                  if (fc.isNotEmpty) ReorderableListView(shrinkWrap: true, physics: const NeverScrollableScrollPhysics(),
                    buildDefaultDragHandles: false,
                    onReorder: (o, n) => setState(() { if (n > o) n--; fc.insert(n, fc.removeAt(o)); }),
                    children: fc.asMap().entries.map((e) => sortCriterionRow(sc: e.value, idx: e.key, list: fc,
                        fieldNames: folderFieldNames, fieldLabel: folderFieldLabel, dirLabel: folderDirLabel)).toList()),
                  addSortBtn(fc, NoteFolderSortField.name.name),
                ]);
              }),

              // ── Sort Internal Items ──
              subSectionHeader('SORT INTERNAL ITEMS', sortItemsCollapsed(), () => setSortItemsCollapsed(!sortItemsCollapsed())),
              if (!sortItemsCollapsed()) Builder(builder: (_) {
                final ic = activePreset?.itemCriteria ?? (isTask ? _noteTaskDefaultItemCriteria : _noteCommonDefaultItemCriteria);
                return Column(crossAxisAlignment: CrossAxisAlignment.stretch, children: [
                  if (ic.isNotEmpty) ReorderableListView(shrinkWrap: true, physics: const NeverScrollableScrollPhysics(),
                    buildDefaultDragHandles: false,
                    onReorder: (o, n) => setState(() { if (n > o) n--; ic.insert(n, ic.removeAt(o)); }),
                    children: ic.asMap().entries.map((e) => sortCriterionRow(sc: e.value, idx: e.key, list: ic,
                        fieldNames: isTask ? taskItemFieldNames : commonItemFieldNames,
                        fieldLabel: isTask ? taskItemFieldLabel : commonItemFieldLabel,
                        dirLabel: isTask ? taskItemDirLabel : commonItemDirLabel)).toList()),
                  addSortBtn(ic, isTask ? NoteTaskItemSortField.name.name : NoteCommonItemSortField.name.name),
                ]);
              }),
            ],
          ],
        ])),
      ]),
    );
  }


  Widget _buildFilterSidebar() {
    if (!_filterSidebarOpen) return const SizedBox.shrink();

    if (_filterSidebarTitle == 'Notes Tasks' || _filterSidebarTitle == 'Notes Common') {
      return _buildNotesFGSSidebar(_filterSidebarTitle);
    }

    final allTags = {
      for (final t in _allTasks) ...t.tagIds.map((id) => id.toString()),
    }.toList()..sort();
    final allProjects = _projects.entries.toList();

    // ── shared helpers ──────────────────────────────────────────────────────
    const accent = Color(0xFF4FC3F7);
    const bg = Color(0xFF1A1C1F);
    const surface = Color(0xFF22252A);
    const border = Color(0xFF2C2F35);

    Widget sectionHeader(
      String title,
      VoidCallback onClearAll,
      bool collapsed,
      VoidCallback onToggle,
    ) {
      return GestureDetector(
        onTap: onToggle,
        child: Padding(
          padding: const EdgeInsets.fromLTRB(10, 10, 10, 6),
          child: Row(
            children: [
              AnimatedRotation(
                turns: collapsed ? -0.25 : 0,
                duration: const Duration(milliseconds: 150),
                child: const Icon(
                  Icons.expand_more_rounded,
                  size: 14,
                  color: Colors.white38,
                ),
              ),
              const SizedBox(width: 6),
              Text(
                title,
                style: const TextStyle(
                  fontSize: 10,
                  fontWeight: FontWeight.w700,
                  letterSpacing: 1.0,
                  color: Colors.white60,
                ),
              ),
              const Spacer(),
              GestureDetector(
                onTap: () {
                  onClearAll();
                },
                child: const Text(
                  'Restore Defaults',
                  style: TextStyle(fontSize: 9, color: accent),
                ),
              ),
            ],
          ),
        ),
      );
    }

    Widget fieldDropdown<T>({
      required T value,
      required List<T> items,
      required String Function(T) label,
      required void Function(T) onChanged,
    }) {
      return GestureDetector(
        onTap: () => showDialog<T>(
          context: context,
          barrierColor: Colors.transparent,
          builder: (_) => _DropdownDialog<T>(
            current: value,
            items: items,
            itemLabel: label,
            onSelected: (v) {
              onChanged(v);
              Navigator.of(context).pop();
            },
          ),
        ),
        child: Container(
          padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 6),
          decoration: BoxDecoration(
            color: surface,
            borderRadius: BorderRadius.circular(5),
            border: Border.all(color: border),
          ),
          child: Row(
            mainAxisSize: MainAxisSize.min,
            children: [
              Flexible(
                child: Text(
                  label(value),
                  overflow: TextOverflow.ellipsis,
                  style: const TextStyle(fontSize: 11, color: Colors.white70),
                ),
              ),
              const SizedBox(width: 4),
              const Icon(
                Icons.expand_more_rounded,
                size: 12,
                color: Colors.white38,
              ),
            ],
          ),
        ),
      );
    }

    Widget dirBtn(
      bool asc,
      void Function(bool) onTap, {
      String? ascLabel,
      String? descLabel,
    }) {
      return GestureDetector(
        onTap: () => onTap(!asc),
        child: Container(
          padding: const EdgeInsets.symmetric(horizontal: 6, vertical: 5),
          decoration: BoxDecoration(
            color: accent.withOpacity(0.12),
            borderRadius: BorderRadius.circular(4),
            border: Border.all(color: accent.withOpacity(0.3)),
          ),
          child: Text(
            asc ? (ascLabel ?? '↑ Asc') : (descLabel ?? '↓ Desc'),
            style: const TextStyle(
              fontSize: 9,
              color: accent,
              fontWeight: FontWeight.w600,
            ),
          ),
        ),
      );
    }

    Widget removeBtn(VoidCallback onTap) => GestureDetector(
      onTap: onTap,
      child: const Padding(
        padding: EdgeInsets.only(left: 4),
        child: Icon(Icons.close_rounded, size: 14, color: Colors.white30),
      ),
    );

    // ── FILTER value widget per rule ────────────────────────────────────────
    Widget filterValueWidget(FilterRule rule) {
      switch (rule.field) {
        case TaskFilterField.none:
          return const SizedBox.shrink();

        case TaskFilterField.name:
          return _NameFilterField(
            initialValue: rule.nameQuery,
            onChanged: (v) => setState(() => rule.nameQuery = v),
          );

        case TaskFilterField.tag:
        case TaskFilterField.project:
        case TaskFilterField.status:
          final items = rule.field == TaskFilterField.tag
              ? allTags
              : rule.field == TaskFilterField.project
              ? allProjects.map((e) => e.key).toList()
              : TaskStatus.values.map((s) => s.name).toList();
          String labelFor(String v) {
            if (rule.field == TaskFilterField.project) {
              return _projects[v]?.title ?? v;
            }
            if (rule.field == TaskFilterField.status) {
              try {
                return TaskStatus.values.byName(v).label;
              } catch (_) {
                return v;
              }
            }
            return v;
          }

          return Column(
            crossAxisAlignment: CrossAxisAlignment.stretch,
            children: [
              ...items.map((v) {
                final checked = rule.selectedValues.contains(v);
                return GestureDetector(
                  onTap: () => setState(() {
                    if (checked)
                      rule.selectedValues.remove(v);
                    else
                      rule.selectedValues.add(v);
                  }),
                  child: Padding(
                    padding: const EdgeInsets.symmetric(vertical: 3),
                    child: Row(
                      children: [
                        AnimatedContainer(
                          duration: const Duration(milliseconds: 100),
                          width: 14,
                          height: 14,
                          decoration: BoxDecoration(
                            color: checked
                                ? accent.withOpacity(0.2)
                                : Colors.transparent,
                            borderRadius: BorderRadius.circular(3),
                            border: Border.all(
                              color: checked ? accent : Colors.white30,
                              width: 1.2,
                            ),
                          ),
                          child: checked
                              ? const Icon(
                                  Icons.check_rounded,
                                  size: 10,
                                  color: accent,
                                )
                              : null,
                        ),
                        const SizedBox(width: 8),
                        if (rule.field == TaskFilterField.status) ...[
                          Builder(
                            builder: (_) {
                              try {
                                final s = TaskStatus.values.byName(v);
                                return Row(
                                  children: [
                                    Icon(s.icon, size: 11, color: s.color),
                                    const SizedBox(width: 4),
                                  ],
                                );
                              } catch (_) {
                                return const SizedBox.shrink();
                              }
                            },
                          ),
                        ],
                        Expanded(
                          child: Text(
                            labelFor(v),
                            style: TextStyle(
                              fontSize: 11,
                              color: checked ? Colors.white : Colors.white60,
                            ),
                          ),
                        ),
                      ],
                    ),
                  ),
                );
              }),
            ],
          );

        case TaskFilterField.repeating:
          final repOptions = [
            {
              'value': 'repeating',
              'label': 'Repeating',
              'icon': Icons.repeat_rounded,
              'color': const Color(0xFF4FC3F7),
            },
            {
              'value': 'nonRepeating',
              'label': 'Non-Repeating',
              'icon': Icons.repeat_one_rounded,
              'color': const Color(0xFF9E9E9E),
            },
          ];
          return Column(
            crossAxisAlignment: CrossAxisAlignment.stretch,
            children: repOptions.map((opt) {
              final value = opt['value'] as String;
              final label = opt['label'] as String;
              final icon = opt['icon'] as IconData;
              final color = opt['color'] as Color;
              final checked = rule.selectedValues.contains(value);
              return GestureDetector(
                onTap: () => setState(() {
                  if (checked)
                    rule.selectedValues.remove(value);
                  else
                    rule.selectedValues.add(value);
                }),
                child: Padding(
                  padding: const EdgeInsets.symmetric(vertical: 3),
                  child: Row(
                    children: [
                      AnimatedContainer(
                        duration: const Duration(milliseconds: 100),
                        width: 14,
                        height: 14,
                        decoration: BoxDecoration(
                          color: checked
                              ? color.withOpacity(0.2)
                              : Colors.transparent,
                          borderRadius: BorderRadius.circular(3),
                          border: Border.all(
                            color: checked ? color : Colors.white30,
                            width: 1.2,
                          ),
                        ),
                        child: checked
                            ? Icon(Icons.check_rounded, size: 10, color: color)
                            : null,
                      ),
                      const SizedBox(width: 8),
                      Icon(
                        icon,
                        size: 12,
                        color: checked ? color : color.withOpacity(0.45),
                      ),
                      const SizedBox(width: 5),
                      Expanded(
                        child: Text(
                          label,
                          style: TextStyle(
                            fontSize: 11,
                            color: checked ? Colors.white : Colors.white60,
                          ),
                        ),
                      ),
                    ],
                  ),
                ),
              );
            }).toList(),
          );

        case TaskFilterField.groups:
          if (_groupContainers.isEmpty) {
            return const Padding(
              padding: EdgeInsets.symmetric(vertical: 4),
              child: Text(
                'No group containers defined.',
                style: TextStyle(fontSize: 10, color: Colors.white38),
              ),
            );
          }
          return Column(
            crossAxisAlignment: CrossAxisAlignment.stretch,
            children: _groupContainers.map((gc) {
              final value = gc.id;
              final label = gc.displayLabel.isEmpty ? '(unnamed)' : gc.displayLabel;
              final checked = rule.selectedValues.contains(value);
              return GestureDetector(
                onTap: () => setState(() {
                  if (checked)
                    rule.selectedValues.remove(value);
                  else
                    rule.selectedValues.add(value);
                }),
                child: Padding(
                  padding: const EdgeInsets.symmetric(vertical: 3),
                  child: Row(
                    children: [
                      AnimatedContainer(
                        duration: const Duration(milliseconds: 100),
                        width: 14,
                        height: 14,
                        decoration: BoxDecoration(
                          color: checked
                              ? accent.withOpacity(0.2)
                              : Colors.transparent,
                          borderRadius: BorderRadius.circular(3),
                          border: Border.all(
                            color: checked ? accent : Colors.white30,
                            width: 1.2,
                          ),
                        ),
                        child: checked
                            ? const Icon(Icons.check_rounded, size: 10, color: accent)
                            : null,
                      ),
                      const SizedBox(width: 8),
                      Expanded(
                        child: Text(
                          label,
                          style: TextStyle(
                            fontSize: 11,
                            color: checked ? Colors.white : Colors.white60,
                          ),
                        ),
                      ),
                    ],
                  ),
                ),
              );
            }).toList(),
          );

        case TaskFilterField.insertionDate:
          String fmt(DateTime? d) => d == null
              ? 'Any'
              : '${d.day.toString().padLeft(2, '0')}/${d.month.toString().padLeft(2, '0')}/${d.year}';

          Widget datePick2(
            String label,
            DateTime? val,
            void Function(DateTime) onPick,
          ) {
            return Row(
              children: [
                SizedBox(
                  width: 36,
                  child: Text(
                    label,
                    style: const TextStyle(fontSize: 10, color: Colors.white38),
                  ),
                ),
                Expanded(
                  child: GestureDetector(
                    onTap: () async {
                      final p = await showDatePicker(
                        context: context,
                        initialDate: val ?? DateTime.now(),
                        firstDate: DateTime(2020),
                        lastDate: DateTime(2040),
                        builder: (ctx, c) => Theme(
                          data: Theme.of(ctx).copyWith(
                            colorScheme: const ColorScheme.dark(
                              primary: accent,
                              surface: Color(0xFF1E2124),
                            ),
                          ),
                          child: c!,
                        ),
                      );
                      if (p != null) onPick(p);
                    },
                    child: Container(
                      padding: const EdgeInsets.symmetric(
                        horizontal: 8,
                        vertical: 5,
                      ),
                      decoration: BoxDecoration(
                        color: surface,
                        borderRadius: BorderRadius.circular(4),
                        border: Border.all(color: border),
                      ),
                      child: Text(
                        fmt(val),
                        style: const TextStyle(
                          fontSize: 10,
                          color: Colors.white70,
                        ),
                      ),
                    ),
                  ),
                ),
                if (val != null)
                  GestureDetector(
                    onTap: () => setState(() {
                      if (label == 'From')
                        rule.dateFrom = null;
                      else
                        rule.dateTo = null;
                    }),
                    child: const Padding(
                      padding: EdgeInsets.only(left: 4),
                      child: Icon(
                        Icons.close_rounded,
                        size: 12,
                        color: Colors.white30,
                      ),
                    ),
                  ),
              ],
            );
          }

          return Column(
            crossAxisAlignment: CrossAxisAlignment.stretch,
            children: [
              datePick2(
                'From',
                rule.dateFrom,
                (d) => setState(() => rule.dateFrom = d),
              ),
              const SizedBox(height: 5),
              datePick2(
                'To',
                rule.dateTo,
                (d) => setState(() => rule.dateTo = d),
              ),
            ],
          );

        case TaskFilterField.scheduledDate:
          String fmt(DateTime? d) => d == null
              ? 'Any'
              : '${d.day.toString().padLeft(2, '0')}/${d.month.toString().padLeft(2, '0')}/${d.year}';

          Widget datePick(
            String label,
            DateTime? val,
            void Function(DateTime) onPick,
          ) {
            return Row(
              children: [
                SizedBox(
                  width: 36,
                  child: Text(
                    label,
                    style: const TextStyle(fontSize: 10, color: Colors.white38),
                  ),
                ),
                Expanded(
                  child: GestureDetector(
                    onTap: () async {
                      final p = await showDatePicker(
                        context: context,
                        initialDate: val ?? DateTime.now(),
                        firstDate: DateTime(2020),
                        lastDate: DateTime(2040),
                        builder: (ctx, c) => Theme(
                          data: Theme.of(ctx).copyWith(
                            colorScheme: const ColorScheme.dark(
                              primary: accent,
                              surface: Color(0xFF1E2124),
                            ),
                          ),
                          child: c!,
                        ),
                      );
                      if (p != null) onPick(p);
                    },
                    child: Container(
                      padding: const EdgeInsets.symmetric(
                        horizontal: 8,
                        vertical: 5,
                      ),
                      decoration: BoxDecoration(
                        color: surface,
                        borderRadius: BorderRadius.circular(4),
                        border: Border.all(color: border),
                      ),
                      child: Text(
                        fmt(val),
                        style: const TextStyle(
                          fontSize: 10,
                          color: Colors.white70,
                        ),
                      ),
                    ),
                  ),
                ),
                if (val != null)
                  GestureDetector(
                    onTap: () => setState(() {
                      if (label == 'From')
                        rule.dateFrom = null;
                      else
                        rule.dateTo = null;
                    }),
                    child: const Padding(
                      padding: EdgeInsets.only(left: 4),
                      child: Icon(
                        Icons.close_rounded,
                        size: 12,
                        color: Colors.white30,
                      ),
                    ),
                  ),
              ],
            );
          }

          return Column(
            crossAxisAlignment: CrossAxisAlignment.stretch,
            children: [
              datePick(
                'From',
                rule.dateFrom,
                (d) => setState(() => rule.dateFrom = d),
              ),
              const SizedBox(height: 5),
              datePick(
                'To',
                rule.dateTo,
                (d) => setState(() => rule.dateTo = d),
              ),
            ],
          );

        case TaskFilterField.estimatedTime:
        case TaskFilterField.timeSpent:
          return Row(
            children: [
              Expanded(
                child: _MinuteInput(
                  label: 'Min',
                  value: rule.numMin,
                  onChanged: (v) => setState(() => rule.numMin = v),
                ),
              ),
              const SizedBox(width: 6),
              Expanded(
                child: _MinuteInput(
                  label: 'Max',
                  value: rule.numMax,
                  onChanged: (v) => setState(() => rule.numMax = v),
                ),
              ),
            ],
          );
      }
    }

    // ── Build section ──────────────────────────────────────────────────────
    return Container(
      width: 264,
      decoration: BoxDecoration(
        color: bg,
        border: Border(left: BorderSide(color: Colors.white.withOpacity(0.07))),
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.stretch,
        children: [
          // Header
          Container(
            padding: const EdgeInsets.fromLTRB(14, 11, 10, 11),
            decoration: BoxDecoration(
              border: Border(
                bottom: BorderSide(color: Colors.white.withOpacity(0.07)),
              ),
            ),
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              mainAxisSize: MainAxisSize.min,
              children: [
                Row(
                  children: [
                    const Icon(
                      Icons.filter_list,
                      size: 13,
                      color: Colors.white54,
                    ),
                    const SizedBox(width: 8),
                    const Expanded(
                      child: Text(
                        'Filter / Group / Sort',
                        style: TextStyle(
                          fontSize: 11,
                          fontWeight: FontWeight.w600,
                          color: Colors.white70,
                        ),
                      ),
                    ),
                    GestureDetector(
                      onTap: () => setState(() => _filterSidebarOpen = false),
                      child: const Icon(
                        Icons.close_rounded,
                        size: 15,
                        color: Colors.white38,
                      ),
                    ),
                  ],
                ),
              ],
            ),
          ),

          Expanded(
            child: ListView(
              padding: const EdgeInsets.only(bottom: 20),
              children: [
                // ════════════════ FILTER ════════════════
                sectionHeader(
                  'FILTER',
                  () => setState(() => _filterRules.clear()),
                  _fgsSectionFilterCollapsed,
                  () => setState(() => _fgsSectionFilterCollapsed = !_fgsSectionFilterCollapsed),
                ),
                if (!_fgsSectionFilterCollapsed)
                ..._filterRules.asMap().entries.map((entry) {
                  final idx = entry.key;
                  final rule = entry.value;
                  return Container(
                    key: ValueKey(rule.id),
                    margin: const EdgeInsets.fromLTRB(10, 0, 10, 8),
                    padding: const EdgeInsets.all(10),
                    decoration: BoxDecoration(
                      color: surface,
                      borderRadius: BorderRadius.circular(7),
                      border: Border.all(color: border),
                    ),
                    child: Column(
                      crossAxisAlignment: CrossAxisAlignment.stretch,
                      children: [
                        Row(
                          children: [
                            Expanded(
                              child: fieldDropdown<TaskFilterField>(
                                value: rule.field,
                                items: TaskFilterField.values
                                    .where((f) => f != TaskFilterField.none)
                                    .toList(),
                                label: (f) => f.label,
                                onChanged: (f) => setState(() {
                                  rule.field = f;
                                  rule.selectedValues.clear();
                                  rule.nameQuery = '';
                                  rule.dateFrom = null;
                                  rule.dateTo = null;
                                  rule.numMin = null;
                                  rule.numMax = null;
                                  // Default repeating filter to both options
                                  if (f == TaskFilterField.repeating) {
                                    rule.selectedValues.addAll(const {
                                      'repeating',
                                      'nonRepeating',
                                    });
                                  }
                                }),
                              ),
                            ),
                            removeBtn(
                              () => setState(() => _filterRules.removeAt(idx)),
                            ),
                          ],
                        ),
                        if (rule.field != TaskFilterField.none) ...[
                          const SizedBox(height: 8),
                          filterValueWidget(rule),
                        ],
                      ],
                    ),
                  );
                }),
                if (!_fgsSectionFilterCollapsed)
                Padding(
                  padding: const EdgeInsets.symmetric(horizontal: 10),
                  child: GestureDetector(
                    onTap: () => setState(
                      () => _filterRules.add(FilterRule(id: _gristId())),
                    ),
                    child: Container(
                      padding: const EdgeInsets.symmetric(vertical: 7),
                      decoration: BoxDecoration(
                        color: Colors.white.withOpacity(0.03),
                        borderRadius: BorderRadius.circular(5),
                        border: Border.all(color: Colors.white12),
                      ),
                      child: const Row(
                        mainAxisAlignment: MainAxisAlignment.center,
                        children: [
                          Icon(Icons.add, size: 13, color: Colors.white38),
                          SizedBox(width: 4),
                          Text(
                            'Add Filter',
                            style: TextStyle(
                              fontSize: 11,
                              color: Colors.white38,
                            ),
                          ),
                        ],
                      ),
                    ),
                  ),
                ),

                // ════════════════ GROUP ════════════════
                Padding(
                  padding: const EdgeInsets.only(top: 6),
                  child: Container(
                    height: 1,
                    color: Colors.white.withOpacity(0.05),
                  ),
                ),
                sectionHeader(
                  'GROUP',
                  () => setState(() {
                    _groupContainers = _defaultGroupContainers();
                    _collapsedContainerIds.clear();
                  }),
                  _fgsSectionGroupCollapsed,
                  () => setState(() => _fgsSectionGroupCollapsed = !_fgsSectionGroupCollapsed),
                ),
                if (!_fgsSectionGroupCollapsed)
                // ── Metagroup chips (individual criteria, drag one at a time) ──
                _MetagroupCriteriaPanel(
                  allTasks: _allTasks,
                  projects: _projects,
                  groupContainers: _groupContainers,
                  onAddCriterion: (gcTarget, criterion) => setState(() {
                    final items = gcTarget.criteriaItems;
                    // Set operator before the new item if list not empty
                    if (items.isNotEmpty) {
                      items.last.operatorAfter = gcTarget.defaultOperator;
                    }
                    items.add(criterion);
                  }),
                  onAddContainer: (gc) => setState(() => _groupContainers.add(gc)),
                  gristId: _gristId,
                ),
                if (!_fgsSectionGroupCollapsed)
                // ── Container list ───────────────────────────────────────
                ReorderableListView(
                  shrinkWrap: true,
                  physics: const NeverScrollableScrollPhysics(),
                  buildDefaultDragHandles: false,
                  onReorder: (o, n) => setState(() {
                    if (n > o) n--;
                    final item = _groupContainers.removeAt(o);
                    _groupContainers.insert(n, item);
                  }),
                  children: _groupContainers.asMap().entries.map((entry) {
                    final idx = entry.key;
                    final gc = entry.value;
                    final labelCtrl = TextEditingController(text: gc.displayLabel);

                    // ── Helper: add criterion to this container ─────────
                    void addCriterion(ContainerCriteriaItem newItem) {
                      setState(() {
                        if (gc.criteriaItems.isNotEmpty) {
                          gc.criteriaItems.last.operatorAfter = gc.defaultOperator;
                        }
                        gc.criteriaItems.add(newItem);
                      });
                    }

                    // ── Flat-token criteria list ─────────────────────────
                    // Each criterion AND each operator becomes its own row,
                    // so every element is independently draggable/reorderable.
                    Widget buildFlatCriteriaList() {
                      final tokens = _flattenGcTokens(gc.criteriaItems);
                      if (tokens.isEmpty) return const SizedBox.shrink();
                      return Padding(
                        padding: const EdgeInsets.fromLTRB(8, 0, 8, 6),
                        child: ReorderableListView(
                          shrinkWrap: true,
                          physics: const NeverScrollableScrollPhysics(),
                          buildDefaultDragHandles: false,
                          onReorder: (oldIdx, newIdx) => setState(() {
                            if (newIdx > oldIdx) newIdx--;
                            final tok = tokens.removeAt(oldIdx);
                            tokens.insert(newIdx, tok);
                            _rebuildGcFromTokens(tokens, gc);
                          }),
                          children: tokens.asMap().entries.map((e) {
                            final tokIdx = e.key;
                            final tok = e.value;

                            if (tok is _GcCriterionToken) {
                              // ── Criterion chip ────────────────────────
                              final item = tok.item;
                              final col = item.color;
                              final isParen =
                                  item.type == CriteriaItemType.parenOpen ||
                                  item.type == CriteriaItemType.parenClose;
                              return Container(
                                key: ValueKey(tok.tokenKey),
                                margin: const EdgeInsets.only(bottom: 2),
                                decoration: BoxDecoration(
                                  color: col.withOpacity(isParen ? 0.08 : 0.12),
                                  borderRadius: BorderRadius.circular(5),
                                  border: Border.all(color: col.withOpacity(0.4)),
                                ),
                                child: Row(
                                  mainAxisSize: MainAxisSize.min,
                                  children: [
                                    ReorderableDragStartListener(
                                      index: tokIdx,
                                      child: Padding(
                                        padding: const EdgeInsets.symmetric(
                                            horizontal: 3),
                                        child: Icon(Icons.drag_indicator,
                                            size: 10,
                                            color: col.withOpacity(0.5)),
                                      ),
                                    ),
                                    Padding(
                                      padding: const EdgeInsets.only(
                                          right: 4, top: 2, bottom: 2),
                                      child: Text(
                                        item.label,
                                        style: TextStyle(
                                          fontSize: 10,
                                          color: col,
                                          fontWeight: FontWeight.w600,
                                        ),
                                      ),
                                    ),
                                    if (_groupContainers.length > 1)
                                      GestureDetector(
                                        onTap: () {
                                          showDialog<GroupContainer>(
                                            context: context,
                                            barrierColor: Colors.black54,
                                            builder: (_) =>
                                                _MoveToContainerDialog(
                                              containers: _groupContainers
                                                  .where((c) => c.id != gc.id)
                                                  .toList(),
                                            ),
                                          ).then((target) {
                                            if (target == null) return;
                                            setState(() {
                                              // Remove criterion + trailing op
                                              final newToks = _flattenGcTokens(
                                                  gc.criteriaItems);
                                              final ci = newToks.indexWhere(
                                                (t) =>
                                                    t is _GcCriterionToken &&
                                                    t.item.id == item.id,
                                              );
                                              if (ci >= 0) {
                                                newToks.removeAt(ci);
                                                if (ci < newToks.length &&
                                                    newToks[ci]
                                                        is _GcOperatorToken) {
                                                  newToks.removeAt(ci);
                                                }
                                              }
                                              _rebuildGcFromTokens(newToks, gc);
                                              // Append to target container
                                              if (target.criteriaItems
                                                  .isNotEmpty) {
                                                target.criteriaItems.last
                                                    .operatorAfter =
                                                    target.defaultOperator;
                                              }
                                              item.operatorAfter = null;
                                              target.criteriaItems.add(item);
                                            });
                                          });
                                        },
                                        child: Padding(
                                          padding: const EdgeInsets.only(
                                              right: 3),
                                          child: Icon(Icons.arrow_forward,
                                              size: 9,
                                              color: col.withOpacity(0.5)),
                                        ),
                                      ),
                                    GestureDetector(
                                      onTap: () => setState(() {
                                        final newToks = _flattenGcTokens(
                                            gc.criteriaItems);
                                        final ci = newToks.indexWhere(
                                          (t) =>
                                              t is _GcCriterionToken &&
                                              t.item.id == item.id,
                                        );
                                        if (ci >= 0) {
                                          newToks.removeAt(ci);
                                          if (ci < newToks.length &&
                                              newToks[ci]
                                                  is _GcOperatorToken) {
                                            newToks.removeAt(ci);
                                          }
                                        }
                                        _rebuildGcFromTokens(newToks, gc);
                                      }),
                                      child: Padding(
                                        padding:
                                            const EdgeInsets.only(right: 4),
                                        child: Icon(Icons.close,
                                            size: 9,
                                            color: col.withOpacity(0.5)),
                                      ),
                                    ),
                                  ],
                                ),
                              );
                            } else {
                              // ── Operator token ────────────────────────
                              final opTok = tok as _GcOperatorToken;
                              Color opColor;
                              switch (opTok.op) {
                                case LogicalOperator.and:
                                  opColor = const Color(0xFF4FC3F7);
                                case LogicalOperator.or:
                                  opColor = const Color(0xFFFFB74D);
                                case LogicalOperator.xor:
                                  opColor = const Color(0xFFCE93D8);
                              }
                              return SizedBox(
                                key: ValueKey(tok.tokenKey),
                                child: Row(
                                  mainAxisSize: MainAxisSize.min,
                                  children: [
                                    ReorderableDragStartListener(
                                      index: tokIdx,
                                      child: Padding(
                                        padding: const EdgeInsets.symmetric(
                                            horizontal: 3),
                                        child: Icon(Icons.drag_indicator,
                                            size: 10,
                                            color: opColor.withOpacity(0.4)),
                                      ),
                                    ),
                                    // Tap to cycle AND → OR → XOR
                                    GestureDetector(
                                      onTap: () => setState(() {
                                        final ops = LogicalOperator.values;
                                        opTok.op = ops[(ops.indexOf(opTok.op) +
                                                1) %
                                            ops.length];
                                        _rebuildGcFromTokens(tokens, gc);
                                      }),
                                      child: Container(
                                        margin: const EdgeInsets.symmetric(
                                            vertical: 2),
                                        padding: const EdgeInsets.symmetric(
                                            horizontal: 5, vertical: 2),
                                        decoration: BoxDecoration(
                                          color: opColor.withOpacity(0.12),
                                          borderRadius:
                                              BorderRadius.circular(4),
                                          border: Border.all(
                                              color:
                                                  opColor.withOpacity(0.35)),
                                        ),
                                        child: Text(
                                          opTok.op.label,
                                          style: TextStyle(
                                            fontSize: 8,
                                            fontWeight: FontWeight.w700,
                                            color: opColor,
                                            letterSpacing: 0.5,
                                          ),
                                        ),
                                      ),
                                    ),
                                    // Remove this operator
                                    GestureDetector(
                                      onTap: () => setState(() {
                                        final newToks = _flattenGcTokens(
                                            gc.criteriaItems);
                                        newToks.removeWhere((t) =>
                                            t.tokenKey == opTok.tokenKey);
                                        _rebuildGcFromTokens(newToks, gc);
                                      }),
                                      child: Padding(
                                        padding: const EdgeInsets.only(
                                            left: 2, right: 4),
                                        child: Icon(Icons.close,
                                            size: 9,
                                            color: opColor.withOpacity(0.5)),
                                      ),
                                    ),
                                  ],
                                ),
                              );
                            }
                          }).toList(),
                        ),
                      );
                    }

                    return Container(
                      key: ValueKey(gc.id),
                      margin: const EdgeInsets.fromLTRB(10, 0, 10, 6),
                      decoration: BoxDecoration(
                        color: surface,
                        borderRadius: BorderRadius.circular(7),
                        border: Border.all(color: border),
                      ),
                      child: Column(
                        crossAxisAlignment: CrossAxisAlignment.stretch,
                        children: [
                          // Header row
                          Padding(
                            padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 6),
                            child: Row(
                              children: [
                                ReorderableDragStartListener(
                                  index: idx,
                                  child: const Padding(
                                    padding: EdgeInsets.only(right: 6),
                                    child: Icon(Icons.drag_indicator, size: 14, color: Colors.white24),
                                  ),
                                ),
                                Expanded(
                                  child: TextField(
                                    controller: labelCtrl,
                                    style: const TextStyle(fontSize: 12, color: Colors.white70),
                                    decoration: const InputDecoration(
                                      isDense: true,
                                      border: InputBorder.none,
                                      contentPadding: EdgeInsets.zero,
                                    ),
                                    onChanged: (v) => setState(() => gc.displayLabel = v),
                                  ),
                                ),
                                // Default operator selector for new items
                                GestureDetector(
                                  onTap: () => setState(() {
                                    final ops = LogicalOperator.values;
                                    final curr = ops.indexOf(gc.defaultOperator);
                                    gc.defaultOperator = ops[(curr + 1) % ops.length];
                                  }),
                                  child: Container(
                                    margin: const EdgeInsets.only(right: 4),
                                    padding: const EdgeInsets.symmetric(horizontal: 4, vertical: 2),
                                    decoration: BoxDecoration(
                                      color: Colors.white.withOpacity(0.05),
                                      borderRadius: BorderRadius.circular(3),
                                      border: Border.all(color: Colors.white12),
                                    ),
                                    child: Text(
                                      gc.defaultOperator.label,
                                      style: const TextStyle(fontSize: 8, color: Colors.white38),
                                    ),
                                  ),
                                ),
                                // Collapse toggle
                                GestureDetector(
                                  onTap: () => setState(() {
                                    if (_collapsedContainerIds.contains(gc.id)) {
                                      _collapsedContainerIds.remove(gc.id);
                                    } else {
                                      _collapsedContainerIds.add(gc.id);
                                    }
                                  }),
                                  child: Padding(
                                    padding: const EdgeInsets.only(right: 4),
                                    child: Icon(
                                      _collapsedContainerIds.contains(gc.id)
                                          ? Icons.expand_more
                                          : Icons.expand_less,
                                      size: 14,
                                      color: Colors.white38,
                                    ),
                                  ),
                                ),
                                removeBtn(() => setState(() => _groupContainers.removeAt(idx))),
                              ],
                            ),
                          ),
                          // ── Criteria items + action row (hidden when collapsed) ─
                          if (!_collapsedContainerIds.contains(gc.id)) ...[
                          buildFlatCriteriaList(),
                          // ── Add-criteria action row ───────────────────
                          Padding(
                            padding: const EdgeInsets.fromLTRB(8, 0, 8, 8),
                            child: Row(
                              children: [
                                // Add open parenthesis
                                GestureDetector(
                                  onTap: () {
                                    addCriterion(ContainerCriteriaItem(
                                      id: _gristId(),
                                      type: CriteriaItemType.parenOpen,
                                    ));
                                  },
                                  child: Container(
                                    padding: const EdgeInsets.symmetric(horizontal: 6, vertical: 3),
                                    decoration: BoxDecoration(
                                      color: const Color(0xFF4FC3F7).withOpacity(0.08),
                                      borderRadius: BorderRadius.circular(4),
                                      border: Border.all(color: const Color(0xFF4FC3F7).withOpacity(0.25)),
                                    ),
                                    child: const Text(
                                      '(',
                                      style: TextStyle(fontSize: 11, color: Color(0xFF4FC3F7), fontWeight: FontWeight.w700),
                                    ),
                                  ),
                                ),
                                const SizedBox(width: 4),
                                // Add close parenthesis
                                GestureDetector(
                                  onTap: () {
                                    addCriterion(ContainerCriteriaItem(
                                      id: _gristId(),
                                      type: CriteriaItemType.parenClose,
                                    ));
                                  },
                                  child: Container(
                                    padding: const EdgeInsets.symmetric(horizontal: 6, vertical: 3),
                                    decoration: BoxDecoration(
                                      color: const Color(0xFF4FC3F7).withOpacity(0.08),
                                      borderRadius: BorderRadius.circular(4),
                                      border: Border.all(color: const Color(0xFF4FC3F7).withOpacity(0.25)),
                                    ),
                                    child: const Text(
                                      ')',
                                      style: TextStyle(fontSize: 11, color: Color(0xFF4FC3F7), fontWeight: FontWeight.w700),
                                    ),
                                  ),
                                ),
                                const SizedBox(width: 4),
                                // Add AND operator
                                GestureDetector(
                                  onTap: () {
                                    if (gc.criteriaItems.isNotEmpty &&
                                        gc.criteriaItems.last.operatorAfter == null) {
                                      setState(() => gc.criteriaItems.last.operatorAfter = LogicalOperator.and);
                                    }
                                  },
                                  child: Container(
                                    padding: const EdgeInsets.symmetric(horizontal: 5, vertical: 3),
                                    decoration: BoxDecoration(
                                      color: const Color(0xFF4FC3F7).withOpacity(0.08),
                                      borderRadius: BorderRadius.circular(4),
                                      border: Border.all(color: const Color(0xFF4FC3F7).withOpacity(0.25)),
                                    ),
                                    child: const Text(
                                      'AND',
                                      style: TextStyle(
                                        fontSize: 8,
                                        color: Color(0xFF4FC3F7),
                                        fontWeight: FontWeight.w700,
                                      ),
                                    ),
                                  ),
                                ),
                                const SizedBox(width: 4),
                                // Add OR operator
                                GestureDetector(
                                  onTap: () {
                                    if (gc.criteriaItems.isNotEmpty &&
                                        gc.criteriaItems.last.operatorAfter == null) {
                                      setState(() => gc.criteriaItems.last.operatorAfter = LogicalOperator.or);
                                    }
                                  },
                                  child: Container(
                                    padding: const EdgeInsets.symmetric(horizontal: 5, vertical: 3),
                                    decoration: BoxDecoration(
                                      color: const Color(0xFFFFB74D).withOpacity(0.08),
                                      borderRadius: BorderRadius.circular(4),
                                      border: Border.all(color: const Color(0xFFFFB74D).withOpacity(0.25)),
                                    ),
                                    child: const Text(
                                      'OR',
                                      style: TextStyle(
                                        fontSize: 8,
                                        color: Color(0xFFFFB74D),
                                        fontWeight: FontWeight.w700,
                                      ),
                                    ),
                                  ),
                                ),
                                const SizedBox(width: 4),
                                // Add XOR operator
                                GestureDetector(
                                  onTap: () {
                                    if (gc.criteriaItems.isNotEmpty &&
                                        gc.criteriaItems.last.operatorAfter == null) {
                                      setState(() => gc.criteriaItems.last.operatorAfter = LogicalOperator.xor);
                                    }
                                  },
                                  child: Container(
                                    padding: const EdgeInsets.symmetric(horizontal: 5, vertical: 3),
                                    decoration: BoxDecoration(
                                      color: const Color(0xFFCE93D8).withOpacity(0.08),
                                      borderRadius: BorderRadius.circular(4),
                                      border: Border.all(color: const Color(0xFFCE93D8).withOpacity(0.25)),
                                    ),
                                    child: const Text(
                                      'XOR',
                                      style: TextStyle(
                                        fontSize: 8,
                                        color: Color(0xFFCE93D8),
                                        fontWeight: FontWeight.w700,
                                      ),
                                    ),
                                  ),
                                ),
                              ],
                            ),
                          ),
                          ], // end if (!collapsed)
                        ],
                      ),
                    );
                  }).toList(),
                ),

                // ════════════════ SORT ════════════════
                Padding(
                  padding: const EdgeInsets.only(top: 6),
                  child: Container(
                    height: 1,
                    color: Colors.white.withOpacity(0.05),
                  ),
                ),
                sectionHeader(
                  'SORT',
                  () => setState(() {
                    _sortCriteria.clear();
                    // Clear any extra Default criteria (Insertion Date is always the fixed fallback)
                    _defaultSortCriteria.clear();
                    // Deactivate any custom preset
                    _activeCustomPresetId[_tasksNavSection] = null;
                  }),
                  _fgsSectionSortCollapsed,
                  () => setState(() => _fgsSectionSortCollapsed = !_fgsSectionSortCollapsed),
                ),

                if (!_fgsSectionSortCollapsed)
                // ── Custom Preset dropdown ───────────────────────────────────────
                Builder(builder: (context) {
                  final pageKey = _tasksNavSection;
                  final presets = _presetsForPage(pageKey);
                  final activePreset = _activePresetFor(pageKey);

                  // The "Default" option is represented by null activePreset
                  final selectedName = activePreset?.name ?? 'Default';

                  Future<void> promptAddCustom() async {
                    final ctrl = TextEditingController();
                    final name = await showDialog<String>(
                      context: context,
                      builder: (_) => AlertDialog(
                        backgroundColor: const Color(0xFF1E2124),
                        shape: RoundedRectangleBorder(
                          borderRadius: BorderRadius.circular(10),
                        ),
                        title: const Text(
                          'New Custom Sort',
                          style: TextStyle(
                            fontSize: 13,
                            fontWeight: FontWeight.w600,
                            color: Colors.white,
                          ),
                        ),
                        content: TextField(
                          controller: ctrl,
                          autofocus: true,
                          style: const TextStyle(
                            fontSize: 12,
                            color: Colors.white,
                          ),
                          decoration: const InputDecoration(
                            hintText: 'Preset name…',
                            hintStyle: TextStyle(
                              fontSize: 12,
                              color: Colors.white38,
                            ),
                            enabledBorder: UnderlineInputBorder(
                              borderSide: BorderSide(color: Colors.white24),
                            ),
                            focusedBorder: UnderlineInputBorder(
                              borderSide: BorderSide(color: accent),
                            ),
                          ),
                          onSubmitted: (v) {
                            if (v.trim().isNotEmpty)
                              Navigator.of(context).pop(v.trim());
                          },
                        ),
                        actions: [
                          TextButton(
                            onPressed: () => Navigator.of(context).pop(null),
                            child: const Text(
                              'Cancel',
                              style: TextStyle(fontSize: 11, color: Colors.white38),
                            ),
                          ),
                          TextButton(
                            onPressed: () {
                              final v = ctrl.text.trim();
                              if (v.isNotEmpty) Navigator.of(context).pop(v);
                            },
                            child: const Text(
                              'Add',
                              style: TextStyle(fontSize: 11, color: accent),
                            ),
                          ),
                        ],
                      ),
                    );
                    if (name != null && name.isNotEmpty) {
                      setState(() {
                        final newPreset = CustomSortPreset(
                          id: _gristId(),
                          name: name,
                        );
                        _presetsForPage(pageKey).add(newPreset);
                        _activatePreset(pageKey, newPreset.id);
                      });
                    }
                  }

                  return Padding(
                    padding: const EdgeInsets.fromLTRB(10, 0, 10, 8),
                    child: Column(
                      crossAxisAlignment: CrossAxisAlignment.stretch,
                      children: [
                        // ── Label row ──────────────────────────────────────
                        const Padding(
