                if (!_fgsSectionSortCollapsed && _sortCriteria.isNotEmpty && _activePresetFor(_tasksNavSection) == null)
                Padding(
                  padding: const EdgeInsets.symmetric(horizontal: 10),
                  child: GestureDetector(
                    onTap: () => setState(
                      () {
                        _sortCriteria.add(SortCriterion(id: _gristId()));
                        // Adding a criterion sort deactivates custom preset
                        _activeCustomPresetId[_tasksNavSection] = null;
                      },
                    ),
                    child: Container(
                      padding: const EdgeInsets.symmetric(vertical: 7),
                      decoration: BoxDecoration(
                        color: Colors.white.withOpacity(0.03),
                        borderRadius: BorderRadius.circular(5),
