  /// Renders tasks grouped by the active [_groupContainers] configuration.
  Widget _buildGroupedByContainers(
    List<Task> allPool,
    DateTime today,
    Set<String> allSubtaskIds,
  ) {
    final List<Widget> sections = [];
    final Set<String> assignedIds = {};

    for (final container in _groupContainers) {
      List<Task> matched;
      if (container.isRest) {
        matched = allPool.where((t) => !assignedIds.contains(t.id)).toList();
      } else {
        matched = allPool.where((t) => container.matches(t, today)).toList();
        for (final t in matched) assignedIds.add(t.id);
      }

      final collapsed = _collapsedContainerIds.contains(container.id);
      final isOverdueBucket = container.overdueMatch == true;

      sections.add(Column(
        crossAxisAlignment: CrossAxisAlignment.stretch,
        key: ValueKey(container.id),
        children: [
          // Section header
          InkWell(
            onTap: () => setState(() {
              if (collapsed)
                _collapsedContainerIds.remove(container.id);
              else
                _collapsedContainerIds.add(container.id);
            }),
            child: Container(
              padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 10),
              decoration: BoxDecoration(
                border: Border(
                  bottom: BorderSide(color: _tasksBorder, width: 0.5),
                ),
              ),
              child: Row(
                children: [
                  Icon(
                    collapsed
                        ? Icons.keyboard_arrow_right
                        : Icons.keyboard_arrow_down,
                    size: 14,
                    color: isOverdueBucket
                        ? const Color(0xFFEF5350)
                        : Colors.white38,
                  ),
                  const SizedBox(width: 6),
                  Text(
                    container.displayLabel.toUpperCase(),
                    style: TextStyle(
                      fontSize: 11,
                      fontWeight: FontWeight.w600,
                      letterSpacing: 0.8,
                      color: isOverdueBucket
                          ? const Color(0xFFEF5350)
                          : Colors.white54,
                    ),
                  ),
                  const SizedBox(width: 8),
                  Container(
                    padding: const EdgeInsets.symmetric(horizontal: 6, vertical: 1),
                    decoration: BoxDecoration(
                      color: isOverdueBucket
                          ? const Color(0xFFEF5350).withOpacity(0.15)
                          : Colors.white.withOpacity(0.06),
                      borderRadius: BorderRadius.circular(8),
                    ),
                    child: Text(
                      '${matched.length}',
                      style: TextStyle(
                        fontSize: 10,
                        fontWeight: FontWeight.bold,
                        color: isOverdueBucket
                            ? const Color(0xFFEF5350)
                            : Colors.white38,
                      ),
                    ),
                  ),
                ],
              ),
            ),
          ),
          if (!collapsed && matched.isNotEmpty)
            _buildReorderableTaskList(matched, today, allSubtaskIds),
        ],
      ));

      // Spacer between buckets
      sections.add(const SizedBox(height: 40));
    }

    return Column(
      crossAxisAlignment: CrossAxisAlignment.stretch,
      children: sections,
    );
  }

  /// Renders Today's tasks grouped by project, identical visual style to a
  /// normal project view. Each project with tasks due today gets a collapsible
  /// header; tasks without a project fall under "Inbox".
  /// Renders [tasks] grouped by [_groupOption] into collapsible sections.
  Widget _buildGroupedByOption(
    List<Task> tasks,
    DateTime today,
    Set<String> allSubtaskIds,
  ) {
    if (tasks.isEmpty) {
      return const Padding(
        padding: EdgeInsets.only(top: 60),
        child: Center(
          child: Text('No tasks', style: TextStyle(color: Colors.white24)),
        ),
      );
    }

    // Build a map of groupKey → tasks
    Map<String, List<Task>> groups = {};
    const ungrouped = '—';

    // Use first GroupCriterion for primary grouping (legacy _groupOption shim
    // still works for the existing rendering paths via the getter).
    final primaryGroup = _groupCriteria.isNotEmpty
        ? _groupCriteria.first
        : null;
    for (final t in tasks) {
      final String key = primaryGroup != null
          ? primaryGroup.keyFor(t, _projects)
          : ungrouped;
      groups.putIfAbsent(key, () => []).add(t);
    }

    final sortedKeys = groups.keys.toList();
    // Sort group keys by the criterion direction
    if (primaryGroup != null) {
      sortedKeys.sort(
        (a, b) => primaryGroup.ascending ? a.compareTo(b) : b.compareTo(a),
      );
    } else {
      sortedKeys.sort();
    }
    // Put ungrouped / no-date at the end regardless of direction
    if (sortedKeys.remove(ungrouped)) sortedKeys.add(ungrouped);
    if (sortedKeys.remove('No date')) sortedKeys.add('No date');

    return Column(
      crossAxisAlignment: CrossAxisAlignment.stretch,
      children: sortedKeys.map((key) {
        final groupTasks = groups[key]!;
        final expanded = !_collapsedGroups.contains(key);
        return Column(
          crossAxisAlignment: CrossAxisAlignment.stretch,
          children: [
            InkWell(
              onTap: () => setState(() {
                if (expanded)
                  _collapsedGroups.add(key);
                else
                  _collapsedGroups.remove(key);
              }),
              child: Container(
                padding: const EdgeInsets.symmetric(
                  horizontal: 16,
                  vertical: 10,
                ),
                decoration: BoxDecoration(
                  border: Border(
                    bottom: BorderSide(color: _tasksBorder, width: 0.5),
                  ),
                ),
                child: Row(
                  children: [
                    Icon(
                      expanded
                          ? Icons.keyboard_arrow_down
                          : Icons.keyboard_arrow_right,
                      size: 14,
                      color: Colors.white38,
                    ),
                    const SizedBox(width: 6),
                    Expanded(
                      child: Text(
                        key == '__inbox__' ? 'Inbox' : key,
                        style: const TextStyle(
                          fontSize: 11,
                          fontWeight: FontWeight.w600,
                          letterSpacing: 0.8,
                          color: Colors.white54,
                        ),
                      ),
                    ),
                    Container(
                      padding: const EdgeInsets.symmetric(
                        horizontal: 6,
                        vertical: 1,
                      ),
                      decoration: BoxDecoration(
                        color: Colors.white.withOpacity(0.06),
                        borderRadius: BorderRadius.circular(8),
                      ),
                      child: Text(
                        '${groupTasks.length}',
                        style: const TextStyle(
                          fontSize: 10,
                          fontWeight: FontWeight.bold,
                          color: Colors.white38,
                        ),
                      ),
                    ),
                  ],
                ),
              ),
            ),
            if (expanded)
              _buildReorderableTaskList(groupTasks, today, allSubtaskIds),
          ],
        );
      }).toList(),
    );
  }

  Widget _buildTodayByProject(
    List<Task> tasks,
    DateTime today,
    Set<String> allSubtaskIds,
  ) {
    if (tasks.isEmpty) return const SizedBox.shrink();

    // Group by projectId
    final Map<String, List<Task>> byProject = {};
    for (final t in tasks) {
      byProject.putIfAbsent(t.projectId, () => []).add(t);
    }

    // Order: follow _projectOrder, then any leftover (e.g. INBOX_PROJECT)
    final orderedIds = [
      ..._projectOrder.where((id) => byProject.containsKey(id)),
      ...byProject.keys.where((id) => !_projectOrder.contains(id)),
    ];

    return Column(
      crossAxisAlignment: CrossAxisAlignment.stretch,
      children: [
        for (final pid in orderedIds) ...[
          _buildTodayProjectSection(pid, byProject[pid]!, today, allSubtaskIds),
        ],
      ],
    );
  }

  Widget _buildTodayProjectSection(
    String projectId,
    List<Task> tasks,
    DateTime today,
    Set<String> allSubtaskIds,
  ) {
    final proj = _projects[projectId];
    final label = projectId == 'INBOX_PROJECT'
        ? 'Inbox'
        : (proj?.title ?? projectId);
    final color = _projectColors[projectId] ?? _tasksAccent;
    final icon = _projectIcons[projectId] ?? '';
    final expandKey = 'today_proj_$projectId';
    final expanded = _repeatGroupsExpanded[expandKey] ?? true;

    return Column(
      crossAxisAlignment: CrossAxisAlignment.stretch,
      children: [
        // ── Project header ──────────────────────────────────────────────
        InkWell(
          onTap: () =>
              setState(() => _repeatGroupsExpanded[expandKey] = !expanded),
          child: Container(
            padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 8),
            decoration: BoxDecoration(
              border: Border(
                bottom: BorderSide(color: _tasksBorder, width: 0.5),
              ),
            ),
            child: Row(
              children: [
                Icon(
                  expanded
                      ? Icons.keyboard_arrow_down
                      : Icons.keyboard_arrow_right,
                  size: 14,
                  color: Colors.white38,
                ),
                const SizedBox(width: 6),
                // Project icon
                SizedBox(
                  width: 14,
                  height: 14,
                  child: icon.isNotEmpty
                      ? Text(
                          icon,
                          style: const TextStyle(
                            fontSize: 12,
                            fontFamilyFallback: [
                              'NotoColorEmoji',
                              'Apple Color Emoji',
                              'Segoe UI Emoji',
                            ],
                          ),
                        )
                      : Icon(Icons.folder_outlined, size: 12, color: color),
                ),
                const SizedBox(width: 6),
                Text(
                  label.toUpperCase(),
                  style: TextStyle(
                    fontSize: 10,
                    fontWeight: FontWeight.w700,
                    letterSpacing: 0.8,
                    color: ensureAccentVisible(color).withOpacity(0.8),
                  ),
                ),
                const SizedBox(width: 8),
                Container(
                  padding: const EdgeInsets.symmetric(
                    horizontal: 6,
                    vertical: 1,
                  ),
                  decoration: BoxDecoration(
                    color: Colors.white.withOpacity(0.06),
                    borderRadius: BorderRadius.circular(8),
                  ),
                  child: Text(
                    '${tasks.length}',
                    style: const TextStyle(
                      fontSize: 10,
                      fontWeight: FontWeight.bold,
                      color: Colors.white38,
                    ),
                  ),
                ),
              ],
            ),
          ),
        ),
        if (expanded) _buildGroupedBucketList(tasks, today, allSubtaskIds),
      ],
    );
  }


  // ══════════════════════════════════════════════════════════════════════════
  // VISUALIZER — folder-tree browser + entity description area
  // ══════════════════════════════════════════════════════════════════════════

  // ── Generalized entity types: paths and registry ─────────────────────────

  String get _genRoot   => '${_wsFilesDir(_workspaceId)}/generalized';
  String get _vaultRoot => '${_wsFilesDir(_workspaceId)}/vault';
  EntityLocator get _entityLocator => EntityLocator(_typeRegistry, _genRoot);
  bool _isVaultCat(String cat) => cat == 'works' || cat == 'personal_memory';

  /// Loads generalized/.types/*.yaml. No type is created automatically: the
  /// user defines them in the entity types designer.
  Future<void> _loadTypeRegistry() async {
    if (_workspaceId.isEmpty) return;
    try {
      await Directory('$_genRoot/.types').create(recursive: true);
      await Directory('$_vaultRoot/works').create(recursive: true);
      await Directory('$_vaultRoot/personal_memory').create(recursive: true);
      final reg = await EntityTypeRegistry.load('$_genRoot/.types');
      for (final e in reg.errors) {
        debugPrint('type registry: $e');
      }
      _typeRegistry = reg;
    } catch (e) {
      debugPrint('_loadTypeRegistry ERROR: $e');
    }
  }

  Future<void> _loadVisualizerChildren() async {
    if (_workspaceId.isEmpty) return;
    setState(() => _visualizerLoading = true);
    await _loadTypeRegistry();
    final filesRoot = _wsFilesDir(_workspaceId);
    final result = <String, List<String>>{};
    final fileEntryResult = <String, List<Map<String, dynamic>>>{};
    final locator = _entityLocator;

    // Entity types: root instances and, recursively, child containers.
    Future<void> collect(String rel) async {
      final loc = locator.locate(rel);
      if (loc == null) return;
      for (final slot in loc.def.children) {
        if (slot.isOne) {
          await collect('$rel/${slot.folder}');
          continue;
        }
        final names = await locator.listNames('${loc.dir}/${slot.folder}');
        result['$rel/${slot.folder}'] = names;
        for (final n in names) {
          await collect('$rel/${slot.folder}/$n');
        }
      }
    }

    for (final def in _typeRegistry.rootTypes) {
      final names = await locator.listRoot(def);
      result[def.folder!] = names;
      for (final n in names) {
        await collect('${def.folder}/$n');
      }
    }

    // projects/ plus the Vault file-manager sections.
    for (final cat in ['projects', 'works', 'personal_memory']) {
      final dir = Directory(cat == 'projects' ? '$filesRoot/projects' : '$_vaultRoot/$cat');
      if (!await dir.exists()) { result[cat] = []; continue; }
      final children = <String>[];
      // For file-manager sections list BOTH files and directories.
      final bool isFileMgrSection = cat == 'works' || cat == 'personal_memory';
      final entries = <Map<String, dynamic>>[];

      await for (final e in dir.list()) {
        if (e is Directory) {
          final name = e.uri.pathSegments.where((s) => s.isNotEmpty).last;
          if (!name.startsWith('.')) {
            children.add(name);
            if (isFileMgrSection) {
              entries.add({'name': name, 'isDir': true, 'ext': '', 'size': 0});
            }
          }
        } else if (isFileMgrSection && e is File) {
          final name = e.uri.pathSegments.where((s) => s.isNotEmpty).last;
          if (!name.startsWith('.')) {
            children.add(name);
            final stat = await e.stat();
            final ext = name.contains('.')
                ? name.substring(name.lastIndexOf('.')).toLowerCase()
                : '';
            entries.add({'name': name, 'isDir': false, 'ext': ext, 'size': stat.size});
          }
        }
      }
      // Sort: directories first, then files, both alphabetically.
      if (isFileMgrSection) {
        entries.sort((a, b) {
          final aDir = a['isDir'] as bool;
          final bDir = b['isDir'] as bool;
          if (aDir && !bDir) return -1;
          if (!aDir && bDir) return 1;
          return (a['name'] as String).toLowerCase()
              .compareTo((b['name'] as String).toLowerCase());
        });
        final sortedNames = entries.map((e) => e['name'] as String).toList();
        result[cat] = sortedNames;
        fileEntryResult[cat] = entries;
      } else {
        children.sort();
        result[cat] = children;
      }
    }
    if (mounted) setState(() {
      _visualizerChildren = result;
      _visualizerFileEntries = fileEntryResult;
      _visualizerLoading = false;
    });
  }

  // ── File-manager helpers for Works / Personal Memory ─────────────────────

  /// Returns an appropriate [IconData] for a sidebar entry in a file-manager
  /// section (works, personal_memory).
  IconData _visualizerEntryIcon(String name, bool isDir) {
    if (isDir) return Icons.folder_outlined;
    final ext = name.contains('.')
        ? name.substring(name.lastIndexOf('.')).toLowerCase()
        : '';
    switch (ext) {
      case '.md':   return Icons.description_outlined;
      case '.pdf':  return Icons.picture_as_pdf_outlined;
      case '.png':
      case '.jpg':
      case '.jpeg':
      case '.webp':
      case '.gif':  return Icons.image_outlined;
      case '.mp4':
      case '.mov':
      case '.avi':
      case '.mkv':  return Icons.videocam_outlined;
      case '.mp3':
      case '.wav':
      case '.flac':
      case '.ogg':  return Icons.audio_file_outlined;
      case '.json': return Icons.data_object_rounded;
      case '.txt':  return Icons.subject_rounded;
      default:      return Icons.insert_drive_file_outlined;
    }
  }

  /// Human-readable file size label (e.g. "4.2 KB").
  String _fileSizeLabel(int bytes) {
    if (bytes < 1024) return '${bytes}B';
    if (bytes < 1024 * 1024) return '${(bytes / 1024).toStringAsFixed(1)} KB';
    return '${(bytes / (1024 * 1024)).toStringAsFixed(1)} MB';
  }

  /// Opens the platform file manager at [dirPath].
  void _revealInFileManager(String dirPath) {
    try {
      if (Platform.isLinux)   Process.run('xdg-open', [dirPath]);
      if (Platform.isMacOS)   Process.run('open', [dirPath]);
      if (Platform.isWindows) Process.run('explorer', [dirPath]);
    } catch (e) {
      debugPrint('_revealInFileManager error: $e');
    }
  }

  /// Opens [filePath] with the OS default application for its file type.
  void _openWithSystemApp(String filePath) {
    try {
      if (Platform.isLinux)   Process.run('xdg-open', [filePath]);
      if (Platform.isMacOS)   Process.run('open', [filePath]);
      if (Platform.isWindows) Process.run('start', ['', filePath], runInShell: true);
    } catch (e) {
      debugPrint('_openWithSystemApp error: $e');
    }
  }

  /// Shows a small dialog that lets the user name a new file or folder,
  /// then creates it inside [dirPath] and refreshes the sidebar.
  Future<void> _showVisualizerNewItemDialog(
    BuildContext ctx,
    String dirPath,   // absolute path of the parent directory
    bool isFile,
  ) async {
    final ctrl = TextEditingController();
    final confirmed = await showDialog<bool>(
      context: ctx,
      builder: (dctx) => AlertDialog(
        backgroundColor: const Color(0xFF1E2124),
        shape: RoundedRectangleBorder(
          borderRadius: BorderRadius.circular(10),
          side: BorderSide(color: Colors.white.withOpacity(0.08)),
        ),
        title: Text(
          isFile ? 'New File' : 'New Folder',
          style: const TextStyle(
              color: Colors.white,
              fontSize: 15,
              fontWeight: FontWeight.w600),
        ),
        content: TextField(
          controller: ctrl,
          autofocus: true,
          style: const TextStyle(color: Colors.white, fontSize: 13),
          decoration: InputDecoration(
            hintText: isFile ? 'filename.md' : 'folder name',
            hintStyle: const TextStyle(color: Colors.white38, fontSize: 13),
            filled: true,
            fillColor: Colors.white.withOpacity(0.05),
            isDense: true,
            contentPadding:
                const EdgeInsets.symmetric(horizontal: 12, vertical: 10),
            border: OutlineInputBorder(
              borderRadius: BorderRadius.circular(6),
              borderSide: BorderSide.none,
            ),
          ),
          onSubmitted: (_) => Navigator.of(dctx).pop(true),
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.of(dctx).pop(false),
            child: const Text('Cancel',
                style: TextStyle(color: Colors.white38, fontSize: 13)),
          ),
          TextButton(
            onPressed: () => Navigator.of(dctx).pop(true),
            child: const Text('Create',
                style: TextStyle(color: Colors.blueAccent, fontSize: 13)),
          ),
        ],
      ),
    );
    final name = ctrl.text.trim();
    ctrl.dispose();
    if (confirmed != true || name.isEmpty || !mounted) return;
    try {
      if (isFile) {
        await File('$dirPath/$name').create(recursive: true);
      } else {
        await Directory('$dirPath/$name').create(recursive: true);
      }
      await _loadVisualizerChildren();
    } catch (e) {
      debugPrint('_showVisualizerNewItemDialog error: $e');
    }
  }

  /// Shows the right-click context menu for a Works / Personal Memory entry.
  void _showVisualizerFileContextMenu(
    BuildContext ctx,
    String path,         // e.g. 'works/foo.md'
    String cat,          // 'works' | 'personal_memory'
    String name,         // 'foo.md'
    bool isDir,
    TapDownDetails details,
  ) async {
    final filesRoot = _vaultRoot;
    final absPath = '$filesRoot/$cat/$name';
    final screenSize = MediaQuery.of(ctx).size;
    final dx = details.globalPosition.dx;
    final dy = details.globalPosition.dy;

    final choice = await showMenu<String>(
      context: ctx,
      position: RelativeRect.fromLTRB(
          dx, dy, screenSize.width - dx, screenSize.height - dy),
      color: const Color(0xFF1E2124),
      shape: RoundedRectangleBorder(
        borderRadius: BorderRadius.circular(8),
        side: BorderSide(color: Colors.white.withOpacity(0.08)),
      ),
      items: [
        PopupMenuItem<String>(
          value: 'open',
          height: 36,
          child: _vizFileMenuRow(
            isDir
                ? Icons.folder_open_outlined
                : Icons.open_in_new_rounded,
            isDir ? 'Open Folder' : 'Open with App',
            Colors.white70,
          ),
        ),
        const PopupMenuDivider(height: 1),
        PopupMenuItem<String>(
          value: 'new_file',
          height: 36,
          child: _vizFileMenuRow(
              Icons.note_add_outlined, 'New File Here', Colors.white70),
        ),
        PopupMenuItem<String>(
          value: 'new_folder',
          height: 36,
          child: _vizFileMenuRow(
              Icons.create_new_folder_outlined, 'New Folder Here', Colors.white70),
        ),
        const PopupMenuDivider(height: 1),
        PopupMenuItem<String>(
          value: 'rename',
          height: 36,
          child: _vizFileMenuRow(Icons.drive_file_rename_outline_rounded, 'Rename', Colors.white70),
        ),
        PopupMenuItem<String>(
          value: 'delete',
          height: 36,
          child: _vizFileMenuRow(Icons.delete_outline_rounded, 'Delete', Colors.redAccent),
        ),
        const PopupMenuDivider(height: 1),
        PopupMenuItem<String>(
          value: 'reveal',
          height: 36,
          child: _vizFileMenuRow(Icons.folder_open_outlined, 'Reveal in File Manager', Colors.white70),
        ),
        PopupMenuItem<String>(
          value: 'copy_path',
          height: 36,
          child: _vizFileMenuRow(Icons.content_copy_rounded, 'Copy Path', Colors.white70),
        ),
      ],
    );

    if (choice == null || !mounted) return;
    switch (choice) {
      case 'open':
        // Directories → reveal in OS file manager; files → open with system app.
        if (isDir) {
          _revealInFileManager(absPath);
        } else {
          setState(() {
            _visualizerSelectedPath = path;
            _visualizerRenamingPath = null;
          });
          _loadVisualizerMdContent(path);
          _openWithSystemApp(absPath);
        }
        break;
      case 'new_file':
        // Create a sibling file inside the same parent directory.
        await _showVisualizerNewItemDialog(ctx, '$filesRoot/$cat', true);
        break;
      case 'new_folder':
        await _showVisualizerNewItemDialog(ctx, '$filesRoot/$cat', false);
        break;
      case 'rename':
        _startInlineRename(path, name);
        break;
      case 'delete':
        await _confirmDeleteVisualizerEntry(cat, name, isDir, absPath);
        break;
      case 'reveal':
        _revealInFileManager(isDir ? absPath : '$filesRoot/$cat');
        break;
      case 'copy_path':
        await Clipboard.setData(ClipboardData(text: absPath));
        if (mounted) {
          ScaffoldMessenger.of(context).showSnackBar(
            SnackBar(
              content: Text('Copied: $absPath', style: const TextStyle(fontSize: 12)),
              duration: const Duration(seconds: 2),
              backgroundColor: const Color(0xFF2A2D31),
            ),
          );
        }
        break;
    }
  }

  /// Right-click context menu for entity sections (Events, Public Interactions,
  /// Places, Persons, Self). Mirrors the Works context menu but without
  /// "New Folder Here", and suppresses Rename/Delete for the built-in Self entity.
  void _showVisualizerEntityContextMenu(
    BuildContext ctx,
    String path,   // entity rel, e.g. 'person/Odorico' or 'psyche/Myself/Complexes/-Ego'
    String cat,    // parent rel ('person', 'psyche/Myself/Complexes', ...)
    String name,   // just the entity name (last segment)
    TapDownDetails details,
  ) async {
    final entLoc = _entityLocator.locate(path);
    // Structural (inline) instances such as Self cannot be renamed or deleted.
    final isSelf = entLoc?.inline ?? false;
    final String absPath = '$_genRoot/$path';

    final screenSize = MediaQuery.of(ctx).size;
    final dx = details.globalPosition.dx;
    final dy = details.globalPosition.dy;

    final choice = await showMenu<String>(
      context: ctx,
      position: RelativeRect.fromLTRB(
          dx, dy, screenSize.width - dx, screenSize.height - dy),
      color: const Color(0xFF1E2124),
      shape: RoundedRectangleBorder(
        borderRadius: BorderRadius.circular(8),
        side: BorderSide(color: Colors.white.withOpacity(0.08)),
      ),
      items: [
        PopupMenuItem<String>(
          value: 'open',
          height: 36,
          child: _vizFileMenuRow(
              Icons.folder_open_outlined, 'Open Folder', Colors.white70),
        ),
        const PopupMenuDivider(height: 1),
        PopupMenuItem<String>(
          value: 'new_file',
          height: 36,
          child: _vizFileMenuRow(
              Icons.note_add_outlined, 'New File Here', Colors.white70),
        ),
        if (!isSelf) ...[
          const PopupMenuDivider(height: 1),
          PopupMenuItem<String>(
            value: 'rename',
            height: 36,
            child: _vizFileMenuRow(
                Icons.drive_file_rename_outline_rounded, 'Rename', Colors.white70),
          ),
          PopupMenuItem<String>(
            value: 'delete',
            height: 36,
            child: _vizFileMenuRow(
                Icons.delete_outline_rounded, 'Delete', Colors.redAccent),
          ),
        ],
        const PopupMenuDivider(height: 1),
        PopupMenuItem<String>(
          value: 'reveal',
          height: 36,
          child: _vizFileMenuRow(
              Icons.folder_open_outlined, 'Reveal in File Manager', Colors.white70),
        ),
        PopupMenuItem<String>(
          value: 'copy_path',
          height: 36,
          child: _vizFileMenuRow(
              Icons.content_copy_rounded, 'Copy Path', Colors.white70),
        ),
      ],
    );

    if (choice == null || !mounted) return;
    switch (choice) {
      case 'open':
        _revealInFileManager(absPath);
      case 'new_file':
        await _showVisualizerNewItemDialog(ctx, absPath, true);
        await _loadVisualizerChildren();
      case 'rename':
        _startInlineRename(path, name);
      case 'delete':
        await _confirmDeleteVisualizerEntry(cat, name, true, absPath);
      case 'reveal':
        _revealInFileManager(absPath);
      case 'copy_path':
        await Clipboard.setData(ClipboardData(text: absPath));
        if (mounted) {
          ScaffoldMessenger.of(context).showSnackBar(
            SnackBar(
              content: Text(
                'Copied: $absPath',
                style: const TextStyle(fontSize: 12),
              ),
              duration: const Duration(seconds: 2),
              backgroundColor: const Color(0xFF2A2D31),
            ),
          );
        }
    }
  }

  Widget _vizFileMenuRow(IconData icon, String label, Color color) {
    return Row(children: [
      Icon(icon, size: 14, color: color),
