  /// Lists the children of a directory entry inside Works / Personal Memory.
  Future<List<FileSystemEntity>> _listDirEntries(String dirPath) async {
    final dir = Directory(dirPath);
    if (!await dir.exists()) return <FileSystemEntity>[];
    final list = <FileSystemEntity>[];
    await for (final e in dir.list()) {
      final name = e.uri.pathSegments.where((s) => s.isNotEmpty).last;
      if (!name.startsWith('.')) list.add(e);
    }
    list.sort((a, b) {
      final aIsDir = a is Directory;
      final bIsDir = b is Directory;
      if (aIsDir && !bIsDir) return -1;
      if (!aIsDir && bIsDir) return 1;
      return a.path.toLowerCase().compareTo(b.path.toLowerCase());
    });
    return list;
  }

  Widget _buildFileMgrDirListing(String dirPath) {
    return FutureBuilder<List<FileSystemEntity>>(
      future: _listDirEntries(dirPath),
      builder: (ctx, snap) {
        if (snap.connectionState != ConnectionState.done) {
          return const Center(
              child: CircularProgressIndicator(
                  strokeWidth: 1.5, color: Colors.white24));
        }
        final entries = snap.data ?? [];
        if (entries.isEmpty) {
          return const Center(
              child: Text('Empty folder.',
                  style: TextStyle(color: Colors.white24, fontSize: 13)));
        }
        return GestureDetector(
          // Right-click on empty space inside a dir → create new items there.
          onSecondaryTapDown: (details) async {
            final screenSize = MediaQuery.of(ctx).size;
            final dx = details.globalPosition.dx;
            final dy = details.globalPosition.dy;
            final choice = await showMenu<String>(
              context: ctx,
              position: RelativeRect.fromLTRB(
                  dx, dy, screenSize.width - dx, screenSize.height - dy),
              color: const Color(0xFF1E2124),
              shape: RoundedRectangleBorder(
                borderRadius: BorderRadius.circular(8),
                side: BorderSide(color: Colors.white.withOpacity(0.08)),
              ),
              items: [
                PopupMenuItem<String>(
                  value: 'new_file',
                  height: 36,
                  child: _vizFileMenuRow(
                      Icons.note_add_outlined, 'New File', Colors.white70),
                ),
                PopupMenuItem<String>(
                  value: 'new_folder',
                  height: 36,
                  child: _vizFileMenuRow(
                      Icons.create_new_folder_outlined, 'New Folder', Colors.white70),
                ),
                const PopupMenuDivider(height: 1),
                PopupMenuItem<String>(
                  value: 'reveal',
                  height: 36,
                  child: _vizFileMenuRow(
                      Icons.folder_open_outlined, 'Reveal in File Manager', Colors.white70),
                ),
              ],
            );
            if (choice == null || !mounted) return;
            switch (choice) {
              case 'new_file':
                await _showVisualizerNewItemDialog(ctx, dirPath, true);
              case 'new_folder':
                await _showVisualizerNewItemDialog(ctx, dirPath, false);
              case 'reveal':
                _revealInFileManager(dirPath);
            }
          },
          child: ListView.builder(
            padding: const EdgeInsets.symmetric(vertical: 8),
            itemCount: entries.length,
            itemBuilder: (ctx2, i) {
              final e = entries[i];
              final eName = e.uri.pathSegments.where((s) => s.isNotEmpty).last;
              final eIsDir = e is Directory;
              final eIcon = _visualizerEntryIcon(eName, eIsDir);
              return GestureDetector(
                onSecondaryTapDown: (details) async {
                  final screenSize = MediaQuery.of(ctx2).size;
                  final dx = details.globalPosition.dx;
                  final dy = details.globalPosition.dy;
                  final choice = await showMenu<String>(
                    context: ctx2,
                    position: RelativeRect.fromLTRB(
                        dx, dy, screenSize.width - dx, screenSize.height - dy),
                    color: const Color(0xFF1E2124),
                    shape: RoundedRectangleBorder(
                      borderRadius: BorderRadius.circular(8),
                      side: BorderSide(color: Colors.white.withOpacity(0.08)),
                    ),
                    items: [
                      PopupMenuItem<String>(
                        value: 'open',
                        height: 36,
                        child: _vizFileMenuRow(
                          eIsDir
                              ? Icons.folder_open_outlined
                              : Icons.open_in_new_rounded,
                          eIsDir ? 'Open Folder' : 'Open with App',
                          Colors.white70,
                        ),
                      ),
                      const PopupMenuDivider(height: 1),
                      PopupMenuItem<String>(
                        value: 'new_file',
                        height: 36,
                        child: _vizFileMenuRow(
                            Icons.note_add_outlined, 'New File Here', Colors.white70),
                      ),
                      PopupMenuItem<String>(
                        value: 'new_folder',
                        height: 36,
                        child: _vizFileMenuRow(
                            Icons.create_new_folder_outlined, 'New Folder Here', Colors.white70),
                      ),
                      const PopupMenuDivider(height: 1),
                      PopupMenuItem<String>(
                        value: 'reveal',
                        height: 36,
                        child: _vizFileMenuRow(
                            Icons.folder_open_outlined, 'Reveal in File Manager', Colors.white70),
                      ),
                      PopupMenuItem<String>(
                        value: 'copy_path',
                        height: 36,
                        child: _vizFileMenuRow(
                            Icons.content_copy_rounded, 'Copy Path', Colors.white70),
                      ),
                    ],
                  );
                  if (choice == null || !mounted) return;
                  switch (choice) {
                    case 'open':
                      if (eIsDir) {
                        _revealInFileManager(e.path);
                      } else {
                        _openWithSystemApp(e.path);
                      }
                    case 'new_file':
                      final parentDir = eIsDir ? e.path : dirPath;
                      await _showVisualizerNewItemDialog(ctx2, parentDir, true);
                    case 'new_folder':
                      final parentDir = eIsDir ? e.path : dirPath;
                      await _showVisualizerNewItemDialog(ctx2, parentDir, false);
                    case 'reveal':
                      _revealInFileManager(eIsDir ? e.path : dirPath);
                    case 'copy_path':
                      await Clipboard.setData(ClipboardData(text: e.path));
                  }
                },
                child: InkWell(
                  onTap: () {
                    if (eIsDir) {
                      _revealInFileManager(e.path);
                    } else {
                      _openWithSystemApp(e.path);
                    }
                  },
                  child: Padding(
                    padding: const EdgeInsets.symmetric(horizontal: 20, vertical: 5),
                    child: Row(children: [
                      Icon(eIcon, size: 15,
                          color: eIsDir
                              ? const Color(0xFF8AB4F8)
                              : Colors.white38),
                      const SizedBox(width: 10),
                      Expanded(
                        child: Text(eName,
                            maxLines: 1,
                            overflow: TextOverflow.ellipsis,
                            style: const TextStyle(
                                color: Colors.white70, fontSize: 13)),
                      ),
                    ]),
                  ),
                ),
              );
            },
          ),
        );
      },
    );
  }

