  // ── Person canvas ──────────────────────────────────────────────────────────

  Widget _buildPersonFileBrowser(String rootPath) {
    if (_workspaceId.isEmpty || rootPath.isEmpty) {
      return const Center(child: Text('Nothing selected.', style: TextStyle(color: Colors.white24, fontSize: 13)));
    }

    return FutureBuilder<_FsNode>(
      future: _buildFsTree(rootPath),
      builder: (context, snap) {
        if (snap.connectionState != ConnectionState.done) {
          return const Center(child: CircularProgressIndicator(strokeWidth: 1.5, color: Colors.white24));
        }
        final tree = snap.data;
        if (tree == null || tree.children.isEmpty) {
          return const Center(child: Text('No files found.', style: TextStyle(color: Colors.white24, fontSize: 13)));
        }
        return _VisualizerFileTree(
          nodes: tree.children,
          selectedPath: _personFileOpenPath,
          onOpenMd: (path) async {
            await _openPersonFile(path);
          },
        );
      },
    );
  }

  IconData _fileIcon(String name) {
    if (name.endsWith('.md'))  return Icons.description_outlined;
    if (name.endsWith('.json')) return Icons.data_object_rounded;
    if (name.endsWith('.png') || name.endsWith('.jpg') || name.endsWith('.jpeg') || name.endsWith('.webp'))
      return Icons.image_outlined;
    return Icons.insert_drive_file_outlined;
  }

