  Widget _buildPersonCanvas() {
    final itemName = _visualizerSelectedPath.split('/').last;
    final isSelf   = false;
    final pcLoc    = _entityLocator.locate(_visualizerSelectedPath);
    final pcTab    = _activeTabFor(pcLoc);
    final blocks   = (_personCanvas['blocks'] as List<dynamic>?) ?? [];
    final headerH  = ((_personCanvas['header'] as Map?)?['h'] as num?)?.toDouble() ?? 120.0;

    return Container(
      color: const Color(0xFF0E0E0E),
      child: Column(crossAxisAlignment: CrossAxisAlignment.stretch, children: [

        // ── Tab content ───────────────────────────────────────────────────
        if (pcTab.kind == 'files')
          Expanded(child: _buildFilesSplit(pcLoc?.dir ?? ''))
        else if (pcTab.kind != 'profile' && pcLoc != null)
          Expanded(child: _buildEntityTabView(pcLoc, pcTab))
        else
        Expanded(
          child: _personCanvas.isEmpty
              ? const Center(child: CircularProgressIndicator(strokeWidth: 1.5, color: Colors.white24))
              : LayoutBuilder(
                  builder: (context, constraints) {
                    final canvasW = constraints.maxWidth;
                    _lastCanvasW = canvasW; // captured for _autoAlignPersonCanvas
                    return SingleChildScrollView(
                      child: SizedBox(
                        width: canvasW,
                        height: _personCanvasHeight(blocks, headerH),
                        child: Stack(children: [

                          // ── Profile header block ─────────────────────────
                          Positioned(
                            left: 0, top: 0, right: 0,
                            child: _buildPersonHeaderBlock(itemName, isSelf, headerH, canvasW),
                          ),

                          // ── Canvas blocks ────────────────────────────────
                          ...blocks.map((b) {
                            final block = b as Map<String, dynamic>;
                            final bx = ((block['x'] as num?)?.toDouble() ?? 0.0) * canvasW;
                            final by = ((block['y'] as num?)?.toDouble() ?? 0.0) + headerH + 16;
                            final bw = ((block['w'] as num?)?.toDouble() ?? 0.5) * canvasW;
                            final bh = (block['h'] as num?)?.toDouble() ?? 200.0;
                            final bid = block['id'] as String? ?? '';
                            final btype = block['type'] as String? ?? '';

                            return Positioned(
                              left: bx,
                              top: by,
                              width: bw,
                              height: bh,
                              child: _visualizerEditLayout
                                  ? _buildCanvasBlockEditable(block, bid, btype, bx, by, bw, bh, canvasW)
                                  : _buildCanvasBlockView(btype, bw, bh,
                                      bid: bid,
                                      customLabel: block['label'] as String?,
                                      mdFile: block['mdFile'] as String?,
                                      mdAnchor: block['mdAnchor'] as String?,
                                      mdAnchorMode: (block['mdAnchorMode'] as String?) ?? 'all',
                                      onRename: () => _renameBlock(bid,
                                          (block['label'] as String?)?.isNotEmpty == true
                                              ? block['label'] as String
                                              : _defaultBlockLabel(btype)),
                                      onDelete: () => _deleteBlock(bid),
                                    ),
                            );
                          }),

                          // ── Add Block button (always visible at bottom) ──
                          Positioned(
                            left: 0, right: 0,
                            top: _personCanvasHeight(blocks, headerH) - 48,
                            height: 40,
                            child: Center(
                              child: GestureDetector(
                                onTap: _addNewBlock,
                                child: MouseRegion(
                                  cursor: SystemMouseCursors.click,
                                  child: AnimatedContainer(
                                    duration: const Duration(milliseconds: 120),
                                    padding: const EdgeInsets.symmetric(
                                        horizontal: 16, vertical: 8),
                                    decoration: BoxDecoration(
                                      color: Colors.white.withOpacity(0.04),
                                      borderRadius: BorderRadius.circular(8),
                                      border: Border.all(
                                        color: Colors.white.withOpacity(0.12),
                                        width: 1,
                                      ),
                                    ),
                                    child: Row(mainAxisSize: MainAxisSize.min, children: [
                                      Icon(Icons.add_rounded, size: 14,
                                          color: Colors.white.withOpacity(0.4)),
                                      const SizedBox(width: 6),
                                      Text(
                                        'Add Block',
                                        style: TextStyle(
                                          fontSize: 12,
                                          color: Colors.white.withOpacity(0.4),
                                          fontWeight: FontWeight.w500,
                                        ),
                                      ),
                                    ]),
                                  ),
                                ),
                              ),
                            ),
                          ),
                        ]),
                      ),
                    );
                  },
                ),
        ),
      ]),
    );
  }

  double _personCanvasHeight(List<dynamic> blocks, double headerH) {
    double maxY = headerH + 16;
    for (final b in blocks) {
      final block = b as Map<String, dynamic>;
      final by = ((block['y'] as num?)?.toDouble() ?? 0.0) + headerH + 16;
      final bh = (block['h'] as num?)?.toDouble() ?? 200.0;
      if (by + bh > maxY) maxY = by + bh;
    }
    return maxY + 56; // +56 reserves room for the Add Block button
  }

