    final subLabel = hdrLoc?.def.label ?? 'Person';

    return GestureDetector(
      onVerticalDragUpdate: _visualizerEditLayout ? (details) {
        setState(() {
          final header = Map<String, dynamic>.from((_personCanvas['header'] as Map?) ?? {});
