    final (defaultLabel, icon) = switch (type) {
      'about'       => ('About',       Icons.notes_rounded),
      'works'       => ('Works',       Icons.auto_stories_outlined),
      'connections' => ('Connections', Icons.hub_outlined),
      'log'         => ('Log',         Icons.history_rounded),
      _             => (type.isEmpty ? 'Block' : type, Icons.widgets_outlined),
    };
    final label = (customLabel != null && customLabel.isNotEmpty) ? customLabel : defaultLabel;
    return Container(
      margin: const EdgeInsets.all(4),
      decoration: BoxDecoration(
        color: const Color(0xFF141414),
        borderRadius: BorderRadius.circular(8),
        border: Border.all(color: Colors.white10),
