      child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
        // Block header
        Padding(
          padding: const EdgeInsets.fromLTRB(10, 8, 6, 6),
          child: Row(children: [
            Icon(icon, size: 13, color: Colors.white38),
            const SizedBox(width: 7),
            // Tappable label for rename
            Expanded(
              child: GestureDetector(
                onTap: onRename,
                child: MouseRegion(
                  cursor: onRename != null
                      ? SystemMouseCursors.click
                      : SystemMouseCursors.basic,
                  child: Tooltip(
                    message: onRename != null ? 'Click to rename' : '',
                    waitDuration: const Duration(milliseconds: 600),
                    child: Text(
                      label,
                      style: TextStyle(
                        fontSize: 11,
                        fontWeight: FontWeight.w600,
                        color: onRename != null
                            ? Colors.white60
                            : Colors.white54,
                        letterSpacing: 0.5,
                      ),
                    ),
                  ),
                ),
              ),
            ),
            if (mdAnchor != null) ...[
              Text(mdAnchor,
                  style: const TextStyle(fontSize: 9, color: Colors.white24),
                  overflow: TextOverflow.ellipsis),
              const SizedBox(width: 4),
            ],
            // Delete button
            if (onDelete != null)
              GestureDetector(
                onTap: onDelete,
                child: MouseRegion(
                  cursor: SystemMouseCursors.click,
                  child: Tooltip(
                    message: 'Remove block',
                    waitDuration: const Duration(milliseconds: 400),
                    child: Container(
                      width: 20,
                      height: 20,
                      decoration: BoxDecoration(
                        color: Colors.transparent,
                        borderRadius: BorderRadius.circular(4),
                      ),
                      child: const Icon(
                        Icons.close_rounded,
                        size: 13,
                        color: Colors.white24,
                      ),
                    ),
                  ),
                ),
              ),
          ]),
        ),
        const Divider(height: 1, color: Colors.white10),
        // Block content
        Expanded(
          child: mdFile == null
              ? Center(child: Text('No file linked',
                  style: const TextStyle(fontSize: 12, color: Colors.white24)))
              : _CanvasBlockContent(
                  mdFile: mdFile,
                  mdAnchor: mdAnchor,
                  mdAnchorMode: mdAnchorMode,
                ),
        ),
      ]),
    );
  }

  /// Default display label derived from block type.
  String _defaultBlockLabel(String type) => switch (type) {
    'about'       => 'About',
    'works'       => 'Works',
    'connections' => 'Connections',
    'log'         => 'Log',
    _             => type.isEmpty ? 'Block' : type,
  };

  /// Shows a rename dialog for a block and saves the result.
  Future<void> _renameBlock(String bid, String currentLabel) async {
    final ctrl = TextEditingController(text: currentLabel);
    final result = await showDialog<String>(
      context: context,
      barrierColor: Colors.black54,
      builder: (ctx) => AlertDialog(
        backgroundColor: const Color(0xFF1E2025),
        shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(10)),
        title: const Text(
          'Rename block',
          style: TextStyle(color: Colors.white70, fontSize: 14, fontWeight: FontWeight.w600),
        ),
        content: TextField(
          controller: ctrl,
          autofocus: true,
          style: const TextStyle(color: Colors.white, fontSize: 13),
          decoration: InputDecoration(
            hintText: 'Block title…',
            hintStyle: const TextStyle(color: Colors.white24),
            enabledBorder: OutlineInputBorder(
              borderSide: const BorderSide(color: Color(0xFF2C2F35)),
              borderRadius: BorderRadius.circular(6),
            ),
            focusedBorder: OutlineInputBorder(
              borderSide: const BorderSide(color: Colors.blueAccent),
              borderRadius: BorderRadius.circular(6),
            ),
            contentPadding: const EdgeInsets.symmetric(horizontal: 10, vertical: 10),
          ),
          onSubmitted: (v) => Navigator.pop(ctx, v.trim()),
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(ctx),
            child: const Text('Cancel', style: TextStyle(color: Colors.white38, fontSize: 12)),
          ),
          TextButton(
            onPressed: () => Navigator.pop(ctx, ctrl.text.trim()),
            child: const Text('Rename', style: TextStyle(color: Colors.blueAccent, fontSize: 12)),
          ),
        ],
      ),
    );
    ctrl.dispose();
    if (result == null || result.isEmpty) return;
    setState(() {
      final blocks = List<dynamic>.from((_personCanvas['blocks'] as List?) ?? []);
      final idx = blocks.indexWhere((b) => (b as Map)['id'] == bid);
      if (idx == -1) return;
      final updated = Map<String, dynamic>.from(blocks[idx] as Map);
      updated['label'] = result;
      blocks[idx] = updated;
      _personCanvas = Map<String, dynamic>.from(_personCanvas)..['blocks'] = blocks;
    });
    await _savePersonCanvas(_visualizerSelectedPath);
  }

  /// Removes a block from the canvas after confirmation.
  Future<void> _deleteBlock(String bid) async {
    final confirm = await showDialog<bool>(
      context: context,
      barrierColor: Colors.black54,
      builder: (ctx) => AlertDialog(
        backgroundColor: const Color(0xFF1E2025),
        shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(10)),
        title: const Text(
          'Remove block?',
          style: TextStyle(color: Colors.white70, fontSize: 14, fontWeight: FontWeight.w600),
        ),
        content: const Text(
          'Removes this block from the canvas. The linked file is not affected.',
          style: TextStyle(color: Colors.white38, fontSize: 12),
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(ctx, false),
            child: const Text('Cancel', style: TextStyle(color: Colors.white38, fontSize: 12)),
          ),
          TextButton(
            onPressed: () => Navigator.pop(ctx, true),
            child: const Text('Remove', style: TextStyle(color: Colors.redAccent, fontSize: 12)),
          ),
        ],
      ),
    );
    if (confirm != true) return;
    setState(() {
      final blocks = List<dynamic>.from((_personCanvas['blocks'] as List?) ?? []);
      blocks.removeWhere((b) => (b as Map)['id'] == bid);
      _personCanvas = Map<String, dynamic>.from(_personCanvas)..['blocks'] = blocks;
    });
    await _savePersonCanvas(_visualizerSelectedPath);
  }

  /// Adds a new blank block at the bottom of the canvas.
  Future<void> _addNewBlock() async {
    final blocks = List<dynamic>.from((_personCanvas['blocks'] as List?) ?? []);
    final newId = 'b_${DateTime.now().millisecondsSinceEpoch}';
    double maxY = 0;
    for (final b in blocks) {
      final by = ((b as Map)['y'] as num?)?.toDouble() ?? 0.0;
      final bh = (b['h'] as num?)?.toDouble() ?? 200.0;
      if (by + bh > maxY) maxY = by + bh;
    }
    blocks.add({
      'id': newId,
      'type': 'custom',
      'label': 'New Block',
      'x': _personCanvasPadding / (_lastCanvasW ?? 800.0),
      'y': maxY + _personCanvasGap,
      'w': 1.0 - 2 * (_personCanvasPadding / (_lastCanvasW ?? 800.0)),
      'h': 200.0,
    });
    setState(() {
      _personCanvas = Map<String, dynamic>.from(_personCanvas)..['blocks'] = blocks;
    });
    await _savePersonCanvas(_visualizerSelectedPath);
  }

  // ── Collision resolution ────────────────────────────────────────────────
  // After every move/resize, push overlapping blocks apart so they never
  // overlap. x/w are fractions [0,1]; y/h are logical pixels.
  // The resized/moved block (anchorId) is fixed — everything else is pushed.
  List<dynamic> _resolveCollisions(List<dynamic> blocks, String anchorId, double canvasW, {double gap = 6.0, double wallPad = 0.0}) {
    final double minFrac = wallPad / canvasW + 0.08; // minimum block width as fraction of canvasW

    // Pixel-space accessors
    double left (Map m) => (m['x'] as num).toDouble() * canvasW;
    double top  (Map m) => (m['y'] as num).toDouble();
    double right(Map m) => left(m) + (m['w'] as num).toDouble() * canvasW;
    double bot  (Map m) => top(m)  + (m['h'] as num).toDouble();
    double bw   (Map m) => (m['w'] as num).toDouble() * canvasW;
    double bh   (Map m) => (m['h'] as num).toDouble();

    final result = blocks.map((b) => Map<String, dynamic>.from(b as Map)).toList();

    // Up to 10 passes to settle cascading pushes
    for (int pass = 0; pass < 10; pass++) {
      bool anyPushed = false;

      final anchorIdx = result.indexWhere((b) => b['id'] == anchorId);
      if (anchorIdx == -1) break;
      final anchor = result[anchorIdx];

      for (int i = 0; i < result.length; i++) {
        if (result[i]['id'] == anchorId) continue;
        final b = result[i];

        final penLeft  = right(anchor) - left(b);
        final penRight = right(b)      - left(anchor);
        final penTop   = bot(anchor)   - top(b);
        final penBot   = bot(b)        - top(anchor);

        if (penLeft <= gap || penRight <= gap || penTop <= gap || penBot <= gap) continue;

        anyPushed = true;

        final minX = penLeft < penRight ? penLeft : penRight;
        final minY = penTop  < penBot   ? penTop  : penBot;

        if (minX <= minY) {
          // ── Horizontal push ──────────────────────────────────────────
          if (penLeft < penRight) {
            // Push b rightward: anchor's right edge overlaps b's left side
            final newBLeft = right(anchor) + gap;
            final newBRight = newBLeft + bw(b);
            if (newBRight > canvasW) {
              // b would exceed right wall — clamp b to wall and push anchor back
              b['x'] = ((canvasW - bw(b)) / canvasW).clamp(0.0, 1.0 - minFrac);
              // Shrink anchor's right edge to not overlap b
              final maxAnchorRight = left(b) - gap;
              final curAnchorLeft = left(anchor);
              final newAnchorW = (maxAnchorRight - curAnchorLeft) / canvasW;
              if (newAnchorW >= minFrac) {
                anchor['w'] = newAnchorW;
              } else {
                // Not enough space: push anchor left instead
                anchor['x'] = ((maxAnchorRight - bw(anchor)) / canvasW).clamp(0.0, 1.0 - minFrac);
              }
            } else {
              b['x'] = (newBLeft / canvasW).clamp(0.0, 1.0 - minFrac);
            }
          } else {
            // Push b leftward: anchor's left edge overlaps b's right side
            final newBRight = left(anchor) - gap;
            final newBLeft  = newBRight - bw(b);
            if (newBLeft < 0) {
              // b would exceed left wall — clamp b to wall and push anchor right
              b['x'] = 0.0;
              final minAnchorLeft = right(b) + gap;
              final curAnchorRight = right(anchor);
              final newAnchorW = (curAnchorRight - minAnchorLeft) / canvasW;
              if (newAnchorW >= minFrac) {
                anchor['x'] = minAnchorLeft / canvasW;
                anchor['w'] = newAnchorW;
              } else {
                anchor['x'] = (minAnchorLeft / canvasW).clamp(0.0, 1.0 - minFrac);
              }
            } else {
              b['x'] = (newBLeft / canvasW).clamp(0.0, 1.0 - minFrac);
            }
          }
        } else {
          // ── Vertical push (unchanged — canvas is unbounded vertically) ──
          if (penTop < penBot) {
            b['y'] = (bot(anchor) + gap).clamp(0.0, double.infinity);
          } else {
            b['y'] = (top(anchor) - bh(b) - gap).clamp(0.0, double.infinity);
          }
        }
        result[i] = b;
        result[anchorIdx] = anchor;
      }
      if (!anyPushed) break;
    }
    return result;
  }

  // Helper: update a block field, resolve collisions, rebuild canvas state
  void _updateBlock(String bid, Map<String, dynamic> Function(Map<String, dynamic>) updater, [double canvasW = 800.0]) {
    final blocks = List<dynamic>.from(_personCanvas['blocks'] as List);
    final idx = blocks.indexWhere((b) => (b as Map)['id'] == bid);
    if (idx == -1) return;
    blocks[idx] = updater(Map<String, dynamic>.from(blocks[idx] as Map));
    final resolved = _resolveCollisions(blocks, bid, canvasW,
        gap: _personCanvasGap, wallPad: _personCanvasPadding);
    _personCanvas = Map<String, dynamic>.from(_personCanvas)..['blocks'] = resolved;
  }

  Future<void> _pickBlockMdFile(String bid) async {
    // Derive the item's root folder so the picker opens there directly.
    // Mirrors the rootPath logic in _buildPersonFileBrowser().
    final rootPath = _entityLocator.locate(_visualizerSelectedPath)?.dir ?? '';

    final result = await FilePicker.platform.pickFiles(
      type: FileType.custom,
      allowedExtensions: ['md'],
      dialogTitle: 'Select .md file for block',
      initialDirectory: rootPath,
    );
    if (result == null || result.files.single.path == null) return;
    final path = result.files.single.path!;
    setState(() => _updateBlock(bid, (b) => b..['mdFile'] = path));
    await _savePersonCanvas(_visualizerSelectedPath);
  }

  /// Shows the anchor picker overlay for a block — lets the user pick a
  /// heading section from the linked .md file and set the anchor mode.
  Future<void> _showAnchorPicker(String bid, Map<String, dynamic> block) async {
    final mdFile = block['mdFile'] as String?;
    if (mdFile == null) return;

    String content = '';
    try {
      content = await File(mdFile).readAsString();
    } catch (_) {
      return;
    }

    // Parse headings from content
    final headings = <_MdHeading>[];
    for (final line in content.split('\n')) {
      final m = RegExp(r'^(#{1,6})\s+(.+)$').firstMatch(line.trim());
      if (m != null) {
        headings.add(_MdHeading(
          level: m.group(1)!.length,
          text: m.group(2)!.trim(),
          raw: line.trim(),
        ));
      }
    }

    if (!mounted) return;

    final currentAnchor = block['mdAnchor'] as String?;
    final currentMode   = (block['mdAnchorMode'] as String?) ?? 'all';

    await showDialog<void>(
      context: context,
      barrierColor: Colors.black54,
      builder: (ctx) => _AnchorPickerDialog(
        headings:      headings,
        currentAnchor: currentAnchor,
        currentMode:   currentMode,
        onConfirm: (anchor, mode) {
          setState(() => _updateBlock(bid, (b) {
            b['mdAnchor']     = anchor;
            b['mdAnchorMode'] = mode;
            return b;
          }));
          _savePersonCanvas(_visualizerSelectedPath);
        },
        onClear: () {
          setState(() => _updateBlock(bid, (b) {
            b.remove('mdAnchor');
            b.remove('mdAnchorMode');
            return b;
          }));
          _savePersonCanvas(_visualizerSelectedPath);
        },
      ),
    );
  }

  Widget _buildCanvasBlockEditable(
    Map<String, dynamic> block, String bid, String btype,
    double bx, double by, double bw, double bh, double canvasW,
  ) {
    final headerH = ((_personCanvas['header'] as Map?)?['h'] as num?)?.toDouble() ?? 120.0;
    const double handleThick = 8.0;  // edge handle hit area
    const double cornerSize  = 16.0; // corner handle size
    const double topBarH     = 36.0;

    // ── reusable pan callbacks ────────────────────────────────────────────
    final double padFrac = _personCanvasPadding / canvasW;
    final double minWFrac = padFrac + 0.08;

    void moveBlock(DragUpdateDetails d) => setState(() => _updateBlock(bid, (b) {
      final w = (b['w'] as num).toDouble();
      final newX = ((bx + d.delta.dx) / canvasW).clamp(padFrac, 1.0 - w - padFrac);
      b['x'] = newX;
      b['y'] = (by - headerH - 16 + d.delta.dy).clamp(0.0, double.infinity);
      return b;
    }, canvasW));

    void resizeRight(DragUpdateDetails d) => setState(() => _updateBlock(bid, (b) {
      final x = (b['x'] as num).toDouble();
      final newW = ((bw + d.delta.dx) / canvasW).clamp(minWFrac, 1.0 - x - padFrac);
      b['w'] = newW;
      return b;
    }, canvasW));

    void resizeLeft(DragUpdateDetails d) => setState(() => _updateBlock(bid, (b) {
      final rightEdge = (bx + bw) / canvasW;
      final newX = ((bx + d.delta.dx) / canvasW).clamp(padFrac, rightEdge - minWFrac);
      b['x'] = newX;
      b['w'] = (rightEdge - newX).clamp(minWFrac, 1.0);
      return b;
    }, canvasW));

    void resizeBottom(DragUpdateDetails d) => setState(() => _updateBlock(bid, (b) {
      b['h'] = (bh + d.delta.dy).clamp(80.0, double.infinity);
      return b;
    }, canvasW));

    void resizeTop(DragUpdateDetails d) => setState(() => _updateBlock(bid, (b) {
      final newH = (bh - d.delta.dy).clamp(80.0, double.infinity);
      b['y'] = (by - headerH - 16 + d.delta.dy).clamp(0.0, double.infinity);
      b['h'] = newH;
      return b;
    }, canvasW));

    final mdFile = block['mdFile'] as String?;
    final mdFileName = mdFile != null ? mdFile.split('/').last : null;
    final customLabel = block['label'] as String?;

    return Stack(clipBehavior: Clip.none, children: [

      // ── Main block body ─────────────────────────────────────────────────
      Positioned(
        left: handleThick, top: handleThick,
        right: handleThick, bottom: handleThick,
        child: Container(
          decoration: BoxDecoration(
            color: const Color(0xFF141414),
            borderRadius: BorderRadius.circular(8),
            border: Border.all(color: Colors.blueAccent.withOpacity(0.4), width: 1.5),
          ),
          child: Column(crossAxisAlignment: CrossAxisAlignment.stretch, children: [
            // Top bar: drag handle + md file picker button
            GestureDetector(
              behavior: HitTestBehavior.translucent,
              onPanUpdate: moveBlock,
              child: Container(
                height: topBarH,
                decoration: BoxDecoration(
                  color: Colors.blueAccent.withOpacity(0.08),
                  borderRadius: const BorderRadius.only(
                    topLeft: Radius.circular(7), topRight: Radius.circular(7)),
                ),
                child: Row(children: [
                  const SizedBox(width: 8),
                  const Icon(Icons.drag_indicator_rounded, size: 14, color: Colors.blueAccent),
                  const SizedBox(width: 6),
                  // Rename button (shows current label, tappable)
                  GestureDetector(
                    onTap: () => _renameBlock(bid,
                        (customLabel != null && customLabel.isNotEmpty)
                            ? customLabel
                            : _defaultBlockLabel(btype)),
                    child: MouseRegion(
                      cursor: SystemMouseCursors.click,
                      child: Container(
                        padding: const EdgeInsets.symmetric(horizontal: 6, vertical: 3),
                        decoration: BoxDecoration(
                          color: Colors.white.withOpacity(0.04),
                          borderRadius: BorderRadius.circular(4),
                          border: Border.all(color: Colors.white12),
                        ),
                        child: Row(mainAxisSize: MainAxisSize.min, children: [
                          const Icon(Icons.edit_rounded, size: 9, color: Colors.white38),
                          const SizedBox(width: 4),
                          Text(
                            (customLabel != null && customLabel.isNotEmpty)
                                ? customLabel
                                : _defaultBlockLabel(btype),
                            style: const TextStyle(
                              fontSize: 10,
                              color: Colors.white54,
                              fontWeight: FontWeight.w500,
                            ),
                          ),
                        ]),
                      ),
                    ),
                  ),
                  const Spacer(),
                  // .md file selector button
                  GestureDetector(
                    onTap: () => _pickBlockMdFile(bid),
                    child: Container(
                      margin: const EdgeInsets.symmetric(vertical: 7, horizontal: 4),
                      padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 3),
                      decoration: BoxDecoration(
                        color: mdFile != null
                            ? Colors.blueAccent.withOpacity(0.18)
                            : Colors.white.withOpacity(0.06),
                        borderRadius: BorderRadius.circular(4),
                        border: Border.all(
                          color: mdFile != null ? Colors.blueAccent : Colors.white24,
                          width: 1,
                        ),
                      ),
                      child: Row(mainAxisSize: MainAxisSize.min, children: [
                        Icon(
                          mdFile != null ? Icons.description_rounded : Icons.attach_file_rounded,
                          size: 11,
                          color: mdFile != null ? Colors.blueAccent : Colors.white38,
                        ),
                        const SizedBox(width: 4),
                        Text(
                          mdFileName ?? 'Select .md',
                          style: TextStyle(
                            fontSize: 10,
                            color: mdFile != null ? Colors.blueAccent : Colors.white38,
                            fontWeight: FontWeight.w500,
                          ),
                        ),
                      ]),
                    ),
                  ),
                  // Anchor picker button
                  if (block['mdFile'] != null)
                    GestureDetector(
                      onTap: () => _showAnchorPicker(bid, block),
                      child: Container(
                        margin: const EdgeInsets.symmetric(vertical: 7, horizontal: 2),
                        padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 3),
                        decoration: BoxDecoration(
                          color: block['mdAnchor'] != null
                              ? Colors.tealAccent.withOpacity(0.12)
                              : Colors.white.withOpacity(0.06),
                          borderRadius: BorderRadius.circular(4),
                          border: Border.all(
                            color: block['mdAnchor'] != null
                                ? Colors.tealAccent.withOpacity(0.5)
                                : Colors.white24,
                            width: 1,
                          ),
                        ),
                        child: Row(mainAxisSize: MainAxisSize.min, children: [
                          Icon(Icons.anchor_rounded, size: 10,
                            color: block['mdAnchor'] != null
                                ? Colors.tealAccent
                                : Colors.white38),
                          const SizedBox(width: 3),
                          Text(
                            block['mdAnchor'] != null
                                ? (block['mdAnchor'] as String).replaceAll(RegExp(r'^#+\s*'), '')
                                : 'Anchor',
                            style: TextStyle(
                              fontSize: 10,
                              color: block['mdAnchor'] != null
                                  ? Colors.tealAccent
                                  : Colors.white38,
                              fontWeight: FontWeight.w500,
                            ),
                            overflow: TextOverflow.ellipsis,
                          ),
                        ]),
                      ),
                    ),
                  // Delete block button
                  GestureDetector(
                    onTap: () => _deleteBlock(bid),
                    child: MouseRegion(
                      cursor: SystemMouseCursors.click,
                      child: Tooltip(
                        message: 'Remove block',
                        waitDuration: const Duration(milliseconds: 400),
                        child: Container(
                          margin: const EdgeInsets.symmetric(vertical: 7, horizontal: 4),
                          padding: const EdgeInsets.symmetric(horizontal: 6, vertical: 3),
                          decoration: BoxDecoration(
                            color: Colors.redAccent.withOpacity(0.08),
                            borderRadius: BorderRadius.circular(4),
                            border: Border.all(color: Colors.redAccent.withOpacity(0.3)),
                          ),
                          child: const Icon(Icons.delete_outline_rounded,
                              size: 11, color: Colors.redAccent),
                        ),
                      ),
                    ),
                  ),
                  const SizedBox(width: 4),
                ]),
              ),
            ),
            // Block content
            Expanded(child: _buildCanvasBlockView(btype, bw, bh,
              bid: bid,
              customLabel: customLabel,
              mdFile: block['mdFile'] as String?,
              mdAnchor: block['mdAnchor'] as String?,
              mdAnchorMode: (block['mdAnchorMode'] as String?) ?? 'all',
            )),
          ]),
        ),
      ),

      // ── Edge handles ────────────────────────────────────────────────────

      // Left edge
      Positioned(
        left: 0, top: cornerSize, bottom: cornerSize, width: handleThick,
        child: GestureDetector(
          behavior: HitTestBehavior.translucent,
          onPanUpdate: resizeLeft,
          child: MouseRegion(
            cursor: SystemMouseCursors.resizeLeftRight,
            child: Container(color: Colors.transparent),
          ),
        ),
      ),
      // Right edge
      Positioned(
        right: 0, top: cornerSize, bottom: cornerSize, width: handleThick,
        child: GestureDetector(
          behavior: HitTestBehavior.translucent,
          onPanUpdate: resizeRight,
          child: MouseRegion(
            cursor: SystemMouseCursors.resizeLeftRight,
            child: Container(color: Colors.transparent),
          ),
        ),
      ),
      // Top edge
      Positioned(
        top: 0, left: cornerSize, right: cornerSize, height: handleThick,
        child: GestureDetector(
          behavior: HitTestBehavior.translucent,
          onPanUpdate: resizeTop,
          child: MouseRegion(
            cursor: SystemMouseCursors.resizeUpDown,
            child: Container(color: Colors.transparent),
          ),
        ),
      ),
      // Bottom edge
      Positioned(
        bottom: 0, left: cornerSize, right: cornerSize, height: handleThick,
        child: GestureDetector(
          behavior: HitTestBehavior.translucent,
          onPanUpdate: resizeBottom,
          child: MouseRegion(
            cursor: SystemMouseCursors.resizeUpDown,
            child: Container(color: Colors.transparent),
          ),
        ),
      ),

      // ── Corner handles ──────────────────────────────────────────────────

      // Top-left
      Positioned(
        left: 0, top: 0, width: cornerSize, height: cornerSize,
        child: GestureDetector(
          behavior: HitTestBehavior.translucent,
          onPanUpdate: (d) { resizeLeft(d); resizeTop(d); },
          child: MouseRegion(
            cursor: SystemMouseCursors.resizeUpLeftDownRight,
            child: _cornerDot(),
          ),
        ),
      ),
      // Top-right
      Positioned(
        right: 0, top: 0, width: cornerSize, height: cornerSize,
        child: GestureDetector(
          behavior: HitTestBehavior.translucent,
          onPanUpdate: (d) { resizeRight(d); resizeTop(d); },
          child: MouseRegion(
            cursor: SystemMouseCursors.resizeUpRightDownLeft,
            child: _cornerDot(),
          ),
        ),
      ),
      // Bottom-left
      Positioned(
        left: 0, bottom: 0, width: cornerSize, height: cornerSize,
        child: GestureDetector(
          behavior: HitTestBehavior.translucent,
          onPanUpdate: (d) { resizeLeft(d); resizeBottom(d); },
          child: MouseRegion(
            cursor: SystemMouseCursors.resizeUpRightDownLeft,
            child: _cornerDot(),
          ),
        ),
      ),
      // Bottom-right
      Positioned(
        right: 0, bottom: 0, width: cornerSize, height: cornerSize,
        child: GestureDetector(
          behavior: HitTestBehavior.translucent,
          onPanUpdate: (d) { resizeRight(d); resizeBottom(d); },
          child: MouseRegion(
            cursor: SystemMouseCursors.resizeUpLeftDownRight,
            child: _cornerDot(),
          ),
        ),
      ),
    ]);
  }

  Widget _cornerDot() => Center(
    child: Container(
      width: 6, height: 6,
      decoration: BoxDecoration(
        color: Colors.blueAccent,
        borderRadius: BorderRadius.circular(3),
      ),
    ),
  );

