  );
}

// ── Metrics data model ────────────────────────────────────────────────────────
class _MetricsData {
  final Duration totalSpent;
  final Duration totalEstimated;
  final int tasksDone;
  final int tasksCreated;
  final int daysWorked;
  final double avgTasksPerDay;
  final double avgBreaksPerDay;
  final Duration avgTimePerDay;
  final Duration avgTimePerTask;
  final Duration avgTimePerTaskWithSubs;
  final Duration avgTimeOnBreaks;

  const _MetricsData({
    required this.totalSpent,
    required this.totalEstimated,
    required this.tasksDone,
    required this.tasksCreated,
    required this.daysWorked,
    required this.avgTasksPerDay,
    required this.avgBreaksPerDay,
    required this.avgTimePerDay,
    required this.avgTimePerTask,
    required this.avgTimePerTaskWithSubs,
    required this.avgTimeOnBreaks,
  });
}

class _MetricRow {
  final String label;
  final String value;
  const _MetricRow(this.label, this.value);
}

// ─────────────────────────────────────────────────────────────────────────────
// _WorklogView  –  collapsible Year > Month > Week > Day worklog
// ─────────────────────────────────────────────────────────────────────────────

class _WorklogView extends StatefulWidget {
  final List<Task> tasks;
  final Map<String, List<_ExecutionSession>> taskSessions;
  final Color accentColor;

  const _WorklogView({
    required this.tasks,
    required this.taskSessions,
    this.accentColor = const Color(0xFF4FC3F7),
  });

  @override
  State<_WorklogView> createState() => _WorklogViewState();
}

class _WorklogViewState extends State<_WorklogView> {
  // Expansion state: key = "year", "year-month", "year-month-week"
  final Set<String> _expanded = {};

  Color get _accent => ensureAccentVisible(widget.accentColor);
  static const _bg = Color(0xFF181A1B);

  static const _monthNames = [
    'January',
    'February',
    'March',
    'April',
    'May',
    'June',
    'July',
    'August',
    'September',
    'October',
    'November',
    'December',
  ];
  static const _monthShort = [
    'Jan',
    'Feb',
    'Mar',
    'Apr',
    'May',
    'Jun',
    'Jul',
    'Aug',
    'Sep',
    'Oct',
    'Nov',
    'Dec',
  ];
  static const _dayShort = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'];

  // Accent color per year position (cycles)
  static const _yearColors = [
    Color(0xFF4FC3F7), // blue
    Color(0xFFAB47BC), // purple
    Color(0xFF26A69A), // teal
    Color(0xFFEF5350), // red
    Color(0xFFFFA726), // orange
  ];

  int _isoWeek(DateTime d) {
    final jan4 = DateTime(d.year, 1, 4);
    final startOfWeek1 = jan4.subtract(Duration(days: jan4.weekday - 1));
    return ((d.difference(startOfWeek1).inDays) ~/ 7) + 1;
  }

  DateTime _dayKey(DateTime d) => DateTime(d.year, d.month, d.day);

  String _fmt(Duration dur) {
    final h = dur.inHours;
    final m = dur.inMinutes % 60;
    final s = dur.inSeconds % 60;
    if (h > 0) return '${h}h ${m.toString().padLeft(2, '0')}m';
    if (m > 0) return '${m}m ${s.toString().padLeft(2, '0')}s';
    return '${s}s';
  }

  void _toggle(String key) => setState(
    () => _expanded.contains(key) ? _expanded.remove(key) : _expanded.add(key),
  );

  bool _isExpanded(String key) => _expanded.contains(key);

  @override
  Widget build(BuildContext context) {
    // ── Build aggregation tree ──────────────────────────────────────────
    // Map<year, Map<month, Map<weekNum, Map<dayKey, _DayData>>>>
    final Map<int, Map<int, Map<int, Map<DateTime, _WlDayData>>>> tree = {};

    for (final task in widget.tasks) {
      for (final s in (widget.taskSessions[task.id] ?? [])) {
        final d = s.startTime;
        final dk = _dayKey(d);
        final wk = _isoWeek(d);
        tree
            .putIfAbsent(d.year, () => {})
            .putIfAbsent(d.month, () => {})
            .putIfAbsent(wk, () => {})
            .update(
              dk,
              (v) {
                v.sessions.add(
                  _WlSession(
                    taskId: task.id,
                    taskTitle: task.title,
                    duration: s.duration,
                  ),
                );
                return v;
              },
              ifAbsent: () => _WlDayData(
                sessions: [
                  _WlSession(
                    taskId: task.id,
                    taskTitle: task.title,
                    duration: s.duration,
                  ),
                ],
              ),
            );
      }
    }

    if (tree.isEmpty) {
      return Container(
        color: _bg,
        child: Center(
          child: Column(
            mainAxisSize: MainAxisSize.min,
            children: [
              Icon(
                Icons.history_toggle_off_rounded,
                size: 48,
                color: Colors.white.withOpacity(0.08),
              ),
              const SizedBox(height: 16),
              Text(
                'No sessions recorded yet',
                style: TextStyle(
                  color: Colors.white.withOpacity(0.25),
                  fontSize: 14,
                  letterSpacing: 0.2,
                ),
              ),
              const SizedBox(height: 6),
              Text(
                'Start a timer on any task to see your worklog here.',
                style: TextStyle(
                  color: Colors.white.withOpacity(0.13),
                  fontSize: 11,
                ),
              ),
            ],
          ),
        ),
      );
    }

    final years = tree.keys.toList()..sort((a, b) => b.compareTo(a));

    return Container(
      color: _bg,
      child: ListView.builder(
        padding: const EdgeInsets.fromLTRB(20, 20, 20, 48),
        itemCount: years.length + 1, // +1 for header
        itemBuilder: (ctx, idx) {
          if (idx == 0) return _buildHeader(tree);
          final year = years[idx - 1];
          return _buildYear(year, tree[year]!, idx - 1);
        },
      ),
    );
  }

  // ── Top summary header ────────────────────────────────────────────────
  Widget _buildHeader(
    Map<int, Map<int, Map<int, Map<DateTime, _WlDayData>>>> tree,
  ) {
    // Total across all
    Duration totalDur = Duration.zero;
    int totalDays = 0;
    final Set<String> totalTasks = {};
    for (final ym in tree.values) {
      for (final wm in ym.values) {
        for (final dm in wm.values) {
          for (final day in dm.values) {
            totalDays++;
            for (final s in day.sessions) {
              totalTasks.add(s.taskId);
              totalDur += s.duration;
            }
          }
        }
      }
    }

    return Padding(
      padding: const EdgeInsets.only(bottom: 24),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Row(
            children: [
              Icon(Icons.query_stats_rounded, size: 18, color: _accent),
              const SizedBox(width: 10),
              const Text(
                'WORKLOG',
                style: TextStyle(
                  color: Colors.white,
                  fontSize: 16,
                  fontWeight: FontWeight.w700,
                  letterSpacing: 1.5,
                ),
              ),
            ],
          ),
          const SizedBox(height: 16),
          Row(
            children: [
              _summaryChip(
                Icons.task_alt_rounded,
                '${totalTasks.length}',
                'tasks',
              ),
              const SizedBox(width: 8),
              _summaryChip(Icons.calendar_today_rounded, '$totalDays', 'days'),
              const SizedBox(width: 8),
              _summaryChip(
                Icons.timer_rounded,
                totalDur.inSeconds > 0 ? _fmt(totalDur) : '—',
                'total',
              ),
            ],
          ),
          const SizedBox(height: 20),
          Container(height: 1, color: Colors.white.withOpacity(0.06)),
        ],
      ),
    );
  }

  Widget _summaryChip(IconData icon, String value, String label) {
    return Expanded(
      child: Container(
        padding: const EdgeInsets.symmetric(vertical: 12, horizontal: 12),
        decoration: BoxDecoration(
          color: Colors.white.withOpacity(0.04),
          borderRadius: BorderRadius.circular(10),
          border: Border.all(color: Colors.white.withOpacity(0.07)),
        ),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Icon(icon, size: 13, color: _accent.withOpacity(0.7)),
            const SizedBox(height: 6),
            Text(
              value,
              style: const TextStyle(
                color: Colors.white,
                fontSize: 15,
                fontWeight: FontWeight.w700,
              ),
            ),
            Text(
              label,
              style: TextStyle(
                color: Colors.white.withOpacity(0.35),
                fontSize: 10,
                letterSpacing: 0.3,
              ),
            ),
          ],
        ),
      ),
    );
  }

  // ── Year block ────────────────────────────────────────────────────────
  Widget _buildYear(
    int year,
    Map<int, Map<int, Map<DateTime, _WlDayData>>> monthMap,
    int colorIdx,
  ) {
    final yKey = '$year';
    final open = _isExpanded(yKey);
    final color = _yearColors[colorIdx % _yearColors.length];

    // Aggregate year
    Duration yDur = Duration.zero;
    int yDays = 0;
    final Set<String> yTasks = {};
    for (final wm in monthMap.values) {
      for (final dm in wm.values) {
        for (final d in dm.values) {
          yDays++;
          for (final s in d.sessions) {
            yTasks.add(s.taskId);
            yDur += s.duration;
          }
        }
      }
    }

    final months = monthMap.keys.toList()..sort((a, b) => b.compareTo(a));

    return Padding(
      padding: const EdgeInsets.only(bottom: 12),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.stretch,
        children: [
          // ── Year header row ──
          GestureDetector(
            onTap: () => _toggle(yKey),
            child: Container(
              padding: const EdgeInsets.fromLTRB(16, 14, 16, 14),
              decoration: BoxDecoration(
                color: color.withOpacity(0.07),
                borderRadius: BorderRadius.circular(12),
                border: Border.all(color: color.withOpacity(0.22)),
              ),
              child: Row(
                children: [
                  // Year badge
                  Container(
                    padding: const EdgeInsets.symmetric(
                      horizontal: 10,
                      vertical: 4,
                    ),
                    decoration: BoxDecoration(
                      color: color.withOpacity(0.18),
                      borderRadius: BorderRadius.circular(6),
                    ),
                    child: Text(
                      '$year',
                      style: TextStyle(
                        color: color,
                        fontSize: 18,
                        fontWeight: FontWeight.w800,
                        letterSpacing: 0.5,
                      ),
                    ),
                  ),
                  const SizedBox(width: 14),
                  // Stats
                  Expanded(
                    child: Wrap(
                      spacing: 8,
                      runSpacing: 4,
                      children: [
                        _statPill('${monthMap.length}mo', color),
                        _statPill('$yDays days', color),
                        if (yDur.inSeconds > 0) _statPill(_fmt(yDur), color),
                        _statPill('${yTasks.length} tasks', color),
                      ],
                    ),
                  ),
                  const SizedBox(width: 8),
                  AnimatedRotation(
                    turns: open ? 0.5 : 0,
                    duration: const Duration(milliseconds: 200),
                    child: Icon(
                      Icons.keyboard_arrow_down_rounded,
                      size: 20,
                      color: color.withOpacity(0.7),
                    ),
                  ),
                ],
              ),
            ),
          ),

          // ── Month list (animated) ──
          AnimatedCrossFade(
            firstChild: const SizedBox.shrink(),
            secondChild: Padding(
              padding: const EdgeInsets.only(top: 6, left: 12),
              child: Column(
                children: months
                    .map((m) => _buildMonth(year, m, monthMap[m]!, color))
                    .toList(),
              ),
            ),
            crossFadeState: open
                ? CrossFadeState.showSecond
                : CrossFadeState.showFirst,
            duration: const Duration(milliseconds: 200),
          ),
        ],
      ),
    );
  }

  // ── Month block ───────────────────────────────────────────────────────
  Widget _buildMonth(
    int year,
    int month,
    Map<int, Map<DateTime, _WlDayData>> weekMap,
    Color yearColor,
  ) {
    final mKey = '$year-$month';
    final open = _isExpanded(mKey);

    Duration mDur = Duration.zero;
    int mDays = 0;
    final Set<String> mTasks = {};
    for (final dm in weekMap.values) {
      for (final d in dm.values) {
        mDays++;
        for (final s in d.sessions) {
          mTasks.add(s.taskId);
          mDur += s.duration;
        }
      }
    }

    final weeks = weekMap.keys.toList()..sort((a, b) => b.compareTo(a));

    return Padding(
      padding: const EdgeInsets.only(bottom: 6),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.stretch,
        children: [
          // ── Month header ──
          GestureDetector(
            onTap: () => _toggle(mKey),
            child: Container(
              padding: const EdgeInsets.fromLTRB(14, 11, 14, 11),
              decoration: BoxDecoration(
                color: Colors.white.withOpacity(0.03),
                borderRadius: BorderRadius.circular(9),
                border: Border.all(color: Colors.white.withOpacity(0.07)),
              ),
              child: Row(
                children: [
                  // Left accent bar
                  Container(
                    width: 3,
                    height: 32,
                    decoration: BoxDecoration(
                      color: yearColor.withOpacity(0.5),
                      borderRadius: BorderRadius.circular(2),
                    ),
                  ),
                  const SizedBox(width: 12),
                  // Month name + year
                  Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Text(
                        _monthNames[month - 1],
                        style: const TextStyle(
                          color: Colors.white,
                          fontSize: 13,
                          fontWeight: FontWeight.w600,
                        ),
                      ),
                      Text(
                        '$year',
                        style: TextStyle(
                          color: Colors.white.withOpacity(0.3),
                          fontSize: 10,
                        ),
                      ),
                    ],
                  ),
                  const SizedBox(width: 12),
                  // Stats row
                  Expanded(
                    child: Row(
                      mainAxisAlignment: MainAxisAlignment.end,
                      children: [
                        _inlineStat(
                          Icons.task_alt_rounded,
                          '${mTasks.length}',
                          yearColor,
                        ),
                        const SizedBox(width: 10),
                        _inlineStat(
                          Icons.calendar_today_rounded,
                          '$mDays d',
                          yearColor,
                        ),
                        const SizedBox(width: 10),
                        if (mDur.inSeconds > 0)
                          _inlineStat(
                            Icons.timer_outlined,
                            _fmt(mDur),
                            yearColor,
                          ),
                      ],
                    ),
                  ),
                  const SizedBox(width: 8),
                  AnimatedRotation(
                    turns: open ? 0.5 : 0,
                    duration: const Duration(milliseconds: 200),
                    child: Icon(
                      Icons.keyboard_arrow_down_rounded,
                      size: 18,
                      color: Colors.white.withOpacity(0.3),
                    ),
                  ),
                ],
              ),
            ),
          ),

          AnimatedCrossFade(
            firstChild: const SizedBox.shrink(),
            secondChild: Padding(
              padding: const EdgeInsets.only(top: 4, left: 16),
              child: Column(
                children: weeks
                    .map(
                      (w) => _buildWeek(year, month, w, weekMap[w]!, yearColor),
                    )
                    .toList(),
              ),
            ),
            crossFadeState: open
                ? CrossFadeState.showSecond
                : CrossFadeState.showFirst,
            duration: const Duration(milliseconds: 180),
          ),
        ],
      ),
    );
  }

  // ── Week block ────────────────────────────────────────────────────────
  Widget _buildWeek(
    int year,
    int month,
    int weekNum,
    Map<DateTime, _WlDayData> dayMap,
    Color yearColor,
  ) {
    final wKey = '$year-$month-$weekNum';
    final open = _isExpanded(wKey);

    Duration wDur = Duration.zero;
    final Set<String> wTasks = {};
    for (final d in dayMap.values) {
      for (final s in d.sessions) {
        wTasks.add(s.taskId);
        wDur += s.duration;
      }
    }

    final days = dayMap.keys.toList()..sort((a, b) => b.compareTo(a));

    // ── Compute the actual Mon–Sun dates for this ISO week ──────────────
    // ISO week 1 = week containing Jan 4
    final jan4 = DateTime(year, 1, 4);
    final startOfWeek1 = jan4.subtract(Duration(days: jan4.weekday - 1));
    final weekMonday = startOfWeek1.add(Duration(days: (weekNum - 1) * 7));
    final weekDates = List.generate(
      7,
      (i) => weekMonday.add(Duration(days: i)),
    );

    final today = DateTime.now();
    final todayKey = DateTime(today.year, today.month, today.day);

    return Padding(
      padding: const EdgeInsets.only(bottom: 4),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.stretch,
        children: [
          // ── Week header ──
          GestureDetector(
            onTap: () => _toggle(wKey),
            child: Container(
              padding: const EdgeInsets.fromLTRB(12, 9, 12, 9),
              decoration: BoxDecoration(
                color: Colors.white.withOpacity(0.02),
                borderRadius: BorderRadius.circular(8),
                border: Border.all(color: Colors.white.withOpacity(0.05)),
              ),
              child: Row(
                children: [
                  // Week badge
                  Container(
                    padding: const EdgeInsets.symmetric(
                      horizontal: 7,
                      vertical: 3,
                    ),
                    decoration: BoxDecoration(
                      color: yearColor.withOpacity(0.1),
                      borderRadius: BorderRadius.circular(5),
                      border: Border.all(color: yearColor.withOpacity(0.25)),
                    ),
                    child: Text(
                      'W$weekNum',
                      style: TextStyle(
                        color: yearColor.withOpacity(0.8),
                        fontSize: 10,
                        fontWeight: FontWeight.w700,
                        letterSpacing: 0.5,
                      ),
                    ),
                  ),
                  const SizedBox(width: 10),

                  // ── 7-day strip ──────────────────────────────────────
                  ...weekDates.map((wd) {
                    final wdk = DateTime(wd.year, wd.month, wd.day);
                    final hasData = dayMap.containsKey(wdk);
                    final isToday = wdk == todayKey;
                    final isWeekend =
                        wd.weekday == DateTime.saturday ||
                        wd.weekday == DateTime.sunday;

                    Color dotColor;
                    Color labelColor;
                    Color bgColor;
                    if (hasData) {
                      dotColor = yearColor;
                      labelColor = isToday
                          ? yearColor
                          : Colors.white.withOpacity(0.75);
                      bgColor = yearColor.withOpacity(0.12);
                    } else {
                      dotColor = Colors.transparent;
                      labelColor = isWeekend
                          ? Colors.white.withOpacity(0.24)
                          : Colors.white.withOpacity(0.22);
                      bgColor = Colors.transparent;
                    }

                    // Time bar height (proportional to day duration vs week max)
                    Duration dayDur = Duration.zero;
                    if (hasData) {
                      for (final s in dayMap[wdk]!.sessions) {
                        dayDur += s.duration;
                      }
                    }
                    final maxSecs = dayMap.values.fold<int>(0, (mx, d) {
                      final ds = d.sessions.fold<int>(
                        0,
                        (sum, s) => sum + s.duration.inSeconds,
                      );
                      return ds > mx ? ds : mx;
                    });
                    final barFill = (maxSecs > 0 && dayDur.inSeconds > 0)
                        ? (dayDur.inSeconds / maxSecs).clamp(0.0, 1.0)
                        : 0.0;

                    return Padding(
                      padding: const EdgeInsets.only(right: 4),
                      child: Column(
                        mainAxisSize: MainAxisSize.min,
                        children: [
                          // Day letter
                          Text(
                            _dayShort[wd.weekday - 1][0], // 'M','T','W'…
                            style: TextStyle(
                              color: labelColor,
                              fontSize: 9,
                              fontWeight: hasData
                                  ? FontWeight.w700
                                  : FontWeight.normal,
                            ),
                          ),
                          const SizedBox(height: 3),
                          // Day number circle / filled dot
                          Container(
                            width: 22,
                            height: 22,
                            decoration: BoxDecoration(
                              color: bgColor,
                              shape: BoxShape.circle,
                              border: isToday
                                  ? Border.all(
                                      color: yearColor.withOpacity(0.7),
                                      width: 1.5,
                                    )
                                  : null,
                            ),
                            child: Center(
                              child: Text(
                                '${wd.day}',
                                style: TextStyle(
                                  color: labelColor,
                                  fontSize: 10,
                                  fontWeight: hasData
                                      ? FontWeight.w700
                                      : FontWeight.normal,
                                ),
                              ),
                            ),
                          ),
                          const SizedBox(height: 3),
                          // Mini activity bar
                          Container(
                            width: 22,
                            height: 3,
                            decoration: BoxDecoration(
                              borderRadius: BorderRadius.circular(2),
                              color: Colors.white.withOpacity(0.06),
                            ),
                            child: Align(
                              alignment: Alignment.centerLeft,
                              child: FractionallySizedBox(
                                widthFactor: barFill,
                                child: Container(
                                  decoration: BoxDecoration(
                                    borderRadius: BorderRadius.circular(2),
                                    color: hasData
                                        ? yearColor.withOpacity(0.75)
                                        : Colors.transparent,
                                  ),
                                ),
                              ),
                            ),
                          ),
                        ],
                      ),
                    );
                  }),

                  const Spacer(),

                  // Stats
                  if (wTasks.isNotEmpty) ...[
                    Text(
                      '${wTasks.length} tasks',
                      style: TextStyle(
                        color: Colors.white.withOpacity(0.35),
                        fontSize: 10,
                      ),
                    ),
                    const SizedBox(width: 6),
                    Container(
                      width: 1,
                      height: 10,
                      color: Colors.white.withOpacity(0.1),
                    ),
                    const SizedBox(width: 6),
                  ],
                  if (wDur.inSeconds > 0)
                    Text(
                      _fmt(wDur),
                      style: TextStyle(
                        color: Colors.white.withOpacity(0.55),
                        fontSize: 10,
                        fontWeight: FontWeight.w600,
                      ),
                    ),
                  const SizedBox(width: 8),
                  AnimatedRotation(
                    turns: open ? 0.5 : 0,
                    duration: const Duration(milliseconds: 200),
                    child: Icon(
                      Icons.keyboard_arrow_down_rounded,
                      size: 16,
                      color: Colors.white.withOpacity(0.25),
                    ),
                  ),
                ],
              ),
            ),
          ),

          AnimatedCrossFade(
            firstChild: const SizedBox.shrink(),
            secondChild: Padding(
              padding: const EdgeInsets.only(top: 3, left: 14),
              child: Column(
                children: days
                    .map((d) => _buildDay(d, dayMap[d]!, yearColor))
                    .toList(),
              ),
            ),
            crossFadeState: open
                ? CrossFadeState.showSecond
                : CrossFadeState.showFirst,
            duration: const Duration(milliseconds: 160),
          ),
        ],
      ),
    );
  }

  // ── Day block ─────────────────────────────────────────────────────────
  Widget _buildDay(DateTime day, _WlDayData data, Color yearColor) {
    // Aggregate tasks (merge duplicate taskIds)
    final Map<String, ({String title, Duration dur})> byTask = {};
    for (final s in data.sessions) {
      byTask.update(
        s.taskId,
        (v) => (title: v.title, dur: v.dur + s.duration),
        ifAbsent: () => (title: s.taskTitle, dur: s.duration),
      );
    }

    Duration dayDur = Duration.zero;
    for (final t in byTask.values) dayDur += t.dur;

    final isToday = () {
      final now = DateTime.now();
      return day.year == now.year &&
          day.month == now.month &&
          day.day == now.day;
    }();

    return Padding(
      padding: const EdgeInsets.only(bottom: 3),
      child: Container(
        decoration: BoxDecoration(
          color: isToday
              ? yearColor.withOpacity(0.06)
              : Colors.white.withOpacity(0.02),
          borderRadius: BorderRadius.circular(7),
          border: Border.all(
            color: isToday
                ? yearColor.withOpacity(0.2)
                : Colors.white.withOpacity(0.04),
          ),
        ),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.stretch,
          children: [
            // Day header
            Padding(
              padding: const EdgeInsets.fromLTRB(11, 8, 11, 6),
              child: Row(
                children: [
                  // Day name + number
                  Row(
                    children: [
                      Text(
                        _dayShort[day.weekday - 1],
                        style: TextStyle(
                          color: isToday
                              ? yearColor
                              : Colors.white.withOpacity(0.5),
                          fontSize: 11,
                          fontWeight: FontWeight.w700,
                          letterSpacing: 0.5,
                        ),
                      ),
                      const SizedBox(width: 4),
                      Container(
                        width: 22,
                        height: 22,
                        decoration: BoxDecoration(
                          color: isToday
                              ? yearColor.withOpacity(0.2)
                              : Colors.transparent,
                          shape: BoxShape.circle,
                        ),
                        child: Center(
                          child: Text(
                            '${day.day}',
                            style: TextStyle(
                              color: isToday
                                  ? yearColor
                                  : Colors.white.withOpacity(0.55),
                              fontSize: 11,
                              fontWeight: FontWeight.w600,
                            ),
                          ),
                        ),
                      ),
                    ],
                  ),
                  const SizedBox(width: 8),
                  if (isToday)
                    Container(
                      padding: const EdgeInsets.symmetric(
                        horizontal: 5,
                        vertical: 1,
                      ),
                      decoration: BoxDecoration(
                        color: yearColor.withOpacity(0.15),
                        borderRadius: BorderRadius.circular(3),
                      ),
                      child: Text(
                        'TODAY',
                        style: TextStyle(
                          color: yearColor,
                          fontSize: 8,
                          fontWeight: FontWeight.w800,
                          letterSpacing: 0.8,
                        ),
                      ),
                    ),
                  const Spacer(),
                  // Task count + time
                  Text(
                    '${byTask.length} task${byTask.length == 1 ? '' : 's'}',
                    style: TextStyle(
                      color: Colors.white.withOpacity(0.3),
                      fontSize: 10,
                    ),
                  ),
                  const SizedBox(width: 6),
                  Container(
                    width: 1,
                    height: 10,
                    color: Colors.white.withOpacity(0.1),
                  ),
                  const SizedBox(width: 6),
                  Text(
                    dayDur.inSeconds > 0 ? _fmt(dayDur) : '—',
                    style: TextStyle(
                      color: yearColor.withOpacity(0.8),
                      fontSize: 10,
                      fontWeight: FontWeight.w700,
                    ),
                  ),
                ],
              ),
            ),

            // Task list
            if (byTask.isNotEmpty) ...[
              Container(
                height: 1,
                color: Colors.white.withOpacity(0.04),
                margin: const EdgeInsets.symmetric(horizontal: 11),
              ),
              Padding(
                padding: const EdgeInsets.fromLTRB(11, 6, 11, 8),
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: byTask.entries.map((e) {
                    return Padding(
                      padding: const EdgeInsets.only(bottom: 4),
                      child: Row(
                        children: [
                          Container(
                            width: 4,
                            height: 4,
                            decoration: BoxDecoration(
                              color: yearColor.withOpacity(0.5),
                              shape: BoxShape.circle,
                            ),
                          ),
                          const SizedBox(width: 8),
                          Expanded(
                            child: Text(
                              e.value.title,
                              style: TextStyle(
                                color: Colors.white.withOpacity(0.65),
                                fontSize: 11,
                              ),
                              maxLines: 1,
                              overflow: TextOverflow.ellipsis,
                            ),
                          ),
                          const SizedBox(width: 8),
                          Text(
                            e.value.dur.inSeconds > 0 ? _fmt(e.value.dur) : '—',
                            style: TextStyle(
                              color: Colors.white.withOpacity(0.3),
                              fontSize: 10,
                              fontFamily: 'monospace',
                            ),
                          ),
                        ],
                      ),
                    );
                  }).toList(),
                ),
              ),
            ],
          ],
        ),
      ),
    );
  }

  // ── Small helpers ─────────────────────────────────────────────────────
  Widget _statPill(String label, Color color) => Container(
    padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 3),
    decoration: BoxDecoration(
      color: color.withOpacity(0.1),
      borderRadius: BorderRadius.circular(20),
      border: Border.all(color: color.withOpacity(0.2)),
    ),
    child: Text(
      label,
      style: TextStyle(
        color: color.withOpacity(0.85),
        fontSize: 10,
        fontWeight: FontWeight.w600,
      ),
    ),
  );

  Widget _inlineStat(IconData icon, String value, Color color) => Row(
    mainAxisSize: MainAxisSize.min,
    children: [
      Icon(icon, size: 10, color: color.withOpacity(0.5)),
      const SizedBox(width: 3),
      Text(
        value,
        style: TextStyle(
          color: Colors.white.withOpacity(0.45),
          fontSize: 10,
          fontWeight: FontWeight.w500,
        ),
      ),
    ],
  );
}

// ── Worklog data models ───────────────────────────────────────────────────────
class _WlSession {
  final String taskId;
  final String taskTitle;
  final Duration duration;
  _WlSession({
    required this.taskId,
    required this.taskTitle,
    required this.duration,
  });
}

class _WlDayData {
  final List<_WlSession> sessions;
  _WlDayData({required this.sessions});
}

// ─────────────────────────────────────────────────────────────────────────────
// _ScheduleCanvas  –  zoomable/pannable week calendar canvas
// ─────────────────────────────────────────────────────────────────────────────

class _ScheduleCanvas extends StatefulWidget {
  final List<Task> allTasks;
  final DateTime weekStart;
  final DateTime? rangeEnd;
  final Map<String, Project> projects;
  final void Function(Task) onTaskUpdated;
  final void Function(DateTime slot, int suggestedDuration) onCreateRequest;
  final void Function(
    DateTime visibleStart,
    DateTime visibleEnd, {
    required bool shiftPanning,
  })?
  onVisibleRangeChanged;
  final Map<String, List<_ExecutionSession>> taskSessions;
  final _ExecutionViewMode execViewMode;
  final Map<String, Color> projectColors;
  // Feature 8: right-click opens the standard task context menu
  final void Function(Task task, Offset globalPos)? onContextMenu;

  const _ScheduleCanvas({
    Key? key,
    required this.allTasks,
    required this.weekStart,
    this.rangeEnd,
    required this.projects,
    this.projectColors = const {},
    this.taskSessions = const {},
    this.execViewMode = _ExecutionViewMode.planning,
    required this.onTaskUpdated,
    required this.onCreateRequest,
    this.onVisibleRangeChanged,
    this.onContextMenu,
  }) : super(key: key);

  @override
  State<_ScheduleCanvas> createState() => _ScheduleCanvasState();
}

class _ScheduleCanvasState extends State<_ScheduleCanvas> {
  // ── Constants ──────────────────────────────────────────────────────────────
  static const double _bHH = 64.0; // base hour height at scale 1.0
  static const double _tCW = 56.0; // time column width (fixed)
  static const double _hdrH = 40.0; // day-header row height
  static const double _padT = 28.0; // top padding above 12 AM
  static const double _padB = 36.0; // bottom padding below 11:55 PM

  // ── State ──────────────────────────────────────────────────────────────────
  // _scale: VERTICAL zoom (hour height = _bHH * _scale).
  // _hScale: HORIZONTAL zoom (visibleDays = ceil(7 / _hScale)).
  // They start equal and can diverge via axis-specific zoom.
  double _scale = 1.0;
  double _hScale = 1.0;

  // _ox: sub-column horizontal offset in screen pixels, kept in (-cw, 0].
  // _dayShift: how many days from widget.weekStart the first visible column is.
  //   0 = Mon of current week; negative = past; positive = future.
  double _ox = 0.0;
  int _dayShift = 0;

  // _oy: vertical scroll in screen pixels (starts at -7h so 7 AM is visible).
  double _oy = 0.0;

  double _canvasW = 0, _canvasH = 0, _scrollH = 0;
  int _visibleDays = 7; // updated every build

  // Pan gesture bookkeeping
  Offset _panPtrStart = Offset.zero;
  double _panOrigOX = 0, _panOrigOY = 0;
  int _panOrigDayShift = 0;

  // Task drag
  String? _dragId;
  int _dragOrigCol = 0, _dragCurCol = 0;
  double _dragOrigWY = 0, _dragCurWY = 0;
  Offset _dragPtrOrigin = Offset.zero;
  // Schedule-X of the pointer at drag-start (in the canvas local coordinate
  // system). Used to resolve the target column from the cursor's actual
  // position, not the block's left edge, so the block always follows the
  // column that the cursor is over.
  double _dragPointerScheduleX = 0;

  // Task resize (vertical)
  String? _resizeId;
  double _resizeOrigH = 0, _resizeCurH = 0;
  Offset _resizePtrOrigin = Offset.zero;

  // Subcol layout: user-controlled sub-column index overrides (taskId → subCol index).
  Map<String, int> _subColOverrides = {};

  // Horizontal (subcol width) resize: dragging the right edge of a card.
  String? _hResizeId;
  double _hResizeOrigFrac = 0;
  double _hResizeCurFrac = 0;
  Offset _hResizePtrOrigin = Offset.zero;
  // Per-task width fraction overrides: taskId → fraction of the day column width.
  Map<String, double> _subColWidthFracs = {};

  // Hover ghost
  int? _hoverCol;
  double? _hoverWY;

  // Hovered schedule card (used to reveal resize dragger on hover)
  String? _hoveredScheduleTaskId;

  // All-day strip collapsed/expanded
  bool _allDayExpanded = false;

  // User-dragged height for the expanded all-day strip (null = auto from maxRows)
  double? _allDayStripUserHeight;

  // IDs of all-day cards the user has manually collapsed to a compact,
  // single-line height. Cards not in this set start auto-sized so their
  // full title is readable. Expansion/retraction is per-card.
  final Set<String> _allDayCardCollapsed = {};

  // Heights the user has manually dragged a card to (per task id). Lets a
  // card grow taller than its auto-fit "readable" size, e.g. to fill space
  // freed up by dragging the strip's overall resize handle.
  final Map<String, double> _allDayCardManualHeight = {};

  // Compact height used for an all-day card the user has retracted.
  static const double _allDayCardCompactH = 24.0;
  // Minimum / maximum heights for an auto-sized (readable) all-day card.
  static const double _allDayCardMinH = 36.0;
  static const double _allDayCardMaxH = 110.0;
  // Maximum height a card can be manually dragged to.
  static const double _allDayCardManualMaxH = 320.0;

  // Cache of measured "readable" heights for all-day cards, keyed by
  // "taskId@width" so it's recomputed if the column width changes.
  final Map<String, double> _allDayCardNaturalHeightCache = {};

  /// Computes the height an all-day card needs so its full title is visible
  /// (no truncation), given the column width it will render in. Mirrors the
  /// padding/icon geometry used by _ScheduleCardContent so the measured line
  /// count matches what is actually rendered.
  double _allDayCardNaturalHeight(Task t, double cw) {
    final cacheKey = '${t.id}@${cw.toStringAsFixed(1)}';
    final cached = _allDayCardNaturalHeightCache[cacheKey];
    if (cached != null) return cached;

    // Card width inside the strip: outer Padding(2,3,2,3) eats 4px.
    final cardW = (cw - 4).clamp(20.0, 2000.0);
    // _ScheduleCardContent inner padding is (5, 3, 4, ...): 9px horizontal.
    const double iconSize = 10.0;
    const double iconGap = 4.0;
    final textW = (cardW - 9 - iconSize - iconGap).clamp(10.0, 2000.0);

    final painter = TextPainter(
      text: TextSpan(
        text: t.title,
        style: const TextStyle(fontSize: 11, fontWeight: FontWeight.w500),
      ),
      textDirection: TextDirection.ltr,
      maxLines: null,
    )..layout(maxWidth: textW);

    final lineCount = painter.computeLineMetrics().length.clamp(1, 6);
    // maxLines in _ScheduleCardContent is derived as (screenH / 14).floor(),
    // so invert that to get the screenH needed for `lineCount` lines, then
    // add back the top/bottom content padding (3 + 14).
    final double height = (lineCount * 14.0) + 17.0;

    final clamped = height.clamp(_allDayCardMinH, _allDayCardMaxH);
    _allDayCardNaturalHeightCache[cacheKey] = clamped;
    return clamped;
  }


  /// Effective render height for an all-day card: compact if the user has
  /// manually retracted it; a manually-dragged height if the user resized it;
  /// otherwise auto-sized to fit its full title.
  double _allDayCardHeight(Task t, double cw) {
    if (_allDayCardCollapsed.contains(t.id)) return _allDayCardCompactH;
    final manual = _allDayCardManualHeight[t.id];
    if (manual != null) {
      return manual.clamp(_allDayCardMinH, _allDayCardManualMaxH);
    }
    return _allDayCardNaturalHeight(t, cw);
  }

  // Pill color mode: false = status color (default), true = project color
  bool _pillColorByProject = false;

  // Task Creation Mode: when true, hovering shows the hint and clicking creates
  // a task — same as holding Shift. Toggled from the bottom bar switcher.
  bool _taskCreationMode = false;

  // Hide Labels Mode: when true, project names and task titles are hidden on
  // schedule cards — useful for a privacy / focus view.
  bool _hideCardLabels = false;

  /// True when the user can create a new task by clicking on the canvas.
  /// Active when Shift is held OR the bottom-bar Task Creation Mode toggle is on.
  bool get _isCreationActive => _shiftDown || _taskCreationMode;

  // When true, the next didUpdateWidget weekStart change will NOT compensate
  // _dayShift — used by deliberate top-bar navigation (Back / Forward / Today).
  bool _skipNextCompensation = false;

  Timer? _clockTimer;

  // ── Lifecycle ──────────────────────────────────────────────────────────────
  @override
  void initState() {
    super.initState();
    // Store the desired 7-AM offset unconditionally. _clampOY cannot do its
    // job here because _canvasH/_scrollH are 0 before the first layout pass.
    // A post-frame callback re-clamps _oy once real dimensions are available,
    // which prevents the first build from clamping everything to 0 and hiding
    // all task cards.
    _oy = -(7 * _bHH + _padT); // scroll to 7 AM on open
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (mounted) {
        setState(() {
          _oy = _clampOY(_oy, _scale);
        });
      }
    });
    _clockTimer = Timer.periodic(const Duration(minutes: 1), (_) {
      if (mounted) setState(() {});
    });
    HardwareKeyboard.instance.addHandler(_handleKeyEvent);
  }

  @override
  void didUpdateWidget(_ScheduleCanvas oldWidget) {
    super.didUpdateWidget(oldWidget);
    // When the parent sets a new weekStart (from Shift-drag feedback), compensate
    // _dayShift so the visual position stays the same.
    // When a deliberate top-bar navigation triggered this update, skip the
    // compensation so the canvas actually jumps to the new date range.
    if (oldWidget.weekStart != widget.weekStart) {
      if (_skipNextCompensation) {
        _skipNextCompensation = false;
        // No compensation — canvas already jumped to the new start.
      } else {
        final diff = widget.weekStart.difference(oldWidget.weekStart).inDays;
        _dayShift -= diff;
      }
    }
    // When the task list is replaced (e.g. a date/time edit was committed from
    // the details panel), trigger a rebuild so card positions recalculate.
    // `identical` is O(1) — it only compares list identity, not contents.
    if (!identical(oldWidget.allTasks, widget.allTasks)) {
      setState(() {});
    }
  }

  @override
  void dispose() {
    HardwareKeyboard.instance.removeHandler(_handleKeyEvent);
    _clockTimer?.cancel();
    super.dispose();
  }

  /// Called whenever a key is pressed/released. When Shift is released we
  /// snap the horizontal position back inside the rangeEnd boundary so the
  /// view never "parks" in an illegal position.
  /// We also rebuild on Shift down/up so the creation hint appears / disappears
  /// immediately without requiring the mouse to move first.
  bool _handleKeyEvent(KeyEvent event) {
    final isShiftKey =
        event.logicalKey == LogicalKeyboardKey.shiftLeft ||
        event.logicalKey == LogicalKeyboardKey.shiftRight;
    if (event is KeyUpEvent && isShiftKey) {
      // Shift just went up — snap rightward overshoot back into range.
      _snapToBoundary();
      if (mounted) setState(() {}); // hide creation hint
    } else if (event is KeyDownEvent && isShiftKey) {
      if (mounted) setState(() {}); // show creation hint
    }
    return false; // never consume
  }

  /// Snap to right boundary when Shift is released or after zoom.
  /// [visibleDays] can be passed explicitly when called right after a zoom
  /// mutation before the next build updates _visibleDays.
  void _snapToBoundary({int? visibleDays}) {
    final vd = visibleDays ?? _visibleDays;
    final cw = _colW(vd);
    if (cw <= 0) return;
    // _applyHorizBounds won't run when _shiftDown, but we just released Shift
    // so call it directly (Shift is already up by the time this runs).
    final mx = _maxDayShift(vd);
    if (mx == null) return;
    if (_dayShift > mx || (_dayShift == mx && _ox < 0)) {
      setState(() {
        _dayShift = mx;
        _ox = 0.0;
      });
    }
  }

  void resetView() {
    setState(() {
      _scale = 1.0.clamp(_absMinScale, 6.0);
      _hScale = 1.0;
      _ox = 0.0;
      _dayShift = 0;
      _oy = _clampOY(-(7 * _bHH * _scale + _padT), _scale);
    });
  }

  /// Called by top-bar navigation buttons (Back / Forward / Today).
  /// Resets the canvas horizontal position to the new [newWeekStart] and
  /// marks that the upcoming didUpdateWidget should NOT compensate _dayShift.
  void navigateTo(DateTime newWeekStart) {
    _skipNextCompensation = true;
    setState(() {
      _dayShift = 0;
      _ox = 0.0;
    });
  }

  /// Called by the Week / Month toggle in the top bar.
  /// 'week'  → show 7 days  (_hScale = 1.0)
  /// 'month' → show 30 days (_hScale = 7/30) from the current weekStart
  void setViewMode(String mode) {
    _skipNextCompensation = true;
    setState(() {
      _dayShift = 0;
      _ox = 0.0;
      if (mode == 'month') {
        _hScale = 7.0 / 30.0; // 30 columns visible
      } else if (mode == '14d') {
        _hScale = 7.0 / 14.0; // 14 columns visible
      } else {
        _hScale = 1.0; // 7 columns visible (week)
      }
    });
  }

  /// Set an arbitrary number of visible days from the Custom dialog.
  void setViewDays(int days) {
    _skipNextCompensation = true;
    setState(() {
      _dayShift = 0;
      _ox = 0.0;
      _hScale = 7.0 / days.clamp(1, 365);
    });
  }

  void zoomIn() {
    setState(() {
      final newScale = (_scale * 1.3).clamp(_absMinScale, 6.0);
      final midY = (_scrollH > 0 ? _scrollH : _canvasH) / 2;
      final origWY = (midY - _oy) / _vScale;
      _scale = newScale;
      _hScale = (_hScale * 1.3).clamp(_absMinScale, 6.0);
      _ox = 0.0;
      _oy = _clampOY(midY - origWY * newScale, newScale);
    });
    final newVD = (7.0 / _hScale).ceil().clamp(7, 365);
    _snapToBoundary(visibleDays: newVD);
  }

  void zoomOut() {
    setState(() {
      final newScale = (_scale / 1.3).clamp(_absMinScale, 6.0);
      final midY = (_scrollH > 0 ? _scrollH : _canvasH) / 2;
      final origWY = (midY - _oy) / _vScale;
      _scale = newScale;
      _hScale = (_hScale / 1.3).clamp(_absMinScale, 6.0);
      _ox = 0.0;
      _oy = _clampOY(midY - origWY * newScale, newScale);
    });
    final newVD = (7.0 / _hScale).ceil().clamp(7, 365);
    _snapToBoundary(visibleDays: newVD);
  }

  // ── Derived geometry ───────────────────────────────────────────────────────
  // Column width in screen pixels: always fills available width exactly.
  double _colW(int visibleDays) =>
      _canvasW > 0 ? (_canvasW - _tCW) / visibleDays : 120.0;

  // Minimum scale: hard floor so day content never becomes invisible.
  static const double _absMinScale = 0.05;

  // Scale at which 24h + pads exactly fills the scroll area.
  double get _fitScale =>
      _scrollH > 0 ? (_scrollH - _padT - _padB) / (24 * _bHH) : _absMinScale;

  // Effective VERTICAL scale: never compress below fit (24h always fills view).
  // Horizontal zoom (_visibleDays) keeps using raw _scale so more days appear.
  double get _vScale => _scale < _fitScale ? _fitScale : _scale;

  // Clamp _oy so content never leaves empty space — but if content is
  // shorter than the canvas (fully zoomed out), pin to top (oy = 0).
  double _clampOY(double oy, double scale) {
    final vs = scale < _fitScale ? _fitScale : scale;
    final totalH = 24 * _bHH * vs + _padT + _padB;
    final h = _scrollH > 0 ? _scrollH : _canvasH;
    if (totalH <= h) return 0.0;
    return oy.clamp(h - totalH, 0.0);
  }

  bool get _busy => _dragId != null || _resizeId != null || _hResizeId != null;

  // ── Coordinate helpers ─────────────────────────────────────────────────────
  // Screen X of the left edge of column [col].  No _scale in horizontal.
  double _sx(int col, double cw) => col * cw + _ox + _tCW;

  // Screen Y of a world-Y position (hours x _bHH).
  double _sy(double wy) => wy * _vScale + _oy + _padT;

  // Column index from screen X.
  int _colFromSX(double sx, double cw) => ((sx - _ox - _tCW) / cw).floor();

  // World-Y from screen Y.
  double _wy(double sy) => (sy - _oy - _padT) / _vScale;

  // ── Snap helpers ───────────────────────────────────────────────────────────
  double _snapWY(double wy) {
    final min5 = ((wy / _bHH * 60) / 5).round() * 5;
    return (min5 / 60.0 * _bHH).clamp(0.0, (23 * 60 + 55) / 60.0 * _bHH);
  }

  double _snapWH(double wh) {
    final slots = ((wh / _bHH * 60) / 5).round().clamp(1, 24 * 12);
    return slots * 5 / 60.0 * _bHH;
  }

  // ── Date helpers ───────────────────────────────────────────────────────────
  DateTime _slotFromWorld(int col, double wy) {
    final day = widget.weekStart.add(Duration(days: col + _dayShift));
    final totalMin = ((wy / _bHH) * 60).round().clamp(0, 23 * 60 + 55);
    return DateTime(
      day.year,
      day.month,
      day.day,
      totalMin ~/ 60,
      totalMin % 60,
    );
  }

  String _fmt12h(int h, int m) {
    final p = h < 12 ? 'AM' : 'PM';
    final hh = h == 0 ? 12 : (h > 12 ? h - 12 : h);
    return '$hh:${m.toString().padLeft(2, '0')} $p';
  }

  // ── Input handlers ─────────────────────────────────────────────────────────

  bool get _altDown => HardwareKeyboard.instance.isAltPressed;
  bool get _shiftDown => HardwareKeyboard.instance.isShiftPressed;

  // Max _dayShift allowed when not Shift-panning: keeps right edge within rangeEnd.
  // We clamp so that dayShift + visibleDays - 1 <= rangeSpan,
  // i.e. the rightmost visible column never exceeds rangeEnd.
  int? _maxDayShift(int visibleDays) {
    if (_shiftDown) return null; // unlocked when Shift is pressed

    // If we are showing 7 days (default), max shift is 0 (panning is locked).
    // If we are zoomed in to show 3 days, max shift is 4 (can pan within the 7 days).
    // If we are zoomed out (>7 days), max shift is 0.
    // This perfectly prevents revealing new columns without Shift.
    return (7 - visibleDays).clamp(0, 365);
  }

  // Absorb full column-widths from _ox into _dayShift so _ox stays in (-cw, 0].
  // allowPast: if false, clamp _dayShift >= 0 (Monday = hard left border).
  void _normalizeOX(double cw, {bool allowPast = false}) {
    if (cw <= 0) return;
    if (_ox <= -cw) {
      final cols = (-_ox / cw).floor();
      _dayShift += cols;
      _ox += cols * cw;
    } else if (_ox > 0) {
      final cols = (_ox / cw).ceil();
      _dayShift -= cols;
      _ox -= cols * cw; // _ox lands in (-cw, 0]
    }
    if (!allowPast && _dayShift < 0) {
      _ox = 0.0;
      _dayShift = 0;
    }
  }

  /// Hard boundary clamp, applied after every horizontal-position mutation.
  /// [vd] is the current visible-day count (pass fresh value from the closure,
  /// not the possibly-stale _visibleDays field).
  void _applyHorizBounds(double cw, int vd) {
    if (_shiftDown) return; // Shift = intentionally unlocked
    // Past (left) boundary — never before weekStart
    if (_dayShift < 0) {
      _dayShift = 0;
      _ox = 0.0;
      return;
    }
    // Future (right) boundary — never past rangeEnd
    final mx = _maxDayShift(vd);
    if (mx == null) return; // no rangeEnd set yet, nothing to clamp
    if (_dayShift > mx) {
      _dayShift = mx;
      _ox = 0.0;
    } else if (_dayShift == mx && _ox < 0) {
      // Sub-column overshoot at the boundary — park flush.
      _ox = 0.0;
    }
  }

  // Zoom horizontal axis around a screen-X position.
  void _zoomH(double screenX, double factor, double cw) {
    final newHScale = (_hScale * factor).clamp(_absMinScale, 6.0);
    final worldCol = (screenX - _ox - _tCW) / cw;
    final newVD = (7.0 / newHScale).ceil().clamp(7, 365);
    final newCw = _canvasW > 0 ? (_canvasW - _tCW) / newVD : cw;
    _hScale = newHScale;
    _ox = screenX - _tCW - worldCol * newCw;
    _normalizeOX(newCw, allowPast: true); // absorb full columns first
    _applyHorizBounds(newCw, newVD); // then enforce boundary
  }

  // Zoom vertical axis around a screen-Y position.
  void _zoomV(double screenY, double factor) {
    final newScale = (_scale * factor).clamp(_absMinScale, 6.0);
    final origWY = _wy(screenY);
    _scale = newScale;
    final newVS = newScale < _fitScale ? _fitScale : newScale;
    _oy = _clampOY(screenY - _padT - origWY * newVS, newScale);
  }

  // Canvas area scroll (Alt = zoom both, plain = pan).
  void _handleScrollCanvas(PointerScrollEvent e, double cw) {
    final vd = _visibleDays;
    setState(() {
      if (_altDown) {
        final factor = 1 + (-e.scrollDelta.dy) * 0.0015;
        _zoomV(e.localPosition.dy, factor);
        // _zoomH computes its own fresh vd from newHScale
        _zoomH(e.localPosition.dx, factor, cw);
      } else if (e.scrollDelta.dx.abs() > e.scrollDelta.dy.abs()) {
        _ox -= e.scrollDelta.dx;
        _normalizeOX(cw, allowPast: _shiftDown);
        _applyHorizBounds(cw, vd);
      } else {
        _oy = _clampOY(_oy - e.scrollDelta.dy, _scale);
      }
    });
  }

  // Day-header row scroll (Alt = zoom H, plain = pan H).
  void _handleScrollDayHeader(PointerScrollEvent e, double cw) {
    final vd = _visibleDays;
    setState(() {
      final dy = e.scrollDelta.dy;
      final dx = e.scrollDelta.dx;
      final dominant = dy.abs() > dx.abs() ? dy : dx;
      if (_altDown) {
        _zoomH(e.localPosition.dx - _tCW, 1 + (-dominant) * 0.0015, cw);
      } else {
        _ox -= dominant;
        _normalizeOX(cw, allowPast: _shiftDown);
        _applyHorizBounds(cw, vd);
      }
    });
  }

  // Time-column scroll (Alt = zoom V, plain = pan V).
  void _handleScrollTimeCol(PointerScrollEvent e) {
    setState(() {
      final dy = e.scrollDelta.dy;
      final dx = e.scrollDelta.dx;
      final dominant = dy.abs() > dx.abs() ? dy : dx;
      if (_altDown) {
        _zoomV(e.localPosition.dy, 1 + (-dominant) * 0.0015);
      } else {
        _oy = _clampOY(_oy - dominant, _scale);
      }
    });
  }

  // ── Build ──────────────────────────────────────────────────────────────────
  @override
  Widget build(BuildContext context) {
    return LayoutBuilder(
      builder: (ctx, box) {
        _canvasW = box.maxWidth;
        _canvasH = box.maxHeight;

        final now = DateTime.now();
        final today = DateTime(now.year, now.month, now.day);

        // visibleDays: zoom out (_scale < 1) -> more days; zoom in -> fewer.
        // Minimum 7 so a full week is always shown at default zoom.
        final int visibleDays = (7.0 / _hScale).ceil().clamp(7, 365);
        _visibleDays = visibleDays;
        final cw = _colW(visibleDays);
        final days = List.generate(
          visibleDays,
          (i) => widget.weekStart.add(Duration(days: i + _dayShift)),
        );

        // Tell parent which date range is visible (post-frame to avoid
        // setState-during-build).
        WidgetsBinding.instance.addPostFrameCallback((_) {
          widget.onVisibleRangeChanged?.call(
            days.first,
            days.last,
            shiftPanning: _shiftDown,
          );
        });

        // Separate date-only (all-day) from datetime (timed) tasks.
        // Uses scheduledDateTime (plannedAt > dueDay+time) for placement.
        final Map<String, int> taskCol = {};
        final Map<String, int> allDayCol = {};

        for (int c = 0; c < visibleDays; c++) {
          final d = days[c];
          for (final t in widget.allTasks) {
            final date = t.scheduledDate;
            if (date == null) continue;
            if (date.year == d.year &&
                date.month == d.month &&
                date.day == d.day) {
              if (t.scheduledDateTime != null) {
                taskCol[t.id] = c;
              } else {
                allDayCol[t.id] = c;
              }
            }
          }
        }

        final allDayTasks = widget.allTasks
            .where((t) => allDayCol.containsKey(t.id))
            .toList();

        final todayCol = days.indexWhere((d) => d == today);

        return Column(
          children: [
            Listener(
              onPointerSignal: (e) {
                if (e is PointerScrollEvent) _handleScrollDayHeader(e, cw);
              },
              child: _buildHeader(days, today, visibleDays, cw),
            ),
            _buildAllDayStrip(allDayTasks, allDayCol, days, visibleDays, cw),
            Expanded(
              child: LayoutBuilder(
                builder: (_, scrollBox) {
                  _scrollH = scrollBox.maxHeight;
                  // Re-clamp immediately with the fresh _scrollH so _oy is
                  // always valid relative to the actual visible area.
                  _scale = _scale.clamp(_absMinScale, 6.0);
                  _oy = _clampOY(_oy, _scale);
                  return Listener(
                    onPointerSignal: (e) {
                      if (e is PointerScrollEvent) _handleScrollCanvas(e, cw);
                    },
                    child: MouseRegion(
                      cursor: _isCreationActive
                          ? SystemMouseCursors.precise
                          : SystemMouseCursors.basic,
                      onHover: _busy
                          ? null
                          : (e) {
                              final sx = e.localPosition.dx;
                              final sy = e.localPosition.dy;
                              final col = _colFromSX(sx, cw);
                              final wy = _wy(sy);
                              if (col >= 0 &&
                                  col < visibleDays &&
                                  wy >= 0 &&
                                  wy < 24 * _bHH) {
                                setState(() {
                                  _hoverCol = col;
                                  _hoverWY = _snapWY(wy);
                                });
                              } else {
                                setState(() {
                                  _hoverCol = null;
                                  _hoverWY = null;
                                });
                              }
                            },
                      onExit: (_) => setState(() {
                        _hoverCol = null;
                        _hoverWY = null;
                      }),
                      child: GestureDetector(
                        behavior: HitTestBehavior.opaque,
                        onScaleStart: _busy
                            ? null
                            : (d) {
                                _panPtrStart = d.localFocalPoint;
                                _panOrigOX = _ox;
                                _panOrigOY = _oy;
                                _panOrigDayShift = _dayShift;
                              },
                        onScaleUpdate: _busy
                            ? null
                            : (d) {
                                if (d.pointerCount >= 2) {
                                  final newScale = (_scale * d.scale).clamp(
                                    _absMinScale,
                                    6.0,
                                  );
                                  final focal = d.localFocalPoint;
                                  final origWY = _wy(focal.dy);
                                  final newVS = newScale < _fitScale
                                      ? _fitScale
                                      : newScale;
                                  setState(() {
                                    _scale = newScale;
                                    _oy = _clampOY(
                                      focal.dy - origWY * newVS,
                                      newScale,
                                    );
                                  });
                                } else {
                                  final delta =
                                      d.localFocalPoint - _panPtrStart;
                                  final vd = _visibleDays;
                                  setState(() {
                                    _ox = _panOrigOX + delta.dx;
                                    _dayShift = _panOrigDayShift;
                                    _normalizeOX(cw, allowPast: _shiftDown);
                                    _applyHorizBounds(cw, vd);
                                    _oy = _clampOY(
                                      _panOrigOY + delta.dy,
                                      _scale,
                                    );
                                  });
                                }
                              },
                        onTapUp: (d) {
                          // Only create a task when Shift is held or the
                          // Task Creation Mode toggle is active.
                          if (!_isCreationActive) return;
                          if (_hoverCol == null || _hoverWY == null) return;
                          final hourH = _bHH * _vScale;
                          final int slotMin = hourH >= 80
                              ? 5
                              : hourH >= 40
                              ? 15
                              : 30;
                          widget.onCreateRequest(
                            _slotFromWorld(_hoverCol!, _hoverWY!),
                            slotMin,
                          );
                        },
                        child: ClipRect(
                          child: Stack(
                            children: [
                              Positioned.fill(
                                child: CustomPaint(
                                  painter: _ScheduleGridPainter(
                                    scale: _vScale,
                                    ox: _ox,
                                    oy: _oy,
                                    colW: cw,
                                    bHH: _bHH,
                                    tCW: _tCW,
                                    padT: _padT,
                                    padB: _padB,
                                    todayCol: todayCol,
                                    visibleDays: visibleDays,
                                  ),
                                ),
                              ),
                              // Time-column overlay: plain scroll = pan V, Alt = zoom V
                              Positioned(
                                left: 0,
                                top: 0,
                                width: _tCW,
                                bottom: 0,
                                child: Listener(
                                  behavior: HitTestBehavior.opaque,
                                  onPointerSignal: (e) {
                                    if (e is PointerScrollEvent)
                                      _handleScrollTimeCol(e);
                                  },
                                  child: const SizedBox.expand(),
                                ),
                              ),
                              if (!_busy &&
                                  _isCreationActive &&
                                  _hoverCol != null &&
                                  _hoverWY != null)
                                _buildHint(_hoverCol!, _hoverWY!, cw),
                              if (todayCol >= 0)
                                ..._buildNowLine(now, todayCol),
                              // ── Compute overlap layout once per build ──────
                              // Group timed tasks by day column, then run the
                              // overlap algorithm for each day.
                              ..._buildOverlapCards(
                                widget.allTasks, taskCol, cw,
                                opacity: widget.execViewMode !=
                                    _ExecutionViewMode.planning ? 0.22 : 1.0,
                              ),
                              // ── Execution session blocks ────────────────────
                              if (widget.execViewMode !=
                                  _ExecutionViewMode.planning)
                                ...widget.taskSessions.entries.expand((entry) {
                                  return (entry.value).map((session) {
                                    final sStart = session.startTime;
                                    final sDay = DateTime(
                                      sStart.year,
                                      sStart.month,
                                      sStart.day,
                                    );
                                    final colIdx = days.indexWhere(
                                      (d) =>
                                          d.year == sDay.year &&
                                          d.month == sDay.month &&
                                          d.day == sDay.day,
                                    );
                                    if (colIdx < 0)
                                      return const Positioned(
                                        top: 0,
                                        left: 0,
                                        child: SizedBox.shrink(),
                                      );

                                    final task = widget.allTasks.firstWhere(
                                      (t) => t.id == entry.key,
                                      orElse: () => Task(
                                        id: '',
                                        title: '?',
                                        isDone: false,
                                        projectId: '',
                                        subTaskIds: [],
                                        timeSpent: 0,
                                        attachments: [],
                                        tagIds: [],
                                      ),
                                    );
                                    if (task.id.isEmpty)
                                      return const Positioned(
                                        top: 0,
                                        left: 0,
                                        child: SizedBox.shrink(),
                                      );

                                    final colorIdx = widget.projects.keys
                                        .toList()
                                        .indexOf(task.projectId);
                                    final color = _projectColor(
                                      task.projectId,
                                      colorIdx < 0 ? 0 : colorIdx,
                                    );

                                    final worldY =
                                        (sStart.hour +
                                            sStart.minute / 60.0 +
                                            sStart.second / 3600.0) *
                                        _bHH;
                                    final durH =
                                        session.duration.inSeconds / 3600.0;
                                    final worldH = durH * _bHH;

                                    final gutter = cw >= 12
                                        ? 3.0
                                        : (cw * 0.25).floorToDouble();
                                    final sx = _sx(colIdx, cw) + gutter;
                                    final sy = _sy(worldY) + 2;
                                    final sw = (cw - gutter * 2).clamp(
                                      1.0,
                                      double.infinity,
                                    );
                                    final sh = (worldH * _vScale - 4).clamp(
                                      6.0,
                                      double.infinity,
                                    );

                                    if (sx + sw < _tCW ||
                                        sx > _canvasW ||
                                        sy + sh < 0 ||
                                        sy > _scrollH) {
                                      return const Positioned(
                                        top: 0,
                                        left: 0,
                                        child: SizedBox.shrink(),
                                      );
                                    }

                                    final segs =
                                        widget.execViewMode ==
                                            _ExecutionViewMode.executionDetail
                                        ? _buildSessionSegs(session, color)
                                        : <_SegBlock>[];

                                    final isInterrupted =
                                        session.status ==
                                        _SessionStatus.interrupted;
                                    final isCompleted =
                                        session.status ==
                                        _SessionStatus.completed;
                                    final borderColor = isInterrupted
                                        ? const Color(
                                            0xFFFFB74D,
                                          ).withOpacity(0.7)
                                        : isCompleted
                                        ? const Color(
                                            0xFF81C784,
                                          ).withOpacity(0.7)
                                        : color.withOpacity(0.6);
                                    final bgColor = isInterrupted
                                        ? const Color(
                                            0xFFFFB74D,
                                          ).withOpacity(0.15)
                                        : isCompleted
                                        ? const Color(
                                            0xFF81C784,
                                          ).withOpacity(0.18)
                                        : color.withOpacity(0.22);

                                    return Positioned(
                                      left: sx,
                                      top: sy,
                                      width: sw,
                                      height: sh,
                                      child: Tooltip(
                                        message:
                                            '${task.title}\n'
                                            '${sStart.hour.toString().padLeft(2, '0')}:${sStart.minute.toString().padLeft(2, '0')}'
                                            ' – ${session.endTime != null ? '${session.endTime!.hour.toString().padLeft(2, '0')}:${session.endTime!.minute.toString().padLeft(2, '0')}' : 'now'}'
                                            '${isInterrupted
                                                ? '  · interrupted'
                                                : isCompleted
                                                ? '  · completed'
                                                : ''}',
                                        child: Container(
                                          decoration: BoxDecoration(
                                            color: bgColor,
                                            borderRadius: BorderRadius.circular(
                                              4,
                                            ),
                                            border: Border.all(
                                              color: borderColor,
                                              width: 1.5,
                                            ),
                                          ),
                                          clipBehavior: Clip.hardEdge,
                                          child: segs.isEmpty
                                              ? (sw > 30
                                                    ? Align(
                                                        alignment: Alignment
                                                            .centerLeft,
                                                        child: Padding(
                                                          padding:
                                                              const EdgeInsets.symmetric(
                                                                horizontal: 4,
                                                              ),
                                                          child: Text(
                                                            task.title,
                                                            style: TextStyle(
                                                              fontSize: 9,
                                                              color: color
                                                                  .withOpacity(
                                                                    0.9,
                                                                  ),
                                                              fontWeight:
                                                                  FontWeight
                                                                      .w500,
                                                            ),
                                                            overflow:
                                                                TextOverflow
                                                                    .ellipsis,
                                                          ),
                                                        ),
                                                      )
                                                    : null)
                                              // ── Execution-Detail card ──
                                              : Container(
                                                  // Thicker unified border enclosing title + W/R bands
                                                  decoration: BoxDecoration(
                                                    borderRadius:
                                                        BorderRadius.circular(
                                                          4,
                                                        ),
                                                    border: Border.all(
                                                      color: borderColor,
                                                      width: 2.0,
                                                    ),
                                                  ),
                                                  clipBehavior: Clip.hardEdge,
                                                  child: Column(
                                                    crossAxisAlignment:
                                                        CrossAxisAlignment
                                                            .stretch,
                                                    children: [
                                                      // ── Title header ──
                                                      if (sw > 32 && sh > 14)
                                                        Container(
                                                          height: 18,
                                                          color: bgColor,
                                                          padding:
                                                              const EdgeInsets.symmetric(
                                                                horizontal: 5,
                                                              ),
                                                          child: Row(
                                                            crossAxisAlignment:
                                                                CrossAxisAlignment
                                                                    .center,
                                                            children: [
                                                              Icon(
                                                                task
                                                                    .status
                                                                    .icon,
                                                                size: 9,
                                                                color: color,
                                                              ),
                                                              const SizedBox(
                                                                width: 3,
                                                              ),
                                                              Expanded(
                                                                child: Text(
                                                                  task.title,
                                                                  style: TextStyle(
                                                                    fontSize: 9,
                                                                    fontWeight:
                                                                        FontWeight
                                                                            .w600,
                                                                    color: Colors
                                                                        .white
                                                                        .withOpacity(
                                                                          0.9,
                                                                        ),
                                                                    letterSpacing:
                                                                        0.1,
                                                                  ),
                                                                  overflow:
                                                                      TextOverflow
                                                                          .ellipsis,
                                                                  maxLines: 1,
                                                                ),
                                                              ),
                                                            ],
                                                          ),
                                                        ),

                                                      // ── Thin separator ──
                                                      if (sw > 32 && sh > 14)
                                                        Container(
                                                          height: 1,
                                                          color: borderColor
                                                              .withOpacity(0.6),
                                                        ),

                                                      // ── W/R bands ──
                                                      Expanded(
                                                        child: Stack(
                                                          children: [
                                                            Positioned.fill(
                                                              child: Column(
                                                                children: segs.map((
                                                                  s,
                                                                ) {
                                                                  final titleH =
                                                                      sw > 32 &&
                                                                          sh >
                                                                              14
                                                                      ? 19.0
                                                                      : 0.0;
                                                                  final bandH =
                                                                      s.frac *
                                                                      (sh -
                                                                          titleH);
                                                                  final isWork =
                                                                      s.label ==
                                                                      'W';
                                                                  final badgeColor =
                                                                      isWork
                                                                      ? const Color(
                                                                          0xFF4FC3F7,
                                                                        )
                                                                      : const Color(
                                                                          0xFF81C784,
                                                                        );
                                                                  return Expanded(
                                                                    flex:
                                                                        (s.frac *
                                                                                1000)
                                                                            .round()
                                                                            .clamp(
                                                                              1,
                                                                              999,
                                                                            ),
                                                                    child: Container(
                                                                      color: s
                                                                          .color,
                                                                      padding:
                                                                          bandH >
                                                                              14
                                                                          ? const EdgeInsets.only(
                                                                              left: 4,
                                                                              top: 3,
                                                                            )
                                                                          : EdgeInsets.zero,
                                                                      alignment:
                                                                          Alignment
                                                                              .topLeft,
                                                                      // ── W / R badge card ──
                                                                      child:
                                                                          bandH >
                                                                              14
                                                                          ? Container(
                                                                              padding: const EdgeInsets.symmetric(
                                                                                horizontal: 4,
                                                                                vertical: 1,
                                                                              ),
                                                                              decoration: BoxDecoration(
                                                                                color: badgeColor.withOpacity(
                                                                                  0.18,
                                                                                ),
                                                                                borderRadius: BorderRadius.circular(
                                                                                  3,
                                                                                ),
                                                                                border: Border.all(
                                                                                  color: badgeColor.withOpacity(
                                                                                    0.55,
                                                                                  ),
                                                                                  width: 0.8,
                                                                                ),
                                                                              ),
                                                                              child: Text(
                                                                                s.label,
                                                                                style: TextStyle(
                                                                                  fontSize: 7,
                                                                                  fontWeight: FontWeight.w800,
                                                                                  color: badgeColor,
                                                                                  letterSpacing: 0.4,
                                                                                ),
                                                                              ),
                                                                            )
                                                                          : null,
                                                                    ),
                                                                  );
                                                                }).toList(),
                                                              ),
                                                            ),
                                                            // ── Resize handle ──
                                                            if (sh > 18)
                                                              Positioned(
                                                                bottom: 0,
                                                                left: 0,
                                                                right: 0,
                                                                height: 12,
                                                                child: Container(
                                                                  decoration: BoxDecoration(
                                                                    borderRadius:
                                                                        const BorderRadius.vertical(
                                                                          bottom:
                                                                              Radius.circular(
                                                                                4,
                                                                              ),
                                                                        ),
                                                                    gradient: LinearGradient(
                                                                      begin: Alignment
                                                                          .topCenter,
                                                                      end: Alignment
                                                                          .bottomCenter,
                                                                      colors: [
                                                                        Colors
                                                                            .transparent,
                                                                        Colors
                                                                            .black
                                                                            .withOpacity(
                                                                              0.3,
                                                                            ),
                                                                      ],
                                                                    ),
                                                                  ),
                                                                  child: Center(
                                                                    child: Container(
                                                                      width: 20,
                                                                      height: 2,
                                                                      decoration: BoxDecoration(
                                                                        color: Colors
                                                                            .white
                                                                            .withOpacity(
                                                                              0.3,
                                                                            ),
                                                                        borderRadius:
                                                                            BorderRadius.circular(
                                                                              1,
                                                                            ),
                                                                      ),
                                                                    ),
                                                                  ),
                                                                ),
                                                              ),
                                                          ],
                                                        ),
                                                      ),
                                                    ],
                                                  ),
                                                ),
                                        ),
                                      ),
                                    );
                                  });
                                }),
                            ],
                          ),
                        ),
                      ),
                    ),
                  );
                },
              ),
            ),
            _buildBottomBar(),
          ],
        );
      },
    );
  }

  // ── Bottom status bar ──────────────────────────────────────────────────────
  Widget _buildBottomBar() {
    // The hover-slot info is only relevant when creation is active.
    final hasHover =
        !_busy && _isCreationActive && _hoverCol != null && _hoverWY != null;

    // Build the left-side content based on mode and hover state.
    Widget leftContent;

    if (hasHover) {
      // ── Derive slot duration from current zoom (same logic as _buildHint) ──
      final hourH = _bHH * _vScale;
      final int slotMin;
      if (hourH >= 80) {
        slotMin = 5;
      } else if (hourH >= 40) {
        slotMin = 15;
      } else {
        slotMin = 30;
      }

      final int startMin = ((_hoverWY! / _bHH) * 60).round().clamp(
        0,
        23 * 60 + 55,
      );
      final int endMin = (startMin + slotMin).clamp(0, 24 * 60);

      final String startLabel = _fmt12h(startMin ~/ 60, startMin % 60);
      final String endLabel = _fmt12h(endMin ~/ 60, endMin % 60);
      final int pct = (_scale * 100).round();
      final String spanLabel = slotMin >= 60
          ? '${slotMin ~/ 60}h'
          : '$slotMin min';

      leftContent = Row(
        mainAxisSize: MainAxisSize.min,
        children: [
          const Icon(Icons.schedule, size: 11, color: Color(0xFF4FC3F7)),
          const SizedBox(width: 6),
          Text(
            'Span at Current Zoom ($pct%): $spanLabel',
            style: const TextStyle(fontSize: 10, color: Color(0xFF6B7080)),
          ),
          const SizedBox(width: 8),
          const Text(
            '────▶',
            style: TextStyle(fontSize: 9, color: Color(0xFF3A4050)),
          ),
          const SizedBox(width: 8),
          Text(
            'Block: $startLabel – $endLabel',
            style: const TextStyle(
              fontSize: 10,
              color: Color(0xFF4FC3F7),
              fontWeight: FontWeight.w600,
            ),
          ),
        ],
      );
    } else if (_taskCreationMode) {
      // Creation mode is on via toggle but mouse isn't hovering a valid slot.
      leftContent = const Row(
        mainAxisSize: MainAxisSize.min,
        children: [
          Icon(Icons.add_circle_outline, size: 11, color: Color(0xFF4FC3F7)),
          SizedBox(width: 6),
          Text(
            'Task Creation Mode — click on the canvas to place a task',
            style: TextStyle(fontSize: 10, color: Color(0xFF4A6070)),
          ),
        ],
      );
    } else {
      // Default idle state: no creation mode, show a concise hint.
      leftContent = const Row(
        mainAxisSize: MainAxisSize.min,
        children: [
          Icon(Icons.drag_indicator, size: 11, color: Color(0xFF4A4F58)),
          SizedBox(width: 6),
          Text(
            'Drag or resize tasks · Right-click a task for details · Hold Shift or enable Task Creation Mode to add',
            style: TextStyle(fontSize: 10, color: Color(0xFF4A4F58)),
          ),
        ],
      );
    }

    return Container(
      height: 28,
      decoration: const BoxDecoration(
        color: Color(0xFF151718),
        border: Border(top: BorderSide(color: Color(0xFF2C2F32), width: 0.5)),
      ),
      padding: const EdgeInsets.symmetric(horizontal: 10),
      child: Row(
        children: [
          leftContent,
          const Spacer(),
          // ── Task Creation Mode toggle ──────────────────────────────────────
          _buildCreationModeToggle(),
          const SizedBox(width: 10),
          _buildHideLabelsToggle(),
          const SizedBox(width: 10),
          _buildPillColorToggle(),
        ],
      ),
    );
  }

  // ── Task Creation Mode toggle ──────────────────────────────────────────────
  Widget _buildCreationModeToggle() {
    final isOn = _taskCreationMode;
    const accent = Color(0xFF4FC3F7);
    const offTrack = Color(0xFF2A2D32);
    const offBorder = Color(0xFF3A4050);

    return GestureDetector(
      onTap: () => setState(() => _taskCreationMode = !_taskCreationMode),
      child: Tooltip(
        message: isOn
            ? 'Task Creation Mode ON — click to disable'
            : 'Task Creation Mode OFF — click to enable (or hold Shift)',
        child: Row(
          mainAxisSize: MainAxisSize.min,
          children: [
            Icon(
              Icons.add_task_rounded,
              size: 11,
              color: isOn ? accent : const Color(0xFF4A4F58),
            ),
            const SizedBox(width: 4),
            Text(
              'Task Creation',
              style: TextStyle(
                fontSize: 9,
                fontWeight: FontWeight.w600,
                color: isOn ? accent : const Color(0xFF4A4F58),
                letterSpacing: 0.3,
              ),
            ),
            const SizedBox(width: 5),
            AnimatedContainer(
              duration: const Duration(milliseconds: 180),
              width: 28,
              height: 14,
              decoration: BoxDecoration(
                borderRadius: BorderRadius.circular(7),
                color: isOn ? const Color(0xFF1A3A4A) : offTrack,
                border: Border.all(
                  color: isOn ? accent.withOpacity(0.5) : offBorder,
                  width: 1,
                ),
              ),
              child: AnimatedAlign(
                duration: const Duration(milliseconds: 180),
                alignment: isOn ? Alignment.centerRight : Alignment.centerLeft,
                child: Padding(
                  padding: const EdgeInsets.symmetric(horizontal: 2),
                  child: Container(
                    width: 10,
                    height: 10,
                    decoration: BoxDecoration(
                      shape: BoxShape.circle,
                      color: isOn ? accent : const Color(0xFF4A4F58),
                    ),
                  ),
                ),
              ),
            ),
          ],
        ),
      ),
    );
  }

  // ── Pill color mode toggle ─────────────────────────────────────────────────
  Widget _buildPillColorToggle() {
    final isProject = _pillColorByProject;
    return GestureDetector(
      onTap: () => setState(() => _pillColorByProject = !_pillColorByProject),
      child: Tooltip(
        message: isProject
            ? 'Coloring by Project — click for Status'
            : 'Coloring by Status — click for Project',
        child: Row(
          mainAxisSize: MainAxisSize.min,
          children: [
            Icon(
              isProject ? Icons.folder_outlined : Icons.flag_outlined,
              size: 11,
              color: isProject
                  ? const Color(0xFF4FC3F7)
                  : const Color(0xFF9E9E9E),
            ),
            const SizedBox(width: 4),
            Text(
              isProject ? 'Project' : 'Status',
              style: TextStyle(
                fontSize: 9,
                fontWeight: FontWeight.w600,
                color: isProject
                    ? const Color(0xFF4FC3F7)
                    : const Color(0xFF6B7080),
                letterSpacing: 0.3,
              ),
            ),
            const SizedBox(width: 5),
            AnimatedContainer(
              duration: const Duration(milliseconds: 180),
              width: 28,
              height: 14,
              decoration: BoxDecoration(
                borderRadius: BorderRadius.circular(7),
                color: isProject
                    ? const Color(0xFF1A3A4A)
                    : const Color(0xFF2A2D32),
                border: Border.all(
                  color: isProject
                      ? const Color(0xFF4FC3F7).withOpacity(0.5)
                      : const Color(0xFF3A4050),
                  width: 1,
                ),
              ),
              child: AnimatedAlign(
                duration: const Duration(milliseconds: 180),
                alignment: isProject
                    ? Alignment.centerRight
                    : Alignment.centerLeft,
                child: Padding(
                  padding: const EdgeInsets.symmetric(horizontal: 2),
                  child: Container(
                    width: 10,
                    height: 10,
                    decoration: BoxDecoration(
                      shape: BoxShape.circle,
                      color: isProject
                          ? const Color(0xFF4FC3F7)
                          : const Color(0xFF6B7080),
                    ),
                  ),
                ),
              ),
            ),
          ],
        ),
      ),
    );
  }

  // ── Hide Labels toggle ────────────────────────────────────────────────────
  Widget _buildHideLabelsToggle() {
    final isHidden = _hideCardLabels;
    const accent = Color(0xFF4FC3F7);
    const offTrack = Color(0xFF2A2D32);
    const offBorder = Color(0xFF3A4050);

    return GestureDetector(
      onTap: () => setState(() => _hideCardLabels = !_hideCardLabels),
      child: Tooltip(
        message: isHidden
            ? 'Labels hidden — click to show project & title'
            : 'Labels visible — click to hide project & title',
        child: Row(
          mainAxisSize: MainAxisSize.min,
          children: [
            Icon(
              isHidden ? Icons.visibility_off_outlined : Icons.label_outline,
              size: 11,
              color: isHidden ? accent : const Color(0xFF4A4F58),
            ),
            const SizedBox(width: 4),
            Text(
              'Labels',
              style: TextStyle(
                fontSize: 9,
                fontWeight: FontWeight.w600,
                color: isHidden ? accent : const Color(0xFF4A4F58),
                letterSpacing: 0.3,
              ),
            ),
            const SizedBox(width: 5),
            AnimatedContainer(
              duration: const Duration(milliseconds: 180),
              width: 28,
              height: 14,
              decoration: BoxDecoration(
                borderRadius: BorderRadius.circular(7),
                color: isHidden ? const Color(0xFF1A3A4A) : offTrack,
                border: Border.all(
                  color: isHidden ? accent.withOpacity(0.5) : offBorder,
                  width: 1,
                ),
              ),
              child: AnimatedAlign(
                duration: const Duration(milliseconds: 180),
                alignment:
                    isHidden ? Alignment.centerRight : Alignment.centerLeft,
                child: Padding(
                  padding: const EdgeInsets.symmetric(horizontal: 2),
                  child: Container(
                    width: 10,
                    height: 10,
                    decoration: BoxDecoration(
                      shape: BoxShape.circle,
                      color: isHidden ? accent : const Color(0xFF4A4F58),
                    ),
                  ),
                ),
              ),
            ),
          ],
        ),
      ),
    );
  }

  // ── All-day strip ──────────────────────────────────────────────────────────
  Widget _buildAllDayStrip(
    List<Task> tasks,
    Map<String, int> colMap,
    List<DateTime> days,
    int visibleDays,
    double cw,
  ) {
    final Map<int, List<Task>> byCol = {};
    for (final t in tasks) {
      final c = colMap[t.id]!;
      (byCol[c] ??= []).add(t);
    }

    final int totalTasks = tasks.length;
    // Each card's height now depends on its own title (auto-sized to be
    // readable, or compacted if the user retracted it), so the strip's
    // overall expanded height is the tallest column's summed card heights —
    // not a fixed row count.
    double maxColH = 0;
    for (final colTasks in byCol.values) {
      double colH = 0;
      for (final t in colTasks.take(4)) {
        colH += _allDayCardHeight(t, cw) + 2.0; // + bottom margin
      }
      if (colH > maxColH) maxColH = colH;
    }
    if (maxColH == 0) maxColH = 38.0; // fallback when nothing to show yet
    final double expandedH = maxColH + 8.0;

    // Collapsed bar height: always 22px, shows count badge + chevron.
    const double collapsedH = 22.0;

    final bool hasEvents = totalTasks > 0;

    const double draggerH = 6.0;
    final double activeH =
        _allDayStripUserHeight?.clamp(collapsedH, 400.0) ?? expandedH;
    final double stripH =
        (_allDayExpanded && hasEvents) ? activeH : collapsedH;

    // Reset user height when collapsed so next expand starts at auto height.
    // (done imperatively: see onTap below)

    final Widget contentRow = Row(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        // Time-column side: toggle button
        GestureDetector(
          onTap: hasEvents
              ? () => setState(() {
                    _allDayExpanded = !_allDayExpanded;
                    if (!_allDayExpanded) _allDayStripUserHeight = null;
                  })
              : null,
          child: Container(
            width: _tCW,
            height: collapsedH,
            alignment: Alignment.center,
            padding: const EdgeInsets.only(right: 4),
            child: Row(
              mainAxisAlignment: MainAxisAlignment.end,
              children: [
                if (hasEvents && !_allDayExpanded)
                  Container(
                    padding: const EdgeInsets.symmetric(
                      horizontal: 4,
                      vertical: 1,
                    ),
                    decoration: BoxDecoration(
                      color: const Color(0xFF4FC3F7).withOpacity(0.18),
                      borderRadius: BorderRadius.circular(8),
                    ),
                    child: Text(
                      '$totalTasks',
                      style: const TextStyle(
                        fontSize: 8,
                        color: Color(0xFF4FC3F7),
                        fontWeight: FontWeight.w600,
                      ),
                    ),
                  ),
                const SizedBox(width: 2),
                AnimatedRotation(
                  turns: (_allDayExpanded && hasEvents) ? 0.25 : 0.0,
                  duration: const Duration(milliseconds: 180),
                  child: Icon(
                    Icons.chevron_right,
                    size: 14,
                    color: hasEvents
                        ? const Color(0xFF6B7080)
                        : const Color(0xFF3A3F48),
                  ),
                ),
              ],
            ),
          ),
        ),
        // Content area: tasks (only visible when expanded)
        Expanded(
          child: ClipRect(
            child: _allDayExpanded && hasEvents
                ? Transform.translate(
                    offset: Offset(_ox, 0),
                    child: Row(
                      mainAxisSize: MainAxisSize.min,
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: List.generate(visibleDays, (c) {
                        final colTasks = byCol[c] ?? [];
                        // Bound each column to the strip's actual available
                        // height so it can scroll instead of being clipped
                        // when cards (combined) need more room than that —
                        // e.g. after the strip was manually shrunk, or a
                        // card was dragged taller than the auto-fit height.
                        final double colAreaH = (stripH - 6).clamp(
                          0.0,
                          4000.0,
                        );
                        return SizedBox(
                          width: cw,
                          height: colAreaH,
                          child: SingleChildScrollView(
                            padding: const EdgeInsets.fromLTRB(2, 3, 2, 3),
                            child: Column(
                              crossAxisAlignment: CrossAxisAlignment.start,
                              mainAxisSize: MainAxisSize.min,
                              children: colTasks.take(4).map((t) {
                                final pillColor = _pillColorByProject
                                    ? (widget.projectColors[t.projectId] ??
                                          t.status.color)
                                    : t.status.color;
                                final projName =
                                    widget.projects[t.projectId]?.title;
                                final cardH = _allDayCardHeight(t, cw);
                                final isCardCollapsed =
                                    _allDayCardCollapsed.contains(t.id);
                                final isCardHovered =
                                    _hoveredScheduleTaskId == t.id;
                                return MouseRegion(
                                  onEnter: (_) => setState(
                                    () => _hoveredScheduleTaskId = t.id,
                                  ),
                                  onExit: (_) => setState(() {
                                    if (_hoveredScheduleTaskId == t.id) {
                                      _hoveredScheduleTaskId = null;
                                    }
                                  }),
                                  child: GestureDetector(
                                    onSecondaryTapDown: (d) =>
                                        widget.onContextMenu
                                            ?.call(t, d.globalPosition),
                                    child: Container(
                                      height: cardH,
                                      margin: const EdgeInsets.only(bottom: 2),
                                      child: Stack(
                                        clipBehavior: Clip.none,
                                        children: [
                                          _ScheduleCardContent(
                                            task: t,
                                            screenH: cardH,
                                            scale: 1.0,
                                            isActive: false,
                                            isHovered: false,
                                            pillColor: pillColor,
                                            projectName: projName,
                                            hideLabels: _hideCardLabels,
                                          ),
                                          // Per-card expand/retract toggle.
                                          Positioned(
                                            top: 1,
                                            right: 1,
                                            child: IgnorePointer(
                                              ignoring: !(isCardHovered ||
                                                  isCardCollapsed),
                                              child: AnimatedOpacity(
                                                opacity: isCardHovered
                                                    ? 1.0
                                                    : (isCardCollapsed
                                                          ? 0.55
                                                          : 0.0),
                                                duration: const Duration(
                                                  milliseconds: 120,
                                                ),
                                                child: GestureDetector(
                                                  behavior:
                                                      HitTestBehavior.opaque,
                                                  onTap: () => setState(() {
                                                    if (isCardCollapsed) {
                                                      _allDayCardCollapsed
                                                          .remove(t.id);
                                                    } else {
                                                      _allDayCardCollapsed
                                                          .add(t.id);
                                                      // Compact view has no
                                                      // use for a manual
                                                      // height override.
                                                      _allDayCardManualHeight
                                                          .remove(t.id);
                                                    }
                                                  }),
                                                  child: Container(
                                                    width: 14,
                                                    height: 14,
                                                    decoration: BoxDecoration(
                                                      color: Colors.black
                                                          .withOpacity(0.4),
                                                      borderRadius:
                                                          BorderRadius.circular(
                                                        3,
                                                      ),
                                                    ),
                                                    child: Icon(
                                                      isCardCollapsed
                                                          ? Icons.unfold_more
                                                          : Icons.unfold_less,
                                                      size: 10,
                                                      color: Colors.white70,
                                                    ),
                                                  ),
                                                ),
                                              ),
                                            ),
                                          ),
                                          // Per-card vertical resize handle —
                                          // lets the card grow taller (e.g.
                                          // to occupy space freed up by
                                          // dragging the strip itself bigger)
                                          // instead of being stuck at the
                                          // auto-fit "readable" height.
                                          if (!isCardCollapsed)
                                            Positioned(
                                              left: 0,
                                              right: 0,
                                              bottom: -3,
                                              height: 8,
                                              child: IgnorePointer(
                                                ignoring: !isCardHovered,
                                                child: MouseRegion(
                                                  cursor: SystemMouseCursors
                                                      .resizeRow,
                                                  child: GestureDetector(
                                                    behavior: HitTestBehavior
                                                        .opaque,
                                                    onVerticalDragUpdate:
                                                        (d) => setState(() {
                                                      final base =
                                                          _allDayCardManualHeight[
                                                                  t.id] ??
                                                              cardH;
                                                      _allDayCardManualHeight[
                                                              t.id] =
                                                          (base + d.delta.dy)
                                                              .clamp(
                                                        _allDayCardMinH,
                                                        _allDayCardManualMaxH,
                                                      );
                                                    }),
                                                    child: AnimatedOpacity(
                                                      opacity: isCardHovered
                                                          ? 1.0
                                                          : 0.0,
                                                      duration: const Duration(
                                                        milliseconds: 120,
                                                      ),
                                                      child: Center(
                                                        child: Container(
                                                          width: 24,
                                                          height: 3,
                                                          decoration:
                                                              BoxDecoration(
                                                            color: Colors
                                                                .white
                                                                .withOpacity(
                                                              0.5,
                                                            ),
                                                            borderRadius:
                                                                BorderRadius
                                                                    .circular(
                                                              2,
                                                            ),
                                                          ),
                                                        ),
                                                      ),
                                                    ),
                                                  ),
                                                ),
                                              ),
                                            ),
                                        ],
                                      ),
                                    ),
                                  ),
                                );
                              }).toList(),
                            ),
                          ),
                        );
                      }),
                    ),
                  )
                : const SizedBox.shrink(),
          ),
        ),
      ],
    );

    return Stack(
      clipBehavior: Clip.none,
      children: [
        // Main strip body
        AnimatedContainer(
          duration: const Duration(milliseconds: 180),
          curve: Curves.easeInOut,
          height: stripH,
          decoration: const BoxDecoration(
            color: Color(0xFF181A1C),
            border: Border(
              bottom: BorderSide(color: Color(0xFF2C2F32), width: 0.5),
            ),
          ),
          child: contentRow,
        ),
        // Resize dragger — only when expanded
        if (_allDayExpanded && hasEvents)
          Positioned(
            left: 0,
            right: 0,
            top: stripH - draggerH / 2,
            height: draggerH + 8, // extra hit area
            child: MouseRegion(
              cursor: SystemMouseCursors.resizeRow,
              child: GestureDetector(
                behavior: HitTestBehavior.opaque,
                onVerticalDragUpdate: (d) {
                  setState(() {
                    final current =
                        _allDayStripUserHeight ?? activeH;
                    _allDayStripUserHeight =
                        (current + d.delta.dy).clamp(collapsedH, 400.0);
                  });
                },
                child: Center(
                  child: Container(
                    width: 36,
                    height: 3,
                    decoration: BoxDecoration(
                      color: const Color(0xFF4B5260),
                      borderRadius: BorderRadius.circular(2),
                    ),
                  ),
                ),
              ),
            ),
          ),
      ],
    );
  }

  // ── Header ─────────────────────────────────────────────────────────────────
  Widget _buildHeader(
    List<DateTime> days,
    DateTime today,
    int visibleDays,
    double cw,
  ) {
    const names = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'];
    const monthNames = [
      '',
      'Jan',
      'Feb',
      'Mar',
      'Apr',
      'May',
      'Jun',
      'Jul',
      'Aug',
      'Sep',
      'Oct',
      'Nov',
      'Dec',
    ];
    final bool showDayName = cw > 44;
    final bool showDay = cw > 14;
    final bool showDot = cw > 30;
    final double fontSize = (cw * 0.38).clamp(6.0, 13.0);
    final double nameFontSize = (cw * 0.30).clamp(5.0, 11.0);

    // Two-row mode: range spans two months AND horizontal zoom <= 25 %
    final bool twoRow =
        _hScale <= 0.25 &&
        days.isNotEmpty &&
        days.first.month != days.last.month;
    const double monthRowH = 16.0;
    const double dayRowH = _hdrH - monthRowH;

    return Container(
      height: _hdrH,
      decoration: const BoxDecoration(
        color: Color(0xFF1A1C1E),
        border: Border(
          bottom: BorderSide(color: Color(0xFF2C2F32), width: 0.5),
        ),
      ),
      child: Row(
        children: [
          SizedBox(width: _tCW),
          Expanded(
            child: ClipRect(
              child: Transform.translate(
                offset: Offset(_ox, 0),
                child: twoRow
                    // ── Two-row layout ─────────────────────────────────
                    ? Column(
                        mainAxisSize: MainAxisSize.min,
                        crossAxisAlignment: CrossAxisAlignment.start,
                        children: [
                          // Top row: month label at start of each new month
                          SizedBox(
                            height: monthRowH,
                            child: Row(
                              mainAxisSize: MainAxisSize.min,
                              children: List.generate(visibleDays, (i) {
                                final d = days[i];
                                final showMonth = i == 0 || d.day == 1;
                                final monthLabel = cw < 14
                                    ? '${d.month}'
                                    : monthNames[d.month];
                                return SizedBox(
                                  width: cw,
                                  child: showMonth
                                      ? Padding(
                                          padding: const EdgeInsets.only(
                                            left: 4,
                                          ),
                                          child: Text(
                                            monthLabel,
                                            overflow: TextOverflow.clip,
                                            style: TextStyle(
                                              fontSize: (cw * 0.32).clamp(
                                                6.0,
                                                11.0,
                                              ),
                                              fontWeight: FontWeight.w600,
                                              color:
                                                  d.month ==
                                                      DateTime.now().month
                                                  ? const Color(0xFF4FC3F7)
                                                  : Colors.white54,
                                            ),
                                          ),
                                        )
                                      : const SizedBox.shrink(),
                                );
                              }),
                            ),
                          ),
                          // Bottom row: day numbers
                          Expanded(
                            child: Row(
                              mainAxisSize: MainAxisSize.min,
                              children: List.generate(visibleDays, (i) {
                                final d = days[i];
                                final isToday = d == today;
                                return SizedBox(
                                  width: cw,
                                  child: Container(
                                    decoration: BoxDecoration(
                                      color: isToday
                                          ? const Color(
                                              0xFF4FC3F7,
                                            ).withOpacity(0.05)
                                          : Colors.transparent,
                                      border: const Border(
                                        left: BorderSide(
                                          color: Color(0xFF2A2D30),
                                          width: 0.5,
                                        ),
                                      ),
                                    ),
                                    child: Center(
                                      child: cw < 6
                                          ? const SizedBox.shrink()
                                          : Row(
                                              mainAxisSize: MainAxisSize.min,
                                              children: [
                                                if (isToday && showDot)
                                                  Container(
                                                    width: (cw * 0.12).clamp(
                                                      3.0,
                                                      5.0,
                                                    ),
                                                    height: (cw * 0.12).clamp(
                                                      3.0,
                                                      5.0,
                                                    ),
                                                    margin:
                                                        const EdgeInsets.only(
                                                          right: 3,
                                                        ),
                                                    decoration:
                                                        const BoxDecoration(
                                                          color: Color(
                                                            0xFF4FC3F7,
                                                          ),
                                                          shape:
                                                              BoxShape.circle,
                                                        ),
                                                  ),
                                                if (showDay)
                                                  Text(
                                                    '${d.day}',
                                                    overflow: TextOverflow.clip,
                                                    style: TextStyle(
                                                      fontSize: (cw * 0.38)
                                                          .clamp(5.0, 11.0),
                                                      fontWeight:
                                                          FontWeight.w700,
                                                      color: isToday
                                                          ? const Color(
                                                              0xFF4FC3F7,
                                                            )
                                                          : Colors.white70,
                                                    ),
                                                  ),
                                              ],
                                            ),
                                    ),
                                  ),
                                );
                              }),
                            ),
                          ),
                        ],
                      )
                    // ── Single-row layout (default) ─────────────────────
                    : Row(
                        mainAxisSize: MainAxisSize.min,
                        children: List.generate(visibleDays, (i) {
                          final d = days[i];
                          final isToday = d == today;
                          final name = names[d.weekday - 1];
                          return SizedBox(
                            width: cw,
                            child: Container(
                              decoration: BoxDecoration(
                                color: isToday
                                    ? const Color(0xFF4FC3F7).withOpacity(0.05)
                                    : Colors.transparent,
                                border: const Border(
                                  left: BorderSide(
                                    color: Color(0xFF2A2D30),
                                    width: 0.5,
                                  ),
                                ),
                              ),
                              child: Center(
                                child: cw < 6
                                    ? const SizedBox.shrink()
                                    : Row(
                                        mainAxisSize: MainAxisSize.min,
                                        children: [
                                          if (isToday && showDot)
                                            Container(
                                              width: (cw * 0.12).clamp(
                                                3.0,
                                                6.0,
                                              ),
                                              height: (cw * 0.12).clamp(
                                                3.0,
                                                6.0,
                                              ),
                                              margin: EdgeInsets.only(
                                                right: showDayName ? 5.0 : 3.0,
                                              ),
                                              decoration: const BoxDecoration(
                                                color: Color(0xFF4FC3F7),
                                                shape: BoxShape.circle,
                                              ),
                                            ),
                                          if (showDay)
                                            RichText(
                                              overflow: TextOverflow.clip,
                                              text: TextSpan(
                                                children: [
                                                  TextSpan(
                                                    text: showDayName
                                                        ? '${d.day} '
                                                        : '${d.day}',
                                                    style: TextStyle(
                                                      fontSize: fontSize,
                                                      fontWeight:
                                                          FontWeight.w700,
                                                      color: isToday
                                                          ? const Color(
                                                              0xFF4FC3F7,
                                                            )
                                                          : Colors.white70,
                                                    ),
                                                  ),
                                                  if (showDayName)
                                                    TextSpan(
                                                      text: name,
                                                      style: TextStyle(
                                                        fontSize: nameFontSize,
                                                        color: isToday
                                                            ? const Color(
                                                                0xFF4FC3F7,
                                                              ).withOpacity(0.8)
                                                            : Colors.white38,
                                                      ),
                                                    ),
                                                ],
                                              ),
                                            ),
                                        ],
                                      ),
                              ),
                            ),
                          );
                        }),
                      ),
              ),
            ),
          ),
        ],
      ),
    );
  }

  // ── Hover hint ─────────────────────────────────────────────────────────────
  Widget _buildHint(int col, double wY, double cw) {
    final hourH = _bHH * _vScale;

    // Match the height to exactly one grid subdivision at the current zoom
    final double slotH;
    if (hourH >= 80) {
      slotH = hourH / 12; // 5-min slot
    } else if (hourH >= 40) {
      slotH = hourH / 4; // 15-min slot
    } else {
      slotH = hourH / 2; // 30-min slot
    }

    final sx = _sx(col, cw) + 3;
    final sy = _sy(wY);
    final w = (cw - 6).clamp(20.0, double.infinity);
    final totalMin = ((wY / _bHH) * 60).round().clamp(0, 23 * 60 + 55);
    final h = totalMin ~/ 60;
    final m = totalMin % 60;

    return Positioned(
      left: sx,
      top: sy,
      width: w,
      height: slotH,
      child: IgnorePointer(
        child: Container(
          decoration: BoxDecoration(
            color: const Color(0xFF4FC3F7).withOpacity(0.10),
            borderRadius: BorderRadius.circular(3),
            border: Border.all(
              color: const Color(0xFF4FC3F7).withOpacity(0.40),
              width: 0.8,
            ),
          ),
          child: slotH >= 14
              ? Padding(
                  padding: const EdgeInsets.symmetric(horizontal: 5),
                  child: Row(
                    children: [
                      if (slotH >= 16)
                        Expanded(
                          child: Text(
                            _fmt12h(h, m),
                            style: const TextStyle(
                              fontSize: 9,
                              color: Color(0xFF4FC3F7),
                              fontWeight: FontWeight.w600,
                            ),
                            overflow: TextOverflow.clip,
                            softWrap: false,
                          ),
                        ),
                      const Icon(Icons.add, size: 11, color: Color(0xFF4FC3F7)),
                    ],
                  ),
                )
              : const SizedBox.shrink(),
        ),
      ),
    );
  }

  // ── Now line ───────────────────────────────────────────────────────────────
  List<Widget> _buildNowLine(DateTime now, int todayCol) {
    final nowWY = (now.hour + now.minute / 60.0) * _bHH;
    final sy = _sy(nowWY);
    if (sy < 0 || sy > _scrollH) return [];
    return [
      Positioned(
        top: sy,
        left: _tCW - 5,
        right: 0,
        child: Row(
          children: [
            Container(
              width: 10,
              height: 10,
              decoration: const BoxDecoration(
                color: Color(0xFFEF5350),
                shape: BoxShape.circle,
              ),
            ),
            Expanded(
              child: Container(height: 1.5, color: const Color(0xFFEF5350)),
            ),
          ],
        ),
      ),
    ];
  }

  // ── Task card ──────────────────────────────────────────────────────────────
  // ── _buildOverlapCards ───────────────────────────────────────────────────
  // Computes the overlap layout for all timed tasks and returns the card
  // widgets ready to be spread into the canvas Stack's children list.
  //
  // Midnight overflow: if a task starts on day N and extends past 00:00, its
  // card is clipped at midnight in column N and a "continuation" card is
  // rendered in column N+1 starting at 00:00, showing the remaining duration.
  List<Widget> _buildOverlapCards(
    List<Task> allTasks,
    Map<String, int> taskCol,
    double cw, {
    double opacity = 1.0,
  }) {
    // Group timed tasks by day column.
    final Map<int, List<Task>> byCol = {};
    for (final t in allTasks) {
      final c = taskCol[t.id];
      if (c == null) continue;
      byCol.putIfAbsent(c, () => []).add(t);
    }

    // Run the overlap layout algorithm for each column.
    final Map<String, _SubColLayout> overlapLayout = {};
    for (final entry in byCol.entries) {
      overlapLayout.addAll(_computeOverlapLayout(entry.value, cw));
    }

    final List<Widget> result = [];

    for (final t in allTasks) {
      final col = taskCol[t.id];
      if (col == null) continue;

      final due = t.scheduledDateTime;
      if (due == null) continue;

      final double startHours = due.hour + due.minute / 60.0;
      final double durationHours = t.durationMinutes.clamp(5, 24 * 60) / 60.0;
      final bool overflowsMidnight = startHours + durationHours > 24.0;

      // Primary card (on the task's own day).
      result.add(_buildCard(
        t,
        col,
        cw,
        opacity: opacity,
        subColLayout: overlapLayout[t.id],
        dayTasks: byCol[col],
        clipAtMidnight: overflowsMidnight,
      ));

      // Continuation card on the next day column (if it exists in the view).
      if (overflowsMidnight) {
        final int nextCol = col + 1;
        // Only render if the next column is visible in the current day range.
        if (nextCol < _visibleDays) {
          result.add(_buildCard(
            t,
            nextCol,
            cw,
            opacity: opacity,
            subColLayout: overlapLayout[t.id],
            dayTasks: byCol[nextCol],
            isContinuation: true,
          ));
        }
      }
    }

    return result;
  }

  // ── Overlap layout ────────────────────────────────────────────────────────
  // Computed once per build for all timed tasks in a day column.
  // Returns, for each taskId, the screen-relative left offset and width
  // *within* the day column (i.e. values in [0, cw)).
  //
  // Algorithm:
  //   1. Group tasks in the column by overlapping time intervals.
  //   2. Within each overlap group sort by _subColOverrides (user-assigned
  //      sub-column index) then by task id (stable, creation-time order).
  //   3. Give each task an equal slice of cw unless _subColWidthFracs
  //      provides a manual width for that task.  Fractions are normalised
  //      so the slices always fill cw.
  Map<String, _SubColLayout> _computeOverlapLayout(
    List<Task> dayTasks,
    double cw,
  ) {
    final result = <String, _SubColLayout>{};
    if (dayTasks.isEmpty) return result;

    // Sort by start time so the sweep works correctly.
    final sorted = List<Task>.from(dayTasks)
      ..sort((a, b) {
        final da = a.scheduledDateTime!;
        final db = b.scheduledDateTime!;
        return da.compareTo(db);
      });

    // Build overlap groups: a group is a maximal set of tasks where every
    // task overlaps with at least one other task in the set.
    final List<List<Task>> groups = [];
    final Set<String> assigned = {};

    for (final task in sorted) {
      if (assigned.contains(task.id)) continue;
      final group = <Task>[task];
      assigned.add(task.id);

      DateTime groupEnd = task.scheduledDateTime!
          .add(Duration(minutes: task.durationMinutes.clamp(5, 24 * 60)));

      // Keep expanding the group until no more overlapping tasks are found.
      bool changed = true;
      while (changed) {
        changed = false;
        for (final other in sorted) {
          if (assigned.contains(other.id)) continue;
          final otherStart = other.scheduledDateTime!;
          if (otherStart.isBefore(groupEnd)) {
            group.add(other);
            assigned.add(other.id);
            final otherEnd = otherStart.add(
                Duration(minutes: other.durationMinutes.clamp(5, 24 * 60)));
            if (otherEnd.isAfter(groupEnd)) groupEnd = otherEnd;
            changed = true;
          }
        }
      }
      groups.add(group);
    }

    // Lay out each group.
    for (final group in groups) {
      final n = group.length;
      if (n == 1) {
        // No overlap – full width.
        result[group.first.id] = _SubColLayout(left: 0, width: cw);
        continue;
      }

      // Sort within the group by user override index, then by task id.
      group.sort((a, b) {
        final ia = _subColOverrides[a.id] ?? 999999;
        final ib = _subColOverrides[b.id] ?? 999999;
        if (ia != ib) return ia.compareTo(ib);
        return a.id.compareTo(b.id); // stable creation-time order
      });

      // Compute widths.  Start with equal slices, then apply manual overrides.
      // Manual fracs are clamped so any single card is at least 15% of cw and
      // at most 85% of cw.  The remaining space is distributed equally among
      // the non-overridden tasks.
      final double minFrac = 0.15;
      final double maxFrac = 0.85;

      // Collect manual fracs (only for tasks in THIS group).
      final manualFracs = <int, double>{};  // index in group → frac
      double manualSum = 0.0;
      int manualCount = 0;
      for (int i = 0; i < n; i++) {
        final f = _subColWidthFracs[group[i].id];
        if (f != null) {
          final clamped = f.clamp(minFrac, maxFrac);
          manualFracs[i] = clamped;
          manualSum += clamped;
          manualCount++;
        }
      }

      // If manual fracs exceed 1.0, normalise them proportionally.
      if (manualSum > 1.0) {
        for (final k in manualFracs.keys.toList()) {
          manualFracs[k] = manualFracs[k]! / manualSum;
        }
        manualSum = 1.0;
      }

      // Distribute remaining space equally among non-overridden tasks.
      final autoCount = n - manualCount;
      final autoFrac = autoCount > 0
          ? ((1.0 - manualSum) / autoCount).clamp(minFrac, 1.0)
          : 0.0;

      // Build final fracs and compute left offsets.
      double left = 0;
      for (int i = 0; i < n; i++) {
        final frac = manualFracs[i] ?? autoFrac;
        final w = frac * cw;
        result[group[i].id] = _SubColLayout(left: left, width: w);
        left += w;
      }
    }

    return result;
  }

  // ── Swap helper ──────────────────────────────────────────────────────────
  // Called at drag-end when a task was dragged *within the same day column*.
  // If the task's new centre-X lands inside another task's sub-column,
  // the two tasks exchange their _subColOverrides indices.
  void _applySubColSwap(
    String draggedId,
    List<Task> dayTasks,
    double cw,
    double dragCentreX,   // screen-relative X within the day column
  ) {
    final layout = _computeOverlapLayout(dayTasks, cw);
    final myLayout = layout[draggedId];
    if (myLayout == null) return;

    // Find which other sub-column the drag centre landed in.
    String? targetId;
    for (final entry in layout.entries) {
      if (entry.key == draggedId) continue;
      final l = entry.value;
      if (dragCentreX >= l.left && dragCentreX < l.left + l.width) {
        targetId = entry.key;
        break;
      }
    }
    if (targetId == null) return;

    // Resolve current sub-column indices (default = position in sorted group).
    final sortedIds = layout.keys.toList(); // already in sub-col order
    final myIdx = _subColOverrides[draggedId] ?? sortedIds.indexOf(draggedId);
    final tgtIdx = _subColOverrides[targetId] ?? sortedIds.indexOf(targetId);

    setState(() {
      _subColOverrides[draggedId] = tgtIdx;
      _subColOverrides[targetId!] = myIdx;
    });
  }

  Widget _buildCard(
    Task t,
    int origCol,
    double cw, {
    double opacity = 1.0,
    _SubColLayout? subColLayout,
    List<Task>? dayTasks,  // all timed tasks on the same day, for swap detection
    bool clipAtMidnight = false,   // true → cap height at midnight boundary
    bool isContinuation = false,   // true → render as overflow tail in next col
  }) {
    final due = t.scheduledDateTime;
    if (due == null)
      return const Positioned(top: 0, left: 0, child: SizedBox.shrink());
    final isDragging = _dragId == t.id;
    final isResizing = _resizeId == t.id;
    final isHResizing = _hResizeId == t.id;
    final hasOverlap = subColLayout != null && (dayTasks?.length ?? 0) > 1;

    final int curCol = isDragging ? _dragCurCol : origCol;
    final double worldYRaw = isDragging
        ? _dragCurWY
        : (due.hour + due.minute / 60.0) * _bHH;
    final double worldHRaw = isResizing
        ? _resizeCurH
        : (t.durationMinutes.clamp(5, 24 * 60) / 60.0) * _bHH;

    // ── Midnight overflow clamping ────────────────────────────────────────────
    // clipAtMidnight:  the card starts on day N; clip it so it ends at 24:00.
    // isContinuation:  the card is the overflow tail on day N+1; start at 0 and
    //                  show the portion that spills past midnight.
    const double kMidnight = 24.0 * _bHH; // world-Y of midnight
    final double worldY;
    final double worldH;
    if (isContinuation) {
      // Spillover portion: how far past midnight does the task reach?
      final double taskEndRaw = worldYRaw + worldHRaw;
      final double spillH = taskEndRaw - kMidnight;
      worldY = 0;
      worldH = spillH.clamp(5.0 / 60.0 * _bHH, kMidnight);
    } else if (clipAtMidnight) {
      worldY = worldYRaw;
      worldH = (kMidnight - worldYRaw).clamp(5.0 / 60.0 * _bHH, kMidnight);
    } else {
      worldY = worldYRaw;
      worldH = worldHRaw;
    }

    // ── Horizontal position/width using subcol layout ────────────────────────
    // When dragging to a different day column the subcol layout no longer
    // applies – fall back to full-column width so the dragged card looks normal.
    final bool useSubcol = hasOverlap && !isDragging;
    final double subLeft  = useSubcol ? subColLayout!.left  : 0;
    final double subWidth = useSubcol
        ? (isHResizing ? _hResizeCurFrac * cw : subColLayout!.width)
        : cw;

    final double gutter = cw >= 12 ? 3.0 : (cw * 0.25).floorToDouble();
    final sx = _sx(curCol, cw) + subLeft + gutter;
    final sy = _sy(worldY);
    final sw = (subWidth - gutter * 2).clamp(1.0, double.infinity);
    final sh = (worldH * _vScale).clamp(6.0, double.infinity);

    // ── Bug fix: viewport height for culling ─────────────────────────────────
    final double viewH = _scrollH > 0
        ? _scrollH
        : (_canvasH > 0 ? _canvasH : double.infinity);

    if (kDebugPlanner) {
      // ignore: avoid_print
      print(
        '[Planner] id=${t.id} plannedAt=${t.plannedAt} '
        'scheduledDateTime=$due worldY=$worldY sy=$sy sh=$sh '
        'durationMinutes=${t.durationMinutes} viewH=$viewH '
        '_scrollH=$_scrollH _canvasH=$_canvasH',
      );
    }

    if (sx + sw < _tCW || sx > _canvasW || sy + sh < 0 || sy > viewH) {
      return const Positioned(top: 0, left: 0, child: SizedBox.shrink());
    }

    // Width of the horizontal-resize handle (right edge of the card).
    // Only shown when the card is part of an overlap group.
    const double _hHandleW = 8.0;

    return Positioned(
      left: sx,
      top: sy,
      width: sw,
      height: sh,
      child: GestureDetector(
        // Feature 8: right-click opens the standard task context menu
        onSecondaryTapDown: (d) =>
            widget.onContextMenu?.call(t, d.globalPosition),
        child: MouseRegion(
          onEnter: (_) => setState(() => _hoveredScheduleTaskId = t.id),
          onExit: (_) => setState(() {
            if (_hoveredScheduleTaskId == t.id) _hoveredScheduleTaskId = null;
          }),
          child: Listener(
          behavior: HitTestBehavior.opaque,
          onPointerDown: (e) {
            final lx = e.localPosition.dx;
            final ly = e.localPosition.dy;

            // ── Horizontal resize handle (right edge, only in overlap) ───────
            if (hasOverlap && lx > sw - _hHandleW) {
              setState(() {
                _hResizeId = t.id;
                _hResizeOrigFrac = subColLayout!.width / cw;
                _hResizeCurFrac  = _hResizeOrigFrac;
                _hResizePtrOrigin = e.position;
              });
              return;
            }

            // ── Vertical resize handle (bottom edge) ─────────────────────────
            if (ly > sh - 12) {
              setState(() {
                _resizeId = t.id;
                // For continuation cards the visible height is only the
                // spillover portion; use the full task duration (worldHRaw)
                // so the resize commits the correct total duration.
                _resizeOrigH = worldHRaw;
                _resizeCurH = worldHRaw;
                _resizePtrOrigin = e.position;
              });
              return;
            }

            // ── Normal drag ───────────────────────────────────────────────────
            // For continuation cards origCol is the *next* day column and
            // worldY is 0 (the card starts at midnight in that column).
            // We must anchor the drag to the task's real column and real
            // world-Y so that a drop-without-move keeps the task unchanged.
            final int dragStartCol = isContinuation ? origCol - 1 : origCol;
            final double dragStartWY = isContinuation ? worldYRaw : worldY;
            setState(() {
              _dragId = t.id;
              _dragOrigCol = dragStartCol;
              _dragCurCol = dragStartCol;
              _dragOrigWY = dragStartWY;
              _dragCurWY = dragStartWY;
              _dragPtrOrigin = e.position;
              _dragPointerScheduleX =
                  _sx(dragStartCol, cw) + subLeft + gutter + e.localPosition.dx;
            });
          },
          onPointerMove: (e) {
            if (_dragId == t.id) {
              final gd = e.position - _dragPtrOrigin;
              final rawWY = _dragOrigWY + gd.dy / _vScale;
              final cursorScheduleX = _dragPointerScheduleX + gd.dx;
              final newCol =
                  _colFromSX(cursorScheduleX, cw).clamp(0, _visibleDays - 1);
              setState(() {
                _dragCurWY = _snapWY(rawWY);
                _dragCurCol = newCol;
              });
            } else if (_resizeId == t.id) {
              final gd = e.position - _resizePtrOrigin;
              setState(() {
                _resizeCurH = _snapWH(_resizeOrigH + gd.dy / _vScale);
              });
            } else if (_hResizeId == t.id) {
              final gd = e.position - _hResizePtrOrigin;
              final newFrac = (_hResizeOrigFrac + gd.dx / cw).clamp(0.15, 0.85);
              setState(() {
                _hResizeCurFrac = newFrac;
              });
            }
          },
          onPointerUp: (e) {
            if (_dragId == t.id) {
              final slot = _slotFromWorld(_dragCurCol, _dragCurWY);
              t.dueDay = slot.toIso8601String().split('T').first;
              t.plannedAt = slot.millisecondsSinceEpoch;
              widget.onTaskUpdated(t);

              // If the drag stayed in the same day column, check for subcol swap.
              if (_dragCurCol == origCol && hasOverlap && dayTasks != null) {
                // The cursor's X relative to the day column left edge.
                final dragGlobalX = e.position.dx;
                final dayColScreenLeft = _sx(origCol, cw);
                final cursorInCol = dragGlobalX - dayColScreenLeft;
                _applySubColSwap(t.id, dayTasks, cw, cursorInCol);
              }

              setState(() { _dragId = null; });
            } else if (_resizeId == t.id) {
              t.durationMinutes = (_resizeCurH / _bHH * 60).round().clamp(
                5, 24 * 60,
              );
              widget.onTaskUpdated(t);
              setState(() { _resizeId = null; });
            } else if (_hResizeId == t.id) {
              // Commit the width fraction override.
              setState(() {
                _subColWidthFracs[t.id] = _hResizeCurFrac;
                _hResizeId = null;
              });
            }
          },
          onPointerCancel: (_) => setState(() {
            _dragId = null;
            _resizeId = null;
            _hResizeId = null;
          }),
          child: Builder(
            builder: (_) {
              final pillColor = _pillColorByProject
                  ? (widget.projectColors[t.projectId] ?? t.status.color)
                  : t.status.color;
              final projName = widget.projects[t.projectId]?.title;

              Widget cardContent = _ScheduleCardContent(
                task: t,
                screenH: sh,
                scale: _vScale,
                isActive: isDragging || isResizing || isHResizing,
                isHovered: _hoveredScheduleTaskId == t.id,
                pillColor: pillColor,
                projectName: projName,
                hideLabels: _hideCardLabels,
              );

              // ── Midnight overflow visual indicators ───────────────────────
              // clipAtMidnight: show a dashed bottom edge so the user sees the
              // task continues into the next day.
              // isContinuation: show a dashed top edge + a small "↩" pill to
              // signal this is the carry-over portion from the previous day.
              if (clipAtMidnight || isContinuation) {
                final Color borderColor = pillColor.withOpacity(0.65);
                cardContent = Stack(
                  clipBehavior: Clip.none,
                  children: [
                    cardContent,
                    if (clipAtMidnight)
                      Positioned(
                        bottom: 0,
                        left: 0,
                        right: 0,
                        child: CustomPaint(
                          size: const Size(double.infinity, 3),
                          painter: _DashedLinePainter(color: borderColor),
                        ),
                      ),
                    if (isContinuation)
                      Positioned(
                        top: 0,
                        left: 0,
                        right: 0,
                        child: Column(
                          mainAxisSize: MainAxisSize.min,
                          crossAxisAlignment: CrossAxisAlignment.start,
                          children: [
                            CustomPaint(
                              size: const Size(double.infinity, 3),
                              painter: _DashedLinePainter(color: borderColor),
                            ),
                            if (sh >= 18)
                              Padding(
                                padding: const EdgeInsets.only(left: 5, top: 2),
                                child: Container(
                                  padding: const EdgeInsets.symmetric(
                                    horizontal: 4,
                                    vertical: 1,
                                  ),
                                  decoration: BoxDecoration(
                                    color: pillColor.withOpacity(0.25),
                                    borderRadius: BorderRadius.circular(3),
                                  ),
                                  child: Text(
                                    '↩ cont.',
                                    style: TextStyle(
                                      fontSize: 9,
                                      color: pillColor.withOpacity(0.9),
                                      fontWeight: FontWeight.w600,
                                      height: 1.1,
                                    ),
                                  ),
                                ),
                              ),
                          ],
                        ),
                      ),
                  ],
                );
              }

              // Overlay the horizontal resize handle when in overlap.
              if (hasOverlap) {
                cardContent = Stack(
                  children: [
                    cardContent,
                    // Right-edge h-resize handle strip.
                    Positioned(
                      right: 0,
                      top: 0,
                      bottom: 0,
                      width: _hHandleW,
                      child: AnimatedOpacity(
                        opacity: (_hoveredScheduleTaskId == t.id || isHResizing) ? 1.0 : 0.0,
                        duration: const Duration(milliseconds: 150),
                        child: MouseRegion(
                          cursor: SystemMouseCursors.resizeLeftRight,
                          child: Container(
                            decoration: BoxDecoration(
                              color: isHResizing
                                  ? pillColor.withOpacity(0.35)
                                  : pillColor.withOpacity(0.12),
                              borderRadius: const BorderRadius.only(
                                topRight: Radius.circular(5),
                                bottomRight: Radius.circular(5),
                              ),
                            ),
                            child: Center(
                              child: Container(
                                width: 2,
                                height: sh > 20 ? 18.0 : sh * 0.6,
                                decoration: BoxDecoration(
                                  color: pillColor.withOpacity(0.55),
                                  borderRadius: BorderRadius.circular(1),
                                ),
                              ),
                            ),
                          ),
                        ),
                      ),
                    ),
                  ],
                );
              }

              return opacity < 1.0
                  ? Opacity(opacity: opacity, child: cardContent)
                  : cardContent;
            },
          ),
        ), // closes Listener
      ), // closes MouseRegion (hover tracking)
    ), // closes GestureDetector (Feature 8 right-click)
    );
  }

  // ── Project colour helpers ────────────────────────────────────────────────
  static const List<Color> _palette = [
    Color(0xFF7986CB),
    Color(0xFF4DD0E1),
    Color(0xFFAED581),
    Color(0xFFFFD54F),
    Color(0xFFFF8A65),
    Color(0xFFF06292),
    Color(0xFF4DB6AC),
    Color(0xFF90CAF9),
    Color(0xFFF48FB1),
  ];

  Color _projectColor(String projectId, int idx) =>
      _palette[idx % _palette.length];

  // ── Build work/rest segment bars for a session block (Execution–Detail) ──
  List<_SegBlock> _buildSessionSegs(
    _ExecutionSession session,
    Color taskColor,
  ) {
    final blocks = session.blocksSnapshot;
    if (blocks.isEmpty) return [];
    final totalMs = blocks.fold<int>(0, (s, b) => s + b.minutes) * 60000;
    if (totalMs == 0) return [];
    final durMs = session.duration.inMilliseconds;
    final segs = <_SegBlock>[];
    int remaining = durMs;
    for (final b in blocks) {
      if (remaining <= 0) break;
      final blockMs = b.minutes * 60000;
      final covered = remaining >= blockMs ? blockMs : remaining;
      segs.add(
        _SegBlock(
          frac: covered / durMs,
          color: b.type == _StagingType.work
              ? const Color(0xFF4FC3F7).withOpacity(0.65)
              : const Color(0xFF81C784).withOpacity(0.5),
          label: b.type == _StagingType.work ? 'W' : 'R',
        ),
      );
      remaining -= covered;
    }
    return segs;
  }
}

// ─────────────────────────────────────────────────────────────────────────────
// _SubColLayout – result of the overlap layout algorithm for a single task.
// ─────────────────────────────────────────────────────────────────────────────
class _SubColLayout {
  final double left;   // pixels from the left edge of the day column
  final double width;  // pixels
  const _SubColLayout({required this.left, required this.width});
}

// ─────────────────────────────────────────────────────────────────────────────
// _DashedLinePainter – draws a horizontal dashed line across the full width.
// Used to mark the midnight-overflow boundary on schedule cards.
// ─────────────────────────────────────────────────────────────────────────────
class _DashedLinePainter extends CustomPainter {
  final Color color;
  final double dashWidth;
  final double dashGap;
  final double strokeWidth;

  const _DashedLinePainter({
    required this.color,
    this.dashWidth = 5.0,
    this.dashGap = 3.0,
    this.strokeWidth = 1.5,
  });

  @override
  void paint(Canvas canvas, Size size) {
    final paint = Paint()
      ..color = color
      ..strokeWidth = strokeWidth
      ..style = PaintingStyle.stroke;
    double x = 0;
    final y = size.height / 2;
    while (x < size.width) {
      canvas.drawLine(Offset(x, y), Offset((x + dashWidth).clamp(0, size.width), y), paint);
      x += dashWidth + dashGap;
    }
  }

  @override
  bool shouldRepaint(_DashedLinePainter o) =>
      o.color != color ||
      o.dashWidth != dashWidth ||
      o.dashGap != dashGap ||
      o.strokeWidth != strokeWidth;
}

// ─────────────────────────────────────────────────────────────────────────────
// _ScheduleGridPainter
// ─────────────────────────────────────────────────────────────────────────────

class _ScheduleGridPainter extends CustomPainter {
  final double scale, ox, oy, colW, bHH, tCW, padT, padB;
  final int todayCol;
  final int visibleDays;

  const _ScheduleGridPainter({
    required this.scale,
    required this.ox,
    required this.oy,
    required this.colW,
    required this.bHH,
    required this.tCW,
    required this.padT,
    required this.padB,
    required this.todayCol,
    required this.visibleDays,
  });

  @override
  void paint(Canvas canvas, Size size) {
    final hourH = bHH * scale; // scaled pixel height of one hour
    final dayH = 24 * hourH; // total height of the 24-hour block

    // Origin of hour-0 in screen coords
    final originY = oy + padT;

    // ── Paints ────────────────────────────────────────────────────────────────
    final hourPaint = Paint()
      ..color = const Color(0xFF2E3135)
      ..strokeWidth = 0.6;
    final halfPaint = Paint()
      ..color = const Color(0xFF262A2D)
      ..strokeWidth = 0.5;
    final qtrPaint = Paint()
      ..color = const Color(0xFF222528)
      ..strokeWidth = 0.4;
    final minPaint = Paint()
      ..color = const Color(0xFF1E2124)
      ..strokeWidth = 0.3;
    final colPaint = Paint()
      ..color = const Color(0xFF2A2D30)
      ..strokeWidth = 0.5;
    final padPaint = Paint()..color = const Color(0xFF0E0F10);

    // ── Top pad zone (above 12 AM) ────────────────────────────────────────────
    final topPadBottom = originY.clamp(0.0, size.height);
    if (topPadBottom > 0) {
      canvas.drawRect(
        Rect.fromLTWH(tCW, 0, size.width - tCW, topPadBottom),
        padPaint,
      );
    }

    // ── Bottom pad zone (below 11:55 PM) ──────────────────────────────────────
    final bottomPadTop = (originY + dayH).clamp(0.0, size.height);
    if (bottomPadTop < size.height) {
      canvas.drawRect(
        Rect.fromLTWH(
          tCW,
          bottomPadTop,
          size.width - tCW,
          size.height - bottomPadTop,
        ),
        padPaint,
      );
    }

    // ── Time column background ────────────────────────────────────────────────
    canvas.drawRect(
      Rect.fromLTWH(0, 0, tCW, size.height),
      Paint()..color = const Color(0xFF151718),
    );

    // ── Today column tint ─────────────────────────────────────────────────────
    if (todayCol >= 0) {
      final x = todayCol * colW + ox + tCW;
      canvas.drawRect(
        Rect.fromLTWH(
          x.clamp(tCW, size.width),
          0,
          colW.clamp(0, size.width - tCW),
          size.height,
        ),
        Paint()..color = const Color(0xFF4FC3F7).withOpacity(0.03),
      );
    }

    // ── Sub-hour lines ────────────────────────────────────────────────────────
    final bool show15 = hourH >= 40;
    final bool show5 = hourH >= 80;

    if (show5 || show15) {
      final int steps = show5 ? 12 : 4;
      for (int h = 0; h < 24; h++) {
        for (int s = 1; s < steps; s++) {
          final y = (h + s / steps) * hourH + originY;
          if (y < 0 || y > size.height) continue;
          final bool isHalf = s == steps ~/ 2;
          final Paint p = isHalf ? halfPaint : (show5 ? minPaint : qtrPaint);
          final double indent = isHalf ? tCW + 8 : tCW + 16;
          canvas.drawLine(Offset(indent, y), Offset(size.width, y), p);
        }
      }
    } else {
      for (int h = 0; h < 24; h++) {
        final y2 = (h + 0.5) * hourH + originY;
        if (y2 >= 0 && y2 <= size.height) {
          canvas.drawLine(
            Offset(tCW + 8, y2),
            Offset(size.width, y2),
            halfPaint,
          );
        }
      }
    }

    // ── Hour lines + labels ───────────────────────────────────────────────────
    final labelStyle = TextStyle(
      fontSize: (8 + scale * 1.5).clamp(9.0, 13.0),
      color: const Color(0xFF8A9099),
      fontWeight: FontWeight.w500,
    );

    for (int h = 0; h <= 24; h++) {
      final y = h * hourH + originY;
      if (y < -20 || y > size.height + 1) continue;

      if (y >= 0) {
        canvas.drawLine(Offset(tCW, y), Offset(size.width, y), hourPaint);
      }

      if (h < 24) {
        final label = h == 0 ? '12 AM' : _labelFor(h);
        final tp = TextPainter(
          text: TextSpan(text: label, style: labelStyle),
          textDirection: TextDirection.ltr,
        )..layout(maxWidth: tCW - 6);
        final labelY = y - tp.height * 0.5;
        if (labelY + tp.height >= 0 && labelY <= size.height) {
          tp.paint(canvas, Offset(tCW - tp.width - 5, labelY));
        }
      }
    }

    // ── Column dividers ───────────────────────────────────────────────────────
    for (int c = 0; c <= visibleDays; c++) {
      final x = c * colW + ox + tCW;
      if (x < tCW - 1 || x > size.width + 1) continue;
      canvas.drawLine(Offset(x, 0), Offset(x, size.height), colPaint);
    }

    // ── Time column right border ──────────────────────────────────────────────
    canvas.drawLine(
      Offset(tCW, 0),
      Offset(tCW, size.height),
      Paint()
        ..color = const Color(0xFF2C2F32)
        ..strokeWidth = 0.5,
    );
  }

  String _labelFor(int h) {
    if (h == 12) return '12 PM';
    final period = h < 12 ? 'AM' : 'PM';
    final hh = h > 12 ? h - 12 : h;
    return '$hh $period';
  }

  @override
  bool shouldRepaint(_ScheduleGridPainter o) =>
      o.scale != scale ||
      o.ox != ox ||
      o.oy != oy ||
      o.colW != colW ||
      o.bHH != bHH ||
      o.padT != padT ||
      o.padB != padB ||
      o.todayCol != todayCol ||
      o.visibleDays != visibleDays ||
      o.tCW != tCW;
}

// ─────────────────────────────────────────────────────────────────────────────
// _ScheduleCardContent
// ─────────────────────────────────────────────────────────────────────────────

class _ScheduleCardContent extends StatelessWidget {
  final Task task;
  final double screenH;
  final double scale;
  final bool isActive;
  final bool isHovered;
  final Color? pillColor;
  final String? projectName;
  final bool hideLabels;

  const _ScheduleCardContent({
    Key? key,
    required this.task,
    required this.screenH,
    required this.scale,
    required this.isActive,
    this.isHovered = false,
    this.pillColor,
    this.projectName,
    this.hideLabels = false,
  }) : super(key: key);

  @override
  Widget build(BuildContext context) {
    final color = pillColor ?? task.status.color;
    final isLight = AppTheme.of(context).isLight;
    final minFontSize = 8.0;

    // Features 4 & 5: override border when fill luminance is too dark/light
    final contrastBorder = adaptiveBorder(color, isLight);

    return MouseRegion(
      cursor: SystemMouseCursors.grab,
      child: Container(
        decoration: BoxDecoration(
          color: color.withOpacity(isActive ? 0.32 : 0.18),
          borderRadius: BorderRadius.circular(5),
          border:
              contrastBorder ??
              Border.all(
                color: color.withOpacity(isActive ? 0.85 : 0.5),
                width: isActive ? 1.5 : 1,
              ),
          boxShadow: isActive
              ? [
                  BoxShadow(
                    color: Colors.black.withOpacity(0.35),
                    blurRadius: 10,
                    offset: const Offset(2, 5),
                  ),
                ]
              : null,
        ),
        clipBehavior: Clip.hardEdge,
        child: Stack(
          children: [
            // Content
            Padding(
              padding: EdgeInsets.fromLTRB(5, 3, 4, screenH > 18 ? 14 : 3),
              child: LayoutBuilder(
                builder: (context, constraints) {
                  final availW = constraints.maxWidth;
                  final double iconSize = (10 * scale).clamp(minFontSize, 14);
                  // Only show icon if it fits (icon + 4px gap)
                  final showIcon = screenH > 8 && availW >= iconSize + 4;
                  final showText =
                      screenH > 16 && availW > (showIcon ? iconSize + 4 : 0);
                  final showProject =
                      !hideLabels &&
                      screenH > 28 &&
                      projectName != null &&
                      projectName!.isNotEmpty;
                  if (!showIcon && !showText) return const SizedBox.shrink();
                  return Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    mainAxisSize: MainAxisSize.max,
                    children: [
                      // ── Project name ──────────────────────────────────
                      if (showProject) ...[
                        Text(
                          projectName!,
                          style: TextStyle(
                            fontSize: (9 * scale).clamp(7.0, 10.0),
                            color: color.withOpacity(0.75),
                            fontWeight: FontWeight.w600,
                            letterSpacing: 0.2,
                          ),
                          overflow: TextOverflow.ellipsis,
                          maxLines: 1,
                        ),
                        const SizedBox(height: 1),
                      ],
                      // ── Status icon + title ───────────────────────────
                      Expanded(
                        child: Row(
                          crossAxisAlignment: CrossAxisAlignment.center,
                          children: [
                            if (showIcon) ...[
                              Icon(
                                task.status.icon,
                                size: iconSize,
                                color: color,
                              ),
                              const SizedBox(width: 4),
                            ],
                            if (showText && !hideLabels)
                              Expanded(
                                child: Text(
                                  task.title,
                                  style: TextStyle(
                                    fontSize: (11 * scale).clamp(
                                      minFontSize,
                                      13,
                                    ),
                                    color: Colors.white.withOpacity(0.88),
                                    fontWeight: FontWeight.w500,
                                  ),
                                  overflow: TextOverflow.ellipsis,
                                  maxLines: (screenH / 14).floor().clamp(1, 20),
                                ),
                              ),
                          ],
                        ),
                      ),
                    ],
                  );
                },
              ),
            ),
            // Resize handle — only visible on hover or while resizing
            if (screenH > 18)
              Positioned(
                bottom: 0,
                left: 0,
                right: 0,
                height: 12,
                child: AnimatedOpacity(
                  opacity: (isHovered || isActive) ? 1.0 : 0.0,
                  duration: const Duration(milliseconds: 150),
                  child: MouseRegion(
                    cursor: SystemMouseCursors.resizeRow,
                    child: Container(
                      decoration: BoxDecoration(
                        borderRadius: const BorderRadius.vertical(
                          bottom: Radius.circular(5),
                        ),
                        gradient: LinearGradient(
                          begin: Alignment.topCenter,
                          end: Alignment.bottomCenter,
                          colors: [Colors.transparent, color.withOpacity(0.35)],
                        ),
                      ),
                      child: Center(
                        child: Container(
                          width: 20,
                          height: 2,
                          decoration: BoxDecoration(
                            color: color.withOpacity(0.6),
                            borderRadius: BorderRadius.circular(1),
                          ),
                        ),
                      ),
                    ),
                  ),
                ),
              ),
          ],
        ),
      ),
    );
  }
}

// ─────────────────────────────────────────────────────────────────────────────
// _TaskRow  –  individual task list card with hover-revealed action buttons
// ─────────────────────────────────────────────────────────────────────────────

class _TaskRow extends StatefulWidget {
  final Task task;
  final DateTime today;
  final Set<String> allSubtaskIds;

  /// Overrides task.timeSpent — use when subtasks aggregate to parent.
  final int? effectiveTimeSpentMs;

  /// Overrides task.durationMinutes — use when subtasks aggregate to parent.
  final int? effectiveDurationMinutes;
  final Map<String, Project> projects;
  final Map<String, String> projectIcons;
  final List<Task> allTasks;
  final String? activeTimerTaskId;
  final String? activeStagingTaskId;
  final VoidCallback? onStopStaging;
  final String? activeFlowtimeTaskId;
  final VoidCallback? onFlowtimeToggle;
  final Map<String, bool> taskDetailExpanded;
  final String Function() formatElapsed;
  final VoidCallback onStatusToggle;
  final void Function(TaskStatus) onStatusSelect;
  final VoidCallback onTimerToggle;
  final VoidCallback? onStagingToggle;
  final bool stagingWasInterrupted;
  final VoidCallback onDetailToggle;
  final VoidCallback? onSubtasksToggle;
  final bool subtasksExpanded;
  final VoidCallback? onShowRepeatTimeline;
  final int repeatInstanceCount;
  final bool isRecurringTask; // true for both parent and instances
  final void Function(Offset globalPos)? onContextMenu;
  final void Function(String newTitle)? onRename;

  /// If provided, replaces the default drag-indicator icon with this widget
  /// (typically a [ReorderableDragStartListener]-wrapped icon).
  final Widget? dragHandle;

  /// Horizontal margin on each side between the card and the list edge (distance_d).
  final double horizPadding;

  /// Called when the user picks a new date from the date chip.
  final void Function(String isoDay, int? plannedAt)? onDateChanged;

  /// Whether to show the countdown chip (days/hours until due) next to the date badge.
  final bool showCountdownOnCards;

  const _TaskRow({
    Key? key,
    required this.task,
    required this.today,
    required this.allSubtaskIds,
    required this.projects,
    required this.projectIcons,
    required this.allTasks,
    required this.activeTimerTaskId,
    this.activeStagingTaskId,
    this.onStopStaging,
    this.activeFlowtimeTaskId,
    this.onFlowtimeToggle,
    required this.taskDetailExpanded,
    required this.formatElapsed,
    required this.onStatusToggle,
    required this.onStatusSelect,
    required this.onTimerToggle,
    this.onStagingToggle,
    this.stagingWasInterrupted = false,
    required this.onDetailToggle,
    this.onSubtasksToggle,
    this.subtasksExpanded = false,
    this.onShowRepeatTimeline,
    this.repeatInstanceCount = 0,
    this.isRecurringTask = false,
    this.onContextMenu,
    this.onRename,
    this.dragHandle,
    this.onDateChanged,
    this.effectiveTimeSpentMs,
    this.effectiveDurationMinutes,
    this.horizPadding = 12.0,
    this.showCountdownOnCards = false,
  }) : super(key: key);

  @override
  State<_TaskRow> createState() => _TaskRowState();
}

class _TaskRowState extends State<_TaskRow> {
  bool _hovered = false;
  // Prevents the card-level right-click menu from also firing when the
  // status icon is right-clicked.
  bool _suppressNextContextMenu = false;
  bool _editing = false;
  late TextEditingController _titleCtrl;
  final FocusNode _titleFocus = FocusNode();
  final GlobalKey _dateChipKey = GlobalKey();

  @override
  void initState() {
    super.initState();
    _titleCtrl = TextEditingController(text: widget.task.title);
    _titleFocus.addListener(() {
      if (!_titleFocus.hasFocus && _editing) _commitEdit();
    });
  }

  @override
  void didUpdateWidget(_TaskRow old) {
    super.didUpdateWidget(old);
    if (!_editing && old.task.title != widget.task.title) {
      _titleCtrl.text = widget.task.title;
    }
  }

  @override
  void dispose() {
    _titleCtrl.dispose();
    _titleFocus.dispose();
    super.dispose();
  }

  void _startEdit() {
    setState(() {
      _editing = true;
      _titleCtrl.text = widget.task.title;
      _titleCtrl.selection = TextSelection(
        baseOffset: 0,
        extentOffset: _titleCtrl.text.length,
      );
    });
    WidgetsBinding.instance.addPostFrameCallback(
      (_) => FocusScope.of(context).requestFocus(_titleFocus),
    );
  }

  void _commitEdit() {
    final newTitle = _titleCtrl.text.trim();
    setState(() => _editing = false);
    if (newTitle.isNotEmpty && newTitle != widget.task.title) {
      widget.onRename?.call(newTitle);
    } else {
      _titleCtrl.text = widget.task.title; // revert if empty or unchanged
    }
  }

  @override
  Widget build(BuildContext context) {
    final task = widget.task;
    final bool isSubtask = widget.allSubtaskIds.contains(task.id);
    final bool isDone =
        task.status == TaskStatus.done || task.status == TaskStatus.cancelled ||
        task.status == TaskStatus.surpassed || task.status == TaskStatus.withdrawn;
    final bool timerActive = widget.activeTimerTaskId == task.id;
    final bool detailActive = widget.taskDetailExpanded[task.id] ?? false;

    DateTime? dueDate;
    bool isOverdue = false;
    String? dateLabel;
    String? timeLabel; // time-of-day portion extracted from dueDay
    if (task.dueDay != null) {
      // Parse as naive wall-clock time (no .toLocal() / no UTC assumption) so
      // that dueDate.difference(AppClock.now()) is apples-to-apples.
      final parsed = DateTime.tryParse(task.dueDay!);
      if (parsed != null) {
        dueDate = DateTime(parsed.year, parsed.month, parsed.day,
            parsed.hour, parsed.minute, parsed.second);
      }
      if (dueDate != null) {
        final d = DateTime(dueDate.year, dueDate.month, dueDate.day);
        isOverdue = d.isBefore(widget.today) && !isDone;
        final todayD = DateTime(
          widget.today.year,
          widget.today.month,
          widget.today.day,
        );
        // Use the centralised chip formatter (shows year for non-current-year dates)
        dateLabel = _fmtDateChip(dueDate);
        // Extract time from plannedAt (set by Task Details > Planning > Time).
        // Show even if 00:00 — only omit when no time has been set at all.
        if (task.plannedAt != null && task.plannedAt! > 0) {
          final scheduledDt = task.scheduledDateTime;
          if (scheduledDt != null) {
            timeLabel =
                '${scheduledDt.hour.toString().padLeft(2, '0')}:${scheduledDt.minute.toString().padLeft(2, '0')}';
          }
        }
      }
    }

    final subtasks = widget.allTasks
        .where((t) => task.subTaskIds.any((id) => id.toString() == t.id))
        .toList();
    final doneSubtasks = subtasks
        .where((t) => t.status == TaskStatus.done)
        .length;

    const surface = Color(0xFF212426);
    const subtaskSurface = Color(
      0xFF262B2F,
    ); // slightly lighter so it's visible
    const border = Color(0xFF2C2F32);

    return GestureDetector(
      onSecondaryTapDown: (d) {
        if (_suppressNextContextMenu) {
          _suppressNextContextMenu = false;
          return;
        }
        widget.onContextMenu?.call(d.globalPosition);
      },
      child: MouseRegion(
        onEnter: (_) => setState(() => _hovered = true),
        onExit: (_) => setState(() => _hovered = false),
        child: Padding(
          padding: EdgeInsets.zero,
          child: Container(
            // When rendered as a subtask inside the subtask container, suppress
            // the horizontal margin so the card fills the container properly.
            margin: isSubtask
                ? const EdgeInsets.symmetric(vertical: 2)
                : EdgeInsets.only(
                    left: widget.horizPadding,
                    right: widget.horizPadding,
                    top: 3,
                    bottom: (!isSubtask && widget.subtasksExpanded) ? 0 : 3,
                  ),
            decoration: BoxDecoration(
              color: isSubtask
                  ? (_hovered
                        ? subtaskSurface.withBlue(subtaskSurface.blue + 8)
                        : subtaskSurface)
                  : (_hovered ? surface.withBlue(surface.blue + 8) : surface),
              borderRadius: (!isSubtask && widget.subtasksExpanded)
                  ? const BorderRadius.only(
                      topLeft: Radius.circular(8),
                      topRight: Radius.circular(8),
                    )
                  : BorderRadius.circular(isSubtask ? 4 : 8),
              border: Border.all(
                color: isOverdue
                    ? const Color(0xFFEF5350).withOpacity(0.3)
                    : _hovered
                    ? Colors.white24
                    : border,
              ),
              boxShadow: (!isSubtask && widget.subtasksExpanded)
                  ? [
                      BoxShadow(
                        color: Colors.black.withOpacity(0.45),
                        blurRadius: 6,
                        offset: const Offset(0, 4),
                        spreadRadius: 0,
                      ),
                    ]
                  : null,
            ),
            child: IntrinsicHeight(
              child: Row(
                children: [
                  // Drag handle — replaced by ReorderableDragStartListener
                  // when the list supports reordering.
                  widget.dragHandle ??
                      Padding(
                        padding: const EdgeInsets.symmetric(horizontal: 8),
                        child: Icon(
                          Icons.drag_indicator,
                          size: 14,
                          color: Colors.white12,
                        ),
                      ),
                  // Status icon — right-click opens status picker only;
                  // flag prevents the card-level Delete menu from also firing.
                  GestureDetector(
                    onTap: widget.onStatusToggle,
                    onSecondaryTapDown: (details) {
                      _suppressNextContextMenu = true;
                      showMenu<TaskStatus>(
                        context: context,
                        position: RelativeRect.fromLTRB(
                          details.globalPosition.dx,
                          details.globalPosition.dy,
                          details.globalPosition.dx + 1,
                          details.globalPosition.dy + 1,
                        ),
                        color: const Color(0xFF252829),
                        shape: RoundedRectangleBorder(
                          borderRadius: BorderRadius.circular(8),
                          side: const BorderSide(color: Colors.white12),
                        ),
                        items: TaskStatus.values.map((s) {
                          final selected = widget.task.status == s;
                          return PopupMenuItem<TaskStatus>(
                            value: s,
                            padding: const EdgeInsets.symmetric(
                              horizontal: 12,
                              vertical: 4,
                            ),
                            child: Row(
                              children: [
                                Icon(
                                  s.icon,
                                  size: 14,
                                  color: selected
                                      ? s.color
                                      : s.color.withOpacity(0.6),
                                ),
                                const SizedBox(width: 10),
                                Text(
                                  s.label,
                                  style: TextStyle(
                                    fontSize: 12,
                                    color: selected
                                        ? Colors.white
                                        : Colors.white70,
                                    fontWeight: selected
                                        ? FontWeight.w600
                                        : FontWeight.normal,
                                  ),
                                ),
                                if (selected) ...[
                                  const Spacer(),
                                  const Icon(
                                    Icons.check,
                                    size: 12,
                                    color: Colors.white54,
                                  ),
                                ],
                              ],
                            ),
                          );
                        }).toList(),
                      ).then((picked) {
                        if (picked != null) widget.onStatusSelect(picked);
                      });
                    },
                    child: Padding(
                      padding: const EdgeInsets.only(right: 10),
                      child: Icon(
                        task.status.icon,
                        size: 16,
                        color: isDone ? Colors.white24 : task.status.color,
                      ),
                    ),
                  ),
                  // Title + project
                  Expanded(
                    child: Padding(
                      padding: const EdgeInsets.symmetric(vertical: 11),
                      child: Column(
                        crossAxisAlignment: CrossAxisAlignment.start,
                        mainAxisSize: MainAxisSize.min,
                        children: [
                          _editing
                              ? TextField(
                                  controller: _titleCtrl,
                                  focusNode: _titleFocus,
                                  maxLines: 1,
                                  strutStyle: const StrutStyle(
                                    forceStrutHeight: true,
                                    fontSize: 13,
                                    height: 1.0,
                                    leading: 0.0,
                                  ),
                                  style: TextStyle(
                                    fontSize: 13,
                                    color: Colors.white.withOpacity(0.88),
                                  ),
                                  decoration: InputDecoration(
                                    isDense: true,
                                    contentPadding: const EdgeInsets.symmetric(
                                      horizontal: 4,
                                      vertical: 4,
                                    ),
                                    filled: true,
                                    fillColor: Colors.white.withOpacity(0.06),
                                    border: OutlineInputBorder(
                                      borderRadius: BorderRadius.circular(4),
                                      borderSide: const BorderSide(
                                        color: Color(0xFF4FC3F7),
                                        width: 0.8,
                                      ),
                                    ),
                                    enabledBorder: OutlineInputBorder(
                                      borderRadius: BorderRadius.circular(4),
                                      borderSide: const BorderSide(
                                        color: Color(0xFF4FC3F7),
                                        width: 0.8,
                                      ),
                                    ),
                                    focusedBorder: OutlineInputBorder(
                                      borderRadius: BorderRadius.circular(4),
                                      borderSide: const BorderSide(
                                        color: Color(0xFF4FC3F7),
                                        width: 1.2,
                                      ),
                                    ),
                                  ),
                                  onSubmitted: (_) => _commitEdit(),
                                )
                              : GestureDetector(
                                  onDoubleTap: widget.onRename != null
                                      ? _startEdit
                                      : null,
                                  child: Row(
                                    mainAxisSize: MainAxisSize.min,
                                    children: [
                                      // Repeat badge: ↻ for series parent, ↩ for instance
                                      if (task.isSeriesParent)
                                        Tooltip(
                                          message:
                                              'Repeating task – ${task.repeatConfig?.label ?? 'Recurring'}',
                                          child: Padding(
                                            padding: const EdgeInsets.only(
                                              right: 5,
                                            ),
                                            child: Icon(
                                              Icons.repeat_rounded,
                                              size: 11,
                                              color: const Color(
                                                0xFF4FC3F7,
                                              ).withOpacity(0.6),
                                            ),
                                          ),
                                        )
                                      else if (task.isPartOfSeries)
                                        Tooltip(
                                          message: 'Repeat instance',
                                          child: Padding(
                                            padding: const EdgeInsets.only(
                                              right: 5,
                                            ),
                                            child: Icon(
                                              Icons.repeat_one_rounded,
                                              size: 11,
                                              color: Colors.white.withOpacity(
                                                0.25,
                                              ),
                                            ),
                                          ),
                                        ),
                                      Flexible(
                                        child: Text(
                                          task.title,
                                          style: TextStyle(
                                            fontSize: 13,
                                            color: isDone
                                                ? Colors.white24
                                                : Colors.white.withOpacity(
                                                    0.88,
                                                  ),
                                            decoration: isDone
                                                ? TextDecoration.lineThrough
                                                : null,
                                            decorationColor: Colors.white38,
                                          ),
                                          overflow: TextOverflow.ellipsis,
                                        ),
                                      ),
                                    ],
                                  ),
                                ),
                          if (task.projectId == 'INBOX_PROJECT' ||
                              widget.projects[task.projectId] != null) ...[
                            const SizedBox(height: 2),
                            Row(
                              mainAxisSize: MainAxisSize.min,
                              children: [
                                () {
                                  final icon = task.projectId == 'INBOX_PROJECT'
                                      ? ''
                                      : (widget.projectIcons[task.projectId] ??
                                            '');
                                  if (icon.isNotEmpty) {
                                    return Padding(
                                      padding: const EdgeInsets.only(right: 3),
                                      child: Text(
                                        icon,
                                        style: const TextStyle(
                                          fontSize: 9,
                                          fontFamilyFallback: [
                                            'NotoColorEmoji',
                                            'Apple Color Emoji',
                                            'Segoe UI Emoji',
                                          ],
                                        ),
                                      ),
                                    );
                                  }
                                  return Padding(
                                    padding: const EdgeInsets.only(right: 3),
                                    child: Icon(
                                      task.projectId == 'INBOX_PROJECT'
                                          ? Icons.inbox_outlined
                                          : Icons.folder_outlined,
                                      size: 9,
                                      color: Colors.white24,
                                    ),
                                  );
                                }(),
                                Flexible(
                                  child: Text(
                                    task.projectId == 'INBOX_PROJECT'
                                        ? 'Inbox'
                                        : widget
                                              .projects[task.projectId]!
                                              .title,
                                    style: const TextStyle(
                                      fontSize: 10,
                                      color: Colors.white30,
                                    ),
                                    overflow: TextOverflow.ellipsis,
                                  ),
                                ),
                              ],
                            ),
                          ],
                          if (subtasks.isNotEmpty) ...[
                            const SizedBox(height: 4),
                            GestureDetector(
                              onTap: widget.onSubtasksToggle,
                              child: Row(
                                mainAxisSize: MainAxisSize.min,
                                children: [
                                  Icon(
                                    widget.subtasksExpanded
                                        ? Icons.keyboard_arrow_down
                                        : Icons.keyboard_arrow_right,
                                    size: 11,
                                    color: Colors.white38,
                                  ),
                                  const SizedBox(width: 2),
                                  Icon(
                                    Icons.account_tree_outlined,
                                    size: 10,
                                    color: Colors.white24,
                                  ),
                                  const SizedBox(width: 4),
                                  Text(
                                    '$doneSubtasks/${subtasks.length}',
                                    style: const TextStyle(
                                      fontSize: 10,
                                      color: Colors.white38,
                                    ),
                                  ),
                                ],
                              ),
                            ),
                          ],
                          if (widget.isRecurringTask) ...[
                            const SizedBox(height: 4),
                            GestureDetector(
                              onTap: widget.onShowRepeatTimeline,
                              child: MouseRegion(
                                cursor: SystemMouseCursors.click,
                                child: Row(
                                  mainAxisSize: MainAxisSize.min,
                                  children: [
                                    _RepeatChainIcon(),
                                    const SizedBox(width: 4),
                                    if (widget.repeatInstanceCount > 0)
                                      Text(
                                        '${widget.repeatInstanceCount} upcoming',
                                        style: const TextStyle(
                                          fontSize: 10,
                                          color: Colors.white38,
                                        ),
                                      ),
                                  ],
                                ),
                              ),
                            ),
                          ],
                        ],
                      ),
                    ),
                  ),
                  // Countdown chip (days/hours until due)
                  if (widget.showCountdownOnCards && dueDate != null)
                    Padding(
                      padding: const EdgeInsets.only(right: 5),
                      child: Builder(builder: (ctx) {
                        final now = AppClock.now();
                        // Use plannedAt (UTC epoch) when available — already the
                        // exact moment in AppClock tz. Otherwise treat dueDay as
                        // naive wall-clock in AppClock tz so difference() is correct.
                        final DateTime effectiveDue;
                        if (task.plannedAt != null && task.plannedAt! > 0) {
                          effectiveDue = AppClock.fromEpoch(task.plannedAt!);
                        } else {
                          final base = dueDate!;
                          if (task.dueDay != null &&
                              !task.dueDay!.contains('T') &&
                              !task.dueDay!.contains(' ')) {
                            effectiveDue = DateTime(base.year, base.month, base.day, 23, 59, 59);
                          } else {
                            effectiveDue = DateTime(base.year, base.month, base.day,
                                base.hour, base.minute, base.second);
                          }
                        }
                        final diff = effectiveDue.difference(now);
                        final isPast = diff.isNegative;
                        final absDiff = diff.abs();
                        final days = absDiff.inDays;
                        final hours = absDiff.inHours % 24;
                        final mins = absDiff.inMinutes % 60;
                        final String label;
                        if (days > 0) {
                          label = isPast ? '+${days}d ${hours}h' : '${days}d ${hours}h';
                        } else {
                          label = isPast ? '+${hours}h ${mins}m' : '${hours}h ${mins}m';
                        }
                        final Color chipColor = isDone
                            ? const Color(0xFF9E9E9E)
                            : isPast
                                ? const Color(0xFFB71C1C)
                                : days == 0
                                    ? const Color(0xFFFF9800)
                                    : days <= 2
                                        ? const Color(0xFFFFD600)
                                        : const Color(0xFF4CAF50);
                        return Container(
                          padding: const EdgeInsets.symmetric(
                            horizontal: 5,
                            vertical: 3,
                          ),
                          decoration: BoxDecoration(
                            color: chipColor.withOpacity(0.13),
                            borderRadius: BorderRadius.circular(5),
                            border: Border.all(
                              color: chipColor.withOpacity(0.4),
                              width: 0.8,
                            ),
                          ),
                          child: Row(
                            mainAxisSize: MainAxisSize.min,
                            children: [
                              Icon(
                                isPast
                                    ? Icons.schedule_rounded
                                    : Icons.hourglass_bottom_rounded,
                                size: 9,
                                color: chipColor,
                              ),
                              const SizedBox(width: 3),
                              Text(
                                label,
                                style: TextStyle(
                                  fontSize: 10,
                                  fontWeight: FontWeight.w600,
                                  color: chipColor,
                                  fontFamily: 'monospace',
                                ),
                              ),
                            ],
                          ),
                        );
                      }),
                    ),
                  // Date badge
                  if (dateLabel != null)
                    Padding(
                      padding: const EdgeInsets.only(right: 6),
                      child: GestureDetector(
                        key: _dateChipKey,
                        onTap: widget.onDateChanged == null
                            ? null
                            : () {
                                final box =
                                    _dateChipKey.currentContext
                                            ?.findRenderObject()
                                        as RenderBox?;
                                final pos =
                                    box?.localToGlobal(Offset.zero) ??
                                    Offset.zero;
                                final size = box?.size ?? Size.zero;
                                _showDueDatePopup(
                                  context: context,
                                  anchorRect: Rect.fromLTWH(
                                    pos.dx,
                                    pos.dy,
                                    size.width,
                                    size.height,
                                  ),
                                  selectedDueDay: task.dueDay,
                                  plannedAt: task.plannedAt,
                                  onConfirm: (isoDay, newPlannedAt) {
                                    widget.onDateChanged?.call(
                                      isoDay,
                                      newPlannedAt,
                                    );
                                  },
                                );
                              },
                        child: MouseRegion(
                          cursor: widget.onDateChanged != null
                              ? SystemMouseCursors.click
                              : MouseCursor.defer,
                          child: Container(
                            padding: const EdgeInsets.symmetric(
                              horizontal: 7,
                              vertical: 3,
                            ),
                            decoration: BoxDecoration(
                              color: isOverdue
                                  ? const Color(0xFFEF5350).withOpacity(0.12)
                                  : Colors.white.withOpacity(0.05),
                              borderRadius: BorderRadius.circular(5),
                              border: Border.all(
                                color: isOverdue
                                    ? const Color(0xFFEF5350).withOpacity(0.4)
                                    : Colors.white12,
                              ),
                            ),
                            child: Row(
                              mainAxisSize: MainAxisSize.min,
                              children: [
                                Icon(
                                  Icons.calendar_today_outlined,
                                  size: 9,
                                  color: isOverdue
                                      ? const Color(0xFFEF5350)
                                      : Colors.white38,
                                ),
                                const SizedBox(width: 4),
                                Text(
                                  dateLabel!,
                                  style: TextStyle(
                                    fontSize: 10,
                                    fontWeight: FontWeight.w500,
                                    color: isOverdue
                                        ? const Color(0xFFEF5350)
                                        : Colors.white38,
                                  ),
                                ),
                                if (timeLabel != null) ...[
                                  const SizedBox(width: 5),
                                  Container(
                                    width: 1,
                                    height: 9,
                                    color: isOverdue
                                        ? const Color(
                                            0xFFEF5350,
                                          ).withOpacity(0.4)
                                        : Colors.white12,
                                  ),
                                  const SizedBox(width: 5),
                                  Icon(
                                    Icons.access_time_rounded,
                                    size: 9,
                                    color: isOverdue
                                        ? const Color(0xFFEF5350)
                                        : Colors.white38,
                                  ),
                                  const SizedBox(width: 3),
                                  Text(
                                    timeLabel!,
                                    style: TextStyle(
                                      fontSize: 10,
                                      fontWeight: FontWeight.w500,
                                      color: isOverdue
                                          ? const Color(0xFFEF5350)
                                          : Colors.white38,
                                    ),
                                  ),
                                ],
                              ],
                            ),
                          ),
                        ),
                      ),
                    ),
                  // ── Right-end area: time stats at rest, buttons on hover ──
                  SizedBox(
                    width: 112,
                    child: Stack(
                      alignment: Alignment.centerRight,
                      children: [
                        // Time stats — visible when not hovered
                        AnimatedOpacity(
                          opacity: (_hovered || timerActive || detailActive)
                              ? 0.0
                              : 1.0,
                          duration: const Duration(milliseconds: 150),
                          child: IgnorePointer(
                            child: Padding(
                              padding: const EdgeInsets.only(right: 8),
                              child: Column(
                                mainAxisSize: MainAxisSize.min,
                                crossAxisAlignment: CrossAxisAlignment.end,
                                children: [
                                  Builder(
                                    builder: (_) {
                                      final ms =
                                          widget.effectiveTimeSpentMs ??
                                          task.timeSpent;
                                      if (ms <= 0)
                                        return const SizedBox.shrink();
                                      final h = ms ~/ 3600000;
                                      final m = (ms % 3600000) ~/ 60000;
                                      return Text(
                                        h > 0 ? '${h}h ${m}m' : '${m}m',
                                        style: const TextStyle(
                                          fontSize: 10,
                                          color: Color(0xFF4A5060),
                                        ),
                                      );
                                    },
                                  ),
                                  Builder(
                                    builder: (_) {
                                      final mins =
                                          widget.effectiveDurationMinutes ??
                                          task.durationMinutes;
                                      final h = mins ~/ 60;
                                      final rm = mins % 60;
                                      return Text(
                                        h > 0
                                            ? (rm > 0
