      ), // GestureDetector
    );
  }
}

// ─────────────────────────────────────────────────────────────────────────────
// _RepeatChainIcon  –  small "dots connected by a vertical line" icon that
//   appears on every recurring task (parent and instances) to open the
//   timeline modal.
// ─────────────────────────────────────────────────────────────────────────────

class _RepeatChainIcon extends StatelessWidget {
  const _RepeatChainIcon();

  @override
  Widget build(BuildContext context) {
    return Container(
      padding: const EdgeInsets.symmetric(horizontal: 6, vertical: 3),
      decoration: BoxDecoration(
        color: Colors.white.withOpacity(0.04),
        borderRadius: BorderRadius.circular(4),
        border: Border.all(color: Colors.white.withOpacity(0.10)),
      ),
      child: SizedBox(
        width: 26,
        height: 8,
        child: CustomPaint(painter: _ChainDotsPainter()),
      ),
    );
  }
}

class _ChainDotsPainter extends CustomPainter {
  @override
  void paint(Canvas canvas, Size size) {
    const color = Color(0xFF8A8F99);
    const dotRadius = 2.0;
    final linePaint = Paint()
      ..color = color.withOpacity(0.5)
      ..strokeWidth = 1.0
      ..style = PaintingStyle.stroke;
    final dotPaint = Paint()
      ..color = color.withOpacity(0.75)
      ..style = PaintingStyle.fill;
    final cy = size.height / 2;
    final leftX  = dotRadius + 0.5;
    final midX   = size.width / 2;
    final rightX = size.width - dotRadius - 0.5;
    // Connecting line
    canvas.drawLine(
      Offset(leftX + dotRadius, cy),
      Offset(rightX - dotRadius, cy),
      linePaint,
    );
    // Three dots
    canvas.drawCircle(Offset(leftX,  cy), dotRadius, dotPaint);
    canvas.drawCircle(Offset(midX,   cy), dotRadius - 0.4, dotPaint);
    canvas.drawCircle(Offset(rightX, cy), dotRadius, dotPaint);
  }

  @override
  bool shouldRepaint(_ChainDotsPainter old) => false;
}

// ─────────────────────────────────────────────────────────────────────────────
// _RecurringTimelineModal  –  full-chain timeline of a recurring task,
//   centered on the task that was tapped.
// ─────────────────────────────────────────────────────────────────────────────

class _RecurringTimelineModal extends StatelessWidget {
  final List<Task> chain;
  final String focusedTaskId;

  /// Called (after the dialog pops) when the user taps the "Recurring" chip
  /// in the header — navigates to the repeat-config panel for the series parent.
  final VoidCallback? onEditRepeatConfig;

  /// Called (after the dialog pops) when the user taps "Details" on an item.
  final void Function(Task instance)? onEditInstance;

  const _RecurringTimelineModal({
    required this.chain,
    required this.focusedTaskId,
    this.onEditRepeatConfig,
    this.onEditInstance,
  });

  @override
  Widget build(BuildContext context) {
    if (chain.isEmpty) return const SizedBox.shrink();

    final focusedIndex = chain.indexWhere((t) => t.id == focusedTaskId);
    final initialIndex = focusedIndex < 0 ? 0 : focusedIndex;

    const bg = Color(0xFF1A1D22);
    const cardBg = Color(0xFF252830);
    const accent = Color(0xFF4FC3F7);
    const lineColor = Color(0xFF2E3440);

    // Build the title from the series parent task (fall back to first in chain)
    final parent = chain.firstWhere(
      (t) => t.isSeriesParent,
      orElse: () => chain.first,
    );
    final repeatLabel = parent.repeatConfig?.label ?? 'Recurring';

    return Dialog(
      backgroundColor: bg,
      shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(14)),
      insetPadding: const EdgeInsets.symmetric(horizontal: 28, vertical: 48),
      child: ConstrainedBox(
        constraints: const BoxConstraints(maxWidth: 480, maxHeight: 600),
        child: Column(
          mainAxisSize: MainAxisSize.min,
          children: [
            // ── Header ────────────────────────────────────────────────────
            Container(
              padding: const EdgeInsets.fromLTRB(20, 18, 16, 14),
              decoration: const BoxDecoration(
                border: Border(bottom: BorderSide(color: Color(0xFF2C2F35))),
              ),
              child: Row(
                children: [
                  // ── Recurring chip (tappable → opens repeat config) ──
                  GestureDetector(
                    onTap: onEditRepeatConfig != null
                        ? () {
                            Navigator.of(context).pop();
                            onEditRepeatConfig!();
                          }
                        : null,
                    child: MouseRegion(
                      cursor: onEditRepeatConfig != null
                          ? SystemMouseCursors.click
                          : MouseCursor.defer,
                      child: Container(
                        padding: const EdgeInsets.symmetric(
                            horizontal: 7, vertical: 3),
                        decoration: BoxDecoration(
                          color: accent.withOpacity(0.10),
                          borderRadius: BorderRadius.circular(6),
                          border:
                              Border.all(color: accent.withOpacity(0.28)),
                        ),
                        child: Row(
                          mainAxisSize: MainAxisSize.min,
                          children: [
                            Icon(Icons.repeat_rounded,
                                size: 11, color: accent.withOpacity(0.8)),
                            const SizedBox(width: 5),
                            Text(
                              repeatLabel,
                              style: TextStyle(
                                fontSize: 11,
                                color: accent.withOpacity(0.9),
                                fontWeight: FontWeight.w600,
                              ),
                            ),
                            if (onEditRepeatConfig != null) ...[
                              const SizedBox(width: 4),
                              Icon(Icons.edit_rounded,
                                  size: 9,
                                  color: accent.withOpacity(0.5)),
                            ],
                          ],
                        ),
                      ),
                    ),
                  ),
                  const SizedBox(width: 10),
                  Expanded(
                    child: Text(
                      parent.title,
                      style: const TextStyle(
                        fontSize: 13,
                        fontWeight: FontWeight.w600,
                        color: Colors.white,
                      ),
                      overflow: TextOverflow.ellipsis,
                    ),
                  ),
                  Text(
                    '${chain.length} total',
                    style: const TextStyle(fontSize: 11, color: Colors.white30),
                  ),
                  const SizedBox(width: 12),
                  GestureDetector(
                    onTap: () => Navigator.of(context).pop(),
                    child: const Icon(Icons.close, size: 16, color: Colors.white38),
                  ),
                ],
              ),
            ),

            // ── Timeline list ─────────────────────────────────────────────
            Flexible(
              child: _RecurringTimelineList(
                chain: chain,
                focusedIndex: initialIndex,
                cardBg: cardBg,
                accent: accent,
                lineColor: lineColor,
                onEditInstance: onEditInstance,
              ),
            ),
          ],
        ),
      ),
    );
  }
}

// Separate stateful widget so we can auto-scroll to focused item.
class _RecurringTimelineList extends StatefulWidget {
  final List<Task> chain;
  final int focusedIndex;
  final Color cardBg;
  final Color accent;
  final Color lineColor;

  /// If provided, each item shows a hover-reveal "Details" button that pops
  /// the dialog and calls this with the tapped task.
  final void Function(Task instance)? onEditInstance;

  const _RecurringTimelineList({
    required this.chain,
    required this.focusedIndex,
    required this.cardBg,
    required this.accent,
    required this.lineColor,
    this.onEditInstance,
  });

  @override
  State<_RecurringTimelineList> createState() => _RecurringTimelineListState();
}

class _RecurringTimelineListState extends State<_RecurringTimelineList> {
  late final ScrollController _scroll;
  int? _hoveredIndex;

  static const double _itemHeight = 72.0;

  @override
  void initState() {
    super.initState();
    _scroll = ScrollController();
    WidgetsBinding.instance.addPostFrameCallback((_) => _scrollToFocused());
  }

  void _scrollToFocused() {
    if (!_scroll.hasClients) return;
    final maxScrollExtent = _scroll.position.maxScrollExtent;
    final targetOffset = widget.focusedIndex * _itemHeight;
    // Center the focused item in the viewport
    final viewportHeight = _scroll.position.viewportDimension;
    final centered = targetOffset - (viewportHeight / 2) + (_itemHeight / 2);
    final clamped = centered.clamp(0.0, maxScrollExtent);
    _scroll.animateTo(
      clamped,
      duration: const Duration(milliseconds: 320),
      curve: Curves.easeOut,
    );
  }

  @override
  void dispose() {
    _scroll.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    final chain = widget.chain;
    return ListView.builder(
      controller: _scroll,
      padding: const EdgeInsets.symmetric(vertical: 8),
      itemCount: chain.length,
      itemBuilder: (context, index) {
        final task = chain[index];
        final isFocused = task.id == chain[widget.focusedIndex].id;
        final isFirst = index == 0;
        final isLast = index == chain.length - 1;
        final isDone = task.status == TaskStatus.done ||
            task.status == TaskStatus.cancelled ||
            task.status == TaskStatus.surpassed;

        // Format date
        String dateStr = '—';
        if (task.dueDay != null) {
          final d = DateTime.tryParse(task.dueDay!);
          if (d != null) dateStr = _fmtDateChip(d);
        }

        // Status color dot
        final statusColor = isDone
            ? Colors.white24
            : (task.status == TaskStatus.none
                ? Colors.white24
                : task.status.color);

        final isHovered = _hoveredIndex == index;

        return MouseRegion(
          onEnter: (_) => setState(() => _hoveredIndex = index),
          onExit: (_) => setState(() {
            if (_hoveredIndex == index) _hoveredIndex = null;
          }),
          child: SizedBox(
          height: _itemHeight,
          child: Row(
            crossAxisAlignment: CrossAxisAlignment.stretch,
            children: [
              // ── Timeline spine (with status icon) ────────────────────
              SizedBox(
                width: 44,
                child: Stack(
                  alignment: Alignment.center,
                  children: [
                    // Vertical line (top half)
                    if (!isFirst)
                      Positioned(
                        top: 0,
                        bottom: _itemHeight / 2,
                        left: 21,
                        width: 2,
                        child: Container(color: widget.lineColor),
                      ),
                    // Vertical line (bottom half)
                    if (!isLast)
                      Positioned(
                        top: _itemHeight / 2,
                        bottom: 0,
                        left: 21,
                        width: 2,
                        child: Container(color: widget.lineColor),
                      ),
                    // Status icon circle — replaces the plain dot
                    Positioned(
                      left: 10,
                      top: (_itemHeight / 2) - 11,
                      child: Container(
                        width: 22,
                        height: 22,
                        decoration: BoxDecoration(
                          shape: BoxShape.circle,
                          color: isFocused
                              ? widget.accent.withOpacity(0.15)
                              : statusColor.withOpacity(isDone ? 0.08 : 0.13),
                          border: Border.all(
                            color: isFocused
                                ? widget.accent
                                : statusColor.withOpacity(
                                    isDone ? 0.25 : 0.60),
                            width: isFocused ? 2 : 1.5,
                          ),
                        ),
                        child: Center(
                          child: Icon(
                            task.status.icon,
                            size: 11,
                            color: isFocused
                                ? widget.accent
                                : statusColor,
                          ),
                        ),
                      ),
                    ),
                  ],
                ),
              ),

              // ── Task card ──────────────────────────────────────────────
              Expanded(
                child: Container(
                  margin: const EdgeInsets.only(
                    right: 16,
                    top: 6,
                    bottom: 6,
                  ),
                  padding: const EdgeInsets.symmetric(
                      horizontal: 12, vertical: 8),
                  decoration: BoxDecoration(
                    color: isFocused
                        ? widget.accent.withOpacity(0.07)
                        : widget.cardBg,
                    borderRadius: BorderRadius.circular(8),
                    border: Border.all(
                      color: isFocused
                          ? widget.accent.withOpacity(0.35)
                          : const Color(0xFF2C2F35),
                    ),
                  ),
                  child: Row(
                    children: [
                      // Instance number badge
                      Container(
                        width: 22,
                        height: 22,
                        margin: const EdgeInsets.only(right: 10),
                        decoration: BoxDecoration(
                          color: isFocused
                              ? widget.accent.withOpacity(0.15)
                              : Colors.white.withOpacity(0.05),
                          borderRadius: BorderRadius.circular(5),
                        ),
                        child: Center(
                          child: Text(
                            '${index + 1}',
                            style: TextStyle(
                              fontSize: 10,
                              fontWeight: FontWeight.w700,
                              color: isFocused
