  final String currentId;
  final String Function(String id) workspaceFilePath;
  final bool allowDismiss;
  final void Function(Map<String, String>) onSelect;
  final void Function(Map<String, String>, String) onRename;
  final void Function(Map<String, String>) onDelete;
  final VoidCallback onCreateNew;
  final VoidCallback onRestoreFromFile;

  const _WorkspaceSwitcherDialog({
    required this.workspaces,
    required this.currentId,
    required this.workspaceFilePath,
    required this.allowDismiss,
    required this.onSelect,
    required this.onRename,
    required this.onDelete,
    required this.onCreateNew,
    required this.onRestoreFromFile,
  });

  @override
  State<_WorkspaceSwitcherDialog> createState() =>
      _WorkspaceSwitcherDialogState();
}

class _WorkspaceSwitcherDialogState extends State<_WorkspaceSwitcherDialog> {
  String _query = '';

  void _showRenameDialog(Map<String, String> item) {
    final ctrl = TextEditingController(text: item['name']);
    showDialog(
      context: context,
      builder: (ctx) => AlertDialog(
        backgroundColor: const Color(0xFF252525),
        title: const Text(
          'Rename Workspace',
          style: TextStyle(color: Colors.white, fontSize: 14),
        ),
        content: TextField(
          controller: ctrl,
          autofocus: true,
          style: const TextStyle(color: Colors.white, fontSize: 13),
          decoration: const InputDecoration(
            enabledBorder: UnderlineInputBorder(
              borderSide: BorderSide(color: Colors.white24),
            ),
            focusedBorder: UnderlineInputBorder(
              borderSide: BorderSide(color: Colors.blueAccent),
            ),
          ),
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(ctx),
            child: const Text(
              'Cancel',
              style: TextStyle(color: Colors.white38),
