                    // Apply Notes Tasks FGS item ordering: manual order takes priority
                    if (widget.noteTaskManualActive) {
                      final si = _applyNoteManualOrder(inboxNotes, widget.noteTaskManualOrder);
                      inboxNotes..clear()..addAll(si);
                      for (final pid in byProject.keys.toList()) {
                        byProject[pid] = _applyNoteManualOrder(byProject[pid]!, widget.noteTaskManualOrder);
                      }
                    } else if (widget.noteTaskItemSortCriteria.isNotEmpty) {
