  /// Timeline strip showing all instances in the series with the current one
  /// highlighted. Scrollable horizontally.
  Widget _buildInstanceTimeline() {
    final sid = widget.task.seriesId;
    if (sid == null) return const SizedBox.shrink();
    // The series parent always has id == seriesId.
    final parentId = sid;
    // Collect all series members sorted by scheduled date
    final series =
        widget.allTasks
            .where((t) => t.seriesId == sid)
            .toList()
          ..sort((a, b) {
            final da = a.scheduledDate ?? DateTime(2099);
            final db = b.scheduledDate ?? DateTime(2099);
            return da.compareTo(db);
          });

    final currentDate = widget.task.scheduledDate;
    final int currentIdx = series.indexWhere((t) => t.id == widget.task.id);
    final int total = series.length;

    String _shortDate(DateTime? d) {
      if (d == null) return '?';
      const months = [
        'Jan',
        'Feb',
        'Mar',
        'Apr',
        'May',
        'Jun',
        'Jul',
        'Aug',
        'Sep',
        'Oct',
        'Nov',
        'Dec',
      ];
      return '${months[d.month - 1]} ${d.day}';
    }

    // ── Auto-centre on the current instance (runs once after first layout) ──
    if (!_timelineScrolled && currentIdx >= 0) {
      WidgetsBinding.instance.addPostFrameCallback((_) {
        if (_timelineCtrl.hasClients && !_timelineScrolled) {
          _timelineScrolled = true;
          // Accumulate the pixel offset to the leading edge of the current dot.
          // Each item occupies: dotWidth + connectorWidth (20 px).
          //   parent dot  = 10 px
          //   regular dot = 8 px
          //   current dot = 14 px  (only at currentIdx, so not in this loop)
          double pixelOffset = 0;
          for (int i = 0; i < currentIdx; i++) {
            final isParent = series[i].id == parentId;
            pixelOffset += (isParent ? 10.0 : 8.0) + 20.0;
          }
          pixelOffset += 7.0; // half of the current dot (14 px / 2)

          final viewportWidth = _timelineCtrl.position.viewportDimension;
          final target = (pixelOffset - viewportWidth / 2).clamp(
            0.0,
            _timelineCtrl.position.maxScrollExtent,
          );
          _timelineCtrl.animateTo(
            target,
            duration: const Duration(milliseconds: 350),
            curve: Curves.easeOut,
          );
        }
      });
    }

    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        // Position badge
        Row(
          children: [
            Container(
              padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 3),
              decoration: BoxDecoration(
                color: const Color(0xFF4FC3F7).withOpacity(0.12),
                borderRadius: BorderRadius.circular(20),
                border: Border.all(
                  color: const Color(0xFF4FC3F7).withOpacity(0.35),
                ),
              ),
              child: Text(
                currentIdx >= 0
                    ? 'Instance ${currentIdx + 1} of $total'
                    : '$total instances',
                style: const TextStyle(
                  fontSize: 10,
                  color: Color(0xFF4FC3F7),
                  fontWeight: FontWeight.w600,
                ),
              ),
            ),
            const SizedBox(width: 8),
            if (currentDate != null)
              Text(
                _shortDate(currentDate),
                style: TextStyle(
                  fontSize: 10,
                  color: Colors.white.withOpacity(0.4),
                ),
              ),
          ],
        ),
        const SizedBox(height: 10),

        // Horizontal scrollable timeline – current instance centred on open
        SizedBox(
          height: 64,
          child: SingleChildScrollView(
            controller: _timelineCtrl,
            scrollDirection: Axis.horizontal,
            child: Row(
              crossAxisAlignment: CrossAxisAlignment.center,
              children: [
                for (int i = 0; i < series.length; i++) ...[
                  _buildTimelineDot(
                    task: series[i],
                    isCurrent: series[i].id == widget.task.id,
                    isParent: series[i].id == parentId,
                    shortDate: _shortDate(series[i].scheduledDate),
                  ),
                  if (i < series.length - 1)
                    Container(
                      width: 20,
                      height: 1.5,
                      color: Colors.white.withOpacity(0.12),
                    ),
                ],
              ],
            ),
          ),
        ),
      ],
    );
  }

  Widget _buildTimelineDot({
    required Task task,
    required bool isCurrent,
    required bool isParent,
    required String shortDate,
  }) {
    final today = DateTime.now();
    final taskDate = task.scheduledDate;
    final isPast =
        taskDate != null &&
        taskDate.isBefore(DateTime(today.year, today.month, today.day));

    Color dotColor;
    if (isCurrent) {
      dotColor = const Color(0xFF4FC3F7);
    } else if (task.isDone || task.status == TaskStatus.done) {
      dotColor = const Color(0xFF4CAF50);
    } else if (isPast) {
      dotColor = Colors.white24;
    } else {
      dotColor = Colors.white38;
    }

    return Column(
      mainAxisAlignment: MainAxisAlignment.center,
      children: [
        // Date label
        Text(
          shortDate,
          style: TextStyle(
            fontSize: 8,
            color: isCurrent
                ? const Color(0xFF4FC3F7)
                : Colors.white.withOpacity(0.3),
            fontWeight: isCurrent ? FontWeight.w700 : FontWeight.normal,
          ),
        ),
        const SizedBox(height: 4),
        // Dot
        Container(
          width: isCurrent ? 14 : (isParent ? 10 : 8),
          height: isCurrent ? 14 : (isParent ? 10 : 8),
          decoration: BoxDecoration(
            shape: BoxShape.circle,
            color: isCurrent ? dotColor.withOpacity(0.2) : Colors.transparent,
            border: Border.all(color: dotColor, width: isCurrent ? 2 : 1.5),
          ),
          child: isCurrent
              ? Center(
                  child: Container(
                    width: 5,
                    height: 5,
                    decoration: const BoxDecoration(
                      shape: BoxShape.circle,
                      color: Color(0xFF4FC3F7),
                    ),
                  ),
                )
              : null,
        ),
        const SizedBox(height: 4),
        // Status dot
        if (task.isDone || task.status == TaskStatus.done)
          const Icon(Icons.check_rounded, size: 8, color: Color(0xFF4CAF50))
        else
          const SizedBox(height: 8),
      ],
    );
  }

  /// START DATE row — editable for parent tasks (and forward-edit mode on
  /// instances), read-only for instances showing their own anchor date.
  Widget _buildStartDateRow() {
    // In forward-edit mode the anchor is locked to the instance's own date.
    final isInstanceEdit =
        !widget.task.isSeriesParent && widget.task.isPartOfSeries && _editingForward;
    final anchorLabel = _anchorDate != null
        ? _fmtDate(_anchorDate!)
        : 'No date set';

    return Row(
      children: [
        Expanded(
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Row(
                children: [
                  const Icon(
                    Icons.play_circle_outline_rounded,
                    size: 11,
                    color: Color(0xFF4FC3F7),
                  ),
                  const SizedBox(width: 5),
                  const Text(
                    'START DATE',
                    style: TextStyle(
                      fontSize: 9,
                      fontWeight: FontWeight.w700,
                      letterSpacing: 0.7,
                      color: Colors.white54,
                    ),
                  ),
                  if (isInstanceEdit) ...[
                    const SizedBox(width: 6),
                    Container(
                      padding: const EdgeInsets.symmetric(
                        horizontal: 5,
                        vertical: 2,
                      ),
                      decoration: BoxDecoration(
                        color: const Color(0xFFFFB74D).withOpacity(0.12),
                        borderRadius: BorderRadius.circular(4),
                        border: Border.all(
                          color: const Color(0xFFFFB74D).withOpacity(0.3),
                        ),
                      ),
                      child: const Text(
                        'ANCHOR',
                        style: TextStyle(
                          fontSize: 8,
                          fontWeight: FontWeight.w700,
                          letterSpacing: 0.5,
                          color: Color(0xFFFFB74D),
                        ),
                      ),
                    ),
                  ],
                ],
              ),
              const SizedBox(height: 6),
              GestureDetector(
                onTap: isInstanceEdit ? null : _pickAnchorDate,
                child: Container(
                  padding: const EdgeInsets.symmetric(
                    horizontal: 10,
                    vertical: 7,
                  ),
                  decoration: BoxDecoration(
                    color: isInstanceEdit
                        ? Colors.white.withOpacity(0.03)
                        : (_anchorDate != null
                              ? const Color(0xFF4FC3F7).withOpacity(0.08)
                              : Colors.white.withOpacity(0.05)),
                    borderRadius: BorderRadius.circular(5),
                    border: Border.all(
                      color: isInstanceEdit
                          ? Colors.white.withOpacity(0.08)
                          : (_anchorDate != null
                                ? const Color(0xFF4FC3F7).withOpacity(0.35)
                                : Colors.white.withOpacity(0.12)),
                    ),
                  ),
                  child: Row(
                    children: [
                      Icon(
                        Icons.calendar_today_outlined,
                        size: 11,
                        color: isInstanceEdit
                            ? Colors.white24
                            : (_anchorDate != null
                                  ? const Color(0xFF4FC3F7)
                                  : Colors.white38),
                      ),
                      const SizedBox(width: 7),
                      Text(
                        anchorLabel,
                        style: TextStyle(
                          fontSize: 11,
                          color: isInstanceEdit
                              ? Colors.white38
                              : (_anchorDate != null
                                    ? Colors.white70
                                    : Colors.white38),
                        ),
                      ),
                      if (!isInstanceEdit && _anchorDate != null) ...[
                        const Spacer(),
                        GestureDetector(
                          onTap: () => setState(() => _anchorDate = null),
                          child: Icon(
                            Icons.close_rounded,
                            size: 12,
                            color: Colors.white.withOpacity(0.3),
                          ),
                        ),
                      ],
                    ],
                  ),
                ),
              ),
            ],
          ),
        ),
      ],
    );
  }

  /// Reusable End Date picker row — used in both parent Generation Range
  /// and instance forward-edit blocks.
  Widget _buildEndDateRow() {
    return Row(
      children: [
        const Text(
          'End date',
          style: TextStyle(fontSize: 11, color: Colors.white54),
        ),
        const Spacer(),
        GestureDetector(
          onTap: _pickEndDate,
          child: Container(
            padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 5),
            decoration: BoxDecoration(
              color: _endDate != null
                  ? const Color(0xFF4FC3F7).withOpacity(0.1)
                  : Colors.white.withOpacity(0.05),
              borderRadius: BorderRadius.circular(4),
              border: Border.all(
                color: _endDate != null
                    ? const Color(0xFF4FC3F7).withOpacity(0.4)
                    : Colors.white.withOpacity(0.12),
              ),
            ),
            child: Row(
              mainAxisSize: MainAxisSize.min,
              children: [
                Icon(
                  Icons.calendar_today_outlined,
                  size: 11,
                  color: _endDate != null
                      ? const Color(0xFF4FC3F7)
                      : Colors.white38,
                ),
                const SizedBox(width: 6),
                Text(
                  _endDate != null ? _fmtDate(_endDate!) : 'No end date',
                  style: TextStyle(
                    fontSize: 11,
                    color: _endDate != null
                        ? const Color(0xFF4FC3F7)
                        : Colors.white38,
                  ),
                ),
              ],
            ),
          ),
        ),
        if (_endDate != null) ...[
          const SizedBox(width: 6),
          GestureDetector(
            onTap: () => setState(() => _endDate = null),
            child: const Icon(
              Icons.close_rounded,
              size: 13,
              color: Colors.white30,
            ),
          ),
        ],
      ],
    );
  }

  /// Reusable Days Ahead field — used in both parent Generation Range
  /// and instance forward-edit blocks.
  Widget _buildDaysAheadSlider() {
    final hasValue = _propagationDays != null;
    return Column(
      crossAxisAlignment: CrossAxisAlignment.stretch,
      children: [
        Row(
          children: [
            const Text(
              'Days ahead',
              style: TextStyle(fontSize: 11, color: Colors.white54),
            ),
            const Spacer(),
            // ── Text field ────────────────────────────────────────────
            SizedBox(
              width: 72,
              height: 30,
              child: TextField(
                controller: _daysAheadCtrl,
                keyboardType: TextInputType.number,
                inputFormatters: [FilteringTextInputFormatter.digitsOnly],
                textAlign: TextAlign.center,
                style: TextStyle(
                  fontSize: 12,
                  fontWeight: FontWeight.w600,
                  color: hasValue ? const Color(0xFF4FC3F7) : Colors.white38,
                ),
                decoration: InputDecoration(
                  isDense: true,
                  hintText: '—',
                  hintStyle: const TextStyle(
                    fontSize: 12,
                    color: Colors.white24,
                  ),
                  contentPadding: const EdgeInsets.symmetric(
                    horizontal: 8,
                    vertical: 6,
                  ),
                  suffixText: hasValue ? 'd' : null,
                  suffixStyle: const TextStyle(
                    fontSize: 11,
                    color: Color(0xFF4FC3F7),
                  ),
                  filled: true,
                  fillColor: hasValue
                      ? const Color(0xFF4FC3F7).withOpacity(0.08)
                      : Colors.white.withOpacity(0.04),
                  enabledBorder: OutlineInputBorder(
                    borderRadius: BorderRadius.circular(6),
                    borderSide: BorderSide(
                      color: hasValue
                          ? const Color(0xFF4FC3F7).withOpacity(0.3)
                          : Colors.white.withOpacity(0.12),
                    ),
                  ),
                  focusedBorder: OutlineInputBorder(
                    borderRadius: BorderRadius.circular(6),
                    borderSide: BorderSide(
                      color: hasValue
                          ? const Color(0xFF4FC3F7)
                          : Colors.white38,
                    ),
                  ),
                ),
                onChanged: (v) {
                  final parsed = int.tryParse(v);
                  setState(() {
                    _propagationDays = (parsed != null && parsed >= 1)
                        ? parsed
                        : null;
                  });
                },
                onEditingComplete: () {
                  final parsed = int.tryParse(_daysAheadCtrl.text);
                  if (parsed != null && parsed >= 1) {
                    setState(() {
                      _propagationDays = parsed;
                      _daysAheadCtrl.text = parsed.toString();
                    });
                  } else {
                    setState(() {
                      _propagationDays = null;
                      _daysAheadCtrl.clear();
                    });
                  }
                  FocusScope.of(context).unfocus();
                },
              ),
            ),
            // ── X clear button ────────────────────────────────────────
            if (hasValue) ...[
              const SizedBox(width: 4),
              GestureDetector(
                onTap: () => setState(() {
                  _propagationDays = null;
                  _daysAheadCtrl.clear();
                }),
                child: const Icon(
                  Icons.close_rounded,
                  size: 13,
                  color: Colors.white30,
                ),
              ),
            ],
          ],
        ),
        const SizedBox(height: 8),
        Text(
          _propagationDays != null && _endDate != null
              ? 'Instances generated up to ${_fmtDate(_endDate!)} or $_propagationDays days from the start date, whichever comes first.'
              : _propagationDays != null
              ? 'Instances generated for $_propagationDays days from the start date.'
              : _endDate != null
              ? 'Instances generated up to ${_fmtDate(_endDate!)}.'
              : 'Instances generated indefinitely (set a days limit or end date to cap generation).',
          style: TextStyle(
            fontSize: 10,
            color: Colors.white.withOpacity(0.35),
            fontStyle: FontStyle.italic,
          ),
        ),
      ],
    );
  }

  /// Read-only summary of the repeat config, inherited from the parent task.
  /// Tapping fires [onOpenParentConfig] which closes this dialog and reopens
  /// the parent's full repeat config dialog.
  Widget _buildReadOnlyConfig() {
    final parentId = widget.task.seriesId ?? widget.task.repeatParentId;
    final parent = parentId != null
        ? widget.allTasks.firstWhere(
            (t) => t.id == parentId,
            orElse: () => widget.task,
          )
        : widget.task;
    final cfg = parent.repeatConfig ?? widget.initial;
    final canOpen = widget.onOpenParentConfig != null;

    return _HoverContainer(
      onTap: canOpen
          ? () {
              Navigator.of(context).pop();
              widget.onOpenParentConfig!();
            }
          : null,
      borderDefault: Colors.white.withOpacity(0.07),
      borderHover: const Color(0xFF4FC3F7).withOpacity(0.4),
      child: Padding(
        padding: const EdgeInsets.all(12),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Row(
              children: [
                Icon(
                  Icons.link_rounded,
                  size: 11,
                  color: Colors.white.withOpacity(0.35),
                ),
                const SizedBox(width: 5),
                Text(
                  'CONFIG (inherited from parent)',
                  style: TextStyle(
                    fontSize: 9,
                    fontWeight: FontWeight.w700,
                    letterSpacing: 0.7,
                    color: Colors.white.withOpacity(0.35),
                  ),
                ),
                const Spacer(),
                if (canOpen)
                  Icon(
                    Icons.open_in_new_rounded,
                    size: 11,
                    color: Colors.white.withOpacity(0.25),
                  ),
              ],
            ),
            const SizedBox(height: 8),
            Text(
              cfg?.label ?? 'No repeat',
              style: const TextStyle(
                fontSize: 12,
                color: Colors.white70,
                fontWeight: FontWeight.w500,
              ),
            ),
            if (cfg?.endDate != null) ...[
              const SizedBox(height: 4),
              Text(
                'Ends ${_fmtDate(cfg!.endDate!)}',
                style: const TextStyle(fontSize: 10, color: Colors.white38),
              ),
            ],
          ],
        ),
      ),
    );
  }

  /// Button shown below the read-only config card for instances.
  /// Switches the dialog into forward-edit mode.
  Widget _buildEditFromHereButton() {
    return GestureDetector(
      onTap: () => setState(() => _editingForward = true),
      child: Container(
        width: double.infinity,
        padding: const EdgeInsets.symmetric(vertical: 8),
        decoration: BoxDecoration(
          color: Colors.white.withOpacity(0.03),
          borderRadius: BorderRadius.circular(6),
          border: Border.all(color: Colors.white.withOpacity(0.1)),
        ),
        child: Row(
          mainAxisAlignment: MainAxisAlignment.center,
          children: [
            Icon(
              Icons.edit_calendar_outlined,
              size: 12,
              color: Colors.white.withOpacity(0.45),
            ),
            const SizedBox(width: 7),
            Text(
              'Change repeat from this instance…',
              style: TextStyle(
                fontSize: 11,
                color: Colors.white.withOpacity(0.5),
              ),
            ),
          ],
        ),
      ),
    );
  }
}

// ─────────────────────────────────────────────────────────────────────────────
// _HoverContainer – a Container that reacts to mouse hover with a border tint.
// Used by _buildReadOnlyConfig to hint that the card is tappable.
// ─────────────────────────────────────────────────────────────────────────────

class _HoverContainer extends StatefulWidget {
  final Widget child;
  final VoidCallback? onTap;
  final Color borderDefault;
  final Color borderHover;

  const _HoverContainer({
    required this.child,
    required this.borderDefault,
    required this.borderHover,
    this.onTap,
  });

  @override
  State<_HoverContainer> createState() => _HoverContainerState();
}

class _HoverContainerState extends State<_HoverContainer> {
  bool _hovered = false;

  @override
  Widget build(BuildContext context) {
    return MouseRegion(
      cursor: widget.onTap != null
          ? SystemMouseCursors.click
          : MouseCursor.defer,
      onEnter: (_) => setState(() => _hovered = true),
      onExit: (_) => setState(() => _hovered = false),
      child: GestureDetector(
        onTap: widget.onTap,
        child: AnimatedContainer(
          duration: const Duration(milliseconds: 120),
          decoration: BoxDecoration(
            color: _hovered && widget.onTap != null
                ? Colors.white.withOpacity(0.04)
                : Colors.white.withOpacity(0.03),
            borderRadius: BorderRadius.circular(7),
            border: Border.all(
              color: _hovered && widget.onTap != null
                  ? widget.borderHover
                  : widget.borderDefault,
            ),
          ),
          child: widget.child,
        ),
      ),
    );
  }
}

// ─────────────────────────────────────────────────────────────────────────────
// _EmojiPickerButton – tappable preview that opens a floating EmojiSelector
// ─────────────────────────────────────────────────────────────────────────────

class _EmojiPickerButton extends StatefulWidget {
  final TextEditingController controller;
  final Color accentColor;

  const _EmojiPickerButton({
    required this.controller,
    required this.accentColor,
  });

  @override
  State<_EmojiPickerButton> createState() => _EmojiPickerButtonState();
}

class _EmojiPickerButtonState extends State<_EmojiPickerButton> {
  final LayerLink _layerLink = LayerLink();
  OverlayEntry? _overlayEntry;
  bool _isOpen = false;

  void _toggle() => _isOpen ? _close() : _open();

  void _open() {
    final overlay = Overlay.of(context);
    _overlayEntry = OverlayEntry(
      builder: (_) => _EmojiPickerOverlay(
        layerLink: _layerLink,
        accentColor: widget.accentColor,
        onSelect: (emoji) {
          widget.controller.text = emoji;
          widget.controller.selection = TextSelection.fromPosition(
            TextPosition(offset: emoji.length),
          );
          _close();
        },
        onClose: _close,
      ),
    );
    overlay.insert(_overlayEntry!);
    setState(() => _isOpen = true);
  }

  void _close() {
    _overlayEntry?.remove();
    _overlayEntry = null;
    if (mounted) setState(() => _isOpen = false);
  }

  @override
  void dispose() {
    _close();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    final icon = widget.controller.text.trim();
    final accent = widget.accentColor;
    return CompositedTransformTarget(
      link: _layerLink,
      child: GestureDetector(
        onTap: _toggle,
        child: AnimatedContainer(
          duration: const Duration(milliseconds: 150),
          width: 36,
          height: 36,
          decoration: BoxDecoration(
            color: _isOpen
                ? accent.withOpacity(0.22)
                : accent.withOpacity(0.08),
            borderRadius: BorderRadius.circular(8),
            border: Border.all(
              color: _isOpen
                  ? accent.withOpacity(0.75)
                  : accent.withOpacity(0.28),
            ),
          ),
          child: icon.isNotEmpty
              ? Center(
                  child: Text(
                    icon,
                    style: const TextStyle(
                      fontSize: 18,
                      fontFamilyFallback: [
                        'NotoColorEmoji',
                        'Apple Color Emoji',
                        'Segoe UI Emoji',
                      ],
                    ),
                  ),
                )
              : Icon(Icons.folder_outlined, color: accent, size: 18),
        ),
      ),
    );
  }
}

