  void _openAddMenu() {
    final overlay = Overlay.of(context);
    _addOverlay = OverlayEntry(builder: (_) => _buildAddDropdown());
    overlay.insert(_addOverlay!);
    setState(() => _addOpen = true);
  }

  void _closeAddMenu() {
    _addOverlay?.remove();
    _addOverlay = null;
    if (mounted) setState(() => _addOpen = false);
  }

  Widget _buildAddDropdown() {
    const items = [
      (
        Icons.label_outline_rounded,
        'Labels',
        'Organize, categorize, and prioritize',
