  void _handleAddItem(String type) {
    _closeAddMenu();
    switch (type) {
      case 'Checklist':
        _showAddChecklistDialog();
        break;
      case 'Labels':
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(
            content: Text('Labels: manage in Trello'),
            duration: Duration(seconds: 2),
          ),
        );
        break;
      case 'Dates':
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(
            content: Text('Dates: manage in Trello'),
            duration: Duration(seconds: 2),
          ),
        );
        break;
      case 'Members':
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(
            content: Text('Members: manage in Trello'),
            duration: Duration(seconds: 2),
          ),
        );
        break;
      case 'Attachment':
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(
            content: Text('Attachments: manage in Trello'),
            duration: Duration(seconds: 2),
          ),
        );
        break;
    }
  }

