          const SizedBox(width: 8),

          // ── Emoji picker button ─────────────────────────────────────────
          _EmojiPickerButton(controller: emojiController, accentColor: color),
        ],
      ),
    );
  }
}

// ── _MetagroupCriteriaPanel ────────────────────────────────────────────────
/// Shows individual criteria chips from each Metagroup that can be dragged
/// one-by-one into a container, or tapped to add to a selected target.
class _MetagroupCriteriaPanel extends StatefulWidget {
  final List<Task> allTasks;
  final Map<String, Project> projects;
  final List<GroupContainer> groupContainers;
  final void Function(GroupContainer target, ContainerCriteriaItem criterion) onAddCriterion;
  final void Function(GroupContainer gc) onAddContainer;
  final String Function() gristId;

  const _MetagroupCriteriaPanel({
    required this.allTasks,
    required this.projects,
    required this.groupContainers,
    required this.onAddCriterion,
    required this.onAddContainer,
    required this.gristId,
  });

  @override
  State<_MetagroupCriteriaPanel> createState() => _MetagroupCriteriaPanelState();
}

class _MetagroupCriteriaPanelState extends State<_MetagroupCriteriaPanel> {
  // Which metagroup is expanded in the dropdown
  TaskMetagroup? _expanded;
  bool _dropdownOpen = false;
  // Currently selected target container (null = add as new container)
  GroupContainer? _targetContainer;

  List<_MetaCriterionSpec> _specsFor(TaskMetagroup mg) {
    switch (mg) {
      case TaskMetagroup.status:
        return TaskStatus.values.map((s) => _MetaCriterionSpec(
          label: s.label,
          color: s.color.withOpacity(0.7),
          buildItem: (id) => ContainerCriteriaItem(
            id: id,
            type: CriteriaItemType.status,
            status: s,
          ),
          buildContainer: (id) => GroupContainer(
            id: id,
            displayLabel: s.label,
            statusMatches: {s},
          ),
        )).toList();
      case TaskMetagroup.repeating:
        return [
          _MetaCriterionSpec(
            label: 'Repeating',
            color: const Color(0xFF7C4DFF).withOpacity(0.7),
            buildItem: (id) => ContainerCriteriaItem(id: id, type: CriteriaItemType.repeating, boolValue: true),
            buildContainer: (id) => GroupContainer(id: id, displayLabel: 'Repeating', repeatingMatch: true),
          ),
          _MetaCriterionSpec(
            label: 'Non-Repeating',
            color: Colors.white38,
            buildItem: (id) => ContainerCriteriaItem(id: id, type: CriteriaItemType.repeating, boolValue: false),
            buildContainer: (id) => GroupContainer(id: id, displayLabel: 'Non-Repeating', repeatingMatch: false),
          ),
        ];
      case TaskMetagroup.scheduledDate:
        return [
          _MetaCriterionSpec(
            label: 'Overdue',
            color: const Color(0xFFEF5350).withOpacity(0.7),
            buildItem: (id) => ContainerCriteriaItem(id: id, type: CriteriaItemType.overdue, boolValue: true),
            buildContainer: (id) => GroupContainer(id: id, displayLabel: 'Overdue', overdueMatch: true),
          ),
          _MetaCriterionSpec(
            label: 'Not Overdue',
            color: Colors.white38,
            buildItem: (id) => ContainerCriteriaItem(id: id, type: CriteriaItemType.overdue, boolValue: false),
            buildContainer: (id) => GroupContainer(id: id, displayLabel: 'Not Overdue', overdueMatch: false),
          ),
        ];
      case TaskMetagroup.remainder:
        return [
          _MetaCriterionSpec(
            label: 'catch-all',
            color: Colors.white24,
            buildItem: (id) => ContainerCriteriaItem(id: id, type: CriteriaItemType.catchAll),
            buildContainer: (id) => GroupContainer(id: id, displayLabel: 'Rest', isRest: true),
          ),
        ];
      case TaskMetagroup.tag:
        final tags = widget.allTasks
            .expand((t) => t.tagIds.map((id) => id.toString()))
            .toSet()
            .toList()
          ..sort();
        return tags.map((tag) => _MetaCriterionSpec(
          label: tag,
          color: const Color(0xFF4FC3F7).withOpacity(0.6),
          buildItem: (id) => ContainerCriteriaItem(
            id: id,
            type: CriteriaItemType.catchAll, // placeholder — tag matching TBD
          ),
          buildContainer: (id) => GroupContainer(id: id, displayLabel: tag),
        )).toList();
      case TaskMetagroup.project:
        return widget.projects.entries.map((e) => _MetaCriterionSpec(
          label: e.value.title,
          color: const Color(0xFF66BB6A).withOpacity(0.6),
          buildItem: (id) => ContainerCriteriaItem(
            id: id,
            type: CriteriaItemType.catchAll,
          ),
          buildContainer: (id) => GroupContainer(id: id, displayLabel: e.value.title),
        )).toList();
    }
  }

  @override
  Widget build(BuildContext context) {
    const accent = Color(0xFF4FC3F7);
    const surface = Color(0xFF22252A);

    return Padding(
      padding: const EdgeInsets.fromLTRB(10, 4, 10, 6),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          // ── Dropdown trigger ─────────────────────────────────────────
          GestureDetector(
            onTap: () => setState(() {
              _dropdownOpen = !_dropdownOpen;
              if (!_dropdownOpen) _expanded = null;
            }),
            child: Container(
              padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 5),
              decoration: BoxDecoration(
                color: _dropdownOpen
                    ? accent.withOpacity(0.10)
                    : Colors.white.withOpacity(0.05),
                borderRadius: BorderRadius.circular(6),
                border: Border.all(
                  color: _dropdownOpen ? accent.withOpacity(0.35) : Colors.white12,
                ),
              ),
              child: Row(
                mainAxisSize: MainAxisSize.min,
                children: [
                  Icon(
                    _dropdownOpen ? Icons.expand_less : Icons.expand_more,
                    size: 12,
                    color: _dropdownOpen ? accent : Colors.white38,
                  ),
                  const SizedBox(width: 5),
                  Text(
                    'Add criteria',
                    style: TextStyle(
                      fontSize: 10,
                      color: _dropdownOpen ? accent : Colors.white54,
                      fontWeight: _dropdownOpen ? FontWeight.w600 : FontWeight.normal,
                    ),
                  ),
                ],
              ),
            ),
          ),

          // ── Dropdown body ─────────────────────────────────────────────
          if (_dropdownOpen) ...[
            const SizedBox(height: 4),
            Container(
              decoration: BoxDecoration(
                color: surface,
                borderRadius: BorderRadius.circular(7),
                border: Border.all(color: Colors.white.withOpacity(0.08)),
              ),
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: TaskMetagroup.values.map((mg) {
                  final isOpen = _expanded == mg;
                  final specs = _specsFor(mg);
                  return Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      // ── Metagroup row (expandable header) ────────────
                      GestureDetector(
                        onTap: () => setState(() => _expanded = isOpen ? null : mg),
                        child: Container(
                          padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 7),
                          decoration: BoxDecoration(
                            color: isOpen ? accent.withOpacity(0.07) : Colors.transparent,
                            borderRadius: BorderRadius.circular(6),
                          ),
                          child: Row(
                            children: [
                              Icon(
                                isOpen ? Icons.keyboard_arrow_down : Icons.keyboard_arrow_right,
                                size: 13,
                                color: isOpen ? accent : Colors.white38,
                              ),
                              const SizedBox(width: 6),
                              Text(
                                mg.label,
                                style: TextStyle(
                                  fontSize: 11,
                                  color: isOpen ? accent : Colors.white60,
                                  fontWeight: isOpen ? FontWeight.w600 : FontWeight.normal,
                                ),
                              ),
                            ],
                          ),
                        ),
                      ),

                      // ── Expanded: option list with draggable items ───
                      if (isOpen) ...[
                        // Target selector
                        if (widget.groupContainers.isNotEmpty)
                          Padding(
                            padding: const EdgeInsets.fromLTRB(10, 0, 10, 4),
                            child: Row(
                              children: [
                                const Text(
                                  'Add to: ',
                                  style: TextStyle(fontSize: 9, color: Colors.white38),
                                ),
                                Expanded(
                                  child: SingleChildScrollView(
                                    scrollDirection: Axis.horizontal,
                                    child: Row(
                                      children: [
                                        GestureDetector(
                                          onTap: () => setState(() => _targetContainer = null),
                                          child: Container(
                                            margin: const EdgeInsets.only(right: 4),
                                            padding: const EdgeInsets.symmetric(horizontal: 5, vertical: 2),
                                            decoration: BoxDecoration(
                                              color: _targetContainer == null
                                                  ? accent.withOpacity(0.15)
                                                  : Colors.transparent,
                                              borderRadius: BorderRadius.circular(4),
                                              border: Border.all(
                                                color: _targetContainer == null
                                                    ? accent.withOpacity(0.4)
                                                    : Colors.white12,
                                              ),
                                            ),
                                            child: Text(
                                              'New Container',
                                              style: TextStyle(
                                                fontSize: 9,
                                                color: _targetContainer == null ? accent : Colors.white38,
                                              ),
                                            ),
                                          ),
                                        ),
                                        ...widget.groupContainers.map((gc) => GestureDetector(
                                          onTap: () => setState(() => _targetContainer = gc),
                                          child: Container(
                                            margin: const EdgeInsets.only(right: 4),
                                            padding: const EdgeInsets.symmetric(horizontal: 5, vertical: 2),
                                            decoration: BoxDecoration(
                                              color: _targetContainer?.id == gc.id
                                                  ? accent.withOpacity(0.15)
                                                  : Colors.transparent,
                                              borderRadius: BorderRadius.circular(4),
                                              border: Border.all(
                                                color: _targetContainer?.id == gc.id
                                                    ? accent.withOpacity(0.4)
                                                    : Colors.white12,
                                              ),
                                            ),
                                            child: Text(
                                              gc.displayLabel.isEmpty ? '(unnamed)' : gc.displayLabel,
                                              style: TextStyle(
                                                fontSize: 9,
                                                color: _targetContainer?.id == gc.id ? accent : Colors.white38,
                                              ),
                                            ),
                                          ),
                                        )),
                                      ],
                                    ),
                                  ),
                                ),
                              ],
                            ),
                          ),
                        // Option rows — each draggable individually
                        ...specs.map((spec) {
                          final dragData = _MetaDragData(
                            spec: spec,
                            targetContainer: _targetContainer,
                          );
                          return Draggable<_MetaDragData>(
                            data: dragData,
                            feedback: Material(
                              color: Colors.transparent,
                              child: Container(
                                padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 5),
                                decoration: BoxDecoration(
                                  color: spec.color.withOpacity(0.25),
                                  borderRadius: BorderRadius.circular(5),
                                  border: Border.all(color: spec.color.withOpacity(0.5)),
                                ),
                                child: Text(
                                  spec.label,
                                  style: TextStyle(
                                    fontSize: 10,
                                    color: spec.color,
                                    fontWeight: FontWeight.w600,
                                  ),
                                ),
                              ),
                            ),
                            childWhenDragging: Opacity(
                              opacity: 0.3,
                              child: _buildSpecRow(spec, accent),
                            ),
                            child: GestureDetector(
                              onTap: () {
                                final target = _targetContainer;
                                if (target != null) {
                                  widget.onAddCriterion(target, spec.buildItem(widget.gristId()));
                                } else {
                                  widget.onAddContainer(spec.buildContainer(widget.gristId()));
                                }
                              },
                              child: _buildSpecRow(spec, accent),
                            ),
                          );
                        }),
                        const SizedBox(height: 4),
                      ],
                    ],
                  );
                }).toList(),
              ),
            ),
          ],
        ],
      ),
    );
  }

  Widget _buildSpecRow(_MetaCriterionSpec spec, Color accent) {
    return Container(
      padding: const EdgeInsets.symmetric(horizontal: 14, vertical: 6),
      child: Row(
        children: [
          Icon(Icons.drag_indicator, size: 11, color: Colors.white24),
          const SizedBox(width: 6),
          Container(
            width: 8,
            height: 8,
            decoration: BoxDecoration(
              color: spec.color,
              borderRadius: BorderRadius.circular(2),
            ),
          ),
          const SizedBox(width: 7),
          Text(
            spec.label,
            style: TextStyle(
              fontSize: 11,
              color: spec.color,
              fontWeight: FontWeight.w500,
            ),
          ),
          const Spacer(),
          Icon(Icons.add, size: 11, color: Colors.white24),
        ],
      ),
    );
  }
}

class _MetaDragData {
  final _MetaCriterionSpec spec;
  final GroupContainer? targetContainer;
  const _MetaDragData({required this.spec, this.targetContainer});
}

class _MetaCriterionSpec {
  final String label;
  final Color color;
  final ContainerCriteriaItem Function(String id) buildItem;
  final GroupContainer Function(String id) buildContainer;

  const _MetaCriterionSpec({
    required this.label,
    required this.color,
    required this.buildItem,
    required this.buildContainer,
  });
}

