  }

  Widget _topBar() => _focused ? _topBarFocused() : _topBarDialog();

  Widget _topBarFocused() => Container(
        height: 46,
        padding: const EdgeInsets.symmetric(horizontal: 8),
        child: Row(children: [
          IconButton(
            tooltip: 'Back',
            icon: const Icon(Icons.arrow_back_rounded, size: 18, color: Colors.white54),
            onPressed: () async {
