            TextButton(
              onPressed: () async {
                if (!await _discardOk()) return;
                widget.onOpenFull!();
              },
              child: const Text('All settings…'),
            ),
          const SizedBox(width: 8),
          ElevatedButton(
            onPressed: _dirty ? _save : null,
