        padding: const EdgeInsets.fromLTRB(16, 0, 16, 8),
        child: Wrap(spacing: 6, runSpacing: 6, children: [
          for (final s in _focused
              ? const [
                  ('general', 'Name & icon'),
                  ('pattern', 'Folder pattern'),
                ]
              : const [
                  ('general', 'General'),
                  ('pattern', 'Folder pattern'),
                  ('tabs', 'Tabs & profile'),
                  ('children', 'Children'),
                  ('properties', 'Properties'),
                  ('exports', 'Exports'),
                  ('yaml', 'YAML'),
                ])
